RG.HK["32"] = [{"id":"32_izumo_taisha","n":"出雲大社（国譲りの神話と巨大神殿）","yomi":"いずもおおやしろ（いずもたいしゃ）","cat":"寺社","rank":"S","y":733,"era":["myth","nara","edo"],"sh":"国宝（本殿）","ad":"出雲市大社町杵築東","st":"一畑電車 出雲大社前駅から歩いて約5分","la":35.4017,"lo":132.6854,"hook":"むかし、この神殿は «東大寺の大仏殿より高かった» といわれる。土の中から出てきた3本束ねの巨大な柱が、その話を本当にした。","lead":"«縁結びの神さま» として知られる大国主大神をまつる神社です。神話では、国をゆずるかわりに大きな宮殿を建ててもらった、とされます。今の本殿は江戸時代の1744年に建てられた国宝で、高さは約24m。古代にはもっと高かったという言い伝えがあります。","story":["『古事記』や『日本書紀』には «国譲り» の話がのっています。地上の国をおさめていた大国主神のもとへ、天の神の使いがやってきて «この国をゆずれ» とせまります。大国主は子どもたちの意見を聞いたあと、国をゆずることを決めました。そのとき出した条件が «わたしの住まいを、天の神の御殿のように太い柱で、高くりっぱに建ててほしい» というもの。これが出雲大社の始まりだと語られています。","では、本当にそんなに高い神殿があったのでしょうか? 平安時代の970年、源為憲という学者が子ども向けの教科書『口遊（くちずさみ）』を書きました。そこに «雲太、和二、京三» という覚え歌があります。大きな建物の1番は出雲（雲太）、2番は大和の東大寺大仏殿（和二）、3番は京の大極殿（京三）という意味です。出雲の神殿は大仏殿より大きかった、というのです。","社家には高さ16丈（約48m）という言い伝えも残り、柱を3本ずつ鉄の輪でたばねた «金輪御造営差図（かなわごぞうえいさしず）» という図面も伝わっていました。けれど長いあいだ «話を大きくしたのでは?» と疑う人もいました。ところが2000年、境内の八足門の前を掘ったところ、スギの大木を3本たばねた巨大な柱の根元が見つかったのです。図面そっくりでした。","この柱は «宇豆柱（うづばしら）» と名づけられ、鎌倉時代の1248年ごろの本殿のものと考えられています。1本の直径は約1.3m、3本たばねると約3mにもなります。«48mは本当か» はいまも研究者のあいだで議論が続いていますが、昔の出雲に «ふつうでは考えられない高さの神殿» があったことは、たしかになりました。","今の本殿は1744年の造営で、高さは8丈（約24m）。それでも神社の本殿としては飛び抜けた大きさです。出雲大社の神職の家は、古代の出雲国造（くにのみやつこ）の子孫とされる千家・北島の両家。60年に一度ほど本殿の屋根をふきかえる «遷宮» があり、2013年には «平成の大遷宮» で神さまが修理を終えた本殿にもどりました。旧暦10月、全国の神々が集まる «神在月» の舞台でもあります。"],"tl":[["733年","『出雲国風土記』完成。«杵築（きづき）» の地名と大神の宮が記される"],["970年","『口遊』に «雲太、和二、京三» と書かれる"],["1248年","このころの本殿の柱が、のちの宇豆柱と考えられる"],["1744年","現在の本殿が完成（延享の造営）"],["1871年","«杵築大社» から «出雲大社» に名前を改める"],["1952年","本殿が国宝に指定される"],["2000年","境内から巨大柱（宇豆柱）が見つかる"],["2013年","平成の大遷宮で本殿遷座祭"]],"who":[["大国主大神","まつられている神。国譲りの神話の主人公"],["源為憲","平安時代の学者。『口遊』で«雲太»と書いた"],["出雲国造（千家家・北島家）","古代からこの神社の祭りをつかさどってきた家"],["天穂日命","出雲国造の祖先とされる神"]],"deep":["«48m説» の根拠は社家の伝承と金輪御造営差図。ただし差図がいつの時代の本殿を描いたかは諸説あり、柱の出土で«大きさ»の信ぴょう性は増したが、高さそのものは今も復元案が複数ある。","出土した宇豆柱と心御柱は、島根県立古代出雲歴史博物館で実物を見られる。境内の出土地点には、柱の位置が丸い印で示されている。","正式な読み方は «いずもおおやしろ»。明治のはじめまでは «杵築大社（きづきのおおやしろ）» と呼ばれていた。","参拝の作法は «二礼四拍手一礼»。ふつうの神社の二拍手とちがう理由ははっきりせず、諸説ある。","本殿は «大社造（たいしゃづくり）»。正面の中央に柱があり、入口が右にかたよるのが特ちょう。内部では御神座が西（横）を向いているといわれる。","神楽殿の大しめ縄は日本最大級。本殿のしめ縄と «なう向き» が一般の神社と逆だといわれる。"],"look":["八足門前の地面に示された宇豆柱の出土位置","国宝の本殿（屋根の千木とかつお木）","神楽殿の大しめ縄","本殿を囲む東西の十九社（神在月に神々が泊まる宿とされる）","近くの古代出雲歴史博物館の宇豆柱と、古代神殿の模型"],"q":["«雲太、和二、京三» の «雲太» とは何のこと?","出雲の神殿が日本一大きい建物だという意味。2番が奈良の大仏殿、3番が京都の大極殿でした。"],"koji":[{"w":"雲太、和二、京三","m":"平安時代の大きな建物ベスト3。出雲大社の神殿が1位とされた"}],"myth":"古代神殿の高さ（16丈＝約48m、さらに32丈説）は伝承で、学説は分かれる。国譲りは神話。","img":["宇豆柱","出雲国造","島根県立古代出雲歴史博物館"],"wp":"出雲大社","rel":{"ev":["fudoki"],"grave":[]},"ph":[["c:1/1c/Haiden_of_Izumo-taisha-1.JPG",5077,3377,"出雲大社"],["c:5/59/Mon-_Izumo_taisha.png",4000,4000],["c:f/f4/Izumo-taisha_Shintotsukawa_Branch.jpg",4320,3240],["c:e/e6/Izumo-taisha14bs4592.jpg",4592,3056],["c:c/cf/Izumo-taisha11n4592.jpg",4592,3056],["c:a/a7/Izumo-taisha05n4592.jpg",4592,3056],["c:7/7a/Izumo-Taisha_Kurayoshi_Branch_ac.jpg",5484,3646],["c:7/7b/Hida_Church%2C_Izumo_Oyashiro.jpg",4608,3456]]},{"id":"32_iwami_ginzan","n":"石見銀山（戦国〜江戸の世界的銀山）","yomi":"いわみぎんざん","cat":"産業","rank":"S","y":1526,"era":["muromachi","azuchi","edo"],"sh":"国指定史跡（石見銀山遺跡）・世界遺産","ad":"大田市大森町","st":"JR大田市駅からバスで約25〜30分「大森代官所跡」。龍源寺間歩へはさらに歩いて約45分（レンタサイクルも便利）","la":35.1042,"lo":132.4399,"hook":"16世紀、ヨーロッパの地図に «銀の山» と書きこまれた日本の山がある。緑の森の下には、数百もの坑道がいまも眠っている。","lead":"戦国時代に本格的な開発が始まり、江戸時代にかけて大量の銀を掘り出した鉱山です。ここの銀は日本のお金になるだけでなく、中国やヨーロッパとの貿易にも使われました。自然をこわしすぎずに銀を掘った «森の鉱山» として、2007年に世界遺産になりました。","story":["1526年ごろ、博多の商人・神屋寿禎（かみやじゅてい）が、日本海を船で進んでいるとき、南の山が光って見えたという言い伝えがあります。寿禎は出雲の鉱山師らの協力をえて、仙ノ山で銀を掘り始めました。これが石見銀山の本格的な開発の始まりです。","でも、掘り出した鉱石から銀だけを取り出すのはむずかしい仕事でした。1533年、寿禎は朝鮮半島から伝わった新しい技術 «灰吹法（はいふきほう）» を、宗丹と慶寿という技術者を招いて取り入れます。鉱石を鉛といっしょにとかし、そのあと灰の上で熱すると、鉛は灰にしみこみ、銀だけがきらりと残るのです。この方法はやがて全国の鉱山に広まり、日本は «銀の国» になっていきました。","«銀のなる山» を戦国大名がほうっておくはずがありません。周防の大内氏、出雲の尼子氏、そして安芸の毛利氏が、銀山と山吹城をめぐって何十年も争いました。最後に勝ったのは毛利元就。銀は毛利の軍資金となり、朝廷への献上にも使われました。","関ヶ原の戦いのあと、徳川家康は銀山を幕府のものにし、大久保長安を送りこみます。江戸時代のはじめには、山のまわりにたくさんの人が暮らしたといわれます。ポルトガルの人がつくった日本地図には、このあたりに «銀鉱山» と書かれました。当時、日本の銀は世界の銀の生産のかなりの部分をしめたといわれ、その中心が石見でした。","やがて銀は掘りつくされ、1923年（大正12年）に銀山は休山しました。坑道の入口 «間歩（まぶ）» は600以上見つかっています。木を切りすぎず、山の森を守りながら掘ってきたので、今も山は緑にもどっています。«鉱山なのに森がきれい» ――それが世界遺産に選ばれた理由のひとつなのです。"],"tl":[["1526年","神屋寿禎が本格的な採掘を始めたと伝わる"],["1533年","灰吹法が取り入れられる"],["1562年","毛利元就が銀山の支配を固める"],["1600年","関ヶ原の戦いのあと、徳川家の直轄地に。大久保長安が支配"],["1923年","休山"],["1969年","«石見銀山遺跡» が国の史跡に"],["2007年","«石見銀山遺跡とその文化的景観» が世界遺産に登録"]],"who":[["神屋寿禎","博多の商人。本格的な開発と灰吹法の導入に関わった"],["毛利元就","争奪戦に勝ち、銀山を手に入れた戦国大名"],["大久保長安","徳川家康に仕え、初期の銀山経営を仕切った"],["井戸平左衛門","江戸中期の大森代官。サツマイモで飢えから人々を救ったといわれる"]],"deep":["灰吹法はもともと朝鮮半島で使われた技術とされる。石見での成功のあと、佐渡や生野などにも広がった。","世界の銀に占める日本の割合は «3分の1» という数字がよく出るが、推計のしかたで幅がある。«石見だけで» ではなく日本全体の数字であることに注意。","1595年のテイセラの日本図には、石見のあたりに «銀鉱山» を意味するラテン語が書かれていることで知られる。","間歩は600以上確認されている。一般公開の龍源寺間歩は江戸中期に開かれた代官所直営の坑道の一つ。大久保間歩は季節限定のガイドツアーで入れる。","世界遺産の範囲は鉱山だけでなく、大森の町、銀を運んだ石見銀山街道、積み出し港の温泉津・鞆ヶ浦・沖泊までふくむ «鉱山と町と道と港のセット»。","精錬のときの煙で木が枯れにくいよう、燃料の森を計画的に使い回したことが、景観が保たれた理由の一つといわれる。"],"look":["龍源寺間歩（手掘りのノミの跡が残る）","清水谷製錬所跡（明治の近代化のあと）","佐毘売山神社（鉱山の神）","大森の町並みと代官所跡","世界遺産センターの展示"],"q":["鉱石から銀だけを取り出す技術を何という?","«灰吹法»。鉛といっしょにとかし、灰の上で熱すると鉛が灰にしみこみ、銀が残ります。"],"koji":[],"myth":"神屋寿禎が «海から光る山を見た» 話は伝承。発見年も1526年とするのが一般的だが、それ以前から銀が知られていたともいわれる。","img":["灰吹法","大久保長安","神屋寿禎"],"wp":"石見銀山","rel":{"ev":["iwami_ginzan"],"grave":[]},"ph":[["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:9/9c/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%933.JPG",4320,3240],["c:0/05/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%9311.JPG",4320,3240],["c:8/81/180505_Yunotsu_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan01s5.jpg",5760,3840],["c:9/9a/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan01s3.jpg",6000,4000],["c:c/c6/180505_House_of_the_Kumagai_Family_Oda_Shimane_pref_Japan01o.JPG",6000,4000],["c:3/33/180504_Shimogawara_Smelting_Ruins_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan01s5.jpg",6000,4000],["c:2/2a/180504_Rakan-ji_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan01o.JPG",6000,4000]]},{"id":"32_matsue_jo","n":"松江城（現存天守・国宝）","yomi":"まつえじょう","cat":"城","rank":"S","y":1611,"era":["edo"],"sh":"国宝（天守）・国指定史跡","ad":"松江市殿町","st":"JR松江駅からバスで約10分「県庁前」下車すぐ","la":35.4753,"lo":133.0506,"hook":"«いつ建てたの?» が長年わからず国宝になれなかった天守。答えは、行方不明だった2枚の木の札が教えてくれた。","lead":"江戸時代の初めに建てられ、今も当時の天守が残る全国12の城のひとつです。黒っぽい板張りの外観がきりっとしていて、«千鳥城» とも呼ばれます。2015年、国宝に指定されました。","story":["関ヶ原の戦いで手がらを立てた堀尾吉晴は、出雲と隠岐をあたえられ、はじめは山の上の月山富田城に入りました。けれど、鉄砲の時代に山城は不便です。城下町も広げられません。«宍道湖のほとりに新しい城をつくろう» と決めたのが、松江城の始まりでした。","工事は1607年から5年ほどかかり、1611年に完成したとされます。しかし吉晴は城の完成直前に亡くなり、あとをついだ孫の忠晴も若くして亡くなって堀尾家は3代で断絶しました。そのあと京極忠高をへて、1638年に松平直政が入り、明治まで松平家10代がこの城の主となります。","明治になると、全国の城はつぎつぎと取りこわされました。松江城も天守以外の建物は売りはらわれ、天守まで壊される寸前に。«城を残したい» と願った地元の人たちがお金を出して天守を買いもどした、と伝わっています。","天守は昭和の初めに国宝（旧制度）になりましたが、戦後の新しい法律では «重要文化財» にとどまりました。完成年を示すはっきりした証拠がなかったのです。昔の写真には天守の中に «慶長十六年» と書かれた祈祷札（きとうふだ）が写っていましたが、実物は行方がわからなくなっていました。","2012年、市の調査で、その祈祷札2枚が城下の松江神社で見つかりました。天守の柱にあった釘の穴と、札の穴の位置もぴったり合います。«1611年には天守が完成していた» ことが確かめられ、2015年、ついに国宝に指定されたのです。«なくし物が国宝をつれてきた»――町の人はそう言って喜びました。"],"tl":[["1600年","堀尾吉晴・忠氏が出雲・隠岐をあたえられる"],["1607年","松江城の築城が始まる"],["1611年","天守完成（祈祷札の年）"],["1638年","松平直政が入り、以後松平家10代の居城に"],["1875年","天守を残してほかの建物が取りこわされる"],["1934年","城跡が国の史跡に"],["2012年","行方不明だった祈祷札が見つかる"],["2015年","天守が国宝に指定"]],"who":[["堀尾吉晴","松江城と城下町をつくった大名"],["松平直政","徳川家康の孫。松江藩松平家の初代"],["松平治郷（不昧）","7代藩主。茶人として有名で、松江の和菓子文化を育てた"],["小泉八雲","明治に松江に住み、城と城下の風景を愛した"]],"deep":["天守は外から見ると4重、内部は5階と地下1階。いちばん下の地下には井戸があり、籠城にそなえたものと考えられている。天守の中に井戸が残るのは珍しい。","柱のまわりに板を張って鉄の帯でしめた «包板（つつみいた）» が多く使われている。太い一本木が手に入りにくかったための工夫と考えられる。","階段は桐の板でできていて、敵が来たら引き上げられるように、また燃えにくいように、という説がある。","築城のときに石垣が何度もくずれ、«人柱» を立てたという伝説がある。町では «盆踊りをすると天守がゆれる» といわれ、長く盆踊りをしなかったという話もあるが、伝承。","天守の附櫓（つけやぐら）から入る形式で、入口に鉄砲をうつための «石落とし» が工夫されている。"],"look":["天守地下の井戸","祈祷札（天守内で複製を展示）","桐の階段と包板の柱","最上階の «天狗の間» から見る宍道湖","堀川めぐりの舟から見る石垣"],"q":["松江城が国宝になる決め手になったものは?","天守の完成年を書いた «祈祷札»。2012年に松江神社で見つかりました。"],"koji":[],"myth":"人柱伝説や、明治の天守買いもどしの金額などは伝承をふくむ。","img":["堀尾吉晴","松平治郷","宍道湖"],"wp":"松江城","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Matsue_Castle_Keep_Tower_20230617.jpg",4988,3741,"松江城"],["c:2/2d/Matsue_castle10bs4592.jpg",4592,3056],["c:9/91/Matsue_castle03bs4592.jpg",4592,3056],["c:7/7b/Horikawa_sightseeing_boat_with_lowering_roof.jpg",4896,3672],["c:b/b4/Matsue_Castle1.jpg",3216,2136],["c:2/23/Matsue_Castle-3.jpg",3216,2136],["c:6/69/Matsue_Castle-1.jpg",3134,2007],["c:3/3c/Matsue_Castle-2.jpg",3079,1892]]},{"id":"32_kojindani","n":"荒神谷遺跡（銅剣358本）","yomi":"こうじんだにいせき","cat":"遺跡","rank":"S","y":-100,"era":["yayoi"],"sh":"国指定史跡・出土品は国宝","ad":"出雲市斐川町神庭","st":"JR荘原駅から車で約5分（歩くと約40分）","la":35.3718,"lo":132.8455,"hook":"それまで日本全国で見つかっていた銅剣は約300本。それを1か所で上回る358本が、小さな谷の斜面から出てきた。","lead":"1984年、農道をつくる前の調査で、弥生時代の銅剣358本がきれいに並べて埋められているのが見つかりました。翌年にはすぐそばから銅鐸6個と銅矛16本も。«出雲には神話だけで遺跡はない» という考えを、ひっくり返した大発見です。","story":["1983年、斐川町の小さな谷で、農道の工事の前に調査をしていた人が、畑のあぜで古い土器のかけらを見つけました。«何かあるかもしれない»。翌1984年の夏に発掘を始めると、斜面の土の中から、緑色にさびた細長い金属が次々に顔を出しました。銅剣です。","数えると、なんと358本。4列にぎっしりと、刃を立てて並べてありました。それまで日本中で見つかった銅剣を全部あわせても約300本だったので、発掘した人たちも最初は信じられなかったといいます。«一つの場所から、全国分より多い銅剣が!»。ニュースは日本中をかけめぐりました。","驚きはまだ終わりません。1985年、銅剣の場所からわずか7mほどはなれたところから、銅鐸6個と銅矛16本がいっしょに見つかりました。銅鐸は近畿、銅矛は九州北部で多く使われた道具とされていたので、«ちがう地域の祭りの道具が、出雲で一緒に埋められていた» ことになります。","«なぜ、こんなにたくさん埋めたの?» これがいちばんの謎です。神さまへのお供えとして大切にしまったという説、ふだんは埋めておき祭りのときに掘り出したという説、新しい祭りに変わるので古い道具をまとめて埋めたという説など、今も答えは出ていません。","銅剣の多くには、柄に入れる部分に «×» の印が刻まれていました。そして1996年、山を越えた3kmあまり先の加茂岩倉遺跡で見つかった銅鐸にも、同じ «×» の印があったのです。弥生時代の出雲に、たくさんの青銅器を集めることのできる大きな力があった――。荒神谷は、そんな «出雲の王» の影を感じさせる場所です。"],"tl":[["紀元前2〜1世紀ごろ","銅剣・銅鐸・銅矛がつくられたと考えられる（埋めた時期は諸説）"],["1983年","農道予定地の調査で土器が見つかる"],["1984年","銅剣358本が出土"],["1985年","銅鐸6個・銅矛16本が出土"],["1987年","国の史跡に指定"],["1998年","出土品が一括して国宝に指定"]],"who":[["弥生時代の出雲の人びと","青銅器を集め、埋めた人たち。名前は伝わっていない"],["発掘調査にあたった島根県の調査員たち","畑のわずかな土器片から大発見につなげた"]],"deep":["銅剣はすべて «中細形銅剣c類» と呼ばれるタイプで、出雲周辺に多いことから «出雲型銅剣» ともいわれる。形がそろっているため、同じ地域でまとめてつくられた可能性が指摘される。","358本のうち344本に «×» 印がある。加茂岩倉の銅鐸にも同じ印があり、同じ集団が関わったと考える説がある。印の意味は不明。","銅剣は刃を上下にして交互に（刃を立てて）並べられていた。ていねいに埋めた «埋納（まいのう）» とみられる。","出土品は国（文化庁）の所有で、島根県立古代出雲歴史博物館で358本がずらりと並ぶ展示を見られる。","遺跡の近くには仏経山（ぶっきょうざん）がそびえ、『出雲国風土記』の «神名火山（かんなびやま）» にあてる説がある。神の山のふもとに埋めた、と考える研究者もいる。"],"look":["発掘当時の並びを再現したレプリカの埋納地","銅鐸・銅矛の出土地","荒神谷博物館の展示","夏の古代ハス（大賀ハス）の池"],"q":["荒神谷遺跡で見つかった銅剣の数は?","358本。それまで全国で見つかっていた銅剣の数を1か所で上回りました。"],"koji":[],"myth":"埋めた目的・時期は諸説。«出雲の王» の実像は不明。","img":["銅剣","銅鐸","島根県立古代出雲歴史博物館"],"wp":"荒神谷遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:7/7a/Koujindani_Remains_01.JPG",1600,1064,"荒神谷遺跡"],["j:8/8a/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_%E9%8A%85%E5%89%A3%E3%83%BB%E9%8A%85%E7%9F%9B.JPG",5554,3692],["j:c/c1/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_4%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2650,3538],["j:7/79/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_6%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2648,3539],["j:b/ba/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_2%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2639,3530],["j:3/33/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_5%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2638,3521],["j:0/06/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_3%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2561,3425],["j:2/2a/%E8%8D%92%E7%A5%9E%E8%B0%B7%E9%81%BA%E8%B7%A1_1%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2518,3360]]},{"id":"32_kamo_iwakura","n":"加茂岩倉遺跡（銅鐸39個）","yomi":"かもいわくらいせき","cat":"遺跡","rank":"S","y":-100,"era":["yayoi"],"sh":"国指定史跡・出土品は国宝","ad":"雲南市加茂町岩倉","st":"JR加茂中駅から車で約10分","la":35.3432,"lo":132.8716,"hook":"重機のバケットにかかったのは、大きな銅鐸の中に小さな銅鐸がすっぽり入った «入れ子»。1か所から39個という、日本一の数だった。","lead":"1996年、農道工事の最中に弥生時代の銅鐸が次々に見つかりました。その数39個は、1か所からの出土として日本でいちばん多い数です。荒神谷遺跡から山を越えて3kmほどの近さで、2つの遺跡はセットで語られます。","story":["1996年10月、山あいの農道工事で、重機が斜面の土をけずっていると、金属の音がしました。出てきたのは緑色の銅鐸。しかも一つではありません。工事はすぐに止められ、調査が始まりました。","調べると、銅鐸は大きいもの（約45cm）と小さいもの（約30cm）があり、大きな銅鐸の中に小さな銅鐸を入れた «入れ子» の状態で埋められていました。ひれ（左右の飾りの板）を上下にして横にねかせる、きちんとした並べ方です。数えると39個。それまでの1か所最多、滋賀県の大岩山の24個を大きく上回りました。","銅鐸の表面には、シカやトンボ、ウミガメなどの絵、そして人の顔のような模様がえがかれたものもあります。«これは何の祭りの場面だろう?» 弥生の人びとが米づくりの豊かさを祈った姿が想像されます。さらに、何個かの銅鐸には荒神谷の銅剣と同じ «×» の印が刻まれていました。","もっと驚いたのは、ここの銅鐸のなかに、近畿地方などで見つかった銅鐸と «同じ鋳型（いがた）» でつくられた兄弟がいたことです。遠くはなれた土地の銅鐸と同じ型から生まれたということは、つくる場所や技術者、あるいは銅鐸そのものが、地域をこえて行き来していたことを示します。","『出雲国風土記』には、このあたりの «神原（かんばら）の郷» について «天の下をつくった大神の御財（みたから）を積み置いたところ» という地名の由来が書かれています。«神の宝を積んだ場所» ――39個の銅鐸は、まさにその言い伝えの正体だったのでしょうか。答えはわかりませんが、想像がふくらむ一文です。"],"tl":[["紀元前2〜1世紀ごろ","銅鐸がつくられたと考えられる（埋めた時期は諸説）"],["733年","『出雲国風土記』に神原郷の «御財を積み置いた所» の記述"],["1996年","農道工事中に銅鐸39個が出土"],["1999年","国の史跡に指定"],["2008年","出土した銅鐸が国宝に指定"]],"who":[["弥生時代の出雲の人びと","銅鐸を埋めた人たち"],["工事関係者と調査員","重機で掘り当てた銅鐸をていねいに取り上げた"]],"deep":["39個は1か所からの出土数として全国最多。それまでの最多は滋賀県野洲市の大岩山で、合計24個だった。","銅鐸は «入れ子» で埋められた例がほかにもあるが、これほどまとまった例は少ない。すきまを少なくする運搬・埋納の工夫とも、意味のある作法とも考えられる。","同じ鋳型でつくられた «同笵（どうはん）銅鐸» が近畿など各地で見つかっている。鋳型の傷の位置までそろうことで判定する。","«×» 印のある銅鐸は荒神谷の銅剣と共通し、二つの遺跡を同じ集団が管理した可能性を示すとされる。","近くの神原神社古墳からは «景初三年» 銘の三角縁神獣鏡が出ており、卑弥呼が魏に使いを送った年（239年）の年号として知られる。"],"look":["出土状況を再現した埋納坑（ガイダンス施設の奥）","加茂岩倉遺跡ガイダンスの展示","谷をかこむ山のかたち（荒神谷と地形を比べると面白い）","古代出雲歴史博物館の実物の銅鐸"],"q":["加茂岩倉遺跡の銅鐸は、どんな状態で埋められていた?","大きな銅鐸の中に小さな銅鐸を入れた «入れ子» の状態で、横にねかせて埋められていました。"],"koji":[],"myth":"風土記の «神の御財» と銅鐸を結びつけるのは推測。","img":["銅鐸","荒神谷遺跡","神原神社古墳"],"wp":"加茂岩倉遺跡","rel":{"ev":[],"grave":[]},"ph":[["j:3/37/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_%E9%8A%85%E9%90%B8%E7%BE%A4.JPG",5141,3379,"加茂岩倉遺跡"],["j:c/c9/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_%E9%8A%85%E9%90%B8%E5%9F%8B%E7%B4%8D%E7%8A%B6%E6%B3%81%E5%BE%A9%E5%85%83.JPG",5468,3350],["j:6/64/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_2%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",4750,3557],["j:0/09/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_8%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",4565,3426],["j:f/f9/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_16%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",4213,3157],["j:b/b0/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_23%E5%8F%B7%E9%8A%85%E9%90%B8-1.JPG",2704,3616],["j:b/bd/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_15%E5%8F%B7%E9%8A%85%E9%90%B8.JPG",2692,3586],["j:2/22/%E5%8A%A0%E8%8C%82%E5%B2%A9%E5%80%89%E9%81%BA%E8%B7%A1_23%E5%8F%B7%E9%8A%85%E9%90%B8-2.JPG",2686,3592]]},{"id":"32_nishidani","n":"西谷墳墓群（四隅突出型墳丘墓）","yomi":"にしだにふんぼぐん","cat":"遺跡","rank":"S","y":200,"era":["yayoi","kofun"],"sh":"国指定史跡","ad":"出雲市大津町","st":"JR出雲市駅から車で約10分（出雲弥生の森博物館に隣接）","la":35.3483,"lo":132.7779,"hook":"四つの角がヒトデのようにのびた不思議な形のお墓。ここには、古墳ができる前の «出雲の王» が眠っている。","lead":"弥生時代の終わりごろに、出雲の有力者たちが築いたお墓の集まりです。四角い墳丘の四隅が外へ飛び出した «四隅突出型墳丘墓（よすみとっしゅつがたふんきゅうぼ）» という、山陰などに多い独特の形をしています。いちばん大きな3号墓は、突出部をふくめると長さ約50mにもなります。","story":["出雲平野を見下ろす丘の上に、こんもりとした墓がいくつも並んでいます。上から見ると、四角形の角がにゅっと外へのびた形。まるで手足をひろげたヒトデか、星のようです。これが «四隅突出型墳丘墓» です。","«なぜ角をのばしたの?» はっきりした答えはありません。墓にのぼる通り道だったという説、祭りの場として見せるための形だという説などがあります。墳丘のすそには石をならべて飾り、遠くからでもよく目立ちました。","いちばん大きい3号墓を発掘すると、墓の上で大がかりな祭りをしたあとが見つかりました。たくさんの土器がこわされて置かれていたのです。その中には、岡山（吉備）でつくられた特殊器台という大きな土器や、北陸の土器にそっくりなものもありました。«王の葬式に、遠くの国から客が来たのでは?» と考えられています。","埋葬された場所からは、コバルトブルーのガラスの玉や、赤い朱がまかれたあとも見つかりました。ガラスは当時の日本ではとても貴重な品です。これだけの品と、遠くの国とのつながりをもっていた人物は、出雲の広い地域をまとめる «王» だったのだろう、と考えられています。","四隅突出型の墓は、出雲だけでなく伯耆・因幡、さらに北陸の富山あたりまで広がっています。日本海ぞいに、同じ «墓の形» を共有する人たちのネットワークがあったのかもしれません。古墳時代の前、日本がまだ一つにまとまる前の、地方の王たちの姿がここから見えてきます。"],"tl":[["2世紀ごろ","このころから四隅突出型墳丘墓が築かれ始める"],["2世紀後半〜3世紀前半ごろ","3号墓など大型の墓が築かれる（年代は研究者により幅がある）"],["1953年","このあたりで墳丘墓の存在が知られはじめる"],["1983年〜","3号墓などの発掘調査が進む"],["2000年","国の史跡に指定"],["2010年","出雲弥生の森博物館が開館"]],"who":[["出雲の «王»（名は不明）","3号墓などに葬られた、弥生の地域の首長"],["吉備・北陸の人びと","葬送の祭りに土器をもって参加した可能性がある"]],"deep":["四隅突出型墳丘墓は中国山地の三次（広島県）あたりで早く現れ、出雲で大型化したとする説がある。分布は山陰から北陸（富山）まで。","3号墓は突出部をのぞく墳丘がおよそ40m×30m、突出部をふくめると約50mといわれ、弥生の墳丘墓として最大級。","墓上から出た吉備系の特殊器台・特殊壺は、のちの前方後円墳に置かれる埴輪のルーツとされる土器。出雲と吉備の交流を示す。","埋葬施設は大きな木の棺を入れた木槨（もっかく）構造をもつものがあるとされ、ていねいな造りだった。","6号墓などは墳丘が復元・整備され、実際にのぼって四隅の形を体感できる。"],"look":["復元された墳丘墓の上から見る出雲平野","四隅の突出部と貼石（はりいし）","出雲弥生の森博物館の3号墓の模型と出土品","丘のまわりの遊歩道"],"q":["西谷墳墓群の墓の形を何という?","«四隅突出型墳丘墓»。四角い墓の四隅が外に飛び出した形です。"],"koji":[],"myth":"«出雲の王» は研究上の呼び名。突出部の意味は諸説。","img":["四隅突出型墳丘墓","出雲市","弥生時代"],"wp":"西谷墳墓群","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Nishidani_Graves-2%2C_funkyu.jpg",5568,3712,"西谷墳墓群"],["c:6/60/Nishidani_Graves-3%2C_funkyu.jpg",5568,3712],["c:3/33/Nishidani_Graves_08.jpg",1432,1288],["c:1/1c/Haiden_of_Izumo-taisha-1.JPG",5077,3377,"出雲市"]]},{"id":"32_gassan_toda","n":"月山富田城（尼子氏の本拠）","yomi":"がっさんとだじょう","cat":"城","rank":"S","y":1566,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"安来市広瀬町富田","st":"JR安来駅からバスで約25分「市立病院前」下車、登山口から本丸まで歩いて30〜40分","la":35.3545,"lo":133.1918,"hook":"«願わくば、我に七難八苦を与えたまえ»――三日月にそう祈った若武者がいた。守ろうとしたのは、この山の城と尼子の家だった。","lead":"戦国時代に山陰の大名・尼子（あまご）氏が本拠にした山城です。山全体が城で、いくつもの段に曲輪（くるわ）が重なり、«難攻不落» といわれました。毛利元就との長い戦いの末に落城し、今は石垣と曲輪の跡が残る «城跡» です。","story":["室町時代、出雲の守護代だった尼子経久は、一度は城を追われましたが、1486年の元日に芸人たちにまぎれて城に入り、取りもどしたと伝わります。そこから尼子氏はぐんぐん力をのばし、孫の晴久の時代には中国地方の11か国に勢いをふるった、といわれます。","1543年、周防の大内義隆が大軍で攻めてきました。けれど月山富田城はびくともせず、大内軍は大きな被害を出して退きます。細い尾根をいくつも登らないと本丸にたどり着けないこの城は、まさに «天然の要塞» でした。","ところが次に攻めてきた毛利元就はちがいました。力でせめるより、城を囲んで食料の道を断つ作戦をとったのです。何年も続いた包囲の末、1566年、晴久の子・尼子義久はついに城を出て降伏しました。","このとき、尼子の家を立て直そうと立ち上がったのが家臣の山中鹿介（幸盛）です。«我に七難八苦を与えたまえ» と三日月に祈ったという話は、のちの時代の軍記物で有名になりました。鹿介は尼子勝久を立てて何度も戦いましたが、1578年、播磨の上月城で敗れ、尼子再興の夢はついえました。","江戸時代のはじめ、堀尾吉晴がこの城に入りましたが、1611年に松江城へ移り、月山富田城は役目を終えました。今、山を登ると、七曲りの道、山中御殿の広い平地、本丸の石垣が次々に現れます。頂上からは、尼子の人たちが見たのと同じ飯梨川の流れと、安来の平野が見わたせます。"],"tl":[["1486年","尼子経久が城を奪回したと伝わる"],["1543年","大内義隆の攻撃をしりぞける（第一次月山富田城の戦い）"],["1566年","毛利元就の包囲により尼子義久が降伏"],["1578年","山中鹿介らが上月城で敗れ、尼子再興ならず"],["1600年","堀尾吉晴が入城"],["1611年","松江城完成にともない廃城に"],["1934年","国の史跡に指定"]],"who":[["尼子経久","城を取りもどし、尼子氏を大きくした «謀将»"],["尼子晴久","経久の孫。尼子氏の最盛期を築いた"],["毛利元就","包囲戦で城を落とした安芸の大名"],["山中鹿介（幸盛）","尼子再興に生涯をかけた家臣。三日月の祈りで有名"],["堀尾吉晴","江戸初めに入城し、のち松江城を築いた"]],"deep":["経久の元日奪回の話（鉢屋衆という芸能集団にまぎれた）は軍記物にもとづく伝承で、史実かどうかは慎重に見る必要がある。","晴久は1552年に室町幕府から出雲・隠岐・因幡・伯耆・美作・備前・備中・備後の8か国の守護に任じられた。«11か国» は勢力範囲をいう言い方。","城は月山の山頂部の本丸・二ノ丸・三ノ丸と、中腹の山中御殿、ふもとの居館部分からなる大規模な山城。","山中御殿から本丸へ向かう «七曲り» は、何度も折れ曲がる登城道で、守りのための工夫。","山中鹿介の «七難八苦» の祈りは江戸時代に教科書的な美談となり、戦前の国語教材にものった。"],"look":["山中御殿の広い平坦地と石垣","七曲りの登城道","本丸跡からの眺め","山中鹿介の銅像（ふもと）","安来市立歴史資料館の城の模型"],"q":["«願わくば、我に七難八苦を与えたまえ» と祈ったといわれる武将は?","尼子の家臣・山中鹿介（幸盛）。三日月に祈ったと伝わります。"],"koji":[{"w":"願わくば我に七難八苦を与えたまえ","m":"どんな苦しみでも受けて立つから、目的をかなえさせてほしい、という強い決意のことば"}],"myth":"経久の奪回の方法、鹿介の祈りの場面は軍記物などによる伝承。","img":["尼子経久","山中幸盛","尼子晴久"],"wp":"月山富田城","rel":{"ev":[],"grave":[]},"ph":[["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"],["c:a/ae/%E6%9C%88%E5%B1%B1%E5%AF%8C%E7%94%B0%E5%9F%8E%E9%81%A0%E6%99%AF%EF%BC%882016%EF%BC%89.JPG",5184,3456],["c:9/9d/%E6%96%B0%E5%AE%AE%E5%85%9A%E9%A4%A8%E8%B7%A1.JPG",5184,3456],["c:3/34/%E5%A0%80%E5%B0%BE%E5%90%89%E6%99%B4%E5%A2%93%E6%89%80.JPG",5184,3456],["c:7/72/Gassan_Toda_Castle_05.JPG",3008,2000],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/34/Amago_Tsunehisa.JPG",1278,1899,"尼子経久"],["c:d/dc/Taiheikieiyuden_36_YamanakaYukimori.jpg",2162,2870,"山中幸盛"]]},{"id":"32_oki_kokubunji","n":"隠岐国分寺（後醍醐天皇の行在所）","yomi":"おきこくぶんじ","cat":"寺社","rank":"S","y":1332,"era":["nara","kamakura"],"sh":"国指定史跡（隠岐国分寺境内）","ad":"隠岐郡隠岐の島町池田","st":"西郷港から車で約15分","la":36.2275,"lo":133.3006,"hook":"鎌倉幕府をたおそうとして敗れた天皇が、流されたのは日本海の島だった。けれど1年ほどで、天皇は小舟で海へこぎ出した。","lead":"奈良時代、全国に置かれた国分寺のひとつです。1332年、鎌倉幕府に対する計画が失敗した後醍醐天皇が隠岐に流され、ここを行在所（あんざいしょ・天皇の仮の住まい）にしたと伝えられています。翌年、天皇は島をぬけ出し、幕府はまもなくほろびました。","story":["1331年、後醍醐天皇は鎌倉幕府をたおそうと兵をあげました（元弘の変）。けれど計画は失敗。天皇はとらえられ、翌1332年、隠岐へ流されることになりました。天皇が島に流されるのは、承久の乱の後鳥羽上皇以来のことです。","天皇に付きしたがったのは、阿野廉子など、ほんのわずかの人たち。島では守護の佐々木清高が見張っていました。«このまま島で一生を終えるのか»――しかし、天皇はあきらめませんでした。本土では楠木正成や、息子の護良親王が幕府と戦い続けていたのです。","1333年の春、天皇は島をぬけ出します。『太平記』などによると、漁船にかくれて海をわたり、伯耆（鳥取県）の名和長年にむかえられて船上山にたてこもりました。«天皇が島を出た!» という知らせは、各地の武士をふるい立たせます。","まもなく足利高氏（尊氏）が京の六波羅探題をせめ落とし、新田義貞が鎌倉をせめて、1333年、鎌倉幕府は滅亡しました。島からの脱出が、時代を動かす引き金になったのです。","国分寺の境内には «後醍醐天皇御在所跡» の碑が立っています。ただし行在所がどこだったかには、この国分寺説と、西ノ島の黒木御所説があり、昔から議論があります。本堂は2007年に火災で失われましたが、その後再建されました。春の «蓮華会舞（れんげえまい）» は、古い舞をいまに伝える国の重要無形民俗文化財です。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["奈良時代","隠岐国分寺が建てられる"],["1331年","元弘の変"],["1332年","後醍醐天皇が隠岐に流される"],["1333年","天皇が隠岐を脱出。同年、鎌倉幕府滅亡"],["2007年","本堂が火災で焼失（のちに再建）"]],"who":[["後醍醐天皇","隠岐に流され、脱出して建武の新政を始めた天皇"],["阿野廉子","天皇に従って隠岐に来た女性。のち後村上天皇の母"],["佐々木清高","隠岐守護。天皇の見張り役だった"],["名和長年","伯耆で脱出した天皇をむかえた武士"]],"deep":["行在所の場所は、隠岐の島町の国分寺説と、西ノ島町の黒木御所（別府）説がある。『増鏡』『太平記』の記述の読み方で意見が分かれる。","国分寺の奈良時代の建物は残っていないが、境内一帯が «隠岐国分寺境内» として国の史跡に指定されている。","蓮華会舞は、平安時代ごろに伝わったとされる舞楽系の芸能で、面をつけた舞が演じられる。国の重要無形民俗文化財。","後醍醐天皇の脱出を助けた人物については、『太平記』のほか地元の伝承も多く、人名や道すじには諸説がある。","隠岐は古代から «遠流（おんる）» の地とされ、小野篁（おののたかむら）も流されている。"],"look":["«後醍醐天皇御在所跡» の碑","再建された本堂と境内の石造物","春の蓮華会舞（行事の日のみ）","周辺の国分尼寺跡"],"q":["後醍醐天皇が隠岐を脱出したあと、むかえた伯耆の武士はだれ?","名和長年。船上山で天皇を守りました。"],"koji":[],"myth":"行在所の場所は国分寺説と黒木御所説がある。脱出の方法の細部は『太平記』などによる。","img":["後醍醐天皇","元弘の乱","名和長年"],"wp":"隠岐国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/e2/Oki_Kokubunji_hondou.JPG",6016,4000,"隠岐国分寺"],["c:c/cf/Oki_Kokubunji_yashiro.JPG",6004,3984],["c:4/4b/Oki_Kokubunji_sanmon.JPG",6016,4000],["c:4/42/Oki_Kokubunji_hondou-ato-2.JPG",6016,4000],["c:7/7c/Oki_Kokubunji_anzaisho-ato.JPG",6006,3986],["c:c/cd/Oki_Kokubun-niji-ato_gaikan.JPG",6016,4000],["c:3/3f/Emperor_Shomu.jpg",1876,3132],["c:0/0b/Emperor_Godaigo_by_Monkan-b%C5%8D_K%C5%8Dshin.jpg",1863,1860]]},{"id":"32_oki_jinja","n":"隠岐神社と後鳥羽上皇火葬塚","yomi":"おきじんじゃ・ごとばじょうこうかそうづか","cat":"墓所","rank":"S","y":1239,"era":["kamakura","showa"],"sh":"","ad":"隠岐郡海士町海士","st":"菱浦港から車で約10分","la":36.0873,"lo":133.1003,"hook":"«われこそは新島守よ»――都の王者だった上皇は、流された島で波に向かってそう歌った。そして19年、ついに都へ帰ることはなかった。","lead":"承久の乱（1221年）に敗れた後鳥羽上皇は、隠岐の中ノ島（海士町）に流され、約19年をこの島で過ごして亡くなりました。上皇が火葬された場所が «火葬塚» として残り、そのそばに、上皇をまつる隠岐神社が昭和になって建てられました。","story":["後鳥羽上皇は、和歌にも武芸にも秀でた、とても力のある上皇でした。けれど、鎌倉幕府の力はどんどん強くなっていきます。1221年、上皇は «北条義時を討て» と命令を出しました。これが承久の乱です。","ところが幕府の軍は大軍で京へ攻め上り、上皇の軍はあっという間に敗れます。北条政子が御家人たちを前に «頼朝公のご恩は山よりも高く、海よりも深い» と語って心をひとつにした、という話は『吾妻鏡』に書かれています。乱のあと、後鳥羽上皇は隠岐へ流されました。","島に着いた上皇が住んだのは、源福寺というお寺の近くの行在所だったといわれます。上皇はここで歌を詠み続け、『遠島百首（えんとうひゃくしゅ）』をまとめました。いちばん有名なのが «我こそは 新島守よ 隠岐の海の 荒き波風 心して吹け»。«わたしこそが新しい島の守り人だ。荒い波も風も、気をつけて吹け» ――負けても王者の気迫を失わない歌です。","上皇は何度も都に帰ることを願いましたが、許されませんでした。そして1239年、島で亡くなります。約19年の月日でした。亡きがらはこの地で火葬され、その場所が今の火葬塚です。遺骨の一部は京へ運ばれ、大原に葬られたと伝わります。","それから700年がたった1939年、上皇をまつる隠岐神社がここに建てられました。島の人たちは今も上皇をしのび、神社の例祭などで上皇をしのびます。刀を好んだ上皇が、鍛冶を集めて刀をつくらせた «御番鍛冶» の話も伝わっています。"],"tl":[["1221年","承久の乱。後鳥羽上皇が隠岐へ流される"],["隠岐時代","『遠島百首』などの歌を詠む"],["1239年","隠岐で崩御。火葬される"],["1939年","崩御700年を記念して隠岐神社が創建される"]],"who":[["後鳥羽上皇","承久の乱に敗れて隠岐に流された上皇。歌人としても名高い"],["北条義時","承久の乱のときの鎌倉幕府の執権"],["北条政子","御家人たちをまとめて幕府を勝利に導いた"],["藤原定家","後鳥羽上皇の命で『新古今和歌集』の撰者となった歌人"]],"deep":["火葬塚は宮内庁が «後鳥羽天皇火葬塚» として管理しており、柵の中には入れない。","『新古今和歌集』は後鳥羽上皇の命でつくられたが、上皇は隠岐でもその改訂を続け、«隠岐本新古今和歌集» と呼ばれる本を残した。","菊の花を好み、刀や道具に菊の紋を用いたことが、皇室の菊の紋のはじまりの一つといわれるが、諸説ある。","«御番鍛冶» は、上皇が月ごとに刀工を交代で呼んで刀を打たせたというもので、隠岐でも刀をつくったと伝わる。","承久の乱のあと、後鳥羽上皇は隠岐、順徳上皇は佐渡、土御門上皇は土佐（のち阿波）へと、三人の上皇が都を離れた。"],"look":["後鳥羽天皇火葬塚（宮内庁管理・柵の外から拝む）","隠岐神社の社殿と参道","行在所跡とされる源福寺跡","海士町後鳥羽院資料館"],"q":["後鳥羽上皇が隠岐で詠んだ «我こそは新島守よ» の歌で、上皇は何に呼びかけている?","隠岐の海の «荒き波風»。«気をつけて吹け» と命じています。"],"koji":[{"w":"我こそは新島守よ隠岐の海の荒き波風心して吹け","m":"流されても王者の誇りを失わない後鳥羽上皇の気迫を表す歌"}],"myth":"行在所の正確な位置、菊紋の由来、御番鍛冶の細部は伝承をふくむ。","img":["後鳥羽天皇","承久の乱","隠岐諸島"],"wp":"隠岐神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/d4/Oki_shrine.jpg",960,720,"隠岐神社"],["c:9/91/Ama_town_Oki_Shrine_ac_%283%29.jpg",5861,3898],["c:c/cd/Emperor_Go-Toba.jpg",2268,2301,"後鳥羽天皇"],["c:5/5c/Setagawa%EF%BC%88Yodogawa%EF%BC%89_Karahashi.jpg",800,600,"承久の乱"],["c:5/51/20090923%E9%9A%A0%E5%B2%90%E8%AB%B8%E5%B3%B6.jpg",1202,960,"隠岐諸島"]]},{"id":"32_kumano_taisha","n":"熊野大社（出雲国一之宮）","yomi":"くまのたいしゃ","cat":"寺社","rank":"S","y":733,"era":["myth","nara"],"sh":"","ad":"松江市八雲町熊野","st":"JR松江駅からバスで約30〜40分（八雲で乗りかえ）「熊野大社前」","la":35.3717,"lo":133.0806,"hook":"出雲大社の使いが持ってきた餅に、熊野の神職が文句をつける――千年以上つづくといわれる、ふしぎな «火のお祭り» がある。","lead":"出雲国の一宮で、『出雲国風土記』には杵築大社（出雲大社）と並んで «大社» と書かれた、出雲で最も格の高い神社のひとつです。火をおこす道具をまつる «火の発祥の神社» とも呼ばれ、出雲大社との深いつながりがあります。","story":["松江の町から山あいへ入り、意宇川（いうがわ）をさかのぼると、静かな森の中に熊野大社があります。まつられているのは «熊野大神 櫛御気野命（くしみけぬのみこと）»。この神は素戔嗚尊（すさのおのみこと）と同じ神とされています。","古代の出雲国造（いずものくにのみやつこ）は、もとはこの意宇（おう）の地にいて、熊野の神をまつっていたと考えられています。733年にできた『出雲国風土記』には、出雲の神社がたくさん出てきますが、«大社» と書かれているのは熊野と杵築の二つだけでした。","毎年10月15日には «鑽火祭（きりびさい）» があります。出雲大社の宮司がやってきて、火をおこす道具の «燧臼（ひきりうす）» と «燧杵（ひきりきね）» を受け取る神事です。このとき出雲大社側は長い餅をおそなえしますが、熊野大社の «亀太夫（かめだゆう）» という役が «去年より小さい»«色が悪い» と、わざと文句をつけるのです。«亀太夫神事» と呼ばれる、ちょっとユーモラスな場面です。","«なぜ文句を言うの?» 熊野が出雲国造の古い本拠の神社で、兄のような立場だったことを示している、とも説明されます。出雲大社の宮司（出雲国造）が代がわりするときの «火継式（ひつぎしき）» でも、熊野の神の火が大切にされます。","境内には «鑽火殿（さんかでん）» という素朴な建物があり、火をおこす道具が納められています。熊野大社が «日本火出初之社（ひのもとひでぞめのやしろ）» と呼ばれるのは、この火の信仰のためです。"],"tl":[["733年","『出雲国風土記』に «熊野大社» と記される"],["927年","『延喜式』神名帳に名神大社として «熊野坐神社» が載る"],["中世","出雲国一宮とされる"],["毎年10月15日","鑽火祭・亀太夫神事が行われる"]],"who":[["櫛御気野命（素戔嗚尊）","まつられている神"],["出雲国造","熊野大神をまつった古代の豪族。今の出雲大社宮司家"],["亀太夫","鑽火祭で出雲大社の餅に文句をつける熊野側の役"]],"deep":["『延喜式』では «熊野坐神社（くまのにいますじんじゃ）» として載る。紀伊の熊野とは別の神社で、どちらが先かなど諸説があるが、関係ははっきりしない。","熊野大社の元宮は、南の天狗山（熊野山）にあったとされ、山頂近くに磐座（いわくら）が残る。","鑽火祭で授けられる燧臼・燧杵は、出雲大社の新嘗祭などで使う神聖な火をおこすための道具。","出雲国一宮は時代によって熊野大社とされたり出雲大社とされたりしたと説明される。今は両社とも一宮を名のる。","風土記の意宇郡は国府・国分寺も置かれた出雲の政治の中心で、熊野大社はその奥座敷にあたる。"],"look":["鑽火殿（火おこしの道具を納める建物）","意宇川にかかる八雲橋と随神門","本殿・稲田神社・伊邪那美神社","10月15日の鑽火祭（行事の日）"],"q":["鑽火祭で、熊野大社の亀太夫は出雲大社の何に文句をつける?","出雲大社がおそなえする «餅»。大きさや色にわざと難くせをつけます。"],"koji":[],"myth":"熊野大社と紀伊熊野の関係、祭神の同一視は諸説。","img":["出雲国造","出雲国風土記","素戔嗚尊"],"wp":"熊野大社","rel":{"ev":[],"grave":[]},"ph":[["c:9/9e/Kumano_taisha.jpg",3872,2592,"熊野大社"],["c:b/b3/%E7%86%8A%E9%87%8E%E5%A4%A7%E7%A4%BE%E9%9A%8F%E7%A5%9E%E9%96%80.JPG",5184,3456],["c:f/f5/%E7%86%8A%E9%87%8E%E5%A4%A7%E7%A4%BE%E9%91%BD%E7%81%AB%E6%AE%BF.JPG",5184,3456],["c:e/ef/%E7%86%8A%E9%87%8E%E5%A4%A7%E7%A4%BE%E8%88%9E%E6%AE%BF.JPG",5184,3456],["c:f/f5/%E7%86%8A%E9%87%8E%E5%A4%A7%E7%A4%BE%E6%8B%9D%E6%AE%BF.JPG",5184,3456],["c:5/5a/%E4%BC%8A%E9%82%AA%E9%82%A3%E7%BE%8E%E7%A5%9E%E7%A4%BE.JPG",5184,3456],["c:5/59/Mon-_Izumo_taisha.png",4000,4000,"出雲国造"],["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"素戔嗚尊"]]},{"id":"32_kamosu","n":"神魂神社（最古の大社造本殿）","yomi":"かもすじんじゃ","cat":"寺社","rank":"S","y":1583,"era":["azuchi"],"sh":"国宝（本殿）","ad":"松江市大庭町","st":"JR松江駅からバスで約20分「風土記の丘入口」下車、歩いて約10分","la":35.4264,"lo":133.0781,"hook":"出雲大社より古い «大社造» の本殿が、松江の小さな森にひっそり建っている。それなのに、古代の記録にはこの神社の名前が見あたらない。","lead":"いま残る大社造（たいしゃづくり）の本殿の中でいちばん古いとされる、1583年に建てられた国宝の本殿をもつ神社です。出雲国造（今の出雲大社宮司家の祖先）とゆかりが深く、古代出雲の中心だった意宇（おう）の地にあります。","story":["石段を登ると、木々のあいだから、高い床と大きな屋根をもつ本殿が見えてきます。これが国宝の神魂神社本殿。戦国時代の終わり、1583年に建てられたものです。出雲大社の本殿（1744年）よりも160年ほど古く、«大社造» の形を今に伝える一番古い建物とされます。","大社造は、正方形に近い平面の真ん中に太い柱（心御柱）が立ち、入口が正面の片側によっている形です。神魂神社の本殿は出雲大社よりも小さいのですが、床がとても高く、柱が太く、どっしりとした力強さがあります。«古い時代の大社造は、こんな感じだったのか» と想像させてくれます。","まつられているのは伊弉冉尊（いざなみのみこと）と伊弉諾尊（いざなぎのみこと）。そして、出雲国造の家とのつながりが深い神社です。出雲国造は、もとは意宇にいて、のちに杵築（出雲大社）へ移ったと考えられています。移ったあとも、国造が代がわりするときには、この神社で儀式をおこなったと伝わります。","ところが «なぜ?» と首をかしげることがあります。733年の『出雲国風土記』にも、平安時代の『延喜式』の神社の一覧にも、神魂神社の名前が見あたらないのです。«もともと国造の家の中の神社で、公の一覧にのらなかったのでは» など、いくつかの説がありますが、はっきりしません。","境内には、苔むした石段や、小さな摂社・末社が並びます。人も少なく、しんとした空気の中で本殿を見上げると、古代出雲の神まつりの世界に迷いこんだような気持ちになります。近くには八重垣神社や、風土記の丘の古墳群もあり、歩いてめぐることができます。"],"tl":[["古代","出雲国造が意宇の地で神をまつる"],["1583年","現在の本殿が建てられる"],["1952年","本殿が国宝に指定される"]],"who":[["伊弉冉尊","まつられている主な神"],["出雲国造","この神社と深いゆかりをもつ、出雲大社宮司家の祖先"]],"deep":["本殿は大社造としては床がとくに高く、正面の階段には屋根がかかる。","本殿内部には、色あざやかに描かれた壁画や天井の雲の絵があるとされるが、非公開。","社名の «かもす» は «神坐す（かみいます）» がなまったものとする説がある。","風土記・延喜式に社名が見えないことから、出雲国造の «斎場» 的な性格をもつ神社だったとする説がある。","出雲大社の本殿と比べると、柱の太さに対して建物がひきしまって見えるのが特ちょう。建築史の教科書に必ず登場する。","近くの八重垣神社は、素戔嗚尊と稲田姫の縁結びの神話で知られる。神魂神社・八重垣神社・六所神社などをめぐる «風土記の丘» 周辺の散策コースは、古代出雲の中心地を歩く道でもある。"],"look":["国宝の本殿（外から拝観）","苔むした石段と参道","摂社・貴布祢稲荷両神社","近くの八雲立つ風土記の丘","境内から見下ろす意宇平野（古代出雲の中心地）"],"q":["神魂神社の本殿は、何という建築様式でいちばん古いもの?","«大社造»。1583年に建てられ、出雲大社本殿よりも古いのです。"],"koji":[],"myth":"社名の由来や、風土記・延喜式に載らない理由は諸説。","img":["大社造","出雲国造","八重垣神社"],"wp":"神魂神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/cc/Kamosu-jinja_Main_Sanctuary_001.jpg",3264,2448,"神魂神社"],["c:b/bd/Kamosu_jinja_keidaisha2.jpg",3872,2592],["c:3/33/Kamosu-jinja_Torii_001.jpg",3264,2448],["c:6/62/Kamosu-jinja_Auxiliary_Tositoku-jinja_001.jpg",3264,2448],["c:5/58/Kamosu-jinja_Auxiliary_Kizuki-jinja_001.jpg",3264,2448],["c:c/c8/Kamosu-jinja_Auxiliary_Kifune-Inari-Ryo-jinja_001.jpg",3264,2448],["c:b/b5/Kamosu-jinja_Auxiliary_Ise-jinja_001.jpg",3219,2414],["c:b/b3/Kamosu-jinja_Main_Sanctuary_and_Worship_Hall_001.jpg",3160,2370]]},{"id":"32_izumo_kokufu","n":"出雲国府跡（意宇平野の古代の役所）","yomi":"いずもこくふあと","cat":"遺跡","rank":"S","y":733,"era":["nara","heian"],"sh":"国指定史跡","ad":"松江市大草町","st":"JR松江駅から車で約15分","la":35.4295,"lo":133.0975,"hook":"『出雲国風土記』をまとめた役人たちは、ここで筆を走らせていたのかもしれない。田んぼの下から、奈良時代の «県庁» が出てきた。","lead":"奈良時代から平安時代にかけて、出雲国をおさめた役所 «国府（こくふ）» の跡です。発掘で大きな建物の柱の穴や、役人が使った木簡・土器などが見つかりました。今は広々とした公園になっていて、建物のあった場所が示されています。","story":["奈良時代、日本は «国» という単位に分けられ、それぞれの国に都から国司という役人が送られてきました。その国司が仕事をした役所が国府で、中心にある建物を国庁（こくちょう）といいます。いまでいえば県庁です。","出雲国の国府は、意宇平野と呼ばれるこの地にありました。733年にまとめられた『出雲国風土記』には、«国庁» と «意宇郡家（ぐうけ）» が同じ場所にあったこと、そこから各地へ道がのびていたことが書かれています。風土記に書かれた位置を手がかりに、研究者たちは国府の場所をさがしました。","1968年から発掘が始まると、田んぼの下から大きな柱の穴が次々に見つかりました。役人たちが文字を書いた木簡や、役所の名前などが墨で書かれた土器、すずりも出てきました。«やっぱりここだ!» 風土記の記述と、土の中の証拠がぴたりと重なった瞬間でした。","国府のまわりには、出雲国分寺や国分尼寺、そして出雲国造がまつった神魂神社や熊野大社もあります。この一帯は、古代出雲の «政治と祈りの中心» だったのです。役人たちは、都から届く命令を読み、税を集め、国の地図や記録をつくりました。","国府跡の一角には «六所神社» があります。国司が国内のおもな神社をまとめてまつった «総社» だと考えられています。今の公園では、柱の位置が示され、奈良時代の役人が見たのと同じ山なみをながめることができます。"],"tl":[["7世紀後半〜8世紀","出雲国府が置かれる"],["733年","『出雲国風土記』が完成し、国庁の位置が記される"],["平安時代","国府が続いて使われる"],["1968〜1970年","本格的な発掘調査"],["1971年","国の史跡に指定"],["1999年〜","再び発掘調査が行われ、整備が進む"]],"who":[["国司","都から送られた役人。国府で出雲国をおさめた"],["出雲臣広嶋","出雲国造。『出雲国風土記』の責任者として名が記される"]],"deep":["『出雲国風土記』は、ほぼ完全な形で残る唯一の風土記。巻末に国庁・郡家・駅・道の位置関係が詳しく書かれ、国府の場所さがしの手がかりになった。","国庁と意宇郡家が同じ場所にあったと風土記にあり、国と郡の役所が近接していた珍しい例として注目される。","出土した木簡や墨書土器から、役所で文書を扱い、物を管理していた様子がうかがえる。","国府の北側を東西に古代の山陰道が通っていたと考えられ、近くに «十字街» と呼ばれる交差点があったと風土記に書かれている。","近くの出雲国分寺跡も国の史跡。国府と国分寺がセットでわかる地域は全国でも貴重。","国府の役人は、都からの命令を伝え、税として集めた米や布、鉄などを都へ送った。出雲は鉄の産地でもあり、そうした品々もこの役所を通って運ばれたと考えられる。"],"look":["史跡公園に示された建物の柱の位置","六所神社","近くの出雲国分寺跡","八雲立つ風土記の丘展示学習館の出土品","国府跡の近くにそびえる茶臼山（風土記の «神名樋野» とされる山）"],"q":["古代の国府の中心の建物を何という?","«国庁»。いまでいう県庁の中心の建物です。"],"koji":[],"myth":"","img":["出雲国風土記","出雲国","国府"],"wp":"出雲国府跡","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/Izumo_Kokufu%2C_gaikan.jpg",5562,3702,"出雲国府跡"],["c:7/7e/Izumo_Kokufu%2C_koden.jpg",5556,3692],["c:e/ea/Izumo_Kokufu%2C_kanga.jpg",5562,3702],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:4/49/Musashikokufuato.jpg",1600,1200,"国府"]]},{"id":"32_okadayama","n":"岡田山1号墳（額田部臣の銘の大刀）","yomi":"おかだやまいちごうふん","cat":"遺跡","rank":"S","y":575,"era":["kofun"],"sh":"国指定史跡（岡田山古墳）・出土品は国の重要文化財","ad":"松江市大草町（八雲立つ風土記の丘）","st":"JR松江駅からバスで約20分「風土記の丘入口」下車、歩いて約5分","la":35.4272,"lo":133.0839,"hook":"さびた大刀をX線で写したら、金属の中から文字が浮かびあがった。そこには、古代の豪族の名前が刻まれていた。","lead":"古墳時代の後期、6世紀後半に築かれた前方後方墳です。1915年に掘られたときに出た大刀を、何十年もたってX線で調べたところ «額田部臣（ぬかたべのおみ）» という文字が見つかりました。文字のある古代の刀は全国でもわずかで、とても貴重な発見です。","story":["岡田山1号墳は、長さ約24mの前方後方墳です。前が四角、後ろも四角という形は、出雲に多い古墳の形のひとつ。中には横穴式石室があり、1915年（大正4年）に地元の人たちによって掘られ、大刀や鏡、馬具などが取り出されていました。","それから70年ちかくたった1980年代、さびだらけの大刀の一本をX線で調べてみました。すると、刀の身の根元あたりに、銀の線を埋めこんで書いた «象嵌（ぞうがん）» の文字が写ったのです。«各田卩臣（ぬかたべのおみ）» ――つまり «額田部臣» と読める文字でした。","«額田部» とは、大王（天皇）家に仕えた人びとの集団の名前です。推古天皇の若いころの名が «額田部皇女» だったことから、その皇女にかかわる人々をまとめた部だったと考える説があります。«臣（おみ）» は、その部を管理した地方豪族の地位を表します。","«出雲の豪族が、大和の大王家のしくみに組みこまれていた»。文字のない時代には見えなかった関係が、この一本の刀から浮かびあがりました。しかも『出雲国風土記』には、大原郡の郡の役人として «額田部臣» の名前が出てきます。古墳の主の子孫が、奈良時代に役人になっていたのかもしれません。","埼玉県の稲荷山古墳の鉄剣、熊本県の江田船山古墳の大刀とともに、古墳時代の «文字のある刀» として教科書でも語られます。古墳は風土記の丘の中にあり、石室の入口をのぞくことができます。出土品は近くの展示学習館で見ることができます。"],"tl":[["6世紀後半ごろ","岡田山1号墳が築かれる"],["733年","『出雲国風土記』に額田部臣の名が見える"],["1915年","古墳が掘られ、大刀などが見つかる"],["昭和","古墳が国の史跡に指定される"],["1980年代","X線調査で大刀の銘文が確認される"]],"who":[["額田部臣","大刀に名が刻まれた、この地域の豪族"],["推古天皇（額田部皇女）","«額田部» の名とかかわるとされる女帝"]],"deep":["銘文は十数文字あったと考えられるが、さびのため読めるのは一部。確実に読めるのが «各田卩臣» で、«額田部臣» の古い書き方とされる。","«卩» は «部» の略字として古代に使われた。«各田» を «ぬかた» と読むのも古代の表記の特ちょう。","大刀は柄頭（つかがしら）が丸い «円頭大刀»。象嵌は銀とされる。","6世紀の銘文で «部» と «臣» がそろって出てくることから、部民制と氏姓制度が地方まで広がっていた証拠として重視される。","出土品（大刀・鏡・馬具など）は一括して国の重要文化財。八雲立つ風土記の丘展示学習館で展示されている。"],"look":["前方後方墳の墳丘の形（整備されている）","横穴式石室の入口","展示学習館の銘文大刀（複製・実物展示は時期により異なる）","近くの岡田山2号墳（円墳）"],"q":["岡田山1号墳の大刀に刻まれていた豪族の名前は?","«額田部臣（ぬかたべのおみ）»。X線調査でわかりました。"],"koji":[],"myth":"額田部と推古天皇の結びつきは有力な説だが確定ではない。","img":["部民制","推古天皇","象嵌"],"wp":"岡田山1号墳","rel":{"ev":[],"grave":[]},"ph":[["c:b/bc/Okadayama_Kofun_Group%2C_gaikan.jpg",5568,3712,"岡田山1号墳"],["c:6/68/Okadayama_Kofun_Group-2%2C_funkyu.jpg",5568,3712],["c:c/c9/Okadayama_Kofun_Group-1%2C_shisetsu.jpg",5568,3712],["c:7/75/Okadayama_Kofun_Group-1%2C_sendou-2.jpg",5568,3712],["c:3/3d/Okadayama_Kofun_Group-1%2C_sendou-1.jpg",5568,3712],["c:0/0c/Okadayama_Kofun_Group-1%2C_sekkan.jpg",5568,3712],["c:a/ae/Okadayama_Kofun_Group-1%2C_genshitsu-2.jpg",5568,3712],["c:e/e0/Okadayama_Kofun_Group-1%2C_genshitsu-1.jpg",5568,3712]]},{"id":"32_sugaya_tatara","n":"菅谷たたら山内（たたら製鉄の村）","yomi":"すがやたたらさんない","cat":"産業","rank":"S","y":1751,"era":["edo","meiji","taisho"],"sh":"国の重要有形民俗文化財（菅谷鑪）","ad":"雲南市吉田町吉田","st":"JR木次線 木次駅などから車で約30分（車が便利）","la":35.218,"lo":132.8665,"hook":"三日三晩、炎をたやさず、砂鉄と炭を入れ続ける。現場を仕切る親方 «村下（むらげ）» は、炎の色だけで炉の中を見ぬいたという。","lead":"日本古来の製鉄法 «たたら製鉄» の作業場 «高殿（たかどの）» が、日本でただ一つ当時のまま残る場所です。まわりには職人たちの住まいや事務所が並び、この集落全体を «山内（さんない）» と呼びました。1751年から1921年まで、およそ170年も鉄をつくり続けました。","story":["中国山地の奥深く、吉田の町からさらに山へ入ると、大きな桂の木のそばに、黒っぽい板でかこまれた建物が現れます。これが菅谷たたらの高殿です。中に入ると天井が高く、真ん中に長方形の炉の跡があります。","たたら製鉄は、川や山でとった砂鉄と、木炭を炉に入れて燃やし、ふいごで風を送り続けて鉄をつくる方法です。一回の作業を «一代（ひとよ）» といい、三日三晩、休みなく続けました。できあがる大きな鉄のかたまりを «鉧（けら）» といい、その中のいちばん良い部分が «玉鋼（たまはがね）»。日本刀の材料になる、特別な鋼です。","作業のリーダーは «村下（むらげ）» と呼ばれる技師長でした。温度計などない時代、村下は炎の色や音、流れ出る «ノロ»（鉄のかす）の様子を見て、炉の中で何が起こっているかを判断したといいます。«ここで砂鉄を入れろ!» その一声が、鉄のできを決めたのです。","このたたらを経営したのは、松江藩の鉄師（てっし）として知られた田部家です。鉄をつくるには大量の木炭が必要で、山の木を切っては植え、30年ほどでまた切るというように、森を回して使いました。高殿の横の桂の木は、製鉄の神 «金屋子神（かなやごかみ）» が降りた木として大切にされてきました。","明治になると、西洋式の製鉄が広がり、たたらは少しずつ姿を消しました。菅谷たたらも1921年に火を止めます。けれど高殿や山内の家々はそのまま残され、1967年に国の重要有形民俗文化財になりました。«もののけの森» を思わせる山の中で、日本の鉄の歴史を体で感じられる場所です。"],"tl":[["1751年","菅谷たたらの操業が始まる"],["江戸時代","田部家が松江藩の鉄師としてたたらを経営"],["明治時代","洋式製鉄が広がり、たたらは減っていく"],["1921年","菅谷たたらが操業を終える"],["1967年","高殿が国の重要有形民俗文化財に"],["2016年","日本遺産 «出雲國たたら風土記» に認定"]],"who":[["村下（むらげ）","たたら操業の技師長。炎を見て炉を操った"],["田部家","吉田の鉄師。菅谷たたらを経営した"],["金屋子神","たたら師たちが信仰した製鉄の神"]],"deep":["高殿は、炉の上に大きな屋根をかけた作業場。今も当時のまま残るのは菅谷の高殿だけとされる。","砂鉄は «鉄穴流し（かんなながし）» という方法で、山をくずして水で流し、重い砂鉄だけを集めた。その跡地は棚田に変わり、奥出雲の景観をつくった。","一代の操業で、砂鉄と木炭がそれぞれ十トン以上使われたといわれる。燃料の森の管理がたたら経営の要だった。","金屋子神は女神とされ、たたら場は女人禁制とされたなど、独特の信仰とタブーがあった。","奥出雲町では1977年から «日刀保たたら» が冬に操業され、日本刀の材料となる玉鋼を今もつくっている。"],"look":["高殿の内部と炉の跡","高殿横の桂の木（金屋子神の神木）","山内の元小屋（事務所）や住居","近くの «鉄の歴史博物館»","吉田の町の田部家土蔵群"],"q":["たたら製鉄でできる、日本刀の材料になる特別な鋼を何という?","«玉鋼（たまはがね）»。鉧（けら）という鉄のかたまりの中から取り出します。"],"koji":[],"myth":"金屋子神の降臨伝承や女人禁制の話は信仰・伝承。","img":["玉鋼","金屋子神","鉄穴流し"],"wp":"たたら製鉄","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Japanischer_Tatara-Ofen_mit_Fl%C3%BCgelgebl%C3%A4se_%2818_Jahrhundert%29.jpg",2000,1660,"たたら製鉄"],["c:d/d2/Tonomaruyama_Tatara_furnace.JPG",2400,1800],["c:4/47/Ohitayama-tatara_Iron_Works_05_Furnace_and_Blower.JPG",2400,1800],["c:5/5d/Japanischer_Tatara-Schmelzofen_-_Zeichnung_von_Adolf_Ledebur_%281901%29.jpg",2400,1800],["c:0/08/Tenbin_Fuigo.png",1668,2284],["c:8/8d/Tamahagane_yao.jpg",2064,1528],["c:7/76/Tatara_%28Making_Japanese_Iron_and_Steel%29.png",2208,1242],["c:5/54/Powder_steel.jpg",1600,1200]]},{"id":"32_koizumi_yakumo","n":"小泉八雲旧居（ヘルンが暮らした武家屋敷）","yomi":"こいずみやくもきゅうきょ（へるんきゅうきょ）","cat":"近代","rank":"S","y":1891,"era":["meiji"],"sh":"国指定史跡","ad":"松江市北堀町","st":"JR松江駅からレイクラインバスで約15分「小泉八雲記念館前」下車すぐ","la":35.4777,"lo":133.0514,"hook":"日本の怪談を世界に伝えた作家は、この小さな武家屋敷の縁側で、庭のカエルやトンボをながめて暮らした。","lead":"『怪談』で知られる作家ラフカディオ・ハーン（のちの小泉八雲）が、1891年に約5か月間住んだ武家屋敷です。三方を庭にかこまれたこの家を、ハーンはとても気に入り、作品にも書きました。松江の人は親しみをこめて «ヘルンさん» と呼びました。","story":["1890年の夏、ギリシャ生まれ、アイルランドなどで育った一人の外国人が、松江にやってきました。ラフカディオ・ハーンです。島根県の中学校（尋常中学校）の英語の先生として招かれたのでした。松江の人たちは «ハーン» を «ヘルン» と読み、«ヘルン先生» と呼びました。","ハーンは、朝の宍道湖、大橋を行きかう人の下駄の音、お寺の鐘、柏手の音に心をうばわれました。«ここには、西洋が失ってしまったものがある» ――そう感じたハーンは、見たもの聞いたものを熱心に書きとめていきます。","1891年、ハーンは松江藩士の家だった根岸家の屋敷を借りて住みました。お堀に面した、武士の町の一角です。いちばんのお気に入りは、家を三方からかこむ庭でした。石灯籠、池、小さな草木、そしてカエルやヘビやトンボ。ハーンは縁側にすわって、庭の生きものたちを飽きずにながめたといいます。","この家での暮らしを支えたのが、松江の士族の娘・小泉セツでした。のちにハーンの妻となるセツは、夜ごとに昔話や怪談を語って聞かせ、それがハーンの作品のもとになりました。«あなたの言葉で、あなたの考えで話してください» と、ハーンはセツにたのんだと伝わります。二人の物語は、2025年からの連続テレビ小説のモデルにもなりました。","寒さの厳しい松江の冬が体にこたえたこともあり、ハーンは1891年11月、熊本の学校へ移りました。松江にいたのは1年3か月ほど。けれど、この町での体験は『知られぬ日本の面影』などに生き生きと書かれ、世界中の人が «日本» を知る窓になりました。隣には小泉八雲記念館があり、ハーンの生涯を学べます。"],"tl":[["1850年","ハーン、ギリシャのレフカダ島で生まれる"],["1890年","来日し、8月に松江へ。島根県尋常中学校の英語教師に"],["1891年","根岸家の屋敷に住む。11月、熊本へ移る"],["1894年","『知られぬ日本の面影』を出版"],["1896年","日本に帰化し «小泉八雲» となる"],["1904年","東京で死去"],["1940年","旧居が国の史跡に指定"]],"who":[["小泉八雲（ラフカディオ・ハーン）","この家に住んだ作家"],["小泉セツ","八雲の妻。昔話を語り、創作を支えた"],["西田千太郎","松江の中学校の教頭。ハーンの親友で案内役"],["根岸家","家の持ち主の松江藩士の家"]],"deep":["エッセイ «日本の庭（In a Japanese Garden）» では、この家の庭のようすが細かく描かれている。庭は今も当時の雰囲気を伝える。","家は今も根岸家の所有で、公開されている。建物の中の部屋から庭をながめられる。","«八雲» の名は、出雲にかかる枕詞 «八雲立つ» からとったとされる。","ハーンの見たものを伝える記録として、当時の松江の風俗・信仰を知るうえでも重要な資料になっている。","ハーンは左目を少年時代の事故で失っていたため、写真では右の横顔を向けていることが多い。"],"look":["三方をかこむ庭（北・西・南）","縁側からの眺め（ハーンの気分で）","隣の小泉八雲記念館","塩見縄手の武家屋敷の町並み"],"q":["松江の人たちはハーンのことを何と呼んだ?","«ヘルンさん»。«Hearn» をヘルンと読んだためといわれます。"],"koji":[],"myth":"セツへの言葉などは伝えられた逸話。","img":["小泉八雲","小泉セツ","塩見縄手","小泉八雲記念館"],"wp":"小泉八雲旧居","rel":{"ev":[],"grave":[]},"ph":[["c:a/a2/Shiominawate_Matsue05s4592.jpg",4592,3056,"小泉八雲旧居"],["c:a/af/Lafcadio_Hearns_Old_Residence02s4592.jpg",4592,3056],["c:0/0e/Lafcadio_Hearns_Old_Residence01bs3200.jpg",3200,2130],["c:0/07/Lafcadio_Hearn_portrait.jpg",712,1024,"小泉八雲"],["c:0/00/Lafcadio_Hearn.jpg",1138,1764,"小泉セツ"],["c:5/52/150321_Shiominawate_Matsue_Shimane_pref_Japan01s3.jpg",6000,4000,"塩見縄手"],["c:a/a8/Lafcadio_Hearn_Memorial_Hall01st3200.jpg",3200,2130,"小泉八雲記念館"]]},{"id":"32_otometoge","n":"乙女峠（浦上四番崩れのキリシタン殉教地）","yomi":"おとめとうげ","cat":"近代","rank":"A","y":1868,"era":["meiji"],"sh":"","ad":"鹿足郡津和野町（津和野駅の西の谷）","st":"JR津和野駅から歩いて約15〜20分（山道を登る）","la":34.4656,"lo":131.7658,"hook":"«山陰の小京都» のすぐそばの静かな谷。ここで明治のはじめ、信仰を捨てなかったために命を落とした人びとがいた。","lead":"明治のはじめ、長崎の浦上のキリシタン（キリスト教の信者）が、各地に流されました（浦上四番崩れ）。津和野にも150人あまりが送られ、この谷の寺に閉じこめられて改宗をせまられ、多くの人が亡くなりました。今は小さなマリア聖堂が建ち、祈りの場所になっています。","story":["江戸時代、キリスト教はきびしく禁じられていました。けれど長崎の浦上では、人びとが250年以上もかくれて信仰を守り続けていました。1865年、長崎にできた大浦天主堂で、浦上の信者がフランス人の神父に信仰を打ち明けます。«わたしたちの心は、あなたと同じです»。この出来事は «信徒発見» と呼ばれます。","ところが明治になっても、新しい政府はキリスト教を禁じたままでした。1868年から、浦上の信者たちは村ごと捕らえられ、全国の藩へ分けて送られます。これを «浦上四番崩れ» といいます。津和野藩にも、まず28人の中心的な信者が、のちにその家族らが送られてきました。","信者たちが閉じこめられたのが、この谷にあった光琳寺というお寺でした。藩は、話し合いで改宗させようとしましたが、うまくいかないと、食事を減らし、寒い冬に池の氷水につけるなど、つらい責めを加えました。«三尺牢» と呼ばれる、立つことも横になることもできない小さな檻に入れられた人もいました。","それでも多くの人が信仰を捨てませんでした。三尺牢に入れられた安太郎という青年は、夜ごとに聖母マリアのような女性が現れてはげましてくれた、と語ったと伝わります。苦しみの中で、たくさんの人が命を落としました。子どもたちもいました。","1873年、外国からの強い抗議もあって、政府はキリスト教禁止の高札をおろし、生き残った人たちは浦上へ帰ることができました。昭和になって、この場所に «乙女峠マリア聖堂» が建てられます。毎年5月3日には «乙女峠まつり» が行われ、亡くなった人びとをしのんで、静かな祈りがささげられています。"],"tl":[["1865年","長崎・大浦天主堂で «信徒発見»"],["1867〜1868年","浦上の信者の捕縛が始まり、明治政府が各地への配流を決める（浦上四番崩れ）"],["1868年","津和野藩に最初の28人が送られる"],["1870年","家族らがさらに送られる"],["1873年","キリスト教禁止の高札が撤去され、信者が帰郷"],["1951年","乙女峠マリア聖堂が建てられる"]],"who":[["浦上の信者たち","信仰を守り通し、この地で多くが亡くなった"],["安太郎","三尺牢で聖母を見たと語ったと伝わる信者"],["守山甚三郎","生き残った信者。のちに津和野での体験を書き残した"],["パウロ・ネーベル神父","戦後、この地を調べ、聖堂の建立に力をつくした"]],"deep":["津和野に送られた信者は計150人あまり、そのうち約37人が亡くなったとされる（数え方で数字に幅がある）。","浦上四番崩れで各地に送られた信者は3000人をこえ、各地で多くの死者が出た。欧米諸国の強い抗議は、条約改正交渉をしていた岩倉使節団にとっても大きな問題となった。","津和野藩は国学がさかんで、藩の学者たちは «説得による改宗» に自信をもっていたともいわれる。","聖堂の中のステンドグラスには、三尺牢や氷責めなど、信者たちの苦しみの場面が描かれている。","«乙女峠» の名は、この谷の名前として以前からあったもので、信者の話とは別の由来とされる。"],"look":["乙女峠マリア聖堂とステンドグラス","殉教者の碑と三尺牢のようす（再現）","津和野の町から聖堂までの山道","5月3日の乙女峠まつり（行事の日）","町なかの津和野カトリック教会"],"q":["浦上の信者が全国の藩へ流された出来事を何という?","«浦上四番崩れ»。明治のはじめの出来事です。"],"koji":[],"myth":"殉教者の人数は資料で幅がある。安太郎の聖母の話は信者の証言として伝わるもの。","img":["浦上四番崩れ","津和野町","大浦天主堂"],"wp":"乙女峠","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"],["c:4/4b/Oura_Cathedral_20180623.jpg",2252,3000,"大浦天主堂"],["c:0/03/View_of_Tsuwano_Station.jpg",4032,3024,"近く: 津和野駅"],["c:d/d2/TsuwanoJo.JPG",2048,1536,"近く: 津和野城"],["c:6/67/Tsuwano_High_School_20170503-1.jpg",3983,2988,"近く: 島根県立津和野高等学校"],["c:7/7e/Otometoge_Saint_Mary%27s_Church_20170503-1.jpg",4032,3024,"近く: 乙女峠マリア聖堂"],["c:b/bf/Torii_of_Yasaka_Shrine_20170503.jpg",4032,3024,"近く: 弥栄神社 (津和野町)"],["c:7/7a/Washibara_Hachiman-g%C5%AB_Two-story_Gate_001.jpg",3245,2433,"近く: 鷲原八幡宮"]]},{"id":"32_yunotsu","n":"温泉津（銀の積み出し港と温泉町）","yomi":"ゆのつ","cat":"町","rank":"A","y":1570,"era":["muromachi","azuchi","edo"],"sh":"重要伝統的建造物群保存地区・世界遺産（石見銀山遺跡の一部）","ad":"大田市温泉津町温泉津","st":"JR温泉津駅から歩いて約20分","la":35.0925,"lo":132.3448,"hook":"石見の銀はこの港から海へ出ていった。そして船乗りたちは、同じ湾にわく温泉で旅のつかれをいやした。","lead":"石見銀山の銀や、銀山で使う物資を運んだ港町で、古くからの温泉地でもあります。戦国時代には毛利氏がここを軍港・銀の積み出し港として使いました。温泉町として全国で初めて «重要伝統的建造物群保存地区» に選ばれ、世界遺産の一部にもなっています。","story":["日本海の入り江の奥に、細長い町があります。«温泉の津（港）» と書いて «ゆのつ»。名前のとおり、港と温泉がひとつになった町です。言い伝えでは、傷ついたタヌキが湯につかって傷を治しているのを見て温泉が見つかった、といわれます。","戦国時代、石見銀山をめぐって大名たちが争いました。銀山を手に入れた毛利氏は、温泉津を大切な港として使います。銀を船に積んで送り出し、逆に、戦いや鉱山のための物資をここで受け取りました。港を守るため、入り江の近くには鵜丸城という城も築かれました。","となりの沖泊（おきどまり）は、深く切れこんだ小さな入り江で、風や波をさけるのに最適でした。岩場には船をつなぐための «鼻ぐり岩» という穴のあいた岩がいくつも残っています。«この穴に、何百年前の船乗りが綱を通したのか»――そう思うと、ただの岩が急に生き生きして見えます。","江戸時代になると、銀は陸路で瀬戸内側へ運ばれるようになりましたが、温泉津は北前船などの港として、また湯治場としてにぎわい続けました。通りには、廻船問屋の大きな家や、温泉宿、お寺が並び、今もその姿が残っています。","町の中心には «元湯» と «薬師湯» という二つの共同浴場があります。お湯は茶色くにごり、熱めです。夜には石見神楽が上演される日もあり、太鼓や笛の音が港町にひびきます。銀と湯と神楽――温泉津は、石見の歴史をまるごと体験できる町です。"],"tl":[["古くから","温泉がわいていたと伝わる"],["16世紀後半","毛利氏が温泉津を銀と物資の港として使う"],["江戸時代","北前船などの港・湯治場としてにぎわう"],["2004年","温泉町として初めて重要伝統的建造物群保存地区に選定"],["2007年","«温泉津・沖泊» が世界遺産の構成資産に"]],"who":[["毛利元就・毛利輝元","温泉津を銀の港・軍港として使った"],["廻船問屋の商人たち","港町の繁栄をささえた"],["石見神楽の舞い手たち","町の夜をいろどる郷土芸能の担い手"]],"deep":["世界遺産の構成資産は «温泉津沖泊道»«沖泊»«温泉津重要伝統的建造物群保存地区» などに分かれ、銀山と港を結ぶ道まで含まれている。","沖泊の鼻ぐり岩は、岩に穴をあけて船の綱をつないだもの。何十か所も確認されている。","鵜丸城は、毛利氏が水軍の拠点として築いた海城とされる。","温泉の開湯は約1300年前とする言い伝えがあるが、確かな記録ではない。","元湯は、湯船に直接わき出す温泉として、昔ながらの入り方の作法が残る。","温泉津は江戸時代も日本海の航路の寄港地として栄え、港には船宿や問屋が集まった。町並みの寺院の多さも、港町として多くの人が行き来した名残といわれる。"],"look":["元湯と薬師湯（共同浴場）","沖泊の入り江と鼻ぐり岩","廻船問屋の家並みと寺院","夜神楽（上演日のみ）","温泉津やきものの里（登り窯）","港を見下ろす高台の寺院からの眺め"],"q":["船の綱をつなぐために穴をあけた岩を何という?","«鼻ぐり岩»。沖泊の岩場に今も残っています。"],"koji":[],"myth":"タヌキの発見伝説、開湯1300年は言い伝え。","img":["石見銀山","石見神楽","北前船"],"wp":"温泉津温泉","rel":{"ev":[],"grave":[]},"ph":[["c:8/81/180505_Yunotsu_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan01s5.jpg",5760,3840,"温泉津温泉"],["c:8/88/%E5%85%B1%E5%90%8C%E6%B5%B4%E5%A0%B4%E5%85%83%E6%B9%AF%E6%B3%89%E8%96%AC%E6%B9%AF.jpg",4032,3024],["c:3/3e/Yunotsuonsenyakushiyu01.jpg",5472,3648],["c:b/bb/Yunotsuonsen01.jpg",5472,3648],["c:a/a3/180505_Yunotsu_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan02s3.jpg",6000,4000],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"]]},{"id":"32_omori_ginzan","n":"大森の町並み（銀山の代官所町）","yomi":"おおもりのまちなみ","cat":"町","rank":"A","y":1800,"era":["edo"],"sh":"重要伝統的建造物群保存地区","ad":"大田市大森町","st":"JR大田市駅からバスで約25〜30分「大森代官所跡」下車すぐ","la":35.1135,"lo":132.4436,"hook":"武士の家と商人の家が、となりどうしに並ぶ。銀の山にぴったりよりそってできた、ちょっと変わった町並み。","lead":"石見銀山のふもと、谷にそって約2kmつづく町です。江戸時代、ここには代官所があり、役人の武家屋敷と、商人や職人の家が入りまじって並びました。1987年に重要伝統的建造物群保存地区に選ばれ、いまも人びとが暮らす «生きた町» です。","story":["銀山の谷を流れる銀山川にそって、細い道が南へのびています。両側には赤い石州瓦の屋根、格子戸、白壁の家。城下町なら武士の町と町人の町は分けられるのがふつうですが、大森では、武家屋敷のとなりに商家、そのとなりにお寺、という並び方をしています。«なぜ?» 狭い谷に、銀山を管理する役人と、それを支える商人・職人がぎっしり集まったからです。","江戸時代の大森は、幕府の役人である代官がおさめる «天領» でした。銀山には全国から人が集まり、町は大いににぎわいました。ところが1800年、大きな火事が起こり、町の多くが焼けてしまいます。今の家並みの多くは、そのあとに建て直されたものです。","町でいちばん大きな商家が «熊谷家住宅»。代官所に出入りする «掛屋» などをつとめた家で、国の重要文化財です。家の中には、何十もの部屋、たくさんの食器や道具が残り、当時の豊かな暮らしをのぞくことができます。武家屋敷の «旧河島家» も公開されていて、下級武士の家の間取りがわかります。","町のはずれの羅漢寺には、岩のくぼみの中に五百羅漢の石像がずらりと並んでいます。銀山で亡くなった人びとや先祖の供養のために、25年かけてつくられたといわれます。表情がみんなちがうので、«自分に似た顔が必ず見つかる» ともいわれます。","銀山が止まったあと、町はさびれかけましたが、地元の人たちが家を修理し、町並みを守ってきました。今は古い家を使った店や工房も増え、世界遺産の町として多くの人が訪れます。夜はとても静かなので、昔の町の空気を感じたければ、朝夕の散歩がおすすめです。"],"tl":[["江戸時代初め","銀山の代官所が置かれ、町が整う"],["1800年","大火で町の多くが焼け、その後再建"],["江戸時代中期","五百羅漢が完成したと伝わる"],["1923年","銀山が休山"],["1987年","重要伝統的建造物群保存地区に選定"],["2007年","世界遺産の構成資産に"]],"who":[["熊谷家","代官所の御用をつとめた豪商"],["代官所の役人たち","町に住み、銀山と天領を管理した"],["大森の住民","町並みを守り続けてきた人びと"]],"deep":["保存地区は «武家と町人の混在» が特ちょうで、城下町とも宿場町ともちがう «鉱山町» のタイプとして評価された。","熊谷家住宅は1801年ごろの再建とされる大きな町家で、国の重要文化財。","羅漢寺の五百羅漢は、石窟の中に安置されていて、石橋・反橋とともに見どころ。","町の中には、観世音寺や城上神社など、寺社も多い。城上神社の拝殿の天井には «鳴き龍» がある。","町並みの建物には、現役の住宅や店が多い。見学のときは住む人の暮らしに配慮を。"],"look":["熊谷家住宅","旧河島家（武家屋敷）","羅漢寺の五百羅漢","城上神社の鳴き龍","銀山川ぞいの町並み"],"q":["大森の町並みでは、武家屋敷と商家はどんなふうに並んでいる?","入りまじって並んでいます。狭い谷に役人と商人が集まったためです。"],"koji":[],"myth":"五百羅漢の制作年数・由来は寺の伝え。","img":["石見銀山","五百羅漢","重要伝統的建造物群保存地区"],"wp":"大森 (大田市)","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan01s3.jpg",6000,4000],["c:5/50/180504_Omori_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan03n.jpg",5790,3860],["c:d/d2/180504_Omori_of_Iwami_Ginzan_Silver_Mine_Oda_Shimane_pref_Japan01bs4.jpg",6000,4000],["c:4/4a/Omori_Old_Street_001.jpg",3202,2401],["c:5/53/Omori_syougakkou.JPG",3072,2304],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"]]},{"id":"32_omori_daikansho","n":"大森代官所跡（石見銀山資料館）","yomi":"おおもりだいかんしょあと","cat":"幕末","rank":"A","y":1866,"era":["edo"],"sh":"国指定史跡（石見銀山遺跡の一部）","ad":"大田市大森町","st":"JR大田市駅からバスで約25〜30分「大森代官所跡」下車すぐ","la":35.1172,"lo":132.4447,"hook":"«芋代官» と呼ばれて、死後に神さまになった代官がいた。そして幕末、この役所は長州軍に明けわたされた。","lead":"江戸幕府が石見銀山と周りの天領（幕府の領地）をおさめるために置いた役所の跡です。いまは江戸後期の表門と門長屋が残り、中は石見銀山資料館になっています。飢えた人びとを救った名代官の話と、幕末の長州軍の進攻の舞台でもあります。","story":["関ヶ原の戦いのあと、石見銀山は徳川家のものになりました。銀山とそのまわりの村々をおさめるため、大森に置かれたのが代官所です。代官は幕府から送られる役人で、銀の生産から年貢の取り立て、裁判まで担いました。","江戸時代の中ごろ、1731年に代官になったのが井戸平左衛門です。着任してまもなく、西日本は大ききんにおそわれます（享保の飢饉）。平左衛門は幕府の許しを待たずに代官所の米蔵を開き、人びとに米を配ったといわれます。さらに、やせた土地でも育つサツマイモの種いもを薩摩から取り寄せ、栽培を広めました。","«許しなく蔵を開いた責任をとって自ら命を絶った» という言い伝えもありますが、実際には病気で亡くなったとする見方が有力です。いずれにせよ、人びとは平左衛門を «芋代官» と呼んで感謝し、各地に «井戸神社» や供養の碑を建てました。いまも石見のあちこちに、その碑が残っています。","時は流れて幕末の1866年。幕府と長州藩の戦い（第二次長州征討）で、長州軍は石見に攻め入り、浜田城を落としました。大森の代官は逃れ、代官所は長州軍の手にわたります。«徳川の銀の山» が、倒幕をめざす長州に押さえられた――時代が大きく動いた瞬間でした。","明治になって代官所は役目を終えましたが、表門と門長屋は残り、1976年から «石見銀山資料館» として使われています。館内では、銀山で使われた道具や、代官所の文書、鉱石などを見ることができます。«銀の山の役所» の空気を感じながら、町並み散策のスタートにしたい場所です。"],"tl":[["1600年","関ヶ原の戦い後、石見銀山が徳川家の支配下に"],["1731年","井戸平左衛門が大森代官に"],["1732年","享保の飢饉。平左衛門がサツマイモの栽培を広める"],["1733年","平左衛門が亡くなる"],["1866年","第二次長州征討で長州軍が石見に進攻、代官所を押さえる"],["1976年","石見銀山資料館が開館"]],"who":[["井戸平左衛門（正明）","«芋代官» と呼ばれた大森代官"],["大久保長安","初期の銀山経営をになった奉行"],["大村益次郎","第二次長州征討で石州口の長州軍を指揮した"]],"deep":["表門と門長屋は江戸後期の建物とされ、代官所の建物として現存する貴重な例。","井戸平左衛門の «自刃説» は後世の伝承で、史料上は病死とされることが多い。","第二次長州征討の石州口の戦いでは、大村益次郎の指揮する長州軍が津和野藩の領内を通って浜田藩に進んだ。","石見銀山資料館は、地元の人たちがお金を出しあって設立した民間の資料館として始まった。","代官所が管理した天領は、石見のほか周辺の村々をふくむ広い範囲におよんだ。"],"look":["表門と門長屋","石見銀山資料館の鉱石・道具の展示","井戸平左衛門を顕彰する井戸神社（町内）","代官所前の広場から見る町並みの入口"],"q":["«芋代官» と呼ばれた大森の代官はだれ?","井戸平左衛門。サツマイモを広めて人びとを飢えから救ったといわれます。"],"koji":[],"myth":"井戸平左衛門の自刃説は伝承。米蔵を開いた話の細部にも諸説。","img":["井戸正明","第二次長州征討","大村益次郎"],"wp":"大森代官所","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan05n.jpg",6000,4000,"大森代官所"],["c:9/96/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan07s3.jpg",6000,4000],["c:4/42/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan02s3.jpg",6000,4000],["c:9/9a/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan01s3.jpg",6000,4000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/ee/Ido_Masaakira02.jpg",464,623,"井戸正明"],["c:7/71/Masujiro_Omura_cropped.jpg",722,948,"大村益次郎"]]},{"id":"32_yamabuki_jo","n":"山吹城（銀山を守る山城）","yomi":"やまぶきじょう","cat":"城","rank":"A","y":1562,"era":["muromachi","azuchi"],"sh":"国指定史跡（石見銀山遺跡の一部）","ad":"大田市大森町","st":"JR大田市駅からバスで約25〜30分「大森代官所跡」付近から登山口へ。山頂まで歩いて40分〜1時間","la":35.108,"lo":132.433,"hook":"この山を取った者が銀を取る。戦国の大名たちは、銀山を見下ろす一つの山城を、何十年も奪い合った。","lead":"石見銀山のすぐそば、要害山（標高約414m）の山頂にあった山城の跡です。銀山を守り、にらみをきかせるための城で、大内・尼子・毛利の三つの大名が激しく取り合いました。今は建物はなく、曲輪や堀切などの跡が残る «城跡» です。","story":["銀山の谷をかこむ山々のうち、ひときわ高い要害山。その頂上から見下ろすと、仙ノ山や銀山の谷がひと目で見わたせます。«銀山を守るなら、この山をおさえなければ» ――山吹城がつくられたのは、そのためでした。","戦国時代、石見銀山はたびたび持ち主を変えました。周防の大内氏、出雲の尼子氏、地元石見の小笠原氏、そして安芸の毛利氏。銀山がほしい大名たちは、まず山吹城をねらいました。城の主が変わるたびに、銀の行き先も変わったのです。","毛利元就も、この城にてこずりました。1559年、元就は山吹城を攻めましたが、尼子方の守りは固く、引き上げるときに大きな被害を出したといわれます（降露坂の戦い）。城を守っていたのは尼子方の本城常光という武将でした。","ところが1562年、本城常光は毛利に味方することを決め、城をわたしました。こうして毛利氏はついに銀山を手に入れます。しかし元就は常光を信用せず、まもなく常光とその一族を討ってしまった、と伝わります。戦国のきびしさを物語る話です。","江戸時代になると、銀山は幕府の直轄となり、山吹城は使われなくなりました。今、登山道を登ると、平らにならした曲輪や、尾根を断ち切った堀切がはっきり残っています。山頂からの眺めは、戦国の武将たちが命がけで守った «銀の谷» そのものです。"],"tl":[["16世紀前半","銀山の開発とともに城が重視される（築城時期は諸説）"],["1556年","忍原の戦いで毛利方が尼子方に敗れたといわれる"],["1559年","毛利元就が山吹城を攻めるが退く（降露坂の戦い）"],["1562年","城主・本城常光が毛利方につき、毛利が銀山を支配"],["江戸時代初め","使われなくなり廃城に"]],"who":[["毛利元就","最後に城と銀山を手に入れた"],["本城常光","尼子方の城主。のちに毛利方につく"],["尼子晴久","城を守らせた出雲の大名"],["大内氏","はやくから銀山と城をおさえようとした"]],"deep":["城は要害山の山頂に本丸を置き、尾根ぞいに曲輪を並べた連郭式の山城とされる。","築城は鎌倉時代末に大内氏が築いたという伝承もあるが、確かな史料はない。","本城常光の謀殺は毛利氏の «銀山を確実におさえるため» の判断とされるが、理由には諸説ある。","銀山と城、周りの «矢筈城»«石見城» などが連携して銀山の防衛線をつくったとされる。","山吹城も世界遺産 «石見銀山遺跡» の構成資産の一つ。","戦国時代の石見銀山の争奪は、銀そのものだけでなく、銀を使った朝鮮・明との交易の利益をめぐる争いでもあったと考えられている。","山吹城の城跡は、ふだんは管理された登山道があるが、道が荒れていることもある。登るときは歩きやすい靴で、雨のあとは足元に注意したい。"],"look":["本丸跡からの銀山の眺め","曲輪と堀切の跡","登山道の途中の石垣の名残","ふもとから見上げる要害山の姿","山頂近くの本丸の平坦地"],"q":["山吹城を守っていたが、1562年に毛利方についた尼子方の武将は?","本城常光。これで毛利氏が銀山を手に入れました。"],"koji":[],"myth":"築城年代や戦いの細部には諸説。","img":["石見銀山","毛利元就","本城常光"],"wp":"山吹城","rel":{"ev":["iwami_ginzan"],"grave":[]},"ph":[["c:5/5a/Yamabuki_castle_overview.JPG",2048,1536,"山吹城"],["c:c/c9/%E5%B1%B1%E5%90%B9%E5%9F%8E%E8%B7%A1_-_panoramio.jpg",1600,1076],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"]]},{"id":"32_hinomisaki","n":"日御碕神社","yomi":"ひのみさきじんじゃ","cat":"寺社","rank":"A","y":1644,"era":["heian","edo"],"sh":"国の重要文化財（社殿）","ad":"出雲市大社町日御碕","st":"出雲大社からバスで約20分「日御碕」下車、歩いてすぐ","la":35.433,"lo":132.6313,"hook":"伊勢の神宮が «日本の昼» を守るなら、ここは «日本の夜» を守る――夕日の岬に、朱色の社殿が二つ並ぶ。","lead":"島根半島の西の端、日御碕にある神社です。天照大御神をまつる «日沈宮（ひしずみのみや）» と、素戔嗚尊をまつる «神の宮» の二つのお社からなります。いまの朱塗りの社殿は、江戸幕府3代将軍・徳川家光の命令で建てられたもので、国の重要文化財です。","story":["出雲大社から海ぞいの道をくねくねと走ると、白い灯台が見える岬に着きます。その手前、松林の中に、あざやかな朱色の社殿が現れます。出雲の神社は落ち着いた木の色の社殿が多いので、«ここだけ日光東照宮みたい!» と驚く人もいます。","じつはこの社殿、江戸時代の1644年ごろ、3代将軍・徳川家光の命令で建てられました。華やかな権現造の建物で、柱や天井には色あざやかな絵がえがかれています。«なぜ将軍がこの岬の神社を?» ――幕府が出雲の神々を大切にした証とも、松江藩を通じて力を示したものともいわれます。","下の宮 «日沈宮» には天照大御神がまつられています。伊勢神宮が «日の本の昼を守る» のに対して、日御碕は «日の本の夜を守る» 神社だと伝えられます。夕日がしずむ西の果ての岬にふさわしい言い伝えです。","日沈宮は、もとは目の前の海に浮かぶ «経島（ふみしま）» にまつられていたといわれます。平安時代、村上天皇の命令で今の場所に移された、と伝わります。経島は今もふだんは人が上陸できない聖なる島で、毎年8月7日の夕方、神職が船でわたってお祭りをします。","経島は、ウミネコが集まって巣をつくる島としても有名で、国の天然記念物です。春から夏にかけて、何千羽ものウミネコの声が岬にひびきます。神社から少し歩くと、石造りでは日本一の高さの出雲日御碕灯台があり、日本海に沈む夕日を見送ることができます。"],"tl":[["733年","『出雲国風土記』に «美佐伎社（みさきのやしろ）» が記される"],["948年","日沈宮が経島から今の場所へ移されたと伝わる"],["1644年ごろ","徳川家光の命で現在の社殿が完成"],["1903年","出雲日御碕灯台が点灯"],["昭和","社殿が国の重要文化財に指定される"]],"who":[["天照大御神","日沈宮にまつられる神"],["素戔嗚尊","神の宮にまつられる神"],["徳川家光","社殿の造営を命じた3代将軍"],["小野家","代々この神社の宮司をつとめてきた家"]],"deep":["社殿は権現造で、日沈宮と神の宮のそれぞれに本殿・幣殿・拝殿がある。楼門や回廊などもあわせて重要文化財。","経島の祭り «夕日の祭り（神幸祭）» は8月7日。ふだんは宮司以外の上陸が許されない。","神の宮は、素戔嗚尊が «わが魂はこの柏の葉のとまる所に住まん» と柏の葉を投げたところ、この地に落ちたという伝承をもつ。","日御碕灯台は高さ約44m、石造の灯台として日本一の高さ。明治36年に初点灯。","宮司の小野家は古くからこの社を守り、中世には出雲大社と勢力を競ったとされる。","境内の石灯籠や狛犬には江戸時代の寄進のものも多く、北前船の船乗りや商人が海の安全を祈って奉納したとされる。"],"look":["朱塗りの楼門と日沈宮・神の宮","経島（ウミネコの繁殖地）","出雲日御碕灯台と展望台","岬に沈む夕日","境内の石灯籠と狛犬"],"q":["日御碕神社が «日本の夜を守る» といわれるのに対し、«日本の昼を守る» とされるのはどこ?","伊勢神宮。日御碕は西の果てで夕日を見送る神社とされます。"],"koji":[],"myth":"日沈宮の遷座の年や、素戔嗚尊の柏の葉の話は社伝・伝承。","img":["経島","出雲日御碕灯台","徳川家光"],"wp":"日御碕神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/78/Hinomisaki-jinja_Two-storied_Gate_001.jpg",3251,2438,"日御碕神社"],["c:1/1f/%D0%94%D0%BE-%D0%BC%D0%B0%D1%80%D1%83.JPG",3648,2736],["c:3/31/Hinomisaki-jinja_monkakujinshauden.jpg",3872,2592],["c:6/60/Hinomisaki-jinja_monkakujinshasaden.jpg",3872,2592],["c:1/15/Hinomisaki-jinja_misogisho.jpg",3872,2592],["c:b/bc/Hinomisaki-jinja_kairo2.jpg",3872,2592],["c:2/27/Hinomisaki-jinja_treasure_house_001.jpg",3264,2448],["c:0/00/Hinomisaki-jinja_Worship_Hall_of_Hishizuminomiya_%28Shrine%29_001.jpg",3264,2448]]},{"id":"32_miho_jinja","n":"美保神社（えびす様の総本宮）","yomi":"みほじんじゃ","cat":"寺社","rank":"A","y":1813,"era":["myth","edo"],"sh":"国の重要文化財（本殿）","ad":"松江市美保関町美保関","st":"JR松江駅からバスを乗りついで約1時間強。車が便利（松江市街から約50分）","la":35.5634,"lo":133.3065,"hook":"国をゆずるかどうか、父から相談された神は、そのとき釣りをしていた。えびす様のふるさとは、島根半島の東の端の港町。","lead":"«えびす様» として親しまれる事代主神（ことしろぬしのかみ）と、三穂津姫命をまつる神社です。全国に3000以上あるえびす社の総本宮とされます。国譲りの神話にちなむお祭りが今も続き、二つの大社造を並べた珍しい本殿は国の重要文化財です。","story":["『古事記』の国譲りの場面。天の神の使いに «国をゆずれ» とせまられた大国主神は、«息子の事代主に聞いてほしい» と答えます。そのとき事代主神は、美保の岬で釣りや鳥の狩りをしていました。使いの船がやってきて問うと、事代主神は «おゆずりしましょう» と答え、乗ってきた船をひっくり返し、青い柴垣の中にかくれた、と語られます。","この話にちなんだお祭りが、今も美保神社で行われています。12月3日の «諸手船（もろたぶね）神事» は、二そうの船が港の中を競うようにこいで進むお祭りで、事代主のもとに使いが急いだ場面を表すといわれます。4月7日の «青柴垣（あおふしがき）神事» では、青い柴垣で飾った船が出て、神話の場面が再現されます。","えびす様は、釣りざおを持ち、鯛をかかえた姿でおなじみです。«なぜ釣りざお?» それは事代主神が美保で釣りをしていた、という神話と結びついているからです。海の幸と商売の神として、漁師や商人たちに厚く信仰されてきました。","本殿は1813年に建てられたもので、二つの大社造の本殿を横につなげた «美保造（比翼大社造）» と呼ばれる珍しい形です。向かって右に三穂津姫命、左に事代主神がまつられています。","美保神社は «鳴り物好きの神さま» とも言われ、昔から太鼓や笛、琴、オルガンまで、たくさんの楽器が奉納されてきました。神社の前から港へのびる «青石畳通り» は、雨にぬれると青く光る石だたみの小道。江戸時代に北前船の風待ち港としてにぎわった美保関の面影を今に伝えています。"],"tl":[["733年","『出雲国風土記』に «美保社» が記される"],["927年","『延喜式』神名帳に «美保神社» が載る"],["1813年","現在の本殿が建てられる"],["毎年4月7日","青柴垣神事"],["毎年12月3日","諸手船神事"]],"who":[["事代主神","まつられている神。えびす様として親しまれる"],["三穂津姫命","まつられている神。高天原から稲穂をもたらしたとされる"],["大国主神","事代主神の父。国譲りの神話の主人公"]],"deep":["本殿の «美保造» は、大社造の本殿二つを «装束の間» でつないだ形。«比翼大社造» とも呼ばれる。","奉納された鳴り物（楽器）は800点をこえ、国の重要有形民俗文化財になっている。","『出雲国風土記』では、美保の地名の由来として、大国主神の子・御穂須須美命（みほすすみのみこと）の名が出てくる。記紀の事代主神との関係は諸説。","諸手船神事の «諸手船» は、古い丸木舟の形を伝えるとされる。","美保関は北前船の寄港地で、青石畳通りの石は江戸時代に敷かれたといわれる。"],"look":["美保造の本殿（外から）","拝殿の天井の高い空間（楽器の奉納が演奏されることも）","青石畳通り","美保関灯台と地蔵崎の眺め"],"q":["国譲りの神話で、事代主神は使いが来たとき何をしていた?","美保の岬で釣り（と鳥の狩り）をしていたと語られます。"],"koji":[],"myth":"えびす＝事代主神とする考えは中世以降に広まったもので、蛭子神をえびすとする系統もある。","img":["事代主神","えびす","美保関町"],"wp":"美保神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/99/Miho-jinja_haiden.jpg",3872,2592,"美保神社"],["c:7/7e/%E7%BE%8E%E4%BF%9D%E7%A5%9E%E7%A4%BE%E7%A5%9E%E9%96%80.JPG",6016,4000],["c:7/76/%E7%BE%8E%E4%BF%9D%E7%A5%9E%E7%A4%BE%E7%A4%BE%E6%AE%BF.JPG",6016,4000],["c:3/31/%E7%BE%8E%E4%BF%9D%E7%A5%9E%E7%A4%BE%E3%81%AE%E7%88%86%E7%AB%B9%E5%BC%8F.jpg",5568,3712],["c:d/d8/%E5%88%A5%E5%8F%B7%E5%A4%A7%E5%BE%A1%E5%89%8D.JPG",6016,4000],["c:0/0e/%E5%88%A5%E5%8F%B7%E4%BA%8C%E5%BE%A1%E5%89%8D.JPG",6016,4000],["c:3/31/Nagatajinjya0906.JPG",4288,2848,"事代主神"],["c:d/d6/Ebisu_at_Ebisu-jinja_-_Kyoto%2C_Japan_-_DSC07332.jpg",3376,5364,"えびす"]]},{"id":"32_inasa","n":"稲佐の浜（国譲り・神迎えの浜）","yomi":"いなさのはま","cat":"伝承","rank":"A","y":733,"era":["myth","nara"],"sh":"","ad":"出雲市大社町杵築北","st":"一畑電車 出雲大社前駅から歩いて約15分（出雲大社から西へ約1km）","la":35.3985,"lo":132.6727,"hook":"剣を波の上に逆さに突き立て、その切っ先にすわって «国をゆずれ» とせまった神がいた。その舞台とされるのが、この浜だ。","lead":"出雲大社から西へ歩いてすぐの砂浜です。『古事記』の国譲りの神話の舞台とされ、旧暦10月には全国から神々がこの浜に上陸するといわれ、«神迎神事（かみむかえしんじ）» が行われます。浜にぽつんと立つ «弁天島» が目じるしです。","story":["『古事記』によると、天照大御神は、地上の国をゆずってもらうため、何度も使いを送りました。けれどうまくいきません。最後に送られたのが、力の強い建御雷神（たけみかづちのかみ）でした。","建御雷神は «伊耶佐（いざさ）の小浜» に降りたつと、長い剣を抜いて、切っ先を上にして波の上に突き立て、その上にあぐらをかいてすわりました。そして大国主神に «この国をゆずるか、どうか» とせまったのです。大国主神は、息子たちの答えを聞いたあと、国をゆずりました。この «いざさの浜» が、稲佐の浜だといわれています。","『出雲国風土記』には、もう一つの壮大な神話 «国引き» が書かれています。八束水臣津野命（やつかみずおみつののみこと）が、«出雲は小さい国だ» と言って、海の向こうの国の余った土地に綱をかけ、«国来い、国来い» と引きよせたのです。そのとき使った綱が、稲佐の浜から南へ続く長い砂浜 «薗の長浜» だとされます。","旧暦10月は、全国では «神無月» ですが、出雲では «神在月»。全国の神々が出雲に集まり、話し合いをすると伝えられます。旧暦10月10日の夜、稲佐の浜でかがり火をたき、海からやってくる神々をむかえるのが «神迎神事» です。神々は «龍蛇さま» に導かれて来るといわれ、そのあと出雲大社へ向かいます。","浜の «弁天島» は、かつて弁財天がまつられていた小さな岩の島で、今は豊玉毘古命がまつられています。夕方には、島のむこうの日本海に夕日がしずみ、多くの人が写真をとりに集まります。神話の舞台に立って、海の向こうからやってくる神々を想像してみましょう。"],"tl":[["712年","『古事記』完成。国譲りの神話が記される"],["733年","『出雲国風土記』完成。国引き神話が記される"],["毎年 旧暦10月10日","神迎神事が行われる"]],"who":[["建御雷神","国譲りをせまった天の神の使い"],["大国主神","国をゆずった出雲の神"],["八束水臣津野命","国引き神話の主人公"],["龍蛇さま","神在月に神々を導くとされる海の使い（セグロウミヘビ）"]],"deep":["『古事記』では «伊耶佐の小浜»、『日本書紀』では «五十田狭の小汀（いたさのおはま）» と書かれる。これを稲佐の浜にあてるのが通説。","国引きで引きよせた土地は «志羅紀（しらぎ）»«佐伎»«良波» «高志（こし）» の4か所とされ、島根半島の成り立ちを語る神話になっている。杭にしたのが三瓶山と大山。","«龍蛇さま» は、この季節に浜に打ち上げられるセグロウミヘビのことで、神の使いとして大切にされる。","浜の南の «屏風岩» は、大国主神と建御雷神が国譲りの話し合いをした場所と伝わる。","神迎神事は夜に行われ、一般の人も参列できる。静かな神事なので写真やライトはひかえめに。"],"look":["弁天島","屏風岩（国譲りの話し合いの場と伝わる）","浜の砂（神在月のあと «お砂» を出雲大社に納める風習がある）","夕日"],"q":["国引き神話で、引きよせた土地をつなぎとめる綱になったといわれる浜は?","«薗の長浜»。稲佐の浜から南へのびる長い砂浜です。"],"koji":[],"myth":"国譲り・国引きは神話。稲佐の浜を伊耶佐の小浜にあてるのは通説だが伝承。","img":["国譲り","国引き","神在月"],"wp":"稲佐の浜","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/Bentenjima_on_Inasa_Beach.jpg",3056,2294,"稲佐の浜"],["c:0/07/Inasanohama.JPG",1280,960]]},{"id":"32_yomotsu_hirasaka","n":"黄泉比良坂（伊賦夜坂）","yomi":"よもつひらさか（いふやざか）","cat":"伝承","rank":"A","y":712,"era":["myth","nara"],"sh":"","ad":"松江市東出雲町揖屋","st":"JR揖屋駅から歩いて約20分","la":35.4246,"lo":133.1487,"hook":"死者の国と生きている者の国をへだてる坂。『古事記』は、その坂が «今の出雲国の伊賦夜坂（いふやざか）» だと、はっきり書いている。","lead":"『古事記』で、伊邪那岐命（いざなきのみこと）が死者の国・黄泉の国からにげ帰るときに通った坂が «黄泉比良坂» です。『古事記』には、その坂が出雲の «伊賦夜坂» だと書かれており、東出雲町揖屋のこの場所が、その伝承地とされています。","story":["日本の国や神々を生んだ夫婦の神、伊邪那岐命と伊邪那美命（いざなみのみこと）。ところが伊邪那美命は火の神を生んだときの大やけどがもとで亡くなり、死者の国 «黄泉の国» へ行ってしまいます。悲しみにくれた伊邪那岐命は、妻を連れもどそうと黄泉の国へ向かいました。","伊邪那美命は «黄泉の国の神と相談します。そのあいだ、決してわたしを見ないで» と言いました。けれど待ちきれなくなった伊邪那岐命は、火をともして中をのぞいてしまいます。そこにいたのは、変わりはてた妻の姿でした。«よくも、わたしにはじをかかせましたね!» 伊邪那美命は怒り、追っ手をさしむけます。","伊邪那岐命は必死ににげ、黄泉比良坂のふもとまで来ると、そこに生えていた桃の実を三つ投げつけて追っ手を追いはらいました。そして最後に、千人がかりでやっと動かせるほどの大岩 «千引の石（ちびきのいわ）» で坂をふさいだのです。","岩をはさんで、二人は別れの言葉をかわします。伊邪那美命が «あなたの国の人を一日に千人殺しましょう» と言うと、伊邪那岐命は «それなら一日に千五百の産屋を建てよう» と答えました。«人が死に、それ以上に生まれる» ことの始まりを語る、とても有名な場面です。","揖屋の森の中の伝承地には、石碑と、しめ縄をはった大きな岩が置かれ、あの世とこの世の境を思わせる、ひんやりとした空気がただよっています。近くには伊邪那美命をまつる揖夜神社があります。ここは神話の «言い伝えの場所» ですが、古代の人が出雲に «あの世の入口» を感じていたことを教えてくれます。"],"tl":[["712年","『古事記』完成。黄泉比良坂は «出雲国の伊賦夜坂» と記される"],["720年","『日本書紀』完成（黄泉の国の話を別の形で伝える）"],["733年","『出雲国風土記』に «伊布夜社（揖夜神社）» が記される"],["昭和","伝承地に石碑が建てられる"]],"who":[["伊邪那岐命","妻を追って黄泉の国へ行き、にげ帰った神"],["伊邪那美命","黄泉の国の神となった妻の神。揖夜神社にまつられる"],["太安万侶","『古事記』を書きまとめた人物"]],"deep":["『古事記』は «其の謂はゆる黄泉比良坂は、今、出雲国の伊賦夜坂と謂ふ» と、神話の場所を現実の地名と結びつけている。これは珍しい例。","«比良坂» の «ひら» は «崖・坂» を意味する古語とする説や、«境» を意味するとする説がある。","『日本書紀』の斉明天皇の条には、«言屋社（いうやのやしろ）» に犬が死人の腕をくわえて置いた、という不吉な出来事が記され、揖夜神社のこととされる。","『出雲国風土記』には、別に «黄泉の坂・黄泉の穴» と呼ばれた洞窟（出雲市の猪目洞窟とされる）の話があり、夢に見ると必ず死ぬと記されている。","桃が魔よけに使われる信仰は、中国の考え方の影響とされ、この神話がその古い例になっている。"],"look":["«神蹟黄泉比良坂伊賦夜坂伝説地» の石碑","しめ縄をはった大岩（千引の石に見立てたもの）","坂道と森の雰囲気","近くの揖夜神社"],"q":["伊邪那岐命が黄泉の追っ手を追いはらうために投げたものは?","桃の実3つ。桃には魔よけの力があると考えられました。"],"koji":[{"w":"一日に千人死に、千五百人生まれる","m":"伊邪那岐命と伊邪那美命の別れの言葉から。人の死と誕生の始まりを語る"}],"myth":"神話の伝承地であり、実際の場所を示すものではない。石碑・岩は後世に置かれたもの。","img":["伊邪那岐","伊邪那美","揖夜神社"],"wp":"黄泉比良坂","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/Yomotsu_Hirasaka.JPG",2352,1568,"黄泉比良坂"],["c:8/84/Kobayashi_Izanami_and_Izanagi.jpg",592,1307,"伊邪那岐"],["c:9/9a/Izumo-iya-jinja-1.jpg",1280,960,"揖夜神社"]]},{"id":"32_sada_jinja","n":"佐太神社（出雲国二宮）","yomi":"さだじんじゃ","cat":"寺社","rank":"A","y":1807,"era":["myth","edo"],"sh":"国の重要文化財（本殿3棟）","ad":"松江市鹿島町佐陀宮内","st":"JR松江駅からバスで約25分「佐太神社前」下車すぐ","la":35.5106,"lo":133.0147,"hook":"神在月、出雲に集まった神々は、出雲大社のあとにもう一か所、この神社にも立ち寄るといわれる。","lead":"出雲国の二宮とされる古い神社で、『出雲国風土記』に «佐太御子社» と書かれています。大社造の本殿が3つ横に並ぶめずらしい姿で、国の重要文化財です。ここに伝わる神楽 «佐陀神能（さだしんのう）» は、ユネスコの無形文化遺産にも登録されています。","story":["松江の北、日本海へぬける途中の平野に、佐太神社があります。正面に立つと、大社造の本殿が3つ、横一列にずらりと並んでいます。真ん中が正中殿、左右が北殿と南殿。«なぜ3つも?» それぞれにちがう神々がまつられていて、合わせて十数柱の神さまがいるのです。","中心の神は «佐太大神»。『出雲国風土記』には、佐太大神は島根半島の北の海にある «加賀の潜戸（かかのくけど）» という洞窟で生まれたと書かれています。母神が «もし生まれる子が男神なら、失った弓矢よ出てこい» と祈ると、金の弓矢が流れてきた。その弓矢で洞窟の岩を射抜くと、光が差しこんだ――なんとも美しい誕生の神話です。","神在月（旧暦10月）に全国から出雲に集まった神々は、出雲大社での話し合いのあと、佐太神社にも立ち寄るといわれます。そのため佐太神社でも «神在祭» が行われ、地元では «お忌み祭» と呼んで、神々のじゃまにならないよう静かに過ごす習わしがありました。","もう一つの宝が «佐陀神能»。毎年9月の «御座替祭（ござかえさい）» のときに舞われる神楽です。江戸時代の初め、神職が京都で能を学び、それを取り入れて、神話の物語を演じる神楽にしたと伝わります。この神楽は出雲地方の神楽のもとになったともいわれ、国の重要無形民俗文化財、そして2011年にはユネスコの無形文化遺産に登録されました。","いまの本殿3棟は1807年に建てられたもの。杉木立に囲まれた境内に立つと、どっしりと並ぶ屋根の迫力に圧倒されます。«出雲の神々の世界は、大社だけじゃない» と教えてくれる神社です。"],"tl":[["733年","『出雲国風土記』に «佐太御子社» と記される"],["927年","『延喜式』神名帳に載る"],["江戸時代初め","佐陀神能が形づくられたと伝わる"],["1807年","現在の本殿3棟が建てられる"],["1976年","佐陀神能が国の重要無形民俗文化財に"],["2011年","ユネスコ無形文化遺産に登録"]],"who":[["佐太大神","まつられている中心の神。猿田彦大神と同じ神ともいわれる"],["枳佐加比売命（きさかひめのみこと）","佐太大神の母とされる神"],["宮川秀行","京都で能を学び佐陀神能をつくったと伝わる神職"]],"deep":["本殿3棟が並ぶ «三殿並立» の大社造は全国でも珍しい。正中殿がやや大きい。","佐太大神を猿田彦大神と同じとする考えは中世以降のもので、諸説ある。","加賀の潜戸は松江市島根町にある海の洞窟で、観光船で見学できる（天候による）。","佐陀神能は «七座»«式三番»«神能» の三つの部分からなるとされ、とくに «神能» は能の形式で神話を演じる。","神在祭（お忌み祭）は、現在は新暦11月の決まった日に行われ、最後に神々を送る «神等去出（からさで）» の神事がある。"],"look":["三つ並ぶ大社造の本殿","佐陀神能の上演（御座替祭などの日）","境内の杉木立","北の日本海側・加賀の潜戸（足をのばして）"],"q":["佐太大神が生まれたと風土記に書かれている洞窟は?","«加賀の潜戸（かかのくけど）»。金の弓矢で岩を射抜いたと語られます。"],"koji":[],"myth":"佐陀神能の成立の経緯、佐太大神と猿田彦の同一視は伝承・諸説。","img":["佐陀神能","加賀の潜戸","神在月"],"wp":"佐太神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/c8/Sada_jinja.jpg",3872,2592,"佐太神社"],["c:9/93/Matsuerougakkou2.jpg",3146,2155,"近く: 島根県立松江ろう学校"],["c:0/0a/Matsue-englishgarden-Station-Platform.JPG",3072,2304,"近く: 松江イングリッシュガーデン前駅"],["c:d/d7/Shimane_NPP_Unit_1-2.jpg",4286,3194,"近く: 島根原子力発電所"],["c:6/60/National_Institute_of_Technology._Matsue_college.jpg",5984,3366,"近く: 松江工業高等専門学校"]]},{"id":"32_yaegaki","n":"八重垣神社（スサノオとクシナダヒメ）","yomi":"やえがきじんじゃ","cat":"寺社","rank":"A","y":800,"era":["myth","heian"],"sh":"国の重要文化財（板絵著色神像）","ad":"松江市佐草町","st":"JR松江駅から市営バス «八重垣神社» 行きで約20分、終点すぐ","la":35.443,"lo":133.0658,"hook":"ヤマタノオロチから守るため、スサノオが恋人をかくした森。池に紙を浮かべて «縁» を占う、日本でいちばん有名な恋占いの神社。","lead":"八重垣神社は、オロチを退治した神スサノオと、助けられたクシナダヒメ（稲田姫）の夫婦をまつる神社です。本殿の奥の «佐久佐女の森» には «鏡の池» があり、紙に硬貨をのせて浮かべる縁占いで知られます。宝物殿には平安時代にさかのぼるといわれる神々の壁画が残ります。","story":["むかし、出雲の斐伊川の上流に、八つの頭と八つの尾をもつ大蛇ヤマタノオロチが現れ、毎年娘を一人ずつ食べていました。最後に残った娘がクシナダヒメ。そこへ高天原を追われた神スサノオがやってきて «その娘をわたしの妻にくれるなら、オロチを退治しよう» と約束します。","神社の言い伝えでは、スサノオは戦いのあいだ、クシナダヒメを «佐久佐女（さくさめ）の森» の奥にかくし、まわりを八重（何重にも）の垣根でかこって守ったといいます。これが «八重垣» の名の由来とされます。ヒメは森の中の池の水を鏡にして、身なりを整えながら夫の帰りを待った――それが «鏡の池» だと伝わります。","スサノオはオロチに強い酒を飲ませ、酔ってねむったところを切りました。尾から出てきたのが、のちに三種の神器のひとつとなる «草薙剣» です。二人は結ばれ、スサノオが詠んだとされるのが «八雲立つ 出雲八重垣 妻籠みに 八重垣作る その八重垣を»。日本で最初の和歌といわれる歌です。","鏡の池の占いはこうです。社務所で占い用紙を受け取り、池に浮かべて硬貨をそっとのせる。すると水にぬれた紙に文字が浮かび、紙が早く沈めば縁が早く、遠くで沈めば遠くの人と縁がある、といわれます。«なぜ紙が沈むのを見るの?» それは、ヒメの鏡だった水に «神のこたえ» を映してもらう、という考えなのでしょう。","境内には、根元が一つで二本に分かれた «夫婦椿» があり、夫婦和合のしるしとして大切にされています。また宝物殿の板絵には、スサノオやクシナダヒメ、アマテラスなどの姿が色あざやかに描かれています。社殿の壁画として神々を描いた例はとても古く、神の姿を絵にしたものとして貴重だとされています。"],"tl":[["神話の時代","スサノオがオロチを退治し、クシナダヒメと結ばれたと伝わる"],["733年","『出雲国風土記』が完成。意宇郡に «佐久佐社» の名が見える"],["平安時代","社殿の板壁に神々の絵が描かれたとされる"],["昭和時代","板絵著色神像が国の重要文化財に指定"],["現在","縁結びの神社として全国から参拝者が訪れる"]],"who":[["スサノオ（素盞嗚尊）","オロチを退治した神。この神社の祭神"],["クシナダヒメ（稲田姫命）","スサノオの妻。森にかくれて夫の勝利を待ったと伝わる"],["アシナヅチ・テナヅチ","クシナダヒメの父母。境内の末社にまつられる"],["巨勢金岡","平安時代の絵師。板絵を描いたと伝わるが確証はない"]],"deep":["板絵著色神像は、もとは本殿の壁に描かれていた板絵で、現在は宝物収蔵庫で見られます。神の姿を描いた社殿の壁画としては最古級の一つとされ、国の重要文化財に指定されています。","板絵の作者を平安時代の絵師・巨勢金岡とする言い伝えがありますが、これは «名人の作» とされることの多い伝承で、確かめられてはいません。制作年代にも諸説があります。","『出雲国風土記』には «佐久佐社» があり、この神社の前身と考えられています。«佐草» という地名もここから来ていると見られます。一方、八重垣神社の名前の由来の場所には別の説もあり、雲南市の須我神社とのかかわりを説くものもあります。","«八雲立つ» の歌は『古事記』『日本書紀』の両方に出てきます。和歌の始まりとして『古今和歌集』の仮名序でも取り上げられ、«三十一文字の歌はスサノオから始まった» と説明されています。","鏡の池の占い用紙には、水にぬれると文字が出てくる特別な紙が使われています。多くの人が浮かべるので池の底には硬貨がたくさん沈んでいます。","出雲の縁結び信仰は、旧暦10月に全国の神々が出雲に集まり «人の縁» を話し合う、という «神在月» の言い伝えともつながっています。"],"look":["鏡の池（佐久佐女の森の奥）と縁占い","夫婦椿（連理玉椿）","宝物収蔵庫の板絵著色神像","本殿と随神門のしめ縄"],"q":["鏡の池の占いで、紙が早く沈むと何を意味するといわれる？","縁が早く訪れる、といわれます。遠くで沈むと、遠くの人と縁があるとされます。"],"koji":[{"w":"八雲立つ 出雲八重垣 妻籠みに 八重垣作る その八重垣を","m":"スサノオが詠んだとされ、日本最初の和歌といわれる。妻を守る垣根を何重にも作ろう、という意味"}],"myth":"ヒメを森にかくした話、池の鏡の話は神社の言い伝え。板絵の作者・制作年代は諸説。","img":["ヤマタノオロチ","スサノオ","クシナダヒメ"],"wp":"八重垣神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/d5/Yaegaki_jinja.jpg",3872,2592,"八重垣神社"],["c:c/cc/Kagaminoike_of_Yaegaki_Shrine.JPG",5184,3456],["c:1/14/Yaegaki_Jinja_honden_hekiga.jpg",832,773],["c:a/a3/Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi.png",2100,1039,"ヤマタノオロチ"],["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"スサノオ"],["c:2/22/Yaegaki_Jinja_hekiga.jpg",750,1120,"クシナダヒメ"]]},{"id":"32_suga_jinja","n":"須我神社（日本初之宮）","yomi":"すがじんじゃ","cat":"寺社","rank":"A","y":733,"era":["myth","nara"],"sh":"","ad":"雲南市大東町須賀","st":"JR木次線・出雲大東駅から車で約10分。路線バスは本数が少ないので車が便利","la":35.3469,"lo":133.0283,"hook":"«わたしの心はすがすがしい!» ――オロチを倒した神がそう叫んで宮をたてた、«日本で最初の宮»。","lead":"須我神社は、スサノオがオロチ退治のあと、クシナダヒメと住むための宮殿をたてた場所と伝わる神社です。そのため «日本初之宮» とよばれます。スサノオがここで詠んだとされる «八雲立つ» の歌から «和歌発祥の地» ともいわれます。","story":["オロチを退治したスサノオは、妻のクシナダヒメと暮らす土地をさがして出雲の国を歩きました。そしてある場所に来たとき、こう言ったと『古事記』は書いています。«吾此地に来て、我が御心すがすがし»――わたしはここに来て、心がすがすがしい。","こうしてその土地は «須賀» とよばれるようになり、スサノオはここに宮をつくりました。すると宮のまわりから雲がむくむくとわき立ちます。それを見て詠んだのが «八雲立つ 出雲八重垣 妻籠みに 八重垣作る その八重垣を» の歌。神社には、この歌が日本の和歌の始まりだとして «和歌発祥の地» の碑が立っています。","«なぜここが日本で最初の宮なの?» 神話の中で、神が地上で «宮» をつくった話がはっきり書かれるのはこれが初めてだから、というのが神社の説明です。もちろん神話の話ですが、古代の人がこの山あいの土地を特別な場所と考えていたことは伝わってきます。","神社のうしろにそびえる八雲山の中腹には «奥宮» があります。大きな岩が三つ寄りそうように立っていて、夫婦岩とよばれ、スサノオ・クシナダヒメ、そして子のスガノユヤマヌシミサルヒコヤシマノ神をあらわすと伝わります。本社から山道を歩いて約20〜30分。杉木立の中にたたずむ岩の前では、古代の人が岩そのものを神として拝んでいた姿が思い浮かびます。","参拝の作法として、まず奥宮の岩にお参りし、それから本社へ――という «二宮詣り» がすすめられています。静かな山里の神社ですが、縁結びや和歌の神として、八重垣神社とあわせて訪ねる人も増えています。"],"tl":[["神話の時代","スサノオが «心すがすがし» と言って宮をたてたと伝わる"],["712年","『古事記』が完成。須賀の宮の話が書かれる"],["733年","『出雲国風土記』完成。大原郡に «須我社» の名が見える"],["927年","『延喜式』神名帳に «須我神社» が載る"],["現在","«日本初之宮»«和歌発祥の地» として親しまれる"]],"who":[["スサノオ（須佐之男命）","オロチ退治のあと、ここに宮をたてたと伝わる"],["クシナダヒメ（稲田比売命）","スサノオの妻。ともにまつられる"],["スガノユヤマヌシミサルヒコヤシマノ神","二人の子とされる神。いっしょにまつられる"],["紀貫之","『古今和歌集』仮名序で、和歌の始まりをスサノオの歌とした"]],"deep":["«すが» ということばは『古事記』『日本書紀』どちらにも出てきます。『日本書紀』では «吾が心清清し» と書かれ、«清々しい» の語源と説明されることもあります。","『出雲国風土記』大原郡の条には «須我山» や «須我小川» の名も見え、奈良時代にこの一帯が «すが» とよばれていたことがわかります。","奥宮の夫婦岩は、社殿のない «磐座（いわくら）» 信仰の姿を残すものとして注目されます。社殿を建てる以前の古い祭りの形を想像させます。","境内の和歌碑には、«八雲立つ» の歌が刻まれています。«八雲立つ» は、のちに «出雲» にかかる枕詞としても使われるようになりました。","須我神社は八重垣神社とともに «スサノオとクシナダヒメの新居» の伝承地とされます。二人の新居の場所がどこかは、神社ごとの伝承で、どれが正しいと決められるものではありません。"],"look":["本殿と «日本初之宮» の額","和歌発祥の地の碑","奥宮・夫婦岩（山道を約20〜30分）","須賀の里の景色（«すがすがしい» と言いたくなるか確かめてみよう）"],"q":["«すがすがしい» の語源になったといわれる、この地名は？","«須賀（すが）»。スサノオが «わが心すがすがし» と言ったことから名がついたと『古事記』は書きます。"],"koji":[{"w":"吾此地に来て、我が御心すがすがし","m":"スサノオがこの地に来て言ったとされることば。心が晴れ晴れとする、という意味"}],"myth":"宮の起源や夫婦岩の意味は神話・伝承。新居の場所は八重垣神社などにも伝承がある。","img":["スサノオ","クシナダヒメ","古事記"],"wp":"須我神社","rel":{"ev":[],"grave":[]},"ph":[["c:1/13/Suga_jinja.jpg",3872,2592,"須我神社"],["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"スサノオ"],["c:2/22/Yaegaki_Jinja_hekiga.jpg",750,1120,"クシナダヒメ"],["c:0/05/Kojiki_Shinpukuji.jpg",246,350,"古事記"]]},{"id":"32_susa_jinja","n":"須佐神社（スサノオの魂を鎮める）","yomi":"すさじんじゃ","cat":"寺社","rank":"A","y":733,"era":["myth","nara","edo"],"sh":"","ad":"出雲市佐田町須佐","st":"JR出雲市駅から車で約40分。バスは乗り換えが必要で本数が少ないので車が便利","la":35.2466,"lo":132.7213,"hook":"«この国は小さいけれど良い国だ» ――荒ぶる神スサノオが、最後に自分の魂を鎮めた山あいの社。","lead":"須佐神社は、スサノオが «自分の名を土地に残し、魂をここに鎮めた» と『出雲国風土記』に書かれた場所にある神社です。スサノオを主な祭神とし、スサノオの本拠地の一つとして大切にされてきました。境内には樹齢千年をこえるといわれる大杉が立っています。","story":["神話のスサノオは、泣きわめいて山を枯らし、姉アマテラスを怒らせて高天原を追い出された、とても荒々しい神です。けれども出雲では、オロチを退治した英雄であり、国を開いた神として語られてきました。","『出雲国風土記』の飯石郡・須佐郷の記事には、スサノオのこんなことばが残っています。«この国は小さい国だが、よい国処だ。だから自分の名を木や石にはつけない（土地の名にしよう）»。そしてスサノオは自分の御魂をここに鎮め、«大須佐田»«小須佐田» という田を定めた、と書かれています。","«なぜ、あの乱暴な神が、ここで静かに魂を鎮めたの?» 風土記の出雲では、スサノオは荒ぶるだけの神ではなく、土地を愛し、田を開く神でした。神々の物語が土地ごとにちがう顔をもっていたことがわかる、貴重な記事です。","神社には «七不思議» とよばれる言い伝えがあります。たとえば境内の «塩井» は、遠く稲佐の浜の海とつながっていて、潮の満ち引きで水の量が変わる――と伝わります。スサノオがこの水で国土を清めたともいわれます。","本殿の裏にそびえる大杉は、根回りがとても太く、樹齢はおよそ1300年といわれます。静まりかえった山里で大杉を見上げると、«ここにスサノオの魂が眠っている» と信じた昔の人の気持ちが少しわかる気がします。社家は代々、スサノオとクシナダヒメの子孫と伝える須佐氏がつとめてきました。"],"tl":[["神話の時代","スサノオが御魂をこの地に鎮めたと伝わる"],["733年","『出雲国風土記』に須佐郷の由来とスサノオのことばが記される"],["927年","『延喜式』神名帳に «須佐神社» が載る"],["江戸時代","松江藩主の崇敬を受け、社殿が整えられる"],["1861年","現在の本殿が建てられたとされる"]],"who":[["スサノオ（須佐之男命）","祭神。自分の魂をここに鎮めたと風土記に書かれる"],["クシナダヒメ（稲田比売命）","スサノオの妻。ともにまつられる"],["アシナヅチ・テナヅチ","クシナダヒメの父母。ともにまつられる"],["須佐氏","代々の宮司家。スサノオの子孫と伝わる"]],"deep":["『出雲国風土記』の須佐郷の記事は、スサノオの «ことば» が直接書かれた数少ない史料です。『古事記』『日本書紀』の荒ぶるスサノオとくらべると、土地を開く穏やかな神の姿が見えてきます。","«須佐» の地名が先にあって、そこからスサノオの名が生まれた、と考える研究者もいます。神の名と地名のどちらが先かは諸説あります。","本殿は大社造で、江戸時代末に建てられたとされます。出雲大社と同じ大社造の本殿は出雲地方に多く、この形の広がりは古代出雲の信仰圏を考える手がかりになります。","七不思議には «塩井» のほか、«影無桜»«相生の松» などが挙げられますが、数え方や中身は資料によって少しちがいます。","2000年代以降、テレビや雑誌で «パワースポット» として紹介され、参拝者が大きく増えました。静かな信仰の場なので、大杉の根を踏まないなど、マナーを守ることが大切です。"],"look":["本殿（大社造）","本殿裏の大杉","塩井（七不思議の一つ）","須佐の山あいの田（風土記の «須佐田» を思い浮かべて）"],"q":["『出雲国風土記』で、スサノオは自分の名を何につけないと言った？","«木や石» にはつけない、と言い、土地（須佐）に名を残したと書かれています。"],"koji":[],"myth":"七不思議・大杉の樹齢・宮司家の系譜は伝承。本殿の建築年は資料により幅がある。","img":["スサノオ","出雲国風土記","大社造"],"wp":"須佐神社","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"スサノオ"],["c:5/53/Izumo-taisha_121538651_f69f257ed0_o.jpg",1935,1413,"大社造"],["c:f/f7/Susa-jinja-honden.jpg",1000,1238,"近く: 佐田町"],["c:7/76/Main_Sanctuary_of_Susa-jinja_001.jpg",2763,2073,"近く: 須佐神社 (出雲市)"]]},{"id":"32_mononobe","n":"物部神社（石見国一之宮）","yomi":"もののべじんじゃ","cat":"寺社","rank":"A","y":513,"era":["kofun","heian","edo"],"sh":"","ad":"大田市川合町川合","st":"JR山陰本線・大田市駅から石見交通バスで約15分、«川合» 付近下車","la":35.1545,"lo":132.5045,"hook":"太陽を背負った鶴の紋。古代の軍事氏族 «物部氏» の祖先神が、石見の山里にまつられている。","lead":"物部神社は石見国の一之宮で、古代の有力豪族・物部氏の祖とされるウマシマジノミコトをまつります。神武天皇の東征を助けた神が、のちに石見へ来て国をしずめたと伝わります。宮中と同じく «鎮魂祭» を伝える神社として知られます。","story":["『日本書紀』などによると、初代とされる神武天皇が大和へ向かったとき、大和の豪族ニギハヤヒの子ウマシマジは天皇に従い、国を平らげるのを助けました。物部氏はこのウマシマジを祖先とする一族で、大和朝廷の軍事や祭りを担った名門です。","神社の伝えでは、ウマシマジはその後、尾張・美濃・越国をしずめたのち石見に入り、鶴に乗って «鶴降山（かくふざん）» に降り立ちました。やがて «八百山（やおやま）» のふもとが大和の天香具山に似ているとして宮をかまえ、ここで亡くなったといいます。本殿の裏に、ウマシマジの墓と伝わる «御神墓» があります。","社紋は «ひおい鶴»。赤い太陽を背負った鶴の姿で、鶴に乗って来たという伝説から生まれたものです。«なぜ石見に物部の神がいるの?» 物部氏の一族がこの地方に勢力をもっていたためとも、朝廷が西の守りとして物部の神をまつったためとも考えられていますが、はっきりとはわかりません。","毎年11月24日には «鎮魂祭» が行われます。ゆらゆらと魂をゆり動かし、体にしっかりつなぎとめて元気を取り戻させる古い祭りで、宮中でも新嘗祭の前に行われてきました。物部氏はこの鎮魂の技を伝える家とされてきたのです。","江戸時代には石見の人々の «一宮さん» として親しまれ、近くの石見銀山で働く人々からも信仰を集めたといわれます。代々の宮司は物部氏の流れをくむと伝える金子家がつとめてきました。"],"tl":[["伝承","ウマシマジが石見に入り、この地に鎮まったと伝わる"],["513年","社伝では継体天皇8年に社殿が建てられたとされる"],["927年","『延喜式』神名帳に石見国安濃郡 «物部神社» が載る"],["平安時代後期","石見国一宮として国司の崇敬を受ける"],["江戸時代","石見の一宮として広く信仰される"]],"who":[["ウマシマジノミコト（宇摩志麻遅命）","祭神。物部氏の祖とされる"],["ニギハヤヒノミコト","ウマシマジの父とされる神"],["神武天皇","初代とされる天皇。ウマシマジが東征を助けたと伝わる"],["金子家","代々の宮司家。物部氏の子孫と伝える"]],"deep":["社伝で社殿創建を継体天皇8年（513年）とするのは、神社の伝えです。この時代の社殿を裏づける史料や遺構は確かめられていません。","鎮魂祭は、『先代旧事本紀』でニギハヤヒが天から授かった «十種神宝» を使って魂をふるい起こす祭りに由来するとされます。『先代旧事本紀』は物部氏の伝承を多くふくむ書物ですが、成立時期や性格については議論があります。","«ひおい鶴» の紋は、鶴に乗って鶴降山に降りたという伝承にもとづきます。鶴降山は神社の南方の山で、山頂近くに降臨の地とされる場所があります。","物部氏は6世紀、仏教をめぐって蘇我氏と争い、物部守屋が587年に滅ぼされました。しかし一族はその後も各地に残り、石上神宮（奈良）など物部系の神社が各地に伝わります。","本殿の裏手の小高い丘にある «御神墓» は、ウマシマジの墓と伝わる場所です。古墳かどうかも含め、学術的な調査結果ははっきりしていません。"],"look":["本殿と «ひおい鶴» の社紋","本殿裏の御神墓（ウマシマジの墓と伝わる）","境内の «一宮» の碑","11月24日の鎮魂祭（見学は神社に確認を）"],"q":["物部神社の社紋 «ひおい鶴» は、鶴が何を背負った姿？","赤い太陽です。ウマシマジが鶴に乗って降りてきたという伝説から生まれました。"],"koji":[],"myth":"ウマシマジの石見入りと御神墓、513年創建はいずれも社伝。宮司家の系譜も伝承。","img":["物部氏","宇摩志麻遅命","一宮"],"wp":"物部神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/ad/Isonokami.jpg",640,334,"物部氏"],["c:f/f1/Umashimaji_by_Kikuchi_Y%C5%8Dsai.png",1784,2632,"宇摩志麻遅命"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"32_mizuwakasu","n":"水若酢神社（隠岐国一之宮）","yomi":"みずわかすじんじゃ","cat":"寺社","rank":"A","y":1795,"era":["nara","heian","edo"],"sh":"国の重要文化財（本殿）","ad":"隠岐郡隠岐の島町郡","st":"隠岐・西郷港から車で約25分（路線バスもあるが本数は少ない）","la":36.287,"lo":133.241,"hook":"日本海に浮かぶ隠岐の島で、海と国土を守ってきた一之宮。屋根の上に «隠岐造» という独特の形が見られる。","lead":"水若酢神社は隠岐国の一之宮で、隠岐の島（島後）の北西部にあります。祭神の水若酢命は、隠岐の国土を開き、日本海の守りについた神と伝わります。本殿は隠岐だけに見られる «隠岐造» で、国の重要文化財です。","story":["本土から船で2時間あまり。隠岐の島後の北西、田んぼに囲まれた杉の森の中に水若酢神社はあります。平安時代の『延喜式』では、全国でも格の高い «名神大社» とされていました。小さな島の神社が、なぜそれほど重んじられたのでしょう。","答えの一つは «海» です。隠岐は大陸や朝鮮半島にも近い日本海の島。都の人にとって、ここは海の向こうとの境目でした。祭神の水若酢命は、隠岐の国土をひらき、日本海の守りについた神と伝わります。海を越えてくるものを見張る神として、朝廷からもあつく敬われたと考えられます。","神社の言い伝えでは、水若酢命はもともと島の北西の海岸に現れ、のちに今の場所へ移されたともいいます。一方で、洪水で社殿が流され、今の場所に移ったという話も伝わっていて、元の場所ははっきりしません。","本殿は江戸時代後期に建てられた «隠岐造»。屋根は茅ぶきで、入口の前に屋根付きの向拝がつき、その向拝が本体の屋根とは別に作られているのが特徴です。春日造や大社造と似ているようで少しちがう、島でうまれた形なのです。","この神社の祭礼では、偶数年の5月に «祭礼風流» が行われ、流鏑馬や山車が奉納されます。また境内には土俵があり、隠岐の «古典相撲» が行われることもあります。一晩中続き、同じ二人が2番取って1勝1敗で分ける «人情相撲» で知られています。"],"tl":[["伝承","水若酢命が隠岐の国土を開いたと伝わる"],["平安時代前期","朝廷から神階を授けられたことが国史に見える"],["927年","『延喜式』神名帳で名神大社とされる"],["1795年","現在の本殿が建てられたとされる"],["昭和時代","本殿が国の重要文化財に指定"]],"who":[["水若酢命","祭神。隠岐の国土を開いた神と伝わる"],["後鳥羽上皇","承久の乱のあと隠岐に流された。一宮として崇敬したと伝わる"],["隠岐の島の人々","祭礼風流や古典相撲を代々受け継いできた"]],"deep":["«隠岐造» は、切妻・妻入りの本体の前に、屋根が独立した向拝をつける形で、隠岐の島々の神社に見られる独自の本殿形式です。水若酢神社と玉若酢命神社の本殿がその代表とされます。","本殿の建築年は、棟札などから寛政7年（1795年）とされます。茅ぶきの大きな屋根と千木・鰹木の組み合わせは、島の神社建築の特徴をよく示しています。","『延喜式』では隠岐国の名神大社は4座とされ、水若酢神社もその一つです。小さな島国に名神大社が複数あったことは、古代の隠岐の重要性を物語っています。","境内には古墳があり、この一帯が古代から島の有力者の拠点だったことがうかがえます。","隠岐の古典相撲は、神社の遷宮や大きな慶事のときに行われる特別な相撲で、一晩かけて行われます。勝ち負けで恨みを残さないよう、同じ組み合わせで2番取り、1勝1敗にするのが習わしです。"],"look":["隠岐造の本殿（茅ぶき屋根と独立した向拝）","境内の古墳","土俵（古典相撲の舞台）","隣接する «隠岐郷土館»（明治の旧周吉外三郡役所の建物）"],"q":["隠岐の神社に見られる独特の本殿の形を何という？","«隠岐造（おきづくり）»。本体の屋根とは別の屋根をもつ向拝が特徴です。"],"koji":[],"myth":"祭神の由来や元の鎮座地は伝承で諸説。本殿の建築年は棟札による通説。","img":["隠岐の島町","隠岐郷土館","隠岐諸島"],"wp":"水若酢神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/Mizuwakasu-jinja_shaden.JPG",6016,4000,"水若酢神社"],["c:7/72/Mizuwakasu-jinja_suizhin-mon.jpg",5986,3954],["c:b/b9/Mizuwakasu-jinja_ninotorii.jpg",6016,4000],["c:f/fd/Mizuwakasu-jinja_kofun-1.jpg",6014,3996],["c:c/c8/Mizuwakasu-jinja_ichinotorii.jpg",5994,3966],["c:5/5c/Mizuwakasu-jinja_honden.jpg",6016,4000],["c:0/03/Rosoku-is.jpg",1024,768,"隠岐の島町"],["c:9/96/Oki_Kyodo-kan.jpg",6016,4000,"隠岐郷土館"]]},{"id":"32_tamawakasu","n":"玉若酢命神社と億岐家（隠岐国総社）","yomi":"たまわかすのみことじんじゃとおきけ","cat":"寺社","rank":"A","y":1795,"era":["nara","heian","edo"],"sh":"国の重要文化財（本殿・億岐家住宅ほか）","ad":"隠岐郡隠岐の島町下西","st":"隠岐・西郷港から車で約10分","la":36.2178,"lo":133.3,"hook":"奈良時代の役所の «鈴» が、いまも神主の家に残っている――全国でここにしかない古代の宝をもつ、隠岐の総社。","lead":"玉若酢命神社は隠岐国の «総社» で、隠岐の島（島後）の西郷の近くにあります。宮司の億岐家は古代の隠岐国造の子孫と伝わり、奈良時代の «駅鈴» や «隠岐倉印» を今に伝えています。境内の «八百杉» は国の天然記念物です。","story":["総社とは、国司が国内の神々をまとめてお参りできるように、国府の近くにまつった神社のことです。玉若酢命神社は隠岐国の総社とされ、この近くに隠岐の国府があったと考えられています。","神社のとなりには、代々の宮司・億岐家の住宅があります。億岐家は古代にこの島を治めた «隠岐国造» の子孫と伝わる家で、ここには驚くべき宝が伝えられてきました。«駅鈴（えきれい）» です。","駅鈴は、奈良時代に都と地方を結んだ «駅制» で使われた鈴で、役人がこれを持っていれば各地の駅で馬を乗りつぐことができました。いわば古代の «通行証» です。«なぜ隠岐に残ったの?» 国司が持っていた駅鈴を、国造の家が大切に預かり続けたためとも考えられています。現存する駅鈴としては全国でここだけのものとされ、いっしょに伝わる «隠岐倉印» とともに国の重要文化財です。","境内にそびえる «八百杉» は、幹回りが10mをこえる巨木で、樹齢は千年とも二千年ともいわれます。若狭から来た八百比丘尼（はっぴゃくびくに）という尼が植えた、という伝説があり、それが名前の由来です。人魚の肉を食べて八百歳まで生きたという、不思議な伝説の人物です。","毎年6月5日の例祭では «御霊会風流» が行われ、島の各地から馬に乗った人が集まって、神社の石段の下の参道を駆け上がる «馬入れ神事» が奉納されます。島の人々が千年以上守ってきた祭りの熱気が感じられる一日です。"],"tl":[["古代","隠岐国造の一族がこの地を拠点にしたと伝わる"],["奈良時代","駅制のもと、駅鈴が隠岐の国司に与えられたと考えられる"],["927年","『延喜式』神名帳に «玉若酢命神社» が載る"],["1795年","現在の本殿が建てられたとされる"],["現代","本殿・億岐家住宅・駅鈴などが国の重要文化財に"]],"who":[["玉若酢命","祭神。隠岐の国土を開いた神と伝わる"],["億岐家","代々の宮司。隠岐国造の子孫と伝わる"],["八百比丘尼","八百杉を植えたと伝わる伝説の尼"],["隠岐の国司","都から来た役人。総社を通じて国内の神々を拝んだ"]],"deep":["駅鈴は律令制の駅制で使われた鈴で、使う資格によって刻みの数が決まっていたとされます。億岐家の駅鈴は古代の実物が伝わる唯一の例とされ、伝来については «光格天皇に献上して返された» など、江戸時代の逸話も伝わります。","«隠岐倉印» は隠岐国の役所の倉（正倉）の印とされる銅印です。古代の国の印の実物が伝わるのはめずらしく、駅鈴とあわせて古代地方行政の貴重な資料です。","億岐家住宅は江戸時代後期の建物で、隠岐の上層農家・社家の造りをよく示すとして国の重要文化財になっています。駅鈴などは宝物館で見学できます（公開日時は事前に確認を）。","本殿は水若酢神社と同じ «隠岐造» で、国の重要文化財です。茅ぶきの屋根に、本体とは別の屋根をもつ向拝がつきます。","八百杉は国の天然記念物。八百比丘尼の伝説は若狭（福井県）を中心に全国に伝わり、各地に «比丘尼が植えた木» の話が残っています。"],"look":["隠岐造の本殿","八百杉（国の天然記念物）","億岐家住宅と宝物館の駅鈴・隠岐倉印","6月5日の御霊会風流・馬入れ神事"],"q":["億岐家に伝わる、古代の «通行証» のような役目をした宝物は？","«駅鈴»。これを持つ役人は駅で馬を乗りつぐことができました。"],"koji":[],"myth":"億岐家の系譜、八百杉の植樹と樹齢は伝承。駅鈴の伝来の逸話にも諸説。","img":["駅鈴","億岐家住宅","八百比丘尼"],"wp":"玉若酢命神社","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Tamawakasumikoto_jinja_Haiden.JPG",2352,1568,"玉若酢命神社"],["j:0/0b/%E9%9A%A0%E5%B2%90%E5%9B%BD%E9%A7%85%E9%88%B4_%28%E8%A4%87%E8%A3%BD%29.JPG",4195,2799],["j:1/10/%E9%9A%A0%E5%B2%90%E5%80%89%E5%8D%B0_%28%E8%A4%87%E8%A3%BD%29.JPG",3712,2476],["c:0/0f/Yaosugi.jpg",2352,1568],["c:9/9a/Tamawakasumikoto_jinja_Zuishinmon.JPG",2352,1568],["c:a/a6/Tamawakasumikoto_jinja_Old_Haiden.JPG",2352,1568],["c:c/c3/Tamawakasumikoto_jinja_Honden.JPG",2352,1568],["c:d/dd/Tamawakasumikoto_jinja_Gate.JPG",2352,1568]]},{"id":"32_gakuenji","n":"鰐淵寺（出雲の山岳仏教の拠点）","yomi":"がくえんじ","cat":"寺社","rank":"A","y":594,"era":["asuka","kamakura","muromachi"],"sh":"国指定史跡（鰐淵寺境内）","ad":"出雲市別所町","st":"一畑電車・雲州平田駅から車で約20分。バスは少ないので車かタクシーで","la":35.4222,"lo":132.7253,"hook":"滝に落とした仏具を、鰐（わに）がエラにかけて持ってきた――不思議な名を持つ、出雲大社と一体だった山の寺。","lead":"鰐淵寺は島根半島の山の中にある天台宗の古い寺です。飛鳥時代に始まったと伝わり、中世には出雲大社と深く結びついて、出雲でいちばん大きな勢力をもつ寺となりました。後醍醐天皇の願文や、飛鳥時代の銅の観音像など、貴重な宝が伝わります。","story":["寺の言い伝えによると、推古天皇の時代、信濃の智春上人という僧がこの山の «浮浪の滝» で修行していました。あるとき、仏にそなえる道具を滝つぼに落としてしまいます。すると鰐（サメのこととも）がそれをエラにかけて浮かび上がってきた――そこで «鰐淵寺» という名がついた、と伝わります。","平安時代の末から、鰐淵寺は比叡山延暦寺とつながる天台宗の寺として大きくなり、たくさんの僧が山の中の坊に住みました。そして出雲大社（当時の杵築大社）と深くかかわり、大社の祭りや造営にも関わるようになります。神と仏をいっしょに拝む «神仏習合» の時代、出雲大社のまつる神は仏とも結びつけて考えられていました。","南北朝の動乱のとき、隠岐を脱出して天下を取りもどそうとした後醍醐天皇は、鰐淵寺の僧・頼源（らいげん）に勝利を祈らせました。寺には、天皇自らが書いたとされる願文が残り、国の重要文化財になっています。«都の天皇が、出雲の山寺にまで願いをかけた» ――この寺の力の大きさがわかります。","戦国時代には尼子氏、その後は毛利氏がこの寺を保護しました。しかし江戸時代になると、出雲大社は仏教色をなくす方向に動き、明治の神仏分離で両者の関係は完全に切れました。今の鰐淵寺は、苔むした石段と杉木立の中に堂が点在する、静かな山寺です。","秋には境内がもみじで真っ赤に染まり、出雲でも有数の紅葉の名所になります。駐車場から本堂まで、渓流沿いの参道を15分ほど歩きます。途中から «浮浪の滝» へ分かれる道もあり、岩の割れ目に建つ蔵王堂を見上げることができます。"],"tl":[["594年","推古天皇2年、智春上人が開いたと伝わる"],["平安時代後期","天台宗の寺として勢力を広げる"],["鎌倉〜南北朝時代","杵築大社と深く結びつき、出雲最大の寺院勢力に"],["1332〜1333年ごろ","後醍醐天皇が鰐淵寺に祈願する"],["戦国時代","尼子氏・毛利氏の保護を受ける"],["明治初め","神仏分離により出雲大社との関係が絶たれる"]],"who":[["智春上人","寺を開いたと伝わる僧"],["後醍醐天皇","隠岐から戻る前後、鰐淵寺に勝利を祈った"],["頼源","鰐淵寺の僧。後醍醐天皇の祈祷にかかわった"],["尼子経久","戦国大名。寺を保護し、大社との関係の調整にもかかわった"]],"deep":["寺宝の «銅造観世音菩薩立像» には «壬辰年» の銘があり、692年を指すと考えるのが一般的です。出雲の地で飛鳥時代の年紀をもつ仏像が伝わることは、古代出雲の仏教を考える上で重要です（国の重要文化財）。","中世の鰐淵寺は、杵築大社の «別当寺»（神社を管理する寺）のような立場にあったとされます。大社の祭神を仏教的に «スサノオ» とする考えが広まったことにも、鰐淵寺の僧が関わったとする研究があります。","南北朝時代の鰐淵寺文書は、中世の出雲の歴史を知るための一級史料とされ、寺の僧が武士や大社とどう関わったかを伝えています。","寺の境内は2015年に国の史跡に指定されたとされます。山中に残る多くの坊跡の石垣や平坦地は、中世の大寺院の広がりをしのばせます。","武蔵坊弁慶がここで修行したという言い伝えもありますが、史実としては確かめられていません。"],"look":["浮浪の滝と岩窟の蔵王堂","根本堂と参道の石段","坊跡の石垣（中世の大寺院の名残り）","秋のもみじ"],"q":["鰐淵寺の名の由来になったと伝わる生きものは？","«鰐（わに）»。滝に落ちた仏具をエラにかけて浮かび上がったと伝わります。"],"koji":[],"myth":"開山と寺名の由来、弁慶修行は伝承。史跡指定年は要確認。","img":["出雲大社","後醍醐天皇","神仏習合"],"wp":"鰐淵寺","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Gakuenji_temple_Konpondo.jpg",3872,2592,"鰐淵寺"],["c:b/b4/Gakuenji_temple_Zaodo.jpg",2592,3872],["c:e/eb/Gakuenji_temple.JPG",3872,2592],["c:1/1c/Haiden_of_Izumo-taisha-1.JPG",5077,3377,"出雲大社"],["c:0/0b/Emperor_Godaigo_by_Monkan-b%C5%8D_K%C5%8Dshin.jpg",1863,1860,"後醍醐天皇"]]},{"id":"32_dainenji_kofun","n":"大念寺古墳（巨大な横穴式石室）","yomi":"だいねんじこふん","cat":"遺跡","rank":"A","y":570,"era":["kofun","edo"],"sh":"国指定史跡","ad":"出雲市今市町","st":"JR出雲市駅から歩いて約10分","la":35.369,"lo":132.761,"hook":"江戸時代、寺の裏の土手から突然現れた «大きな部屋»。中には大人が寝られるほどの巨大な石の棺が眠っていた。","lead":"今市大念寺古墳は、出雲市の中心街にある出雲地方最大の前方後円墳です。6世紀後半につくられ、内部には全長約13mの横穴式石室があります。奥の家形石棺は日本最大級の大きさで、出雲西部の有力な王の墓と考えられています。","story":["江戸時代の後半、今市の大念寺の裏で、村人たちが土を掘っていると、突然ぽっかりと穴があきました。のぞいてみると中には大きな石で組まれた部屋があり、その奥には家の形をした巨大な石の棺が置かれていた――そんな発見の話が伝わります。","見つかった石室は、全長約13m。入口から奥まで、大きな石を積み上げた通路と部屋がつづいています。奥の石棺は長さ3m以上、高さも人の背丈ほどあり、一つの大きな石をくりぬいたふたと身でできています。«なぜこんなに大きな棺が必要だったの?» ――棺の大きさそのものが、葬られた人の力を見せつける役目を持っていたと考えられています。","古墳は全長約90mの前方後円墳で、出雲地方ではいちばんの大きさです。つくられたのは6世紀の後半。同じころ、出雲の東部（今の松江市あたり）には前方後方墳の山代二子塚古墳がつくられています。東は «方»、西は «円»。形のちがう大きな古墳が東西に並び立つことから、当時の出雲には東と西に二つの大きな勢力があったのでは、と考えられています。","やがて7世紀に入ると、出雲の中心は東部の意宇（おう）に移り、出雲国造の本拠も東部に置かれました。一方で出雲大社は西部にあります。この «東と西» の関係が、出雲の古代史を解くカギの一つになっています。","古墳は今、大念寺というお寺の境内にあり、墳丘の上には墓地が広がっています。住宅街の中に突然あらわれる巨大な古墳は、古代の王の力を今に伝えています。"],"tl":[["6世紀後半","前方後円墳が築かれる"],["1826年","文政9年、石室が見つかったと伝わる"],["1924年","国の史跡に指定"],["昭和〜平成","測量や調査が進み、墳丘の形や大きさが確かめられる"]],"who":[["葬られた王","出雲西部を治めた有力者と考えられる（名前は不明）"],["今市の村人","江戸時代に石室を掘りあてたと伝わる"],["出雲国造","7世紀以降、出雲を代表した一族。東部に本拠を置いた"]],"deep":["墳丘の長さは約91〜92mとされ、出雲地方最大の前方後円墳です。ただし住宅地や墓地になっている部分も多く、もとの形の復元には推定がふくまれます。","横穴式石室は全長12.8mほどとされ、玄室と前室からなります。奥の家形石棺は «日本最大級» とよばれ、長さ3.3m前後、ふたを含めた高さも大人の背丈ほどあります。","石室の発見のときに、金銅製の馬具や大刀などが出たと伝わりますが、多くは散らばってしまい、行方のわからないものもあります。","出雲東部の前方後方墳（山代二子塚古墳）と西部の前方後円墳（大念寺古墳）が同じころに築かれたことから、«東西二大勢力» 説が語られます。ただし、両者の関係や、どちらが上位だったかについては諸説があります。","近くの «上塩冶築山古墳» も巨大な横穴式石室と2つの家形石棺をもつ古墳で、大念寺古墳の次の世代の王墓と考えられています。あわせて見ると、出雲西部の王の系譜が想像できます。"],"look":["墳丘の形（前方部と後円部の高さのちがい）","石室の入口（見学の可否は事前に確認を）","大念寺の境内と説明板","近くの上塩冶築山古墳"],"q":["大念寺古墳の形は、前方後円墳？前方後方墳？","前方後円墳です。出雲東部の大古墳・山代二子塚古墳は前方後方墳で、形がちがいます。"],"koji":[],"myth":"発見の年と状況は伝えによる。東西二大勢力説は有力な仮説で、異論もある。","img":["上塩冶築山古墳","横穴式石室","前方後円墳"],"wp":"今市大念寺古墳","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/Imaichi_Dainenji_Kofun%2C_entrance-1.jpg",5568,3712,"今市大念寺古墳"],["c:0/0c/Kamienya_Tsukiyama_Kofun%2C_3D-B-2.jpg",12720,7155],["c:4/44/Kamienya_Jizoyama_Kofun%2C_3D-B-2.jpg",11685,6573],["c:7/75/Imaichi_Dainenji_Kofun_zenkei.JPG",5090,3324],["c:a/a9/Imaichi_Dainenji_Kofun_funcho.JPG",6016,4000],["c:b/b9/Imaichi_Dainenji_Kofun%2C_zenshitsu-2.jpg",5568,3712],["c:2/27/Imaichi_Dainenji_Kofun%2C_zenshitsu-1.jpg",5568,3712],["c:2/22/Imaichi_Dainenji_Kofun%2C_zenshitsu%2C_sekkan.jpg",5568,3712]]},{"id":"32_futagozuka","n":"山代二子塚古墳（前方後方墳）","yomi":"やましろふたごづかこふん","cat":"遺跡","rank":"A","y":550,"era":["kofun"],"sh":"国指定史跡","ad":"松江市山代町","st":"JR松江駅から市営バスで約20分、«山代町» 付近下車、歩いて数分","la":35.438,"lo":133.101,"hook":"«前方後方墳» ――教科書に出てくるこのことばは、この古墳を調べた研究者が名づけたといわれる。","lead":"山代二子塚古墳は、松江市の南にある全長約94mの前方後方墳です。6世紀中ごろにつくられ、この形の古墳としては同時代で全国最大級。出雲東部を治めた大王の墓と考えられています。「前方後方墳」ということばが最初に使われた古墳として知られます。","story":["前が四角、うしろも四角。空から見ると、二つの四角をつなげたような形――それが前方後方墳です。前方後円墳にくらべて数が少なく、とくに6世紀にこんなに大きなものが造られたのは、全国でもめずらしいことです。","«なぜ出雲東部では四角なの?» 出雲では、弥生時代から四角い形の «四隅突出型墳丘墓» がつくられてきました。四角い墓にこだわる伝統が、この地域にはあったのかもしれません。前方後方墳を造り続けた出雲東部の王たちは、大和の王権と結びつきながらも、自分たちの形を守ったと考える研究者もいます。","大正時代、この古墳を調べた地元の研究者・野津左馬之助が、この形を «前方後方墳» とよびました。今では全国で使われる考古学の用語が、ここから生まれたといわれています。","ところが昭和の時代、古墳の一部は土取りのために大きく削られてしまいました。今では、削られた断面を利用して «古墳がどうやって土を盛ってつくられたか» を見せる工夫がされ、墳丘の一部は芝生で元の姿に整備されています。","この一帯は «八雲立つ風土記の丘» とよばれ、出雲国府跡や国分寺跡、岡田山1号墳（«額田部臣» の文字が入った大刀が出た古墳）などが集まっています。古墳の上に立つと、奈良時代に出雲の国の政治の中心となった意宇平野を見渡すことができます。"],"tl":[["6世紀中ごろ","前方後方墳が築かれる"],["大正時代","野津左馬之助が «前方後方墳» の名を用いたといわれる"],["1924年","国の史跡に指定"],["昭和時代","土取りで墳丘の一部が削られる"],["平成","墳丘の復元整備とガイダンス施設の整備が進む"]],"who":[["葬られた王","出雲東部の大首長と考えられる（名前は不明）"],["野津左馬之助","島根の郷土史家。«前方後方墳» の名を使ったといわれる"],["出雲国造","のちに意宇を本拠とした一族。この古墳の主の子孫とみる説もある"]],"deep":["全長は約94mとされ、6世紀の前方後方墳としては全国最大級です。後方部の高さは約9m。まわりには周溝がめぐっていました。","«前方後方墳» の名は、大正時代にこの古墳を記録した野津左馬之助が使ったのが最初、というのが通説です。学術用語として広まったのはその後のことです。","出雲東部には、ほかにも前方後方墳が集中しています。これを、出雲国造につながる東部勢力の «しるし» とみる見方があります。","西部の今市大念寺古墳（前方後円墳）との比較から、6世紀の出雲には東西二つの勢力があったとする説が語られます。両者の関係については諸説があります。","近くの «ガイダンス山代の郷» では、古墳の模型や解説が見られ、周辺の山代方墳や大庭鶏塚古墳とあわせて歩くコースがあります。"],"look":["前方部と後方部の形（上から見ると «二つの四角»）","削られた断面を活かした展示","ガイダンス山代の郷","周辺の大庭鶏塚古墳・山代方墳"],"q":["山代二子塚古墳の形の名前は？","«前方後方墳»。前も後ろも四角い形で、この名はこの古墳を調べた研究者が使ったといわれます。"],"koji":[],"myth":"«前方後方墳» 命名の経緯は通説。削られた時期や範囲は資料により差がある。","img":["前方後方墳","八雲立つ風土記の丘","出雲国府"],"wp":"山代二子塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:0/00/Yamashiro_Futagozuka_Kofun%2C_funkyu-2.jpg",5568,3712,"山代二子塚古墳"],["c:9/90/Yamashiro_Futagozuka_Kofun%2C_zenpoubu.jpg",5568,3712],["c:1/19/Yamashiro_Futagozuka_Kofun%2C_kouhoubu.jpg",5554,3692],["c:7/7d/Yamashiro_Futagozuka_Kofun%2C_danmen.jpg",13898,4780],["c:2/28/Yamashiro_Futagozuka_Kofun%2C_danmen-2.jpg",5544,3676],["j:e/e6/%E5%B1%B1%E4%BB%A3%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3_%E5%86%86%E7%AD%92%E5%9F%B4%E8%BC%AA.JPG",4750,3565],["j:6/6e/%E5%B1%B1%E4%BB%A3%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3_%E5%87%BA%E5%9C%9F%E5%93%81_%28%E5%B3%B6%E6%A0%B9%E5%A4%A7%E5%AD%A6%E7%B7%8F%E5%90%88%E5%8D%9A%E7%89%A9%E9%A4%A8%E5%B1%95%E7%A4%BA%29.JPG",4850,3196],["j:8/82/%E5%B1%B1%E4%BB%A3%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3_%E5%87%BA%E9%9B%B2%E5%9E%8B%E5%AD%90%E6%8C%81%E5%A3%BA_%28%E5%B3%B6%E6%A0%B9%E5%A4%A7%E5%AD%A6%E7%B7%8F%E5%90%88%E5%8D%9A%E7%89%A9%E9%A4%A8%E5%B1%95%E7%A4%BA%29.JPG",3676,4937]]},{"id":"32_kanbara_kofun","n":"神原神社古墳（景初三年銘の鏡）","yomi":"かんばらじんじゃこふん","cat":"遺跡","rank":"A","y":350,"era":["kofun"],"sh":"","ad":"雲南市加茂町神原","st":"JR木次線・加茂中駅から歩いて約20分。車なら加茂岩倉遺跡とあわせて回るのが便利","la":35.3235,"lo":132.836,"hook":"«景初三年» ――卑弥呼が魏に使いを送った年が刻まれた鏡が、出雲の神社の下から出てきた。","lead":"神原神社古墳は、雲南市加茂町の神原神社の境内にあった4世紀の方墳です。1972年の発掘で、«景初三年»（239年）の文字が入った三角縁神獣鏡が見つかりました。邪馬台国の女王・卑弥呼が魏から鏡をもらった年と同じで、大きな話題になりました。","story":["1972年、斐伊川の支流・赤川の改修工事のため、川ぞいにあった神原神社を移すことになりました。そこで社殿の下の古墳を調べたところ、竪穴式石室の中から、一枚の鏡が見つかります。","鏡のふちに近い部分に «景初三年» の文字。景初は中国・魏の年号で、景初三年は西暦239年です。『魏志倭人伝』によると、この年、邪馬台国の女王・卑弥呼は魏に使いを送り、«銅鏡百枚» などを与えられたとされます。«これが卑弥呼の鏡のうちの一枚では?»――発見はたちまち全国の注目を集めました。","鏡の種類は «三角縁神獣鏡»。ふちの断面が三角形で、神仙と獣の模様がある鏡です。この鏡が卑弥呼のもらった鏡かどうかは、じつは今も大きな論争です。中国では三角縁神獣鏡がほとんど見つかっていないため、«日本で作られた» とする説と «魏で作られた» とする説が対立しています。","いずれにしても、4世紀の出雲の首長が、大和の王権と深くつながる鏡を受け取っていたことはたしかです。古墳は一辺約30mの方墳で、竪穴式石室からは鏡のほか、大刀や鉄の道具なども出ました。","神社は移されましたが、石室は移築・復元されて、今は神社の横で見ることができます。すぐ近くの山には、39個の銅鐸が見つかった加茂岩倉遺跡もあります。弥生から古墳へ、出雲の «祭りの道具» がどう変わったのかを考えながら歩くと、ぐっと面白くなります。"],"tl":[["4世紀","方墳が築かれ、首長が葬られる"],["1972年","神社移転にともなう発掘で景初三年銘の三角縁神獣鏡が出土"],["その後","出土品が国の重要文化財に指定される"],["現在","石室が神社のそばに移築・復元され公開"]],"who":[["卑弥呼","邪馬台国の女王。239年に魏へ使いを送ったと『魏志倭人伝』にある"],["葬られた首長","4世紀の出雲の有力者（名前は不明）"],["発掘調査の関係者","1972年、神社移転の前に古墳を調べた"]],"deep":["«景初三年» 銘をもつ鏡は、神原神社古墳の三角縁神獣鏡のほか、大阪府の和泉黄金塚古墳の画文帯神獣鏡が知られています。どちらも卑弥呼の遣使の年と重なるため注目されます。","三角縁神獣鏡は日本各地で数百面見つかっていますが、中国ではほとんど出ていません。«魏鏡説» と «国産鏡説» があり、決着していません。","魏の年号の «景初» は三年までしか使われていないのに、別の古墳から «景初四年» 銘の鏡が見つかっていることも、この論争を複雑にしています。","古墳は一辺約30mの方墳とされます。出雲の前期古墳には方墳が多く、弥生時代の四隅突出型墳丘墓から続く «四角い墓» の伝統と関係づける見方もあります。","出土した鏡は現在、島根県立古代出雲歴史博物館などで展示されることがあります（展示状況は要確認）。"],"look":["移築・復元された竪穴式石室","神原神社の社殿","近くの加茂岩倉遺跡（銅鐸39個の出土地）","博物館で鏡の実物やレプリカを見る"],"q":["神原神社古墳の鏡に刻まれた «景初三年» は西暦何年？","239年。卑弥呼が魏に使いを送った年と同じです。"],"koji":[],"myth":"鏡が卑弥呼に贈られたものかは不明で、三角縁神獣鏡の製作地は諸説。","img":["三角縁神獣鏡","加茂岩倉遺跡","卑弥呼"],"wp":"神原神社古墳","rel":{"ev":[],"grave":[]},"ph":[["c:b/bb/Kanbara-jinja_Kofun%2C_sekishitsu-1.jpg",5568,3712,"神原神社古墳"],["c:a/ae/Kanbara-jinja_Kofun%2C_sekishitsu-2.jpg",5562,3702],["c:4/4f/Kanbara-jinja_Kofun%2C_gaikan.jpg",5568,3712],["c:1/10/Kanbara-jinja_%28Unnan%29%2C_shaden.jpg",5568,3712],["j:2/2f/%E7%A5%9E%E5%8E%9F%E7%A5%9E%E7%A4%BE%E5%8F%A4%E5%A2%B3_%E4%B8%89%E8%A7%92%E7%B8%81%E7%A5%9E%E7%8D%A3%E9%8F%A1.JPG",3169,3175],["j:8/88/%E7%A5%9E%E5%8E%9F%E7%A5%9E%E7%A4%BE%E5%8F%A4%E5%A2%B3_%E9%89%84%E8%A3%BD%E5%93%81.JPG",5158,3381],["j:d/db/%E7%A5%9E%E5%8E%9F%E7%A5%9E%E7%A4%BE%E5%8F%A4%E5%A2%B3_%E7%B4%A0%E7%92%B0%E9%A0%AD%E5%A4%A7%E5%88%80.JPG",4942,3294],["j:1/14/%E8%9F%B9%E6%B2%A2%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E4%B8%89%E8%A7%92%E7%B8%81%E5%90%8C%E5%90%91%E5%BC%8F%E7%A5%9E%E7%8D%A3%E9%8F%A1.JPG",3559,3359,"三角縁神獣鏡"]]},{"id":"32_tamatsukuri","n":"出雲玉作跡（勾玉づくりの工房）","yomi":"いずもたまつくりあと","cat":"遺跡","rank":"A","y":500,"era":["kofun","nara","heian"],"sh":"国指定史跡","ad":"松江市玉湯町玉造","st":"JR山陰本線・玉造温泉駅から歩いて約20分（玉造温泉街の奥）","la":35.415,"lo":133.015,"hook":"青い石から、神にささげる勾玉を――千年以上も «玉づくりの村» だった、古代出雲の工房のあと。","lead":"出雲玉作跡は、古墳時代から平安時代にかけて、勾玉や管玉などの «玉» をつくっていた工房の跡です。近くの花仙山でとれる青めのう（碧玉）などを材料にしていました。ここの玉は朝廷にも献上され、出雲の特別な力の象徴とされました。","story":["玉造温泉の奥にそびえる «花仙山（かせんざん）»。この山からは、青や赤、白のめのう、青い碧玉、水晶など、美しい石がとれます。古代の人々は、この石をけずってみがき、勾玉や管玉をつくりました。","工房の跡からは、作りかけの玉や、玉をみがくための砥石、細い穴をあけるための道具などが見つかっています。«どうやって硬い石に穴をあけたの?» 研究では、細い棒に砂をつけてまわしながら少しずつ穴をあけたと考えられています。一つの管玉に何日もかかったことでしょう。","出雲の玉は、ただのアクセサリーではありませんでした。奈良時代から平安時代、出雲の国造（くにのみやつこ）は都へ行き、天皇の前で «出雲国造神賀詞（かんよごと）» という祝いのことばを読み上げ、玉などをささげました。天皇の長寿と国の平和を祈る儀式で、玉はその力のしるしだったのです。","平安時代の『延喜式』にも、出雲国から毎年、宮中に玉を納めることが定められています。出雲の玉づくりは、朝廷の祭りを支える «国家の仕事» でもあったのです。","今、遺跡のあたりは «史跡公園» として整備され、工房の跡の場所がわかるようになっています。近くの «出雲玉作資料館» では、出土した玉や道具が展示されています。温泉街のお店では、今も花仙山のめのうを使った勾玉が売られていて、古代から続く «玉の里» の歴史を肌で感じられます。"],"tl":[["弥生時代","出雲で玉づくりが始まる"],["古墳時代","花仙山のめのう・碧玉を使った玉づくりが盛んに"],["奈良時代","出雲国造が神賀詞を読み、玉を天皇にささげる"],["平安時代","『延喜式』で出雲国の玉の献上が定められる"],["1922年","国の史跡に指定"]],"who":[["玉作部（たまつくりべ）","玉づくりに携わった人々の集団"],["出雲国造","神賀詞を読み、玉を天皇にささげた"],["フトダマノミコト","玉づくりにかかわる神と伝わる。玉作湯神社などの伝承に登場"]],"deep":["花仙山の石は、成分のちがいから «青めのう»（碧玉）、赤めのう、白めのうなどに分けられます。とくに濃い緑色の碧玉は «出雲石» ともよばれ、古代の管玉の材料として重んじられました。","出雲の碧玉製管玉は、近畿など各地の古墳からも見つかっています。産地を分析する研究によって、花仙山産と考えられる玉が広く流通していたことがわかってきました。","『延喜式』には «出雲国進年料御富岐玉（みほきだま）» の規定があり、出雲から毎年たくさんの玉を宮中に納めることになっていました。","出雲国造神賀詞は、国造が新しく任命されたときに都で奏上したもので、『延喜式』に文章が残ります。奈良時代から平安時代初めにかけて、何度も奏上の記録があります。","玉作跡は、宮垣地区・宮ノ上地区などいくつかの地点にわかれていて、史跡もそれらを合わせて指定されています。"],"look":["史跡公園の工房跡","出雲玉作資料館の出土品","花仙山の姿（遠くから）","玉作湯神社の出土品と «願い石»"],"q":["出雲の玉づくりの材料となった石がとれる山の名前は？","«花仙山（かせんざん）»。めのうや碧玉がとれます。"],"koji":[],"myth":"工房の年代幅や地区名は資料により差がある。","img":["勾玉","花仙山","出雲国造神賀詞"],"wp":"出雲玉作跡","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/140427_Izumo_Tamatsukuri_Historical_Park_Matsue_Shimane_pref_Japan02n.jpg",6000,4000,"出雲玉作跡"],["c:9/9c/140427_Izumo_Tamatsukuri_Historical_Park_Matsue_Shimane_pref_Japan09bs3.jpg",6000,4000],["c:6/69/140427_Izumo_Tamatsukuri_Historical_Park_Matsue_Shimane_pref_Japan01bs4.jpg",6000,4000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:0/00/Magatamas.JPG",3246,4048,"勾玉"]]},{"id":"32_tamatsukuri_onsen","n":"玉造温泉（風土記に «神の湯» と書かれた湯）","yomi":"たまつくりおんせん","cat":"町","rank":"A","y":733,"era":["nara","edo","showa"],"sh":"","ad":"松江市玉湯町玉造","st":"JR山陰本線・玉造温泉駅からバスで約5分、歩いて約20分","la":35.418,"lo":133.01,"hook":"«一度入れば顔かたちが美しくなり、二度入ればどんな病も治る»――1300年前の本に、そう書かれた温泉。","lead":"玉造温泉は、733年にできた『出雲国風土記』に «神の湯» と書かれた、日本でもとても古い温泉の一つです。玉湯川ぞいに旅館が並び、今は «美肌の湯» として知られています。近くには玉作湯神社や出雲玉作跡があり、玉づくりの里としての歴史も感じられます。","story":["『出雲国風土記』の意宇郡・忌部神戸の記事には、川のほとりにわく温泉のにぎわいが書かれています。男も女も、年寄りも若者も、道を行き来して集まり、市のようににぎやかで、にぎわいながら宴を楽しんでいる――そんな様子です。","そして、こう続きます。«一度すすげば顔かたちが美しくなり、二度浴びればたくさんの病がすべて治る。昔から今まで効きめのないことはない。だから人々は «神の湯» とよぶ»。1300年前の人たちも、この湯の力を心から信じていたのです。","«なぜ神の湯とよばれたの?» 風土記によると、この湯は出雲国造が都へ行って神賀詞を読む前に、身を清めた場所でもありました。国造が清める湯――だからこそ、ふつうの湯ではない «神の湯» だったと考えられています。","江戸時代になると、松江藩が温泉を大切に管理し、藩主やその家族が入る湯として一般の人の入浴が制限された時期があったと伝わります。明治時代以降は旅館街として発展し、昭和の時代には山陰を代表する温泉地の一つになりました。","今の温泉街には、玉湯川にかかる橋や川ぞいの小道に、勾玉のモニュメントや神話の像が並んでいます。足湯もあちこちにあり、歩きながら温泉を楽しむことができます。神社の «願い石» と、温泉の湯。古代から続く «祈り» と «癒し» の町です。"],"tl":[["733年","『出雲国風土記』に «神の湯» と記される"],["平安時代","玉作湯神社が『延喜式』神名帳に載る"],["江戸時代","松江藩の管理のもと、藩主の湯として大切にされたと伝わる"],["明治時代以降","旅館が増え、温泉街として発展"],["現在","«美肌の湯» として多くの観光客が訪れる"]],"who":[["出雲国造","都へ神賀詞を奏上する前に、ここで身を清めたとされる"],["少彦名命（スクナヒコナ）","温泉を開いたと伝わる神。玉作湯神社にまつられる"],["松江藩主","温泉を管理し、湯治に訪れたと伝わる"]],"deep":["風土記の原文には «一たび濯げば形容端正しく、再び浴すれば万の病悉に除ゆ» とあり、«神湯（かみのゆ）» の名が出てきます。温泉の効能が文字で書かれたものとしては、日本最古級です。","玉作湯神社は『延喜式』神名帳に載る古い神社で、温泉と玉づくりの神をまつります。境内の «真玉» は «願い石» とよばれ、願いをかなえる石として人気です。","泉質は硫酸塩泉などで、肌にやさしいといわれます。«美肌の湯» の評判は、風土記の «形容端正し» の記述とも重ねて語られています。","江戸時代に一般の入浴が制限されたという話は、地元で語られる «御留湯（おとめゆ）» の伝承です。その期間や範囲は資料によって書き方がちがいます。","温泉街の近くには、古墳時代から平安時代の玉づくり工房跡（出雲玉作跡）があり、«温泉» と «玉» が一つの里の中で結びついていたことがわかります。"],"look":["玉湯川ぞいの温泉街と足湯","玉作湯神社の «願い石»","勾玉橋など神話のモニュメント","出雲玉作資料館・出雲玉作跡"],"q":["『出雲国風土記』で、玉造温泉はなんとよばれていた？","«神の湯（神湯）»。二度入ればすべての病が治る、と書かれています。"],"koji":[{"w":"一たび濯げば形容端正しく、再び浴すれば万の病悉に除ゆ","m":"一度入れば姿が美しくなり、二度入れば病がすべて治る。『出雲国風土記』のことば"}],"myth":"藩主専用の湯（御留湯）の話は伝承。温泉を開いた神の話も伝承。","img":["出雲国風土記","玉作湯神社","出雲玉作跡"],"wp":"玉造温泉","rel":{"ev":[],"grave":[]},"ph":[["c:5/54/140427_Chorakuen_Tamatsukuri_Onsen_Matsue_Shimane_pref_Japan15s3.jpg",4000,2664,"玉造温泉"],["c:c/c8/140427_Tamatsukuri_Onsen_Matsue_Shimane_pref_Japan07bs.jpg",6000,4000],["c:c/ce/140427_Tamatsukuri_Onsen_Matsue_Shimane_pref_Japan02bs.jpg",6000,4000],["c:1/11/140427_Tamatsukuri_Onsen_Matsue_Shimane_pref_Japan01o.JPG",6000,4000],["c:f/fb/140427_Izumo_Tamatsukuri_Historical_Park_Matsue_Shimane_pref_Japan02n.jpg",6000,4000],["c:5/58/140426_Tamatsukuri_Onsen_Matsue_Shimane_pref_Japan01n.jpg",6000,4000],["c:4/45/Tamatsukuri_Onsen_Panoramic_view.JPG",2304,1536],["c:a/a6/Crab_cuisine_in_Tamatsukuri_Onsen.JPG",2304,1536]]},{"id":"32_taisha_keidai","n":"出雲大社境内遺跡（宇豆柱の発見）","yomi":"いずもたいしゃけいだいいせき","cat":"遺跡","rank":"A","y":1248,"era":["heian","kamakura","heisei"],"sh":"国指定史跡","ad":"出雲市大社町杵築東","st":"一畑電車・出雲大社前駅から歩いて約7分","la":35.402,"lo":132.6855,"hook":"«高さ48mの神殿なんて、ただの伝説だろう» ――その常識が、2000年、地面の下から出てきた3本組の巨大な柱で揺らいだ。","lead":"出雲大社の境内の地下からは、2000年に、鎌倉時代の本殿を支えていた巨大な柱 «宇豆柱» が見つかりました。直径1m以上の杉の丸太を3本たばねて1本の柱にしたもので、昔の大社本殿がとても高かったという言い伝えを裏づける発見となりました。","story":["平安時代の970年、源為憲という学者が子ども向けに書いた『口遊（くちずさみ）』に、こんな言葉があります。«雲太、和二、京三»。日本で大きな建物のベスト3は、1番が出雲の大社、2番が大和の東大寺大仏殿、3番が京の大極殿――という意味です。","大仏殿より大きい? 神社の伝えでは、大昔の本殿の高さは32丈（約96m）、中ごろには16丈（約48m）あったといいます。今の本殿は約24mですから、その倍です。長い間、これは «伝説» だと考えられてきました。","ところが2000年、境内の八足門の前で地下室をつくる工事の前に調査をすると、地面の下から巨大な柱の根元が出てきました。直径約1.35mの杉の丸太を3本、鉄の輪でたばねたように組み合わせた柱で、全体の直径は約3mもあります。これが «宇豆柱（うづばしら）»、本殿の正面中央の柱でした。","«3本をたばねた柱» ――じつは出雲国造の千家家には、昔の本殿の設計図と伝わる «金輪御造営差図（かなわのごぞうえいさしず）» が残っていて、そこにも3本の木を金輪でまとめた柱が描かれていました。絵図の通りの柱が、本当に地中から現れたのです。調査の結果、この柱は1248年（宝治2年）に造営された本殿のものと考えられています。","柱の発見で、«高さ48m» が本当だったかどうかがすべて決まったわけではありません。けれども、ふつうでは考えられない巨大な神殿が実際にあったことは、はっきりしました。見つかった宇豆柱は、近くの古代出雲歴史博物館で見ることができ、境内の地面には柱の位置を示す印がつけられています。"],"tl":[["970年","『口遊』に «雲太、和二、京三» と書かれる"],["1248年","宝治2年、本殿が造営される（宇豆柱はこの本殿のものと推定）"],["1744年","延享元年、現在の本殿が建てられる"],["2000年","八足門前の発掘で宇豆柱が見つかる"],["その後","宇豆柱などの出土品が国の重要文化財に。境内遺跡は国の史跡に指定"]],"who":[["源為憲","平安時代の学者。『口遊』で «雲太» と書いた"],["千家家","出雲国造の家。«金輪御造営差図» を伝えた"],["大国主大神","出雲大社の祭神"]],"deep":["宇豆柱は、直径約1.35mの杉材3本を組み合わせたもので、全体の直径は約3mとされます。同じ調査で、本殿中心の «心御柱» や側柱の根元も見つかりました。","柱の年代は、木材の年輪や、いっしょに出た土器などから、宝治2年（1248年）造営の本殿のものと推定されています。","«金輪御造営差図» は、本殿の平面図で、柱を3本ずつ金輪でまとめ、長い階段（引橋）が一町（約109m）続く様子が描かれています。描かれた時期には諸説があります。","«高さ16丈（約48m）» は神社の伝えと古い記録によるもので、発掘で高さそのものが確かめられたわけではありません。複数の建築史家が復元案を出していて、その模型は古代出雲歴史博物館で見られます。","平安時代の記録には、大社の本殿がたびたび «倒れた（転倒）» ことが書かれていて、それも本殿が非常に高かったことの裏づけと考えられています。"],"look":["八足門前の地面に示された宇豆柱の位置","現在の本殿（1744年造営、国宝）","古代出雲歴史博物館の宇豆柱の実物","本殿の復元模型（博物館）"],"q":["«雲太、和二、京三» の «雲太» はどの建物を指す？","出雲大社の本殿。日本一大きな建物という意味です。"],"koji":[{"w":"雲太、和二、京三","m":"出雲大社が1番、東大寺大仏殿が2番、平安京の大極殿が3番に大きい、という平安時代の覚え歌"}],"myth":"本殿の高さ（96m・48m）は伝承と記録による。差図の年代、復元案は諸説。","img":["出雲大社","宇豆柱","口遊"],"wp":"出雲大社境内遺跡","rel":{"ev":["fudoki"],"grave":[]},"ph":[["c:d/d4/Izumooyashiro84.JPG",1600,1200,"出雲大社境内遺跡"],["c:4/40/Izumo-shrine_Shin-no-mihashira.jpg",1600,1200],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:1/1c/Haiden_of_Izumo-taisha-1.JPG",5077,3377,"出雲大社"]]},{"id":"32_kodai_izumo_museum","n":"島根県立古代出雲歴史博物館","yomi":"しまねけんりつこだいいずもれきしはくぶつかん","cat":"学び","rank":"A","y":2007,"era":["yayoi","kofun","heisei"],"sh":"","ad":"出雲市大社町杵築東","st":"一畑電車・出雲大社前駅から歩いて約10分（出雲大社のすぐ東）","la":35.3985,"lo":132.689,"hook":"銅剣358本がずらりと並ぶ «青銅器の壁»。出雲が本当に «神話の国» だったことを、実物で見せてくれる博物館。","lead":"島根県立古代出雲歴史博物館は、2007年に出雲大社のとなりに開館した博物館です。荒神谷遺跡の銅剣358本、加茂岩倉遺跡の銅鐸39個など、国宝の青銅器がまとめて展示されています。2000年に見つかった宇豆柱の実物や、巨大な本殿の復元模型も見られます。","story":["1984年、出雲市（旧斐川町）の荒神谷の山の斜面から、銅剣が次々と見つかりました。その数358本。それまで日本全国で見つかっていた銅剣の数を、たった一か所で上回る、とんでもない発見でした。翌年には、すぐそばから銅鐸6個と銅矛16本も出てきます。","さらに1996年、雲南市（旧加茂町）の加茂岩倉で、農道の工事中に銅鐸がつぎつぎと出てきました。その数39個。一か所から出た銅鐸の数としては日本一です。«なぜ出雲にこんなに青銅器が集まっていたの?» ――それは今も大きななぞで、この博物館は、そのなぞに向き合う場所でもあります。","それまで、出雲神話は «大和の人が考えた作り話» だと考える研究者も多くいました。ところが、この大発見で、弥生時代の出雲に強い力をもつ勢力があったことがはっきりしました。«神話の国・出雲» には、それを裏づける «実物» があったのです。","博物館の中央ロビーには、2000年に出雲大社の境内から見つかった宇豆柱の実物が置かれています。3本の杉をたばねた柱の迫力は、写真では伝わりません。展示室には、昔の本殿が高さ48mだったという説をもとにした1/10の復元模型もあります。","展示は «出雲大社と神々の国のまつり»«出雲国風土記の世界»«青銅器と金色の古代出雲» などのテーマにわかれ、神話の映像シアターもあります。出雲大社にお参りしたあと、ここで «神話の裏にある歴史» を確かめると、旅が何倍も面白くなります。"],"tl":[["1984年","荒神谷遺跡で銅剣358本が見つかる"],["1985年","荒神谷遺跡で銅鐸6個・銅矛16本が見つかる"],["1996年","加茂岩倉遺跡で銅鐸39個が見つかる"],["2000年","出雲大社境内で宇豆柱が見つかる"],["2007年","島根県立古代出雲歴史博物館が開館"],["2008年","加茂岩倉遺跡の銅鐸が国宝に指定される"]],"who":[["荒神谷・加茂岩倉の発見者たち","工事や調査で青銅器を見つけた人々"],["大国主大神","出雲大社の祭神。博物館の神話展示の中心"],["槇文彦","建築家。博物館の建物を設計した"]],"deep":["荒神谷遺跡の銅剣・銅鐸・銅矛は一括して国宝に指定されています。銅剣の多くには «×» 印が刻まれていて、加茂岩倉の銅鐸の一部にも同じ印があることから、両遺跡の関係が注目されています。","加茂岩倉遺跡の銅鐸には、大きな銅鐸の中に小さな銅鐸を入れた «入れ子» の状態で埋められたものがありました。埋めた理由については、祭りの終わりの儀式、隠した、など諸説があります。","荒神谷遺跡・加茂岩倉遺跡とも、青銅器を埋めた時期や理由ははっきりしていません。«出雲の青銅器祭祀の終わり» を示すとする見方があります。","本殿の1/10復元模型は、建築史家による案をもとにしたもので、ほかにもいくつかの復元案があります。館内で複数の模型をくらべられる展示もあります。","建物は建築家・槇文彦の設計です。コールテン鋼の外壁やガラスの大きなロビーが特徴で、裏手には北山の山並みが広がります。"],"look":["荒神谷遺跡の銅剣358本の展示","加茂岩倉遺跡の銅鐸39個","中央ロビーの宇豆柱","古代出雲大社本殿の復元模型"],"q":["荒神谷遺跡で見つかった銅剣は何本？","358本。一か所で、それまで全国で見つかっていた数を上回りました。"],"koji":[],"myth":"青銅器を埋めた理由・時期は諸説。本殿の模型は復元案の一つ。","img":["荒神谷遺跡","加茂岩倉遺跡","銅鐸"],"wp":"島根県立古代出雲歴史博物館","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/150322_Shimane_Museum_of_Ancient_Izumo_Japan07s.jpg",6000,4000,"島根県立古代出雲歴史博物館"],["c:c/c2/150322_Shimane_Museum_of_Ancient_Izumo_Japan20s3.jpg",6000,4000],["c:b/b0/150322_Shimane_Museum_of_Ancient_Izumo_Japan18s.jpg",6000,4000],["c:c/ce/150322_Shimane_Museum_of_Ancient_Izumo_Japan12s3.jpg",6000,4000],["c:0/02/150322_Shimane_Museum_of_Ancient_Izumo_Japan08s.jpg",6000,4000],["c:7/78/150322_Shimane_Museum_of_Ancient_Izumo_Japan05s.jpg",6000,4000],["c:7/70/150322_Shimane_Museum_of_Ancient_Izumo_Japan01s.jpg",6000,4000],["c:0/05/ShimaneMuseumOfAncientIzumo_02.jpg",3072,2048]]},{"id":"32_shiomi_nawate","n":"塩見縄手（松江の武家屋敷通り）","yomi":"しおみなわて","cat":"町","rank":"A","y":1611,"era":["edo","meiji"],"sh":"国指定史跡（小泉八雲旧居）","ad":"松江市北堀町","st":"JR松江駅からレイクラインバスで約15分、«小泉八雲記念館前» 下車すぐ","la":35.4775,"lo":133.051,"hook":"お堀と松並木と黒い板塀――八雲が «日本の魂» を見つけた、松江城のすぐ北の小道。","lead":"塩見縄手は、松江城の北堀ぞいに続く約500mの通りです。江戸時代には中級の藩士の屋敷が並び、今も武家屋敷や小泉八雲旧居が残ります。松の木とお堀が続く景色は «日本の道100選» にも選ばれています。","story":["«縄手» とは、まっすぐに延びた道のこと。1611年に松江城が完成したころ、城の北側の堀にそって、藩士たちの屋敷が並ぶ道がつくられました。ここに屋敷をもった中老・塩見小兵衛が、のちに活躍したことから «塩見縄手» とよばれるようになったと伝わります。","通りには «武家屋敷» が一軒、見学できる形で残っています。玄関や座敷、長屋門、台所、それに家来が住んだ部屋などがあり、江戸時代の中級藩士の暮らしがよくわかります。«なぜ門のわきに長い建物があるの?» それは長屋門といって、家来や使用人が住む部屋を兼ねていたのです。","明治24年（1891年）、この通りの一軒の屋敷を借りて住んだのが、ギリシャ生まれの作家ラフカディオ・ハーン、のちの小泉八雲でした。英語教師として松江に来た八雲は、この家の庭をとても気に入り、のちに «日本の庭» という文章の中で、その庭のようすをくわしく描いています。","八雲が松江に住んだのは1年3か月ほどでしたが、その間に妻・セツと出会い、松江の人々の信仰や怪談、習わしを熱心に書きとめました。これがのちに『知られぬ日本の面影』などの本になり、世界に «日本» を紹介することになります。","今、小泉八雲旧居は国の史跡として公開され、となりには小泉八雲記念館があります。お堀には «堀川めぐり» の小舟が行き来し、船頭さんの声が聞こえてきます。松の緑とお堀の水面、黒い板塀。江戸と明治の空気が、そのまま残っている通りです。"],"tl":[["1611年","松江城が完成。北堀ぞいに藩士の屋敷町がつくられる"],["江戸時代","中級藩士の屋敷が並ぶ通りとなる"],["1891年","小泉八雲が塩見縄手の屋敷に住む（約5か月）"],["1940年","小泉八雲旧居が国の史跡に指定"],["1986年","«日本の道100選» に選ばれる"]],"who":[["塩見小兵衛","松江藩の中老。この通りの名の由来と伝わる"],["小泉八雲（ラフカディオ・ハーン）","作家。この通りの屋敷に住んだ"],["小泉セツ","八雲の妻。松江の昔話を八雲に語った"],["堀尾吉晴","松江城と城下町をつくった大名"]],"deep":["«縄手» は、縄を張ったようにまっすぐな道を意味することばで、各地の城下町や街道で使われています。","小泉八雲旧居は、もと松江藩士・根岸家の屋敷で、八雲が借りて住んでいました。三方を庭に囲まれた書斎は、八雲が『日本の庭』という文章で描いた場所です。","八雲が松江に住んだのは1890年8月から1891年11月までで、塩見縄手の屋敷にいたのはそのうち5か月ほどです。その後、熊本の第五高等中学校へ移りました。","通りの武家屋敷は、江戸時代中期の建物とされ、何度か住む人が代わったといわれます。有料で公開されています。","通りの一帯は松江市の «伝統美観地区» として景観が守られています。電柱や看板をおさえるなど、城下町の雰囲気を保つ工夫がされています。"],"look":["お堀と松並木の景色","武家屋敷（長屋門・台所）","小泉八雲旧居の書斎と庭","小泉八雲記念館","堀川めぐりの遊覧船"],"q":["塩見縄手の «縄手» とはどんな意味？","まっすぐに延びた道のこと。縄を張ったようにまっすぐ、という意味です。"],"koji":[],"myth":"通りの名の由来は伝えによる。武家屋敷の建築年代は資料により差がある。","img":["小泉八雲","松江城","小泉八雲記念館"],"wp":"塩見縄手","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/150321_Shiominawate_Matsue_Shimane_pref_Japan01s3.jpg",6000,4000,"塩見縄手"],["c:2/26/Shiominawate_Matsue06s4592.jpg",4592,3056],["c:a/a2/Shiominawate_Matsue05s4592.jpg",4592,3056],["c:a/ae/Shiominawate_Matsue04s4592.jpg",4592,3056],["c:4/48/Shiominawate_Matsue03s4592.jpg",4592,3056],["c:0/07/Lafcadio_Hearn_portrait.jpg",712,1024,"小泉八雲"],["c:8/88/Matsue_Castle_Keep_Tower_20230617.jpg",4988,3741,"松江城"],["c:a/a8/Lafcadio_Hearn_Memorial_Hall01st3200.jpg",3200,2130,"小泉八雲記念館"]]},{"id":"32_gesshoji","n":"月照寺（松江藩主松平家の廟所）","yomi":"げっしょうじ","cat":"墓所","rank":"A","y":1664,"era":["edo"],"sh":"国指定史跡（松江藩主松平家墓所）","ad":"松江市外中原町","st":"JR松江駅からレイクラインバスで約20分、«月照寺前» 下車すぐ","la":35.4655,"lo":133.04,"hook":"夜な夜な町を歩きまわった大亀の石像――松江藩主9代が眠る «あじさい寺» には、八雲も好んだ怪談が残る。","lead":"月照寺は、松江藩主・松平家の菩提寺です。初代藩主の松平直政が母をとむらうために開き、初代から9代までの藩主の廟所（お墓）が境内に並びます。6代藩主の廟にある大亀の石像や、7代藩主・不昧（ふまい）ゆかりの茶室でも知られます。","story":["1664年（寛文4年）、松江藩の初代藩主・松平直政は、亡くなった母・月照院のために、この地の寺を改めて浄土宗の «月照寺» としました。直政は徳川家康の孫にあたる人物です。やがて直政自身もここに葬られ、代々の藩主の廟所が築かれていきました。","境内は山の斜面に広がり、藩主ごとに門と塀をもった廟所が並びます。門には葵の紋や、藩主の好みを表す彫刻がほどこされ、それぞれに個性があります。初代から9代まで、まるで «殿様たちの住まい» がそろっているようです。","なかでも有名なのが、6代藩主・松平宗衍（むねのぶ）の廟にある大亀の石像です。見上げるほど大きな石の亀が、宗衍の功績をたたえる碑を背負っています。言い伝えでは、この亀が夜になると動き出し、城下の池で水を飲んだり、町を歩きまわって人々をこわがらせたりしたといいます。困った寺の住職が亀に言い聞かせ、背中に碑を立てて動けないようにした――という話です。","«なぜ亀なの?» 亀は長寿のしるしで、中国では «贔屓（ひいき）» とよばれる亀に似た生きものが、重い碑を背負うとされてきました。この怪談は、松江に住んだ小泉八雲も作品の中で紹介したといわれ、八雲はこの寺をとても気に入っていたと伝わります。","7代藩主・松平治郷は «不昧» の号で知られる大名茶人です。境内の «大円庵» は不昧ゆかりの茶室で、寺では抹茶と和菓子をいただくこともできます。6月には3万株ともいわれるあじさいが咲き、«山陰のあじさい寺» とよばれています。"],"tl":[["1638年","松平直政が松江藩主となる"],["1664年","直政が母・月照院のために月照寺を開く"],["1666年","直政が亡くなり、月照寺に葬られる"],["18世紀後半","6代宗衍の廟に大亀の石像が置かれる"],["1818年","7代不昧（治郷）が亡くなる"],["現代","藩主の墓所が国の史跡に指定されている"]],"who":[["松平直政","松江藩初代藩主。家康の孫。月照寺を開いた"],["月照院","直政の母。寺の名の由来"],["松平宗衍","6代藩主。大亀の石像がある廟の主"],["松平治郷（不昧）","7代藩主。大名茶人として知られる"],["小泉八雲","作家。月照寺と大亀の話を好んだと伝わる"]],"deep":["月照寺の廟所には初代直政から9代斉斉（なりたけ）までの藩主が眠ります。一つの寺に9代もの藩主の廟がそろう例は多くありません。","大亀の石像が背負う碑は、宗衍の «寿蔵碑»（生前に功績を記した碑）とされます。亀のような台（亀趺）に碑をのせる形は、中国の石碑の伝統にならったものです。","不昧の廟の門は、不昧自身の好みを反映したデザインといわれ、ぶどうの彫刻などがほどこされています。不昧は茶道 «不昧流» の祖とされます。","直政は結城秀康の三男で、家康の孫にあたります。大坂の陣で若くして活躍したことでも知られます。","大亀の怪談は、松江の町で語り伝えられてきたもので、八雲がそれを書き残したことでさらに広く知られるようになりました。どの作品に書かれたかについては紹介のされ方に差があります。"],"look":["6代宗衍の廟の大亀の石像","7代不昧の廟の門の彫刻","初代直政の廟","茶室 «大円庵»","6月のあじさい"],"q":["月照寺の大亀が背負っているのは何？","6代藩主・松平宗衍の功績を記した «寿蔵碑»。亀が歩き回らないように碑をのせたという伝説もあります。"],"koji":[],"myth":"大亀が歩き回った話、八雲がこの寺を好んだ話は伝承。","img":["松平直政","松平治郷","松江藩"],"wp":"月照寺 (松江市)","rel":{"ev":[],"grave":[]},"ph":[["c:8/86/Gesshouji_Temple_in_Matsue_City_-_%E6%9D%BE%E6%B1%9F%E5%B8%82%E3%81%AE%E6%9C%88%E7%85%A7%E5%AF%BA_2.jpg",1516,1016,"月照寺 (松江市)"],["c:4/4e/Gesshouji_Juzouhi_monument.JPG",1928,2768],["c:e/e8/Matsudaira_Naomasa.jpg",567,834,"松平直政"],["c:c/cb/Matsudaira_Fumai.JPG",1631,2319,"松平治郷"],["c:d/da/150321_Matsue_Castle_Matsue_Shimane_pref_Japan01bs.jpg",5700,3800,"松江藩"]]},{"id":"32_kouunkaku","n":"興雲閣（明治天皇行幸のための迎賓館）","yomi":"こううんかく","cat":"近代","rank":"A","y":1903,"era":["meiji","taisho","heisei"],"sh":"県指定有形文化財","ad":"松江市殿町（松江城山公園内）","st":"JR松江駅からレイクラインバスで約10分、«大手前堀川遊覧船乗場» 下車、歩いて約5分","la":35.4745,"lo":133.05,"hook":"天皇を迎えるために建てたのに、天皇は来なかった――お城の中に立つ、白い «幻の迎賓館»。","lead":"興雲閣は、1903年（明治36年）に松江城の山の中に建てられた洋風の木造建築です。明治天皇が山陰を訪れるときの宿として松江市がつくりましたが、天皇の訪問は実現しませんでした。そのかわり、1907年に皇太子（のちの大正天皇）が泊まりました。","story":["明治の終わりごろ、松江の人々には大きな願いがありました。«明治天皇に松江へ来ていただきたい»。天皇が各地をまわる «行幸» は、町にとって最高の名誉だったのです。そこで松江市は、天皇が泊まるための立派な建物を、お城の山の上に建てることにしました。","できあがったのは、白い壁とベランダのある2階建ての洋館。木造ですが、見た目は西洋風で、細部には日本の大工の技がいきています。このような建物を «擬洋風建築» といいます。«興雲閣» という名前は、雲がわき起こるように国が栄えることを願ってつけられました。","ところが、日露戦争が近づくなど時代が大きく動き、明治天皇の山陰行幸は結局行われませんでした。«せっかく建てたのに…»。松江の人々のがっかりした気持ちが想像できます。","4年後の1907年、明治天皇の皇太子・嘉仁親王（のちの大正天皇）が山陰を訪れ、興雲閣に泊まりました。建物はやっと «天皇家を迎える» という役目を果たすことができたのです。その後、県の施設や郷土館として使われ、長く松江の人々に親しまれてきました。","平成の時代に大がかりな修理が行われ、明治の建てられた当時の姿によみがえりました。今は無料で公開され、1階にはカフェもあります。2階のベランダからは、松の緑の向こうに松江の町並みが見えます。天守とあわせて訪ねれば、«江戸» と «明治» の二つの時代を一度に感じられます。"],"tl":[["1903年","松江市が明治天皇行幸の宿として興雲閣を完成させる"],["1907年","皇太子嘉仁親王（のちの大正天皇）の山陰行啓で宿泊所となる"],["大正〜昭和","県の施設などとして使われる"],["1973年","松江郷土館として公開される"],["2015年","保存修理が終わり、建設当時の姿で再公開"]],"who":[["明治天皇","行幸を迎えるため建てられたが、訪れなかった"],["嘉仁親王（大正天皇）","皇太子のとき山陰を訪れ、興雲閣に泊まった"],["松江市","天皇を迎えるため、城山にこの建物を建てた"]],"deep":["興雲閣は木造2階建ての擬洋風建築で、1・2階に広いベランダがあるのが特徴です。細かい装飾には、日本の寺社建築の技法も見られます。","1907年の皇太子の山陰行啓では、鳥取・島根の各地を訪れ、松江では興雲閣が «御旅館» とされました。","建物は長く «松江郷土館» として使われ、松江の歴史資料を展示していました。修理の際、建設当時の色や部屋の使い方が調べられ、それにもとづいて復原されています。","興雲閣は島根県の指定有形文化財です。明治の地方都市がつくった迎賓施設として、全国的にもめずらしい例です。","同じ時期、山陰では鉄道の開通や港の整備が進み、松江も近代化の波の中にありました。興雲閣は、その «近代への期待» を形にした建物ともいえます。"],"look":["白い外観とベランダ","2階の貴賓室","修理でよみがえった天井や装飾","1階のカフェ","近くの松江城天守（国宝）"],"q":["興雲閣に最初に泊まった皇族は誰？","皇太子の嘉仁親王（のちの大正天皇）。1907年の山陰行啓のときです。"],"koji":[],"myth":"名前の由来の説明は一般的な解釈。建設費の負担の内訳は資料により差がある。","img":["松江城","大正天皇","擬洋風建築"],"wp":"興雲閣","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Kounkaku1.JPG",3216,2136,"興雲閣"],["c:2/23/Kounkaku_Matsue04s4592.jpg",4592,3056],["c:d/d8/Kounkaku_Matsue02s4592.jpg",4592,3056],["c:8/84/Kounkaku_Matsue08nt3200.jpg",3200,2130],["c:8/88/Matsue_Castle_Keep_Tower_20230617.jpg",4988,3741,"松江城"],["c:3/33/Emperor_Taish%C5%8D.jpg",1267,1779,"大正天皇"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"]]},{"id":"32_tsuwano_jo","n":"津和野城（坂崎直盛と亀井氏の山城）","yomi":"つわのじょう","cat":"城","rank":"A","y":1295,"era":["kamakura","muromachi","edo"],"sh":"国指定史跡","ad":"鹿足郡津和野町後田","st":"JR山口線・津和野駅から歩いて約20分で観光リフト乗り場、リフトと山道で本丸へ","la":34.4585,"lo":131.7663,"hook":"«山陰の小京都» を見下ろす標高約370mの山城。100日の籠城戦と、千姫をめぐる事件の舞台。","lead":"津和野城は、鎌倉時代に吉見氏が築いた山城で、江戸時代には坂崎直盛、そして亀井氏の城となりました。建物はもう残っていませんが、山の上には高い石垣がみごとに残り、津和野の町を一望できます。国の史跡です。","story":["1295年（永仁3年）、元寇にそなえて西の守りを任された吉見頼行が、この山に城を築き始めたと伝わります。城は «三本松城» とよばれ、吉見氏はここを拠点に約300年、石見の西部を治めました。","1554年、大内氏を倒した陶晴賢の大軍が城を囲みました。城主・吉見正頼はわずかな兵で籠城し、100日以上も持ちこたえたといわれます。この戦いで陶軍が足止めされたことは、翌年、毛利元就が厳島の戦いで陶晴賢を破るきっかけの一つになったとも語られます。","関ヶ原の戦いのあと、吉見氏は毛利氏とともに萩へ移り、かわって坂崎直盛（出羽守）が城主となりました。直盛は山の上に石垣を積み、近世の城へと大改修します。ところが1616年、大坂の陣で落城する大坂城から徳川家康の孫娘・千姫を救い出したとされる直盛は、千姫の再婚をめぐって幕府と対立し、命を落としました。«千姫事件» です。","«なぜ直盛は幕府にさからったの?» 千姫を自分の家に迎える約束が破られたから、など理由には諸説があり、はっきりとはわかりません。その後の1617年、因幡から亀井政矩が入り、亀井氏が明治まで11代にわたって津和野藩を治めました。","明治になると城の建物は取りこわされ、石垣だけが残りました。今はリフトで山の中腹まで上がり、歩いて本丸へ。天守台や «三十間台» とよばれる高い石垣の上に立つと、赤い石州瓦の町並みと、蒸気機関車が走ることもある山口線が見下ろせます。"],"tl":[["1295年","吉見頼行が築城を始めたと伝わる"],["1554年","陶晴賢の軍に囲まれ、吉見正頼が100日以上の籠城戦"],["1600年","関ヶ原の戦い。吉見氏は萩へ移る"],["1601年ごろ","坂崎直盛が城主となり、石垣の城に改修"],["1616年","千姫事件で坂崎直盛が死去"],["1617年","亀井政矩が入城。以後亀井氏11代が治める"],["明治初め","城の建物が取りこわされる"]],"who":[["吉見頼行","城を築き始めたと伝わる武将"],["吉見正頼","陶晴賢の大軍に対して籠城した城主"],["坂崎直盛","関ヶ原後の城主。石垣の城に改修。千姫事件で死去"],["千姫","徳川家康の孫娘。坂崎直盛の事件にかかわる"],["亀井茲矩・政矩","亀井氏。政矩の代に津和野へ入り、明治まで続いた"]],"deep":["築城年を1295年とするのは伝えによるもので、完成は頼行の子・頼直の代とされます。約30年かかったともいわれます。","坂崎直盛は宇喜多氏の一族で、もと宇喜多詮家といいました。関ヶ原では東軍につき、その功で津和野を与えられました。","千姫事件の中身については、«千姫を奪おうとした»«千姫の再婚の仲人をまかされていたのに面目をつぶされた» など複数の説があり、直盛の最期も «自害» «家臣に討たれた» と伝えが分かれます。","本丸・二の丸・三の丸の石垣がよく残り、とくに «三十間台» の高石垣は見ごたえがあります。麓には江戸時代の «物見櫓» と «馬場先櫓» が残ります。","亀井氏の11代藩主・亀井茲監は、藩校 «養老館» で国学を重んじ、明治の神社行政にも影響を与えました。この藩校から西周や森鷗外が出ています。"],"look":["本丸の三十間台と天守台の石垣","人質櫓跡の石垣","山上からの津和野の町並み","麓の物見櫓・馬場先櫓","観光リフト"],"q":["大坂城から千姫を救い出したとされ、のちに事件を起こした津和野城主は？","坂崎直盛（出羽守）。千姫の再婚をめぐって幕府と対立しました。"],"koji":[],"myth":"築城年、籠城日数、千姫事件の原因と直盛の最期は諸説。","img":["坂崎直盛","千姫","津和野藩"],"wp":"津和野城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d2/TsuwanoJo.JPG",2048,1536,"津和野城"],["c:6/64/%E6%B4%A5%E5%92%8C%E9%87%8E%E5%9F%8E%E9%A6%AC%E5%A0%B4%E5%85%88%E6%AB%93.JPG",3888,2592],["c:a/a7/%E6%B4%A5%E5%92%8C%E9%87%8E%E5%9F%8E%E8%A5%BF%E9%96%80%E6%AB%93%E7%9F%B3%E5%9E%A3.JPG",3888,2592],["c:6/67/%E6%B4%A5%E5%92%8C%E9%87%8E%E5%9F%8E%E7%89%A9%E8%A6%8B%E6%AB%93.JPG",3888,2592],["c:8/88/%E6%B4%A5%E5%92%8C%E9%87%8E%E5%9F%8E%E5%8D%97%E9%96%80%E6%AB%93%E7%9F%B3%E5%9E%A3.JPG",2592,3888],["c:c/c2/%E6%B4%A5%E5%92%8C%E9%87%8E%E5%9F%8E%E4%BA%BA%E8%B3%AA%E9%83%AD%E7%9F%B3%E5%9E%A3.JPG",3888,2592],["c:b/b7/Tsuwano_Castle_13_Taiko-mru.JPG",2400,1800],["c:f/f2/Tsuwano_Castle_12_Tenshu_pedestal_2.JPG",2400,1800]]},{"id":"32_ogai_kyutaku","n":"森鷗外旧宅","yomi":"もりおうがいきゅうたく","cat":"近代","rank":"A","y":1862,"era":["edo","meiji","taisho"],"sh":"国指定史跡","ad":"鹿足郡津和野町町田","st":"JR山口線・津和野駅からバスで約5分、«鷗外旧居前» 下車すぐ。歩くと約25分","la":34.4545,"lo":131.7725,"hook":"«余は石見人森林太郎として死せんと欲す» ――文豪が最後に帰りたかったのは、この小さな家だった。","lead":"森鷗外旧宅は、明治の文豪・森鷗外（本名 森林太郎）が生まれ、10歳まで過ごした家です。森家は津和野藩の典医（藩主の医者）の家でした。となりには森鷗外記念館があり、鷗外の生涯と作品を知ることができます。","story":["1862年（文久2年）、津和野藩の医者の家に、一人の男の子が生まれました。のちの森鷗外、本名 森林太郎です。森家は代々、藩主・亀井家の典医をつとめる家柄で、林太郎は小さいころから大きな期待をかけられて育ちました。","林太郎は5歳ごろから論語などを学び、藩校 «養老館» で漢学を学び、父からはオランダ語の手ほどきも受けたといわれます。«なぜ子どもがオランダ語を?» 当時、西洋の医学はおもにオランダ語の本で学ばれていたからです。医者の家の跡取りとして、早くから西洋の学問にふれていたのです。","1872年、10歳の林太郎は父とともに東京へ出ました。その後、東京大学医学部を卒業して陸軍の軍医となり、ドイツに留学。帰国後は軍医として最高の地位にのぼる一方で、『舞姫』『雁』『高瀬舟』などの小説を書き、夏目漱石とならぶ文豪となりました。","けれど、鷗外は二度と津和野に住むことはありませんでした。1922年、60歳で亡くなる直前、鷗外は親友に遺言を書き取らせます。«余ハ石見人森林太郎トシテ死セント欲ス»。軍医としての位も、作家としての名もいらない、ただの石見の人、森林太郎として死にたい――というのです。","旧宅は木造平屋の質素な家で、林太郎が勉強したといわれる小部屋も残っています。となりの森鷗外記念館では、鷗外の手紙や原稿、愛用品が展示されています。町の中心にある永明寺には、鷗外の墓もあります（東京の禅林寺にもお墓があります）。故郷を思い続けた文豪の気持ちを、静かな家の中で感じてみてください。"],"tl":[["1862年","津和野藩典医の家に森林太郎（鷗外）が生まれる"],["1872年","父とともに上京する"],["1884年","陸軍軍医としてドイツに留学"],["1890年","小説『舞姫』を発表"],["1922年","60歳で死去。«石見人森林太郎» として死にたいと遺言"],["1969年","旧宅が国の史跡に指定"]],"who":[["森鷗外（森林太郎）","この家で生まれ育った文豪・軍医"],["森静男","鷗外の父。津和野藩の典医"],["西周","津和野出身の思想家。鷗外の親類で、上京後の鷗外を支えた"],["賀古鶴所","鷗外の親友。遺言を書き取った"]],"deep":["鷗外の遺言は «墓ハ森林太郎墓ノ外一字モホル可ラス» と続き、墓に肩書きや称号を刻まないように求めています。実際に墓石には «森林太郎墓» とだけ刻まれています。","旧宅は、鷗外が上京したあと他人の手に渡りましたが、のちに町が買いもどして保存しました。建物の一部は修理を重ねています。","養老館は津和野藩の藩校で、亀井茲監の時代に国学や医学などが重んじられました。建物の一部が今も津和野の町に残っています。","鷗外の本名 «林太郎» と、ペンネーム «鷗外» のほかに、«観潮楼主人» などの号もあります。«観潮楼» は東京の鷗外の家の名前です。","鷗外記念館は1995年に開館しました。旧宅と合わせて見学することで、鷗外の «故郷への思い» をたどることができます。"],"look":["旧宅の間取りと勉強部屋","森鷗外記念館の展示","永明寺の鷗外の墓","町の中心にある藩校 «養老館» の建物"],"q":["森鷗外が遺言で «〜として死にたい» と書いたのは、何人としてでしょう？","«石見人（いわみびと）森林太郎»。肩書きのない、故郷の一人として死にたいと願いました。"],"koji":[{"w":"余ハ石見人森林太郎トシテ死セント欲ス","m":"鷗外の遺言の一節。地位や名声をすて、石見の人・森林太郎として死にたいという思い"}],"myth":"幼少期の学習内容の細部は伝記による。","img":["津和野町","西周 (啓蒙家)"],"wp":"森鷗外","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Mori_Ogai_in_the_atelier_of_Sculptor_Takeishi_Kozaburo_in_1916.jpg",740,1118,"森鷗外"],["c:7/7b/Birthplace_of_Mori_Ogai_20170503.jpg",3996,2997],["c:c/c1/Mori-Ogai-Gedenkst%C3%A4tte.jpg",3008,2000],["c:3/3d/Japanese_students_in_German_Reich_cropped_2_Ishiguro_Tadanori_Kaikyu_90_nen_Frame_165.jpg",2008,1598],["c:4/49/%E5%8D%83%E4%BD%8F%E3%82%B6%E3%83%BB%E3%82%BF%E3%83%AF%E3%83%BC%E3%81%AE%E5%89%8D%E3%81%AB%E3%81%82%E3%82%8B%E6%A3%AE%E9%B7%97%E5%A4%96%E6%97%A7%E5%B1%85%E6%A9%98%E4%BA%95%E5%A0%82%E8%B7%A1%E3%81%AE%E7%A2%91.jpg",960,540],["c:1/1b/Mori_Ogai_house_Kokura.jpg",640,480],["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"],["c:b/bc/Nishi_Amane%2C_supervisor_of_the_Tokyo_Normal_School.jpg",1391,1951,"西周 (啓蒙家)"]]},{"id":"32_manpukuji_masuda","n":"萬福寺（雪舟の庭）","yomi":"まんぷくじ","cat":"寺社","rank":"A","y":1374,"era":["muromachi","edo"],"sh":"国の重要文化財（本堂）・国指定史跡及び名勝（庭園）","ad":"益田市東町","st":"JR山陰本線・山口線 益田駅から歩いて約20分、またはバスで約5分","la":34.6737,"lo":131.8545,"hook":"水墨画の巨匠・雪舟が、石と池で描いた «立体の山水画»。庭の奥には仏教の世界の中心・須弥山がそびえる。","lead":"萬福寺は益田市にある時宗の寺で、室町時代の画僧・雪舟がつくったと伝わる庭園で知られます。本堂は南北朝時代の建物で国の重要文化財、庭園は国の史跡と名勝です。石見の領主・益田氏の保護を受けて栄えました。","story":["もとはこの寺、益田川の河口近くにあった «安福寺» という寺だったと伝わります。平安時代の大地震と津波で流され、1374年（応安7年）、益田氏の当主・益田兼見が今の場所に移して «萬福寺» と改めたといわれます。本堂はそのころの建物とされ、どっしりとした屋根が南北朝時代の雰囲気を伝えています。","1479年ごろ、この町に一人の画僧がやって来ました。雪舟です。中国（明）で本場の水墨画を学んだ雪舟は、益田氏の当主・益田兼堯（かねたか）に招かれ、益田に滞在しました。そのとき兼堯の肖像画を描き、萬福寺と医光寺の庭をつくったと伝わります。","萬福寺の庭は、本堂の裏の斜面を利用しています。中央の池は «心» の字をかたどったといわれ、その奥の築山には、仏教の世界の中心にそびえる «須弥山（しゅみせん）» をあらわした石組があります。«なぜ庭に山を?» 雪舟は、絵でえがいてきた山水の世界を、本物の石と水と木で表そうとしたのかもしれません。","本堂の縁側に座ると、庭全体が一幅の掛け軸のように見えます。季節によって緑、紅葉、雪と表情を変え、見る位置によって石の重なりもちがって見えます。500年以上前の人が見たのと同じ景色を、今も見ることができるのです。","江戸時代の終わり、1866年の第二次長州征討では、益田の町が長州軍と幕府方の戦いの舞台になりました。萬福寺も戦いにまきこまれ、本堂の柱には当時の弾のあとが残っているといわれます。静かな庭の寺にも、激しい歴史の一ページが刻まれています。"],"tl":[["1026年","万寿の大地震と津波で、前身の安福寺が流されたと伝わる"],["1374年","益田兼見が寺を今の場所に移し、萬福寺と改めたとされる"],["1479年ごろ","雪舟が益田を訪れ、庭をつくったと伝わる"],["1866年","第二次長州征討の益田の戦いで寺が戦場となる"],["明治〜昭和時代","本堂が国の重要文化財に、庭園が国の史跡及び名勝に指定"]],"who":[["雪舟","室町時代の画僧。庭をつくったと伝わる"],["益田兼見","益田氏の当主。寺を今の場所に移したとされる"],["益田兼堯","益田氏の当主。雪舟を招き、肖像画を描いてもらった"],["大村益次郎","1866年、益田に攻め込んだ長州軍の指揮官"]],"deep":["雪舟が描いた «益田兼堯像» は国の重要文化財で、雪舟の数少ない肖像画の一つです。画中の記述から1479年の作とされ、雪舟が益田に来た時期を知る手がかりになっています。","萬福寺と医光寺の庭はどちらも «雪舟作» と伝わり、益田市内には «雪舟の郷記念館» もあります。ただし、庭の作者を雪舟とする直接の史料は少なく、後の改修も考えられます。","庭の石組は «須弥山式» とよばれる形で、中央に高い石を立て、そのまわりに山々や海を表す石を配置します。","本堂は寄棟造の大きな建物で、南北朝時代の時宗寺院の本堂として貴重です。","萬福寺の本尊は阿弥陀如来。時宗は一遍を開祖とする念仏の宗派で、踊り念仏で知られます。"],"look":["雪舟庭園（須弥山の石組と池）","本堂（国の重要文化財）","本堂の柱の弾のあと（といわれる箇所）","近くの医光寺の雪舟庭園と総門"],"q":["萬福寺の庭の奥の石組は、仏教の世界の中心にある何という山を表している？","«須弥山（しゅみせん）»。雪舟が庭の中にこの山を表したと伝わります。"],"koji":[],"myth":"庭の作者を雪舟とするのは伝承。寺の移転年、弾痕の由来も伝えによる。","img":["雪舟","医光寺","益田氏"],"wp":"萬福寺 (益田市)","rel":{"ev":[],"grave":[]},"ph":[["c:0/05/%E8%90%AC%E7%A6%8F%E5%AF%BA%E5%BA%AD%E5%9C%92%28%E7%9B%8A%E7%94%B0%E5%B8%82%29.jpg",2048,1371,"萬福寺 (益田市)"],["c:7/75/Portrait_of_Sesshu.jpg",988,1217,"雪舟"]]},{"id":"32_mitaku_odoi","n":"三宅御土居跡（益田氏の館）","yomi":"みやけおどいあと","cat":"城","rank":"A","y":1380,"era":["muromachi","azuchi"],"sh":"国指定史跡（益田氏城館跡）","ad":"益田市三宅町","st":"JR山陰本線・山口線 益田駅から歩いて約20分","la":34.672,"lo":131.8505,"hook":"ふだんは平地の館、いざとなれば裏山の城へ――中世の武士の «暮らしと守り» がセットで残る、益田氏の本拠。","lead":"三宅御土居跡は、石見西部を治めた武士・益田氏の館のあとです。周りを土塁（土の壁）と堀で囲んだ大きな館で、南北朝時代から戦国時代の終わりまで使われました。近くの山城・七尾城とあわせて «益田氏城館跡» として国の史跡になっています。","story":["益田氏は、平安時代の終わりに石見国の役人として力をのばし、やがて益田の地に根をおろした武士の一族です。鎌倉時代から戦国時代まで、およそ400年にわたってこの地方を治めました。","南北朝時代、益田氏の当主・益田兼見は、それまでの館から、益田川のそばのこの場所に新しい館を移したと伝わります。«御土居（おどい）» とは、土を盛った土塁で囲まれた屋敷のこと。東西200m近い広い敷地を、高い土塁と堀が取り囲んでいました。","«なぜ館と城が別々なの?» ふだん政治をしたり、家族と暮らしたりするのは、便利な平地の館。一方、敵が攻めてきたら、背後の山にある七尾城にこもって戦う――中世の武士は、このように «館» と «詰めの城» を使い分けていました。三宅御土居と七尾城は、そのしくみがよくわかる組み合わせなのです。","発掘調査では、建物のあとや井戸、鍛冶の工房、それに中国や朝鮮から来た陶磁器などが見つかりました。日本海に面した益田は、海を通じて大陸とも結びついていたのです。雪舟を招いた益田兼堯も、この館で暮らしていたと考えられています。","関ヶ原の戦いのあと、毛利氏の家臣となっていた益田元祥は、毛利氏が周防・長門に移ったのにしたがって益田を去り、長門の須佐に移りました。館はその役目を終え、のちに寺が建てられるなどしましたが、土塁は今も高く残っています。整備された史跡公園では、中世の武士の館の大きさを歩いて体感できます。"],"tl":[["平安時代末","益田氏の祖が石見国の役人として力をのばす"],["14世紀後半","益田兼見が館をこの地に移したと伝わる"],["1479年ごろ","益田兼堯が雪舟を益田に招く"],["1600年","関ヶ原の戦い。のちに益田元祥は長門の須佐へ移る"],["2004年","七尾城跡とあわせ «益田氏城館跡» として国の史跡に"]],"who":[["益田兼見","館をここに移したと伝わる当主"],["益田兼堯","雪舟を招いた当主"],["益田元祥","毛利氏の重臣。益田を離れ長門の須佐へ移った"],["雪舟","益田に滞在した画僧"]],"deep":["«御土居» は、土塁で囲んだ館を指す言葉で、中国地方などで使われます。三宅御土居の土塁は、東側と西側がとくによく残っています。","三宅御土居と七尾城はあわせて «益田氏城館跡» として2004年に国の史跡に指定されました。館と詰城が一体として指定されている点が特徴です。","発掘で見つかった輸入陶磁器には、中国の青磁・白磁のほか朝鮮半島の陶磁器もあり、益田の港が日本海交易の拠点だったことを示すと考えられています。","益田氏は須佐（今の山口県萩市須佐）に移ったあと、長州藩の永代家老として続きました。幕末の家老・益田親施（右衛門介）は、禁門の変の責任をとって切腹した三家老の一人です。","館の跡には長く泉光寺という寺がありましたが、史跡整備のため移転しました。"],"look":["東側・西側の高い土塁","堀のあと","史跡公園の説明板と遺構表示","背後の七尾城跡（登山道あり）"],"q":["ふだん暮らす館に対して、いざというときにこもる山城を何とよぶ？","«詰めの城（詰城）»。益田氏の場合、七尾城がその役目でした。"],"koji":[],"myth":"館の移転時期と兼見の関与は伝えによる。敷地の規模は資料により差がある。","img":["益田氏","七尾城 (石見国)","益田元祥"],"wp":"三宅御土居跡","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Miyake_Odoi_remains_2_Square.JPG",2400,1800,"三宅御土居跡"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/9e/Miyake_Odoi_remains_6_West-Rampart.JPG",2400,1800],["c:5/5a/Miyake_Odoi_remains_5_East-Rampart.JPG",2400,1800],["c:e/e3/Miyake_Odoi_remains_4_Moat.JPG",2400,1800],["c:f/f9/Miyake_Odoi_remains_3_Well.JPG",2400,1800],["c:6/66/Miyake_Odoi_remains_1_Overview.JPG",2400,1800],["c:a/a3/MasudaNanaojyo.jpg",3504,2336,"七尾城 (石見国)"]]},{"id":"32_takatsu_kakinomoto","n":"高津柿本神社（柿本人麻呂を祀る）","yomi":"たかつかきのもとじんじゃ","cat":"寺社","rank":"A","y":1681,"era":["asuka","heian","edo"],"sh":"","ad":"益田市高津町","st":"JR山口線・益田駅から車で約10分、またはバスで «柿本神社前» 下車","la":34.689,"lo":131.812,"hook":"«万葉集» 最高の歌人は、石見の海で最期を迎えた――その魂をまつる、海を見わたす丘の上の社。","lead":"高津柿本神社は、飛鳥時代の歌人・柿本人麻呂をまつる神社です。人麻呂は石見国の役人として赴任し、この地で亡くなったと伝わります。人麻呂が亡くなった «鴨島» は、平安時代の地震で海に沈んだといわれ、江戸時代に今の丘の上に社が移されました。","story":["柿本人麻呂は、『万葉集』を代表する歌人です。天皇や皇子をたたえる長い歌や、妻との別れを悲しむ歌をたくさん残し、のちの時代には «歌の聖（ひじり）» とあがめられました。けれども、その生涯には分からないことが多く、どこで生まれ、どこで亡くなったのかも、はっきりしていません。","『万葉集』には、人麻呂が石見国で死を前にして詠んだとされる歌があります。«鴨山の 岩根しまける 我をかも 知らにと妹が 待ちつつあるらむ» ――鴨山の岩を枕に横たわっているわたしを知らずに、妻は帰りを待っているのだろうか。石見に残した妻との別れの歌も、人麻呂の代表作です。","益田では、人麻呂は高津川の河口にあった «鴨島» で亡くなり、そこにまつられたと伝わります。ところが1026年（万寿3年）の大地震と津波で、鴨島は海の底に沈んでしまったといわれます。«島ごと消えた?» ――そのとき、人麻呂の像が流れ着いたところに社がまつりなおされた、とも語り伝えられています。","江戸時代の1681年ごろ、津和野藩主の亀井茲親が、海を見わたす高角山の今の場所に社を移しました。やがて人麻呂の千年忌には、朝廷から高い神の位が贈られ、全国の歌人がここへ歌を奉納するようになります。","人麻呂は «ひとまる» とも読まれたことから «火止まる»（火事よけ）や «人産まる»（安産）の神としても信仰されました。境内からは益田の町と日本海を見下ろせます。海の向こうに沈んだという鴨島を思いながら、1300年前の歌人の声に耳をすませてみてください。"],"tl":[["7世紀後半〜8世紀初め","柿本人麻呂が活躍。石見で亡くなったと伝わる"],["1026年","万寿の大地震と津波で鴨島が沈んだと伝わる"],["1681年ごろ","津和野藩主・亀井茲親が社を今の地に移す"],["1723年","人麻呂の千年忌。朝廷から神位が贈られたと伝わる"],["現在","学問・和歌・安産・火よけの神として信仰される"]],"who":[["柿本人麻呂","祭神。『万葉集』を代表する歌人"],["依羅娘子（よさみのおとめ）","人麻呂の妻とされる人。人麻呂の死を悲しむ歌が『万葉集』にある"],["亀井茲親","津和野藩主。社を今の地に移した"],["斎藤茂吉","歌人。人麻呂が亡くなった «鴨山» の場所を研究した"]],"deep":["人麻呂の亡くなった «鴨山» の場所には、益田の鴨島説のほか、斎藤茂吉が唱えた邑南町・美郷町（旧邑智郡）の湯抱（ゆがかえ）説など、いくつもの説があります。","鴨島が地震で沈んだという話は、益田の沖に «鴨島の遺跡» があるとする調査が行われたこともあり、今も関心を集めています。ただし沈んだ島の存在については確かめられていません。","益田市の戸田には、人麻呂の生まれた地と伝わる «戸田柿本神社» もあります。人麻呂の生まれと死の両方の伝承が益田にあるわけです。","江戸時代、人麻呂は «歌聖» として神格化され、明石（兵庫県）の柿本神社とともに、全国の歌人の信仰を集めました。","本殿は江戸時代の建物で、島根県の文化財に指定されています。"],"look":["丘の上の本殿","境内からの益田の町と日本海の眺め","人麻呂の歌碑","近くの戸田柿本神社（生誕地伝承）"],"q":["人麻呂が亡くなったと伝わる鴨島は、その後どうなったといわれる？","1026年の大地震と津波で海に沈んだといわれます。"],"koji":[{"w":"鴨山の 岩根しまける 我をかも 知らにと妹が 待ちつつあるらむ","m":"人麻呂が死を前に詠んだとされる歌。岩を枕に倒れた自分を知らず、妻は帰りを待っているのだろうか"}],"myth":"人麻呂の終焉の地・鴨島の水没・像の漂着は伝承。鴨山の場所は諸説。遷座・神位の年は通説。","img":["柿本人麻呂","万葉集","戸田柿本神社"],"wp":"高津柿本神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f6/Takatsu_Kakinomoto_Jinja_Haiden.jpg",3200,2400,"高津柿本神社"],["c:d/d8/Takatsu_Kakinomoto_Jinja_Torii.jpg",3200,2400],["c:a/a8/Takatsu_Kakinomoto_Jinja_Hitomarokouzou.jpg",1800,2400],["c:8/81/%E6%9F%BF%E6%9C%AC%E4%BA%BA%E9%BA%BB%E5%91%82%EF%BC%88%E7%8B%A9%E9%87%8E%E5%AE%89%E4%BF%A1%E7%AD%86%EF%BC%89.jpg",3714,4119,"柿本人麻呂"],["c:a/ae/Genryaku_Manyosyu.JPG",1333,1000,"万葉集"]]},{"id":"32_hamada_jo","n":"浜田城（長州軍に追われ自焼）","yomi":"はまだじょう","cat":"城","rank":"A","y":1620,"era":["edo"],"sh":"県指定史跡","ad":"浜田市殿町","st":"JR山陰本線・浜田駅から歩いて約15分","la":34.9012,"lo":132.0765,"hook":"«敵に渡すくらいなら» ――幕末、長州軍が迫る中、藩士たちは自らの城に火を放った。","lead":"浜田城は、江戸時代の初めに古田重治が築いた城で、浜田藩の政治の中心でした。1866年の第二次長州征討で、長州軍に攻められた浜田藩は、城に自ら火をつけて退きました。今は石垣が残り、城山公園になっています。","story":["1619年（元和5年）、伊勢の松坂から古田重治が石見の浜田にやってきました。重治は海に面した小高い山に城を築き、ふもとに城下町をつくります。これが浜田城、別名 «亀山城» です。石見の西の守りと、日本海の港をおさえる大切な城でした。","その後、城主は何度か代わり、幕末には松平武聰（たけあきら）が藩主となりました。武聰は水戸藩主・徳川斉昭の子で、のちの15代将軍・徳川慶喜の弟です。つまり浜田藩は、徳川将軍家ととても近い藩だったのです。","1866年、幕府は長州藩を討つために軍を出しました（第二次長州征討）。石見方面では、大村益次郎が率いる長州軍が益田から攻め入り、浜田藩をはじめとする幕府方の軍は次々に敗れます。藩主の武聰は病気で、指揮をとることもままなりませんでした。","7月18日、浜田藩はついに城を守ることをあきらめました。«城を敵に使わせるわけにはいかない»。藩士たちは城に火を放ち、藩主とともに松江の方へ退きました。天守も櫓も、炎の中に消えていきました。«なぜ戦わずに焼いたの?» 城を守るだけの兵力がもうなかったこと、そして城を敵の拠点にさせないためだったと考えられます。","浜田藩はその後、美作（岡山県）の鶴田に移り、浜田は長州藩の支配を受けることになりました。今、城山には本丸・二の丸の石垣が残り、二の丸には護国神社が建っています。本丸から見下ろす浜田の港と日本海は、この城が海を守るために築かれたことを教えてくれます。"],"tl":[["1619年","古田重治が浜田に入り、築城を始める"],["1623年ごろ","浜田城と城下町がほぼ完成"],["1648年","古田氏が断絶し、城主が代わる"],["1866年7月18日","第二次長州征討で浜田藩が城に火を放ち退く"],["明治以降","城跡は公園となり、二の丸に護国神社が建つ"]],"who":[["古田重治","浜田城を築いた初代藩主"],["松平武聰","幕末の藩主。徳川慶喜の弟"],["大村益次郎","石州口の長州軍を指揮した"],["浜田藩士たち","城に火を放って退いた"]],"deep":["浜田城は «亀山城» ともよばれ、海に突き出た丘を利用した平山城です。本丸には三重の天守があったとされます。","築城主の古田重治は、茶人・古田織部の一族とする説がありますが、系譜の関係には諸説があります。","浜田藩の藩主は古田氏のあと、松平（松井）氏、本多氏、松平（越智）氏などが入れかわりました。天保年間の «竹島事件» で浜田藩の関係者が処罰されたことも知られています。","浜田藩は城を焼いたあと、飛び地の美作・鶴田（岡山県）に移り、«鶴田藩» として明治を迎えました。","城跡には、浜田城の門と伝わる «北門» が移築されて残っています。島根県の史跡に指定されています。"],"look":["本丸・二の丸の石垣","移築された北門","本丸からの浜田港と日本海の眺め","二の丸の護国神社"],"q":["浜田藩の最後の藩主・松平武聰の兄にあたる将軍は？","15代将軍・徳川慶喜。どちらも水戸藩主・徳川斉昭の子です。"],"koji":[],"myth":"天守の形、北門の由来、古田重治と古田織部の関係には諸説・伝承がある。","img":["浜田藩","松平武聰","古田重治"],"wp":"浜田城","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/Hamada_castle_sannomaru_ishigaki2.JPG",3072,2304,"浜田城"],["c:e/e0/Hamada_castle_tamagura.JPG",3072,2304],["c:0/07/Hamada_castle_sanzyuuyagura.JPG",3072,2304],["c:2/2a/Hamada_castle_sannomaru_ishigaki1.JPG",3072,2304],["c:c/cd/Hamada_castle_sannomaru.JPG",3072,2304],["c:e/ef/Hamada_castle_rokkennnagaya.JPG",3072,2304],["c:a/ad/Hamada_castle_ninomonn1.JPG",3072,2304],["c:d/d4/Hamada_castle_ninomon3.JPG",3072,2304]]},{"id":"32_sekishuguchi","n":"石州口の戦いの跡（第二次長州征討・大村益次郎の長州軍）","yomi":"せきしゅうぐちのたたかいのあと","cat":"幕末","rank":"A","y":1866,"era":["edo"],"sh":"","ad":"益田市染羽町・東町周辺（益田の戦いの地）","st":"JR益田駅から歩いて約20分（医光寺・萬福寺周辺）","la":34.6745,"lo":131.8575,"hook":"最新の銃と戦術で、わずか一か月あまりで石見を制した長州軍。幕府の «終わりのはじまり» は、この石見の地にもあった。","lead":"1866年（慶応2年）の第二次長州征討で、長州藩は周りの四つの方面から攻められました。そのうち石見方面の戦いを «石州口の戦い» といいます。大村益次郎が率いる長州軍は益田から浜田へと進み、浜田城を落とし、石見銀山までおさえました。","story":["1866年、幕府は長州藩を討つため、大軍を四方から攻め込ませようとしました。長州では «四境戦争» とよばれる戦いです。石見との境の «石州口» では、長州軍の指揮をとったのが、医者から兵学者になった大村益次郎でした。","長州軍は、まず津和野藩の領地を通りました。津和野藩は戦いに加わらず、長州軍の通過を認めたといわれます。そして6月、長州軍は浜田藩領の益田に入り、医光寺や萬福寺のあたりで幕府方の軍とぶつかりました。これが «益田の戦い» です。","このとき長州軍は、射程の長い新式の銃をもち、少人数の隊で素早く動く戦い方をとりました。«なぜ人数の多い幕府方が負けたの?» 幕府方は古い装備や戦い方のままで、指揮もまとまっていなかったためだといわれます。浜田藩のほか、福山藩・紀州藩などの兵も加わっていましたが、しだいに押し返されていきました。","益田の戦いでは、浜田藩の岸静江が関所を守って一人踏みとどまり、戦死したと伝わります。長州軍もその勇気をたたえたといわれ、益田には今も彼の墓があります。敵味方を問わず、多くの若者がこの戦いで命を落としました。","長州軍はさらに東へ進み、7月18日、浜田藩は城に火を放って退きました。その後、幕府の天領だった石見銀山も長州軍の支配下に入ります。石州口の勝利は、長州藩が幕府に勝つ大きな力となり、幕府の権威が崩れていくきっかけの一つとなりました。益田の寺々を歩くと、静かな境内に、150年前の激しい戦いの記憶が眠っています。"],"tl":[["1864年","第一次長州征討。長州藩は幕府に謝罪する"],["1866年6月","第二次長州征討が始まる。長州軍が津和野藩領を通って益田へ"],["1866年6月","益田の戦い。医光寺・萬福寺周辺で戦闘"],["1866年7月","周布・大麻山などで戦い、7月18日に浜田藩が城を焼いて退く"],["1866年7月","長州軍が石見銀山を支配下におく"],["1866年8月","将軍家茂の死去を受け、幕府は停戦へ向かう"]],"who":[["大村益次郎","石州口の長州軍を指揮した兵学者"],["岸静江","浜田藩士。関所を守り戦死したと伝わる"],["松平武聰","浜田藩主。徳川慶喜の弟"],["亀井茲監","津和野藩主。中立の立場をとった"]],"deep":["大村益次郎はもとの名を村田蔵六といい、蘭学・兵学者として長州藩の軍制改革を進めました。石州口の勝利で名を上げ、のちに戊辰戦争でも活躍します。","長州軍が使ったミニエー銃は、弾がまっすぐ遠くまで飛ぶよう工夫された銃で、幕府方の多くが使っていた古い火縄銃やゲベール銃に対して大きな差がありました。","津和野藩は長州藩のとなりにありながら、戦いには加わらず、長州軍の通過を認めました。藩主・亀井茲監の判断は、藩を戦火から守ったと評価される一方、幕府への背きとも見られました。","岸静江の最期の場所とされる «扇原関門» 跡には碑があり、益田市内に墓があります。人物の細部については伝承も多くふくまれます。","益田の医光寺・萬福寺には、戦いのときの弾痕と伝わる跡が残るとされます。見学の際は寺の方に確認してください。"],"look":["医光寺の総門と雪舟庭園（戦いの舞台）","萬福寺本堂（弾痕と伝わる跡）","岸静江の墓・扇原関門跡の碑","浜田城跡（最後の舞台）"],"q":["石州口の戦いで長州軍を指揮したのは誰？","大村益次郎。新しい銃と戦術で幕府方を破りました。"],"koji":[],"myth":"岸静江の最期の様子、寺に残る弾痕の由来は伝承をふくむ。戦闘の日付は資料により前後する。","img":["大村益次郎","医光寺"],"wp":"長州征討","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Modernized_troops_of_the_Second_Choshu_Expedition_1865.jpg",2825,1999],["c:8/80/Modern_Costumes_of_Japanese_Officers_Shogunate_Army_1866.png",2634,1980],["c:9/96/Takadahan_warriors_Second_Choshu_Expedition.jpg",2927,1438],["c:8/8f/Kuruma.png",1000,1000],["c:2/25/Keiheitai.jpg",800,527],["c:7/71/Masujiro_Omura_cropped.jpg",722,948,"大村益次郎"]]},{"id":"32_kurogi_gosho","n":"黒木御所跡（西ノ島の後醍醐天皇伝承地）","yomi":"くろぎごしょあと","cat":"伝承","rank":"A","y":1332,"era":["kamakura"],"sh":"","ad":"隠岐郡西ノ島町別府","st":"隠岐・西ノ島の別府港から歩いて約5分","la":36.096,"lo":133.058,"hook":"鎌倉幕府を倒そうとして流された天皇は、この小さな岬の館から脱出の機会をうかがったのか――。","lead":"黒木御所跡は、1332年に隠岐へ流された後醍醐天皇がいたと伝わる場所の一つです。西ノ島の別府港に近い小さな丘の上にあり、天皇をしのぶ碑と社があります。ふもとには資料館 «碧風館» があります。ただし行在所の場所は、隠岐の島町の国分寺とする説もあります。","story":["鎌倉時代の終わり、後醍醐天皇は鎌倉幕府を倒して、天皇中心の政治を取りもどそうと計画しました。しかし計画は失敗し（元弘の変）、1332年、天皇は幕府によって隠岐へ流されます。その100年あまり前、承久の乱で後鳥羽上皇が流されたのと同じ島々でした。","西ノ島の言い伝えでは、天皇はこの丘の上の館に住まわされたといいます。«黒木» とは、皮をはいでいない丸太のこと。急いでつくられた質素な館だったので、«黒木御所» とよばれたと伝わります。«都の天皇が、丸太の家に?» 島の人々は、天皇の苦労を思って、この話を大切に語り伝えてきました。","けれど後醍醐天皇はあきらめませんでした。本土では、楠木正成や護良親王が幕府と戦い続けていました。1333年のはじめ、天皇は見張りのすきをついて隠岐を脱出し、伯耆国（鳥取県）の名和長年のもとにたどり着きます。そして船上山で兵を挙げ、その年のうちに鎌倉幕府はほろびました。","脱出のとき、島の人々が天皇を助けたという話も、隠岐の各地に伝わっています。一方で、天皇がいたのは西ノ島ではなく、隠岐の島町の国分寺だったとする説も有力で、どちらが正しいかは今も決まっていません。","黒木御所跡の丘に登ると、別府の入り江と島々の景色が広がります。すぐ近くの資料館 «碧風館» には、後醍醐天皇にかかわる資料が展示されています。天皇がこの海を見つめながら何を思ったのか――想像しながら歩いてみてください。"],"tl":[["1221年","承久の乱。後鳥羽上皇が隠岐（中ノ島）に流される"],["1331年","元弘の変。後醍醐天皇の倒幕計画が失敗"],["1332年","後醍醐天皇が隠岐へ流される"],["1333年","後醍醐天皇が隠岐を脱出し、船上山で挙兵。鎌倉幕府がほろぶ"],["1334年","建武の新政が始まる"]],"who":[["後醍醐天皇","隠岐に流され、脱出して鎌倉幕府を倒した天皇"],["名和長年","伯耆の武士。隠岐を脱出した天皇を迎えた"],["楠木正成","天皇が隠岐にいる間も幕府と戦い続けた武将"],["後鳥羽上皇","承久の乱のあと隠岐に流された上皇"]],"deep":["後醍醐天皇の隠岐での行在所については、『太平記』などの記述をもとに、西ノ島の黒木御所説と、島後（隠岐の島町）の国分寺説があります。どちらも根拠となる伝承や史料があり、決着していません。","«黒木» は、樹皮をつけたままの丸木のことで、古くから仮の御殿や質素な建物を表す言葉として使われてきました。","天皇の脱出については『太平記』に物語風に書かれていますが、どこの港から出たのかなど細部には諸説があります。","黒木御所跡の近くには、天皇に仕えた人々にかかわる伝承地もあり、西ノ島では天皇にまつわる地名や祭りが語り継がれています。","隠岐は奈良時代から «遠流（おんる）» の地とされ、小野篁、後鳥羽上皇、後醍醐天皇などが流されました。"],"look":["丘の上の黒木御所跡の碑と社","別府の入り江の眺め","資料館 «碧風館»","西ノ島の摩天崖・国賀海岸（自然の名所）"],"q":["«黒木御所» の «黒木» とはどんな木のこと？","皮をはいでいない丸太のこと。急ごしらえの質素な館だったことを表しています。"],"koji":[],"myth":"後醍醐天皇の行在所の場所は西ノ島説と隠岐の島町（国分寺）説があり決着していない。","img":["後醍醐天皇","元弘の乱","西ノ島町"],"wp":"黒木御所","rel":{"ev":[],"grave":[]},"ph":[["c:0/0b/Emperor_Godaigo_by_Monkan-b%C5%8D_K%C5%8Dshin.jpg",1863,1860,"後醍醐天皇"],["c:b/b3/%E7%A8%B2%E6%9D%91%E3%83%B6%E5%B4%8E%E7%9F%B3%E7%A2%91.jpg",600,800,"元弘の乱"],["c:5/55/Matengai_Cliff_at_Kuniga_coast%2C_Nishinoshima.jpg",4752,3168,"西ノ島町"]]},{"id":"32_oki_sodo","n":"隠岐騒動（島民が郡代を追放した自治）","yomi":"おきそうどう","cat":"幕末","y":1868,"era":["edo","meiji"],"sh":"","rank":"A","ad":"隠岐郡隠岐の島町西郷地区（旧郡代役所があった港町）","st":"西郷港（本土の七類港・境港からフェリー・高速船）から歩いてすぐの港町一帯","la":36.205,"lo":133.325,"hook":"明治維新の年、日本海の島で、島の人々が役人を追い出し «自分たちで島を治めた»。そんな事件がありました。","lead":"1868年、隠岐の島後（どうご）の島民たちが、島を治めていた松江藩の郡代（役人の長）を島から追い出しました。そのあと、およそ80日ほど島の人たちが自分たちで島を運営したといわれます。«隠岐騒動» とよばれるこの出来事は、明治維新のまっただ中に起きた、とてもめずらしい «島の自治» の試みでした。","story":["幕末、日本の近くの海には外国の船がたびたび姿を見せるようになりました。隠岐は日本海のまんなかに浮かぶ島。幕府の領地でしたが、実際には松江藩が預かって治めていました。«異国船が来たらどうする?» 島の庄屋や神主たちは不安をつのらせ、自分たちで島を守る力を持ちたいと考えるようになります。","島には、京都で学んだ儒学者・中沼了三の教えを受けた若者たちがいました。彼らは «尊王»、つまり天皇を中心にした国づくりの考えに強くひかれていました。1867年、島の人々は若者が武芸や学問を学ぶ «文武館» をつくりたいと願い出ますが、松江藩の役人に聞き入れられませんでした。«自分たちの島を守りたいだけなのに、なぜ?» という不満がふくらみます。","1868年のはじめ、新しい政府から山陰道に «鎮撫使»（しずめる役目の使者）が送られてきます。そのころ、島の側に届いた文書の扱いをめぐって、松江藩との対立は一気に深まりました。そしてついに3月、島じゅうから集まった大勢の島民が郡代役所を取り囲み、郡代を島から退去させたのです。刀で斬りあう戦いではなく、数の力で «出ていってください» と迫った、と伝えられます。","その後、島では庄屋や神主たちが中心となって役所を運営しました。しかし5月、松江藩の兵が島にもどって役所を取り返そうとし、発砲によって島民側に死者が出てしまいます。故郷を守ろうとした人々の命が失われた、悲しい出来事でした。その後、鳥取藩などが間に入り、松江藩は兵を引きあげました。","翌年には隠岐県が置かれ、隠岐は新しい政府が直接治める土地になります。島の人たちの自治は短いあいだで終わりましたが、«島のことは島の人が決めたい» という思いは、今も隠岐の歴史を語るときに欠かせない物語です。のちに、この出来事を «隠岐コミューン» と呼んで、ヨーロッパの市民自治になぞらえる人も現れました。"],"tl":[["1863年ごろ","異国船への備えとして、隠岐の警備が強められる"],["1867年","島民が «文武館» 設立を願い出るが認められない"],["1868年3月","島民が郡代を島から退去させる（隠岐騒動）"],["1868年5月","松江藩兵が役所を奪い返そうとし、島民側に死者が出る"],["1868年","鳥取藩などの仲介で松江藩が撤兵する"],["1869年","隠岐県が置かれる（のち他県に合併）"]],"who":[["中沼了三","隠岐出身の儒学者。京都で教え、島の若者に尊王の考えを広めた"],["島後の庄屋・神主たち","騒動と自治の中心になった人々"],["松江藩の郡代","島を治めていた役人。島から退去させられた"],["鳥取藩","松江藩と島民のあいだに入り、争いを収める役目を果たした"]],"deep":["«自治は約80日» という数字がよく語られますが、どこからどこまでを数えるかで長さは変わります。松江藩兵の撤退後も島民側の運営が続いた期間を含めると、もっと長いとみる見方もあります。","隠岐は幕府の天領でしたが、実際の支配は松江藩の «預かり» でした。幕府がなくなりかけた時期に «島はいったい誰のものか» があいまいになったことが、騒動の大きな背景です。","騒動の中心は武士ではなく、庄屋や神主など島の有力者でした。隠岐は神社の多い島で、神主たちは読み書きや学問に明るく、島の意見をまとめる力を持っていました。","明治のはじめ、政府は神仏分離の方針を出しました。隠岐ではその後、寺や仏像が大きく壊される «廃仏毀釈» が特にはげしく起きたことで知られ、騒動を担った人々の考え方とのつながりが指摘されています。","騒動をあらわした記録や、島民が出した願書などが残っており、郷土史家や研究者によって少しずつ読み解かれてきました。出来事の日付や人数には、史料によって違いがあります。"],"look":["西郷港のまわり（郡代役所があった港町の雰囲気）","隠岐郷土館で、島の明治のころの資料","島じゅうに残る神社（騒動を支えた神主たちの舞台）"],"q":["隠岐騒動で、島民が島から退去させたのは誰?","松江藩の «郡代»（島を治める役人の長）です。島民は大勢で役所を囲み、退去を迫りました。"],"myth":"自治の日数、参加した人数、死者の数は史料や数え方で違いがある。«隠岐コミューン» は後世の呼び方。","img":["隠岐国","中沼了三","隠岐諸島","廃仏毀釈"],"wp":"隠岐騒動","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/51/20090923%E9%9A%A0%E5%B2%90%E8%AB%B8%E5%B3%B6.jpg",1202,960,"隠岐諸島"],["c:0/03/Rosoku-is.jpg",1024,768,"近く: 隠岐の島町"],["c:2/24/Tamawakasumikoto_jinja_Haiden.JPG",2352,1568,"近く: 玉若酢命神社"],["c:9/94/Tamawakasumikoto-jinja_8gou-fun.JPG",6016,4000,"近く: 玉若酢命神社古墳群"],["c:b/bb/Mioya-jinja_%28Okinoshima%29%2C_haiden.jpg",5966,3924,"近く: 水祖神社"],["c:d/d6/Oshiro_Funkyu-bo_zenkei.JPG",6016,4000,"近く: 大城墳丘墓"]]},{"id":"32_taishaeki","n":"旧大社駅（神殿風の駅舎）","yomi":"きゅうたいしゃえき","cat":"近代","y":1924,"era":["taisho","showa"],"sh":"国の重要文化財","rank":"A","ad":"出雲市大社町北荒木","st":"一畑電車 出雲大社前駅から歩いて約20分。JR出雲市駅からバスも利用できる","la":35.3872,"lo":132.688,"hook":"駅なのに、まるで神社。出雲大社へ向かう人をむかえた、大きな屋根の «神殿のような駅»。","lead":"旧大社駅は、出雲大社の近くにあった国鉄大社線の終点の駅です。今の駅舎は1924年に建てられたもので、瓦屋根が重なる和風の姿が、神社の建物のように見えます。大社線は1990年に廃止されましたが、駅舎はそのまま残され、国の重要文化財になっています。","story":["明治の終わり、出雲大社へお参りする人は、まだ馬車や歩きで長い道のりを進んでいました。«もっと多くの人に、楽に大社まで来てほしい。» そんな願いから、1912年、出雲今市（いまの出雲市）から大社までの鉄道が開かれました。これが大社線です。","やがて参拝の人がふえ、最初の駅舎では手ぜまになりました。そこで1924年に建て替えられたのが、いま残る駅舎です。高い天井、大きな木の梁、神社のような屋根。駅に降りた人は «ああ、神々の国に来たのだ» と感じたことでしょう。なぜこれほど立派なのか? それは大社線が、全国から大社参りの人を運ぶ «表玄関» の役目を持っていたからです。","昭和のころには、大阪などから大社まで直通の列車も走りました。団体旅行の臨時列車が何本も着き、長いホームは人でいっぱいになったといいます。駅前から大社の鳥居まで続く神門通りは、にぎやかな参道になりました。","しかし自動車やバスが広まると、鉄道を使う人は少しずつ減っていきました。そして1990年3月31日、大社線は最後の列車を見送り、翌日に廃止されます。地元の人たちは «この駅だけは残したい» と願い、駅舎は壊されずに保存されました。","今も駅舎の中には、昔の出札口（切符売り場）や待合室が残り、ホームと線路の一部、そして蒸気機関車D51が静かに置かれています。列車はもう来ませんが、人々を大社へ送り出した時間が、建物の中にそのまま閉じこめられているようです。"],"tl":[["1912年","大社線が開業し、大社駅ができる"],["1924年","現在の駅舎に建て替えられる"],["昭和のころ","大阪方面などからの直通列車や団体臨時列車が乗り入れる"],["1990年","大社線が廃止され、駅も役目を終える"],["2004年","駅舎が国の重要文化財に指定される"]],"who":[["出雲大社への参拝客","この駅のいちばんのお客さん。全国から集まった"],["鉄道院・鉄道省の技術者","神社風の駅舎を設計・建設した"],["大社の町の人々","廃止後も駅舎を守り、保存を願った"]],"deep":["駅舎は木造平屋で、屋根は «入母屋造» を組み合わせた和風。外から見ると大きな屋根が何段にも重なり、正面の車寄せが堂々とした印象をつくっています。","内部は高い天井と太い梁が見どころ。和風の外観に対し、室内には洋風のシャンデリア風照明が下がるなど、大正時代らしい «和と洋のまじりあい» が感じられます。","大社には鉄道の駅がふたつありました。国鉄の大社駅と、一畑電鉄（現・一畑電車）の出雲大社前駅です。出雲大社前駅の駅舎（1930年）も洋風の近代建築として知られ、ふたつをくらべるとおもしろいです。","大社線は全長7.5kmほどの短い路線でした。短いのに立派な駅を持っていたところに、«参拝の鉄道» という性格がよく表れています。","ホームには国鉄の蒸気機関車 D51 が保存されています。大社線で実際にどの車両が走っていたかは時期によって違うので、展示車両は «鉄道の時代の記念» として見るとよいでしょう。"],"look":["大きな屋根が重なる正面の外観","待合室の高い天井と照明","出札口（切符売り場）の窓口","ホームと保存されたD51形蒸気機関車"],"q":["大社線が廃止されたのは何年?","1990年です。3月31日に最後の列車が走り、その後も駅舎は保存されて、2004年に国の重要文化財になりました。"],"myth":"","img":["大社線","出雲大社","出雲大社前駅","国鉄D51形蒸気機関車"],"wp":"大社駅","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/Kyu-Taisha_station01st3200.jpg",3200,2130,"大社駅"],["c:8/87/Old_Taisha_station_Under_construction_2021.jpg",5056,3792],["c:c/cb/Kyu-Taisha_station06s4592.jpg",4592,3056],["c:b/b3/Kyu-Taisha_station05n4592.jpg",4592,3056],["c:a/a7/Kyu-Taisha_station02s4592.jpg",4592,3056],["c:7/72/D51_774_at_Taisha_Station-2.jpg",5365,3575],["c:d/d4/Taisha_Station_Fare_Gate.jpg",3648,2736],["c:6/64/Taisha_Station_Timetable.jpg",3618,2696]]},{"id":"32_taisha_kichi","n":"大社基地跡（斐川の旧海軍飛行場・掩体壕）","yomi":"たいしゃきちあと","cat":"昭和","y":1945,"era":["showa"],"sh":"","rank":"A","ad":"出雲市斐川町（出西・直江周辺の平野部）","st":"JR直江駅・出雲市駅から車で10〜15分ほど。遺構は田畑の中に点在し、車での見学が便利","la":35.37,"lo":132.82,"hook":"戦争の終わりの年、出雲の田んぼの中に、大急ぎで海軍の飛行場がつくられた。","lead":"大社基地は、太平洋戦争の終わりごろ、今の出雲市斐川町の平野につくられた海軍の飛行場です。«大社» と名前がついていますが、場所は大社町ではなく斐川の田んぼの広がる地域でした。いまも、飛行機をかくすための施設などの跡が、畑や住宅地の中に残っています。","story":["1944年、戦争は日本にとってますます苦しくなっていました。本土の空を守り、また攻撃に出るための飛行場が、全国で急いでつくられます。出雲平野の斐川の地もそのひとつに選ばれました。広く平らで、長い滑走路をとることができたからです。","工事には、地元の人々や学生、たくさんの人手がかり出されたといわれます。«一日でも早く完成させよ。» 田んぼをつぶし、土を運び、固める。重い機械は多くなく、人の力で進められた工事でした。家や田畑を手放さなければならなかった人もいました。","基地が使われはじめたのは1945年、戦争最後の年です。海軍の飛行機が配備され、ここから出撃した部隊もあったと伝えられます。7月ごろにはアメリカ軍の飛行機による空襲も受けました。なぜ出雲の平野にまで? それは、ここがすでに戦いの最前線の一部になっていたからです。","8月15日、戦争は終わりました。基地は使われなくなり、やがて滑走路のあとは農地へともどされていきます。いまこの地を歩くと、ふつうの田園風景の中に、コンクリートのかたまりのような建物がぽつんと残っているのに気づきます。それが、飛行機や物資を守るためにつくられた施設の跡です。","この場所では、ここで働いた人、ここから飛び立った人、そして空襲で被害を受けた人たちがいました。遺構は、その人たちのことを静かに伝える記憶の場所です。見学のときは、亡くなった方々への思いを胸に、そっと見てまわりたいところです。"],"tl":[["1944年","出雲平野の斐川で海軍飛行場の建設が始まる"],["1945年","大社基地として使われはじめる"],["1945年7月ごろ","アメリカ軍機の空襲を受けたと伝わる"],["1945年8月","終戦。基地は役目を終える"],["戦後","滑走路などの跡地は農地や住宅地にもどされる"]],"who":[["海軍航空隊の隊員","基地に配属され、飛行機を運用した"],["地元の住民・学生","建設工事に動員された"],["土地を提供した農家","田畑を基地用地として手放した"]],"deep":["名前の «大社» は、出雲大社のある大社町から取られたともいわれますが、基地の本体は斐川町側にありました。旧海軍の飛行場は、近くの有名な地名で呼ばれることがよくありました。","戦争末期につくられた飛行場は、わずか1年たらずで工事から終戦までを迎えたものが多く、大社基地もそのひとつです。短い期間しか使われなかったため、記録が少なく、細かなことにはまだわからない点があります。","「掩体壕（えんたいごう）」は、空襲から飛行機を守るために土やコンクリートでつくった «かまぼこ形の車庫» のような施設です。全国の飛行場跡に残っていますが、出雲にも関連する遺構が伝わっています。","遺構の多くは田畑や私有地の中にあります。見学は道路から見るのが基本で、勝手に敷地へ入らないようにしましょう。地元では戦争遺跡として調べ、伝える取り組みも行われています。","戦後、出雲の空の玄関は «出雲空港»（斐川町）として別の場所に生まれました。同じ斐川の平野に、戦争の飛行場と平和な時代の空港がある、というつながりも覚えておきたい点です。"],"look":["田園の中に残るコンクリートの遺構","平らで広い出雲平野（滑走路が置かれた理由がわかる）","地元の案内板や説明板"],"q":["飛行機を空襲から守るための «かまぼこ形» の施設を何という?","«掩体壕（えんたいごう）» です。土やコンクリートで飛行機をおおい、爆撃から守りました。"],"myth":"配備された機種・部隊、出撃の詳細、空襲の日付や被害の規模は資料によって違い、確かめきれていない点が多い。遺構の位置も要確認。","img":["掩体壕","出雲空港","斐川町"],"wp":"大社基地","rel":{"ev":[],"grave":[]},"ph":[["c:8/8f/Former_Taisha_Air_Base_Site.jpg",3032,2274,"大社基地"],["c:f/f8/Typhoon_Takes_Off_from_RAF_Coningsby_as_Part_of_Op_Ellamy_MOD_45152517.jpg",3000,1805,"掩体壕"],["c:5/5c/150322_Izumo_Airport_Izumo_Shimane_pref_Japan01s3.jpg",6000,4000,"出雲空港"],["c:7/7a/Koujindani_Remains_01.JPG",1600,1064,"斐川町"]]},{"id":"32_akana_jo","n":"赤穴城（尼子と毛利の境目の城）","yomi":"あかなじょう","cat":"城","y":1542,"era":["muromachi","azuchi"],"sh":"","rank":"A","ad":"飯石郡飯南町赤名","st":"JR三次駅や出雲市駅から車で約1時間。赤名の町なかから登山道あり","la":34.997,"lo":132.708,"hook":"出雲の南の入り口。大内の大軍を、ここで何十日も足止めした城がある。","lead":"赤穴城は、出雲と備後（広島県）の国境に近い赤名の町にあった山城で、«瀬戸山城» ともよばれます。戦国時代、出雲の尼子氏の南の守りでした。1542年、大内義隆の大軍が出雲へ攻めこんだとき、城主・赤穴光清がここで大軍を長く食い止めたことで知られています。","story":["赤名は、山陽側から出雲へ入る峠道の町です。«ここを越えれば出雲。» 旅人も軍勢も、必ずこの道を通りました。その道をにらむ山の上に、赤穴氏の城がありました。赤穴氏はこの地を治める領主で、出雲の尼子氏に従っていました。","1542年、周防・長門（山口県）の大名・大内義隆が、尼子氏をたおそうと大軍で出雲へ攻め入ります。その軍勢の中には、まだ若い毛利元就の姿もありました。大内軍が最初にぶつかったのが、この赤穴城でした。«小さな山城など、すぐに落ちるだろう。» ところがそうはいきませんでした。","城主の赤穴光清は、兵をはげまして守りを固め、大内軍の攻撃を何度もはね返しました。攻める側にも名のある武将の戦死が出たと伝わります。戦いは長引き、大内軍は思わぬところで時間をうばわれました。しかし戦いのさなか、光清は矢に当たって討ち死にしたといわれ、城はついに開かれます。","赤穴城で足止めされたことは、そのあとの大内軍の月山富田城攻めにも影を落としたと考えられています。大内軍は富田城を落とせず、大きな損害を出して退きました。なぜ負けたのか? 赤穴での苦戦もそのひとつだった、と語られることがあります。","その後、尼子氏がほろびると、赤穴城は毛利氏の城となり、江戸時代のはじめにその役目を終えました。今の山の上には、曲輪（くるわ）や堀切などの跡が残り、赤名の町と峠道を見おろすことができます。"],"tl":[["戦国時代","赤穴氏が赤名を治め、尼子氏に従う"],["1542年","大内義隆の出雲攻めで、赤穴光清が籠城して抵抗"],["1542年","光清が討ち死にし、城が開かれると伝わる"],["1543年","大内軍が月山富田城攻めに失敗して退く"],["1566年","尼子氏が毛利氏に降伏。赤穴は毛利方の拠点に"],["江戸時代初め","城としての役目を終える"]],"who":[["赤穴光清","城主。大内の大軍を相手に籠城し、戦死したと伝わる"],["大内義隆","周防の大名。出雲攻めの総大将"],["毛利元就","大内軍の一員として出雲攻めに加わった"],["尼子晴久","出雲の大名。赤穴氏の主君"]],"deep":["«赤穴» と «赤名»: 城の名や一族の名は «赤穴»、今の地名は «赤名» と書くのがふつうです。どちらも «あかな» と読みます。","城は «瀬戸山城» の名でも知られます。山頂部に主郭を置き、尾根にそって曲輪をならべ、堀切で区切る、中国山地らしい山城のつくりです。","1542〜43年の大内氏の出雲遠征は、大内氏が衰えるきっかけになったともいわれます。義隆は養子の大内晴持をこの退却の途中で失いました。","毛利元就にとって、この遠征の失敗は «出雲の尼子は簡単には倒せない» という苦い教訓になりました。約20年後、元就は時間をかけた包囲作戦で尼子氏を追いつめます。","赤名は江戸時代も出雲と備後を結ぶ街道の宿場として栄えました。城のふもとの町並みにも、峠の町の雰囲気が残っています。"],"look":["山頂の主郭と、そこから見える赤名の町と峠道","尾根を断ち切る堀切","登山口の案内板"],"q":["1542年、赤穴城を攻めた大内軍の総大将は誰?","周防の大名・大内義隆です。軍の中には若いころの毛利元就もいました。"],"myth":"光清の戦死のようす、籠城の日数、攻め手の戦死者などは軍記物にもとづく部分があり、細部には諸説がある。","img":["瀬戸山城","赤穴光清","大内義隆","月山富田城"],"wp":"赤穴城","rel":{"ev":[],"grave":[]},"ph":[["c:4/4e/Akana_Castle.jpg",3872,2592,"赤穴城"],["c:2/29/Matsuda_Sakon_Grave.JPG",5184,3456],["c:a/ad/Iinan_Distant_view.JPG",5184,3456],["c:5/5f/Akana_Castle_Ooremon.JPG",5184,3456],["c:3/3b/Akana_Castle_Honmaru.JPG",5184,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:7/7f/%C5%8Cuchi_Yoshitaka.jpg",1249,2545,"大内義隆"],["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"]]},{"id":"32_shiraga_jo","n":"白鹿城（毛利元就の出雲攻め）","yomi":"しらがじょう","cat":"城","y":1563,"era":["muromachi"],"sh":"","rank":"A","ad":"松江市法吉町","st":"JR松江駅からバスで法吉方面へ約20分、そこから登山道を歩いて約30分","la":35.496,"lo":133.053,"hook":"月山富田城を守る «尼子十旗» の第一の城。毛利元就はここを落とすため、地面の下まで戦場にしたといわれる。","lead":"白鹿城は、松江市の北にある山城で、尼子氏の本城・月山富田城を守る支城のなかでも特に大切な城でした。1563年、毛利元就の大軍に囲まれ、長い戦いのすえに落城します。この城が落ちたことで、尼子氏は日本海側からの補給の道を失い、ほろびへの道を歩みはじめました。","story":["1560年代、中国地方で勢いを伸ばした毛利元就は、宿敵・尼子氏の出雲へついに攻めこみます。尼子氏の本城・月山富田城は «難攻不落» といわれた名城。元就は正面からいきなり攻めるのではなく、まわりの城を一つずつ落として、富田城を孤立させる作戦を選びました。","その最初の大きな目標が白鹿城でした。白鹿城は宍道湖と中海にはさまれた島根半島のつけ根にあり、日本海から富田城へ兵糧を運ぶ «命綱» を守る位置にありました。城を守ったのは尼子方の松田氏。«ここを失えば、富田は干上がる。» 城兵は必死でした。","1563年、毛利軍は城を囲みます。攻撃は激しく、毛利軍は石見銀山の鉱夫を使って城の下へ坑道を掘り、水の手（井戸）をねらったと伝わります。尼子側も負けずに掘り返し、地下で両軍がぶつかった、という話も残っています。本当に地面の下で戦ったのでしょうか? 真偽は分かりませんが、それほど必死の攻防だったことが伝わってきます。","尼子氏は富田城から救援の軍を出しましたが、毛利軍にはばまれて城に近づけませんでした。やがて城内の水や食料はつき、白鹿城はついに降伏します。攻撃が始まってからおよそ2か月あまりのことでした。","この戦いの少し前、元就は長男・隆元を急な病で失っていました。悲しみのなかで進めた出雲攻めだったのです。白鹿城が落ちたことで尼子氏の補給路は細り、1566年、月山富田城は開城します。いま山の上には、曲輪の跡と «白鹿城跡» の碑が、静かに松江の町を見下ろしています。"],"tl":[["戦国時代","尼子氏が白鹿城を富田城の支城として重視する"],["1562年","毛利元就が出雲へ進攻を始める"],["1563年8月","毛利隆元が出雲へ向かう途中で急死"],["1563年","毛利軍が白鹿城を包囲し、坑道を掘って攻めたと伝わる"],["1563年秋","白鹿城が降伏・落城"],["1566年","月山富田城が開城し、尼子氏が降伏"]],"who":[["毛利元就","白鹿城を攻めた毛利軍の総大将"],["松田誠保","城を守った尼子方の武将と伝わる"],["尼子義久","尼子氏当主。富田城から救援軍を送った"],["毛利隆元","元就の長男。出雲攻めの途中に急死した"]],"deep":["«尼子十旗» は、月山富田城のまわりを守った10の支城をまとめた呼び名で、白鹿城はその «第一» とされます。ただし十旗の顔ぶれは史料によって少しちがいます。","白鹿城は、島根半島の港と富田城を結ぶ補給ルートの要でした。毛利は白鹿を落とすことで、日本海側からの兵糧補給を断つことをねらったと考えられています。","坑道戦の話は、石見銀山を押さえていた毛利ならではのエピソードとして有名ですが、軍記物にもとづく話で、細部までは確かめられていません。","元就は白鹿城攻めの近くに陣を置き、ふもとには «真山城»（しんやまじょう）などの関連の城もあります。のちに尼子再興軍の山中鹿介は、この真山城を拠点にしました。","城跡には曲輪・堀切・土塁などが残り、戦国の山城のつくりを歩いて感じることができます。地元では案内板や登山道の整備が進められています。"],"look":["山頂の曲輪群と «白鹿城跡» の碑","城を区切る堀切","山の上から見る宍道湖・中海と松江の町","近くの真山城跡"],"q":["白鹿城を攻めるとき、毛利軍が坑道を掘るために使ったといわれるのは?","石見銀山の鉱夫（ほりこ）です。銀山を持っていた毛利ならではの作戦と伝わります。"],"koji":[{"w":"兵糧攻め","m":"城を囲んで食料や水が入らないようにし、降伏させる攻め方。白鹿城は水の手を断たれて降伏した"}],"myth":"坑道戦のようす、城将の名、包囲の日数は軍記物による部分が多く諸説ある。","img":["毛利元就","月山富田城","尼子十旗","毛利隆元"],"wp":"白鹿城","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Shiraga_castle.jpg",3872,2592,"白鹿城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"],["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"],["c:e/ed/M%C5%8Dri_Takamoto.jpg",1013,1158,"毛利隆元"]]},{"id":"32_fube_yama","n":"布部山の戦い（山中鹿介の尼子再興軍）","yomi":"ふべやまのたたかい","cat":"古戦場","y":1570,"era":["muromachi"],"sh":"","rank":"A","ad":"安来市広瀬町布部","st":"JR安来駅から車で約30分。広瀬町の月山富田城跡から南へ車で約15分","la":35.333,"lo":133.195,"hook":"«願わくば我に七難八苦を与えたまえ»。その言葉で知られる山中鹿介が、毛利の大軍とぶつかった山。","lead":"布部山の戦いは、1570年、ほろびた尼子氏をもう一度立て直そうとした «尼子再興軍» と、毛利氏の大軍とのあいだで起きた戦いです。再興軍を率いたのは尼子勝久と、家臣の山中鹿介。月山富田城の南にある布部の山で戦いましたが、再興軍は敗れ、出雲での再興の夢は大きく遠のきました。","story":["1566年、尼子氏は月山富田城を開き、毛利元就に降伏しました。けれども、あきらめない家臣がいました。山中鹿介です。鹿介は、京都の寺にいた尼子一族の若者・勝久をむかえて主君とし、«尼子をもう一度!» と旗を上げました。","1569年、再興軍は隠岐から島根半島へ上陸します。毛利の主力が九州で戦っていたすきをつき、出雲のあちこちの城をたちまち取りもどしました。散らばっていた旧臣たちも次々と集まり、再興軍の勢いは大きくふくらみます。残るは毛利方が守る月山富田城。再興軍はこれを囲みました。","しかし毛利も黙ってはいません。1570年、元就の孫・毛利輝元を総大将に、吉川元春・小早川隆景の大軍が出雲へやってきます。«富田城を救え。» 再興軍は富田城の南、布部の山に陣を構えて、毛利軍をむかえ討つことにしました。","戦いは山の地形を生かした再興軍が、はじめは有利に進めたともいわれます。けれども、兵の数の差は大きく、毛利軍が別の道から回りこむと、再興軍の陣はくずれました。多くの兵が討たれ、鹿介たちは退くしかありませんでした。","この敗戦で、再興軍は出雲での力を大きく失いました。それでも鹿介はあきらめず、そのあとも各地で戦いを続けます。やがて織田信長の力を借り、播磨の上月城で最後の戦いにいどむことになるのです。布部の山には古戦場の碑が立ち、再起にかけた人々の姿を今に伝えています。"],"tl":[["1566年","月山富田城が開城し、尼子氏が毛利氏に降伏"],["1568〜69年","山中鹿介らが尼子勝久をむかえ、再興軍を起こす"],["1569年","再興軍が島根半島に上陸し、出雲の城を次々に奪う"],["1570年","布部山の戦い。毛利輝元らの軍に再興軍が敗れる"],["1578年","播磨の上月城が落ち、勝久は自害。鹿介も護送中に討たれる"]],"who":[["山中鹿介幸盛","尼子再興軍の中心人物。«七難八苦» の逸話で知られる"],["尼子勝久","再興軍の主君。尼子一族の出身"],["毛利輝元","元就の孫。毛利軍の総大将"],["吉川元春","元就の次男。毛利軍の主力を率いた"],["小早川隆景","元就の三男。毛利軍の一翼をになった"]],"deep":["布部山の戦いの年は、元号が永禄から元亀に変わる年でした。そのため «永禄13年» とも «元亀元年» とも書かれます。","再興軍の上陸地は、島根半島の «千酘（ちいそ）» の浦と伝えられます。そこから近くの真山城などを拠点にしました。","このとき毛利元就は年老いて病気がちで、実際の指揮は孫の輝元と、吉川・小早川の «毛利両川» がになったとされます。","«願わくば我に七難八苦を与えたまえ» は、三日月に祈った鹿介の言葉として有名です。ただしこれは後世の軍記物や読み物で広まった話で、本人の言葉として確かめられているわけではありません。","布部山の敗戦のあとも、再興軍は出雲の一部でしばらく抵抗を続けました。完全に出雲から退いたのは翌年以降とされます。"],"look":["布部山古戦場の碑と説明板","月山富田城跡（再興軍が囲んだ城）","城跡の近くにある山中鹿介の像"],"q":["尼子再興軍が主君としてむかえた尼子一族の若者は?","尼子勝久です。京都の寺にいたところを、山中鹿介らがむかえて大将にしました。"],"koji":[{"w":"願わくば我に七難八苦を与えたまえ","m":"どんな苦しみでも受けて立つから、主家再興の力を与えてほしい、という鹿介の祈りとして伝わる言葉"}],"myth":"戦いの経過（回りこみの有無など）や兵力は軍記物による。«七難八苦» の祈りは伝承。","img":["山中幸盛","尼子勝久","月山富田城","上月城の戦い"],"wp":"布部山の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/%E5%B8%83%E9%83%A8%E3%81%AE%E4%B8%AD%E5%B1%B1.jpg",4608,3456,"布部山の戦い"],["c:4/4f/%E7%A4%BE%E6%97%A5%E7%A5%9E%E7%A4%BE%E8%B7%A1.jpg",4608,3456],["c:a/a5/%E5%B8%83%E9%83%A8%E5%B1%B1%E3%81%AE%E6%88%A6%E3%81%84%EF%BC%BF%E5%90%88%E6%88%A6%E5%9B%B3.png",5200,4600],["c:6/61/%E5%B8%83%E9%83%A8%E3%81%AE%E8%A6%81%E5%AE%B3%E5%B1%B1.jpg",4608,3456],["c:2/2b/%E5%B0%BC%E5%AD%90%E6%9C%AC%E9%99%A3%E3%81%AE%E5%90%8D%E6%B0%B4.jpg",3456,4608],["c:7/74/%E5%A4%9A%E4%B9%85%E5%92%8C%E5%9F%8E.jpg",4608,3456],["c:4/40/Mori_Motonari.jpg",1935,4000],["c:4/4f/%E5%B8%83%E9%83%A8%E5%B1%B1%E3%81%AE%E6%88%A6%E3%81%84%EF%BC%BF%E9%80%B2%E8%B7%AF%E5%9B%B3.png",1600,1600]]},{"id":"32_oki_kyodokan","n":"隠岐郷土館（旧周吉外三郡役所）","yomi":"おききょうどかん","cat":"近代","y":1885,"era":["meiji"],"sh":"県指定有形文化財","rank":"A","ad":"隠岐郡隠岐の島町郡","st":"西郷港から車で約30分（島の北西部・五箇地区）。バスは本数が少ないので要確認","la":36.281,"lo":133.244,"hook":"島の緑の中に、白い洋館。明治の隠岐の役所が、そのまま島の歴史の «宝箱» になった。","lead":"隠岐郷土館は、明治時代に建てられた «周吉外三郡役所» の建物を使った郷土資料館です。島後の五箇地区にあり、白い壁と上げ下げ窓の洋風の建物が目を引きます。館の中には、隠岐の島の暮らしや祭り、漁や牛の飼育の道具などが展示され、島の歴史をまるごと知ることができます。","story":["明治になって、隠岐は «周吉（すき）»«穏地（おち）»«海士（あま）»«知夫（ちぶ）» の4つの郡に分けられました。これらをまとめて治める役所として建てられたのが «周吉外三郡役所»。«周吉ほか三つの郡» という意味です。","建物は1885年に完成したとされます。そのころ、日本の各地で «文明開化» の洋風建築がつくられていました。けれど、ここは本土から船で何時間もかかる島。«島にも新しい時代の役所を。» 大工たちは、見たことのない洋館を、見よう見まねで建てたのかもしれません。","役所としての仕事を終えたあと、建物は現在の場所に移されて郷土館になりました。いまは、隠岐の人たちが使ってきた生活道具や漁具、民俗資料が並んでいます。隠岐の島々に伝わる牛突き（闘牛）や、古典相撲の資料も見ることができます。","なぜ島の役所の建物が大切に残されたのでしょう? それは、この建物そのものが «隠岐が近代の日本に加わった証» だからです。郷土館の近くには、昔の民家を移した展示もあり、島の暮らしの移り変わりを感じられます。","窓の外には、隠岐の山と田んぼが広がります。展示を見たあとで外に出ると、ここで暮らしてきた人たちの長い時間が、景色の中にとけこんでいるように感じられるでしょう。"],"tl":[["1868〜69年","隠岐騒動を経て、隠岐県などが置かれる"],["明治時代","隠岐は周吉・穏地・海士・知夫の4郡に"],["1885年","周吉外三郡役所の庁舎が建てられる"],["昭和時代","建物が移築され、隠岐郷土館として公開される"]],"who":[["隠岐の島民","郡役所を通して、明治の新しい行政を体験した"],["郡役所の役人","4郡の行政をまとめた"],["地元の大工","島で洋風の庁舎を建てた"]],"deep":["外観は擬洋風建築とよばれるスタイル。西洋の建物をまねながら、日本の大工の技術で建てた、明治ならではの建物です。","郡の名前の «周吉» は «すき»、«穏地» は «おち» と読みます。古代の隠岐国には4つの郡があり、その名前が明治にも引き継がれました。","«牛突き» は隠岐の島町に伝わる伝統の闘牛で、鎌倉時代に隠岐に流された後鳥羽上皇をなぐさめるために始まった、という言い伝えがあります（確かな記録ではありません）。","隠岐の島々は «隠岐ユネスコ世界ジオパーク» に認定されています。郷土館の展示は、島の自然と人の暮らしのつながりを知る入り口にもなります。","開館期間や休館日は季節によって変わることがあります。冬は休館することもあるので、行く前に確認しましょう。","明治の郡役所は、県と町村のあいだで税や戸籍、学校などの仕事をまとめる役所でした。郡役所の制度は大正時代に廃止され、多くの庁舎が姿を消したため、残っている建物は貴重です。"],"look":["白壁と上げ下げ窓の洋風の外観","島の生活道具・漁具の展示","牛突きなど隠岐の祭りの資料"],"q":["«周吉外三郡役所» の «三郡» とは、周吉のほかどの郡?","«穏地»«海士»«知夫» の3つです。隠岐の4つの郡をまとめて治める役所でした。"],"myth":"建築年・移築年、文化財の指定区分は要確認。牛突きの起源の話は伝承。","img":["隠岐郡","隠岐の島町","擬洋風建築","隠岐国"],"wp":"隠岐郷土館","rel":{"ev":[],"grave":[]},"ph":[["c:9/96/Oki_Kyodo-kan.jpg",6016,4000,"隠岐郷土館"],["c:4/44/Shimane_Oki-gun.png",310,240,"隠岐郡"],["c:0/03/Rosoku-is.jpg",1024,768,"隠岐の島町"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"]]},{"id":"32_wako_museum","n":"和鋼博物館（安来と鉄の道）","yomi":"わこうはくぶつかん","cat":"産業","y":1993,"era":["edo","meiji","heisei"],"sh":"","rank":"A","ad":"安来市安来町","st":"JR安来駅から歩いて約15分","la":35.433,"lo":133.253,"hook":"炎とふいごと砂鉄。日本刀を生んだ «たたら製鉄» の世界へ、安来の港町から入っていく。","lead":"和鋼博物館は、日本古来の製鉄法 «たたら製鉄» を紹介する博物館です。安来は、中国山地でつくられた鉄を船で運び出す港として栄えた町。博物館では、巨大なふいごや製鉄の道具、日本刀の材料になる «玉鋼（たまはがね）» などを見ることができます。","story":["出雲の山あいには、昔から砂鉄をふくむ山がたくさんありました。その砂鉄と、山の木からつくった木炭を、粘土の炉に入れて三日三晩燃やす。これが «たたら製鉄» です。炉に風を送るのは、何人もの人が足でふむ大きなふいご。«もっと風を! 火を絶やすな!» 真っ赤な炎の前で、人々は休まず働きました。","たたらでつくられた鉄のかたまりは «けら» とよばれ、その中のいちばん良い部分が «玉鋼» です。刀鍛冶たちはこの玉鋼を何度も折り返してきたえ、日本刀をつくりました。出雲や伯耆でつくられた鉄は、全国の職人たちに求められました。","その鉄を全国へ運び出したのが安来の港です。山から川を下って集められた鉄は、安来から船に積まれ、中海・日本海を通って各地へ運ばれました。«安来鋼» という言葉が生まれるほど、安来は鉄の町として知られるようになります。","明治になると西洋式の製鉄が広まり、たたらは少しずつ姿を消していきました。けれど安来では、たたらの伝統を受けついだ特別な鋼をつくる工場がつくられ、刃物や工具用の高級な鋼の産地として発展しました。","和鋼博物館は、こうした «鉄の道» の歴史を伝えるため、1993年に開館しました。館内では、天秤ふいごを実際にふむ体験や、刀の材料になる鋼の展示もあります。なぜ日本刀はあれほど強くて美しいのか? その答えのひとつが、ここにあります。"],"tl":[["古代〜中世","中国山地で砂鉄と木炭による製鉄が行われる"],["江戸時代","たたら製鉄が大規模になり、安来港から鉄が積み出される"],["明治時代","洋式製鉄の広まりで、たたらがおとろえる"],["明治〜大正","安来に近代的な製鋼の工場がつくられる"],["1993年","和鋼博物館が開館"]],"who":[["たたら師（村下）","炉の火を見きわめて製鉄を指揮した職人"],["鉄師（てっし）","たたら製鉄を経営した山の有力者"],["刀鍛冶","玉鋼から日本刀をきたえた職人"],["安来の商人・船乗り","鉄を全国へ運んだ"]],"deep":["«村下（むらげ）» は、たたら製鉄の技術の責任者です。炎の色や音で炉の中のようすを読みとる、長年の経験が必要な仕事でした。","天秤ふいごは、板の両はしを交互に足でふんで風を送る仕組み。«番子（ばんこ）» とよばれる人が交代でふみ続けました。«かわりばんこ» の語源という説もありますが、確かではありません。","たたら製鉄には大量の木炭が必要で、山の森を計画的に切り、育てることが欠かせませんでした。奥出雲の棚田や景観には、鉄穴流し（かんなながし）で山を切りくずした跡が生かされています。","たたら製鉄の技術は、戦後いったん途絶えましたが、日本刀の材料を得るために奥出雲町で «日刀保たたら» として復活し、今も冬に操業されています。","民謡 «安来節» は、安来の港町のにぎわいの中で育った唄です。どじょうすくいの踊りで知られ、鉄の町の人々の暮らしとも結びついています。"],"look":["大きな天秤ふいご（体験もできる）","玉鋼やけらの実物展示","たたら製鉄の炉の模型や映像","安来港と鉄の積み出しの歴史のコーナー"],"q":["たたら製鉄でつくられる鉄のうち、日本刀の材料になる最良の部分を何という?","«玉鋼（たまはがね）» です。けらという鉄のかたまりの中から選び出されます。"],"myth":"«かわりばんこ» の語源説は俗説。展示内容や体験の実施は時期で変わる。","img":["たたら製鉄","玉鋼","安来市","日本刀"],"wp":"和鋼博物館","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Wak%C5%8D_Museum.jpg",3648,2338,"和鋼博物館"],["c:c/c2/Wak%C5%8D_Museum_D51_488.jpg",3584,2060],["c:1/10/Japanischer_Tatara-Ofen_mit_Fl%C3%BCgelgebl%C3%A4se_%2818_Jahrhundert%29.jpg",2000,1660,"たたら製鉄"],["c:8/8d/Tamahagane_yao.jpg",2064,1528,"玉鋼"],["c:2/2f/Adachi_Museum_of_Art01st3200.jpg",3200,2130,"安来市"],["c:d/d9/Antique_Japanese_%28samurai%29_katana_met_museum.jpg",3716,2462,"日本刀"]]},{"id":"32_fudoki_oka","n":"八雲立つ風土記の丘","yomi":"やくもたつふどきのおか","cat":"学び","y":733,"era":["kofun","nara"],"sh":"","rank":"A","ad":"松江市大庭町","st":"JR松江駅からバスで約20分「風土記の丘入口」下車、歩いて約5分","la":35.433,"lo":133.098,"hook":"1300年前の «出雲国風土記» に書かれた景色が、いまも田んぼと古墳の中に残る。","lead":"八雲立つ風土記の丘は、松江市南部の意宇（おう）平野にある、古墳や遺跡をめぐる歴史公園です。この一帯は古代出雲の中心で、国府（国の役所）や国分寺が置かれていました。展示学習館では、古墳から出た大刀や埴輪を見ることができ、周りには大小の古墳が点在しています。","story":["«八雲立つ出雲»。古い歌にうたわれたこの言葉は、雲がわき立つ出雲の国をたたえたものです。奈良時代の733年、この国のようすをまとめた本が完成しました。«出雲国風土記» です。山や川の名前、村の由来、神々の話まで、くわしく書かれています。","風土記がつくられたころ、出雲国の役所・国府は、このあたりの意宇平野にありました。«国府はどこにあったのか?» 長い間はっきりしませんでしたが、発掘調査によって建物の跡が見つかり、国の史跡になりました。風土記の丘は、そうした古代の遺跡が集まる場所なのです。","丘の中には、古墳時代の古墳がいくつも残っています。なかでも岡田山1号墳からは、«額田部臣（ぬかたべのおみ）» という文字がきざまれた大刀が見つかりました。6世紀ごろの、日本で最も古い時期の文字資料のひとつです。出雲の豪族が、大和の政権とどうつながっていたのかを知る手がかりになりました。","展示学習館には、ふり返った鹿の姿をした «見返りの鹿» の埴輪もあります。すらりとした首をひねり、後ろを見ているその姿は、まるで何かの気配を感じたかのよう。古代の職人は、何を思ってこの鹿をつくったのでしょう。","丘の上に立つと、意宇平野が一望できます。田んぼの向こうには、古い神社や国分寺の跡。1300年前、役人たちが行き来した道も、この平野のどこかにあったはずです。風土記を片手に歩けば、古代の出雲が少しずつ見えてきます。"],"tl":[["6世紀ごろ","意宇平野に岡田山古墳などの古墳がつくられる"],["奈良時代","出雲国府が置かれる"],["733年","出雲国風土記が完成する"],["741年以降","聖武天皇の命で、国ごとに国分寺が建てられる"],["1972年","八雲立つ風土記の丘が開設される"]],"who":[["出雲臣広島","出雲国造で、出雲国風土記をまとめた責任者として名が残る"],["額田部臣","岡田山1号墳の大刀の銘文に出てくる氏の名"],["古墳の豪族","意宇平野に古墳を築いた有力者たち"]],"deep":["出雲国風土記は、全国の風土記の中でただひとつ、ほぼ完全な形で残っている本とされます。733年という完成の年が書かれていることも大きな特徴です。","岡田山1号墳の大刀の銘文は、昭和の終わりごろにX線調査で見つかりました。«各田卩臣（額田部臣）» と読まれ、古墳時代の地方にも文字が伝わっていたことを示しています。","このあたりには、前方後方墳の «山代二子塚古墳» もあります。前方後方墳は出雲に特に多い形で、«前方後方墳» という言葉自体、この古墳の研究から広まったともいわれます。","«風土記の丘» は、1960〜70年代に国の事業として全国各地につくられた歴史公園です。八雲立つ風土記の丘はそのひとつで、遺跡と自然を一緒に守ることを目的としています。","近くには神魂（かもす）神社や八重垣神社など、古い由緒をもつ神社も集まっています。神魂神社の本殿は国宝で、大社造の古い形を伝えるとされます。"],"look":["展示学習館の «額田部臣» 銘大刀と «見返りの鹿» 埴輪","岡田山古墳","丘の上から見る意宇平野","近くの出雲国府跡・国分寺跡"],"q":["出雲国風土記が完成したのは何年?","733年（天平5年）です。完成年がわかり、ほぼ完全に残っている、たいへん貴重な風土記です。"],"koji":[{"w":"八雲立つ","m":"«雲がいくえにもわき立つ» の意味で、«出雲» にかかる古いことば（まくらことば）"}],"myth":"","img":["出雲国風土記","岡田山古墳","出雲国府","山代二子塚古墳"],"wp":"八雲立つ風土記の丘","rel":{"ev":[],"grave":[]},"ph":[["c:7/7a/%E5%B2%A1%E7%94%B0%E5%B1%B1%E5%8F%A4%E5%A2%B31%E5%8F%B7%E5%A2%B3.JPG",5184,3456,"八雲立つ風土記の丘"],["j:1/15/%E5%AF%BA%E5%BA%8A1%E5%8F%B7%E5%A2%B3_%E6%96%9C%E7%B8%81%E7%A5%9E%E7%8D%A3%E9%8F%A1.JPG",3109,3115],["j:0/09/%E5%B9%B3%E6%89%80%E9%81%BA%E8%B7%A1_%E9%A6%AC%E5%BD%A2%E5%9F%B4%E8%BC%AA.JPG",5234,3491],["j:4/43/%E5%B9%B3%E6%89%80%E9%81%BA%E8%B7%A1_%E4%BA%BA%E7%89%A9%E5%9F%B4%E8%BC%AA.JPG",4392,3300],["j:b/b2/%E5%B9%B3%E6%89%80%E9%81%BA%E8%B7%A1_%E5%AE%B6%E5%BD%A2%E5%9F%B4%E8%BC%AA.JPG",4732,3551],["j:0/06/%E5%B9%B3%E6%89%80%E9%81%BA%E8%B7%A1_%E8%A6%8B%E8%BF%94%E3%82%8A%E3%81%AE%E9%B9%BF%E5%9F%B4%E8%BC%AA.JPG",3614,4812],["j:a/a4/%E4%BC%9D%E7%86%8A%E9%87%8E_%E9%8A%85%E9%90%B8.JPG",2506,3342],["j:9/91/%E5%B0%8F%E5%B1%8B%E8%B0%B73%E5%8F%B7%E5%A2%B3_%E5%9B%9B%E3%81%A1%E9%8F%A1.JPG",2679,2686]]},{"id":"32_yurahime","n":"由良比女神社（イカ寄せの浜）","yomi":"ゆらひめじんじゃ","cat":"寺社","y":927,"era":["heian","edo"],"sh":"","rank":"B","ad":"隠岐郡西ノ島町浦郷","st":"西ノ島の別府港から車で約15分。浦郷の港町から歩いてすぐ","la":36.088,"lo":133.001,"hook":"昔、秋の夜になると、神社の前の浜にイカが群れをなして押しよせたという。","lead":"由良比女神社は、隠岐・島前の西ノ島にある古い神社です。平安時代の «延喜式» に名前がのる格式の高い神社で、海の神さまとして島の人々に大切にされてきました。神社の前の浜は «イカ寄せの浜» とよばれ、昔はイカが自然に浜へ寄ってきたという不思議な話が伝わっています。","story":["西ノ島の浦郷は、入り江の奥にひっそりとある港町です。その海辺に、由良比女神社の鳥居が立っています。神社にまつられているのは «由良比女命（ゆらひめのみこと）»。海を渡ってきた女神だと伝えられています。","言い伝えによると、女神が海を渡っていたとき、イカが女神の手にかみついてしまいました。«なんと無礼な!» イカはおわびのしるしに、毎年この浜に集まって女神に仕えるようになった、というのです。","実際、昔は秋から冬にかけての夜、浜にイカがたくさん寄ってきて、村の人たちは手づかみや網で取ったといわれます。«イカ寄せ» のうわさは島の外にも伝わり、見物に来る人もいたほどでした。なぜイカは浜に寄ってきたのでしょう? 潮の流れや地形が関係していたのかもしれませんが、今でもはっきりした理由はわかっていません。","残念ながら、近年はイカが寄ってくることはほとんどなくなったといわれます。それでも、浜の近くには «イカ寄せの浜» の碑が立ち、島の人々は神社を大切に守り続けています。","由良比女神社は、隠岐の船乗りや漁師にとって大切な神さまでした。海に囲まれた島で、魚やイカの恵みに感謝し、無事を祈る。その気持ちが、この小さな入り江にこめられています。"],"tl":[["古代","由良比女命をまつる神社として信仰される"],["927年","延喜式が完成し、名神大社として名がのる"],["江戸時代","イカ寄せの浜の話が広く知られる"],["近代以降","イカの寄りが減り、伝承と碑が残る"]],"who":[["由良比女命","まつられている女神。イカにまつわる伝承がある"],["浦郷の漁師たち","イカ寄せの恵みを受け、神社を守ってきた"],["隠岐の船乗り","海の安全を祈って参拝した"]],"deep":["延喜式の神名帳で «名神大社» とされた神社は、全国でも特に格の高い神社でした。隠岐には名神大社が4社あり、由良比女神社はそのひとつです。","西ノ島の別の場所に «由良比女神社» の元宮とされる場所があるという説もあり、神社の場所がかつて移ったとも考えられています。","イカ寄せの伝承には、女神が手をかまれたという話のほかにも、細かな違いのある話がいくつも伝わっています。","浦郷の入り江は奥が深く、波がおだやか。こうした地形が、昔イカが寄りやすかった理由のひとつだったのでは、とも言われます。","西ノ島は隠岐ユネスコ世界ジオパークの一部で、近くには国賀海岸の断崖など、雄大な自然の見どころもあります。","隠岐では古くから、スルメイカなどのイカ漁がさかんでした。イカ寄せの伝説は、海の恵みとともに生きてきた島の暮らしそのものを語る物語といえます。神社の祭りでも海の幸への感謝がささげられます。"],"look":["海辺に立つ鳥居と社殿","«イカ寄せの浜» の碑","入り江の港町・浦郷の景色"],"q":["由良比女神社の前の浜が «イカ寄せの浜» とよばれる理由は?","昔、秋から冬の夜にイカが群れで浜へ寄ってきたと伝わるからです。女神の手をかんだおわびに来る、という伝説があります。"],"myth":"イカが寄ってくる理由は伝説で、科学的にははっきりしない。元宮の位置は諸説。","img":["隠岐諸島","西ノ島町","延喜式神名帳","名神大社"],"wp":"由良比女神社","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Yurahime_jinja_Haiden.JPEG",2352,1568,"由良比女神社"],["c:2/2d/Oki_Nishinoshima_Yutahime_Shrine_ac_%283%29.jpg",6016,4000],["c:9/91/Oki-Dozen_Kagura%2C_Yurahime_Shrine%2C_Nishinoshima_%286%29.jpg",4752,3168],["c:a/a3/Yurahime_jinja_keidaisha.JPG",2352,1568],["c:e/e6/Yurahime_jinja_Honden.jpg",2352,1568],["c:3/36/Yurahime_jinja_Gate.JPG",2352,1568],["c:c/cc/YurahimeJinja_Zuishinmon.JPG",2352,1568],["c:3/39/Precincts_of_Yurahime_jinja.JPG",2352,1568]]},{"id":"32_takuhi","n":"焼火神社（海の守りの神と隠岐の灯火）","yomi":"たくひじんじゃ","cat":"寺社","y":1732,"era":["heian","kamakura","edo"],"sh":"国の重要文化財（本殿など）","rank":"B","ad":"隠岐郡西ノ島町美田","st":"西ノ島の別府港から車で登山口まで約20分、そこから山道を歩いて約20分","la":36.063,"lo":133.035,"hook":"嵐の夜、海の上に不思議な火がともり、船を港へ導いた。その火をまつる、岩に抱かれた神社。","lead":"焼火神社は、隠岐・西ノ島の焼火山の中腹にある神社です。むき出しの大きな岩壁にくいこむように社殿が建てられていて、その姿はとても神秘的。海の安全を守る神として、隠岐の島の人々だけでなく、日本海を行き来する船乗りたちからも深く信仰されてきました。","story":["焼火神社の «焼火（たくひ）» とは、«火をたく» という意味です。昔、海の中から光る火が上がり、この山に入っていった、という言い伝えがあります。人々はその火を神の力と考え、山の上におまつりしました。","もうひとつ、有名な話があります。鎌倉時代のはじめ、承久の乱に敗れた後鳥羽上皇が隠岐へ流されるとき、船は嵐にあって方向を見失いました。そのとき、暗い海の向こうに火が見え、その火をたよりに進んで、無事に島に着いたというのです。«この火はどこから来たのか?» 上皇は神の火だと感じ、神社をあつく信仰したと伝えられます。","江戸時代、日本海には «北前船» とよばれる商いの船がさかんに行き来しました。島前の港は、風待ちや潮待ちのために船が立ちよる場所でした。船乗りたちは焼火の神に航海の安全を祈り、お札をいただいて船に祭ったといいます。遠い港でも «焼火さま» の名は知られていました。","いまの本殿は江戸時代中ごろの1732年に建てられたもので、岩のくぼみにはまりこむように建っています。本殿・通殿・拝殿がつながる珍しいつくりで、国の重要文化財に指定されています。","山道を登って神社にたどりつくと、深い森と岩、そして木造の社殿が一体となった景色が広がります。ここに立つと、夜の海にともった火を見て、ほっと胸をなでおろした船乗りたちの気持ちが、少しわかる気がします。"],"tl":[["平安時代","海からの火が山に入ったという伝承が生まれる"],["1221年","承久の乱。後鳥羽上皇が隠岐へ流される"],["江戸時代","北前船の船乗りたちから航海の神として信仰される"],["1732年","現在の本殿が建てられる"],["近代以降","本殿などが国の重要文化財に指定される"]],"who":[["後鳥羽上皇","隠岐へ流される途中、神の火に導かれたと伝わる"],["北前船の船乗り","航海安全を祈り、お札を受けた"],["隠岐の島民","神社を守り、祭りを続けてきた"]],"deep":["«焼火» は «たくひ» と読み、山の名は «焼火山（たくひやま）»。標高は約450mで、山頂近くからは島前の島々と内海が見渡せます。","焼火神社の神の火は、昔から «灯台» のような役目になぞらえられます。実際に山の上で火がたかれたのか、伝説だけなのかは、はっきりしていません。","本殿は岩の割れ目に屋根の一部がはまりこむように建てられ、自然の岩壁そのものを神聖なものとして敬う、古い信仰の形を感じさせます。","江戸時代の «諸国の船乗りが焼火の神を信じた» ことは、各地に残る絵馬や記録などから知られています。北前船の寄港地の神社に、焼火の信仰が伝わっている例もあるといわれます。","後鳥羽上皇は隠岐の中ノ島（海士町）で約19年を過ごし、そこで亡くなりました。上皇ゆかりの地は、中ノ島の隠岐神社や行在所跡に多く残っています。"],"look":["岩壁にはまりこむように建つ本殿","本殿・通殿・拝殿が連なる社殿のつくり","参道の森と大きな岩","山から見える島前の内海"],"q":["焼火神社の本殿が建てられたのは何年?","1732年（享保17年）です。岩壁にくいこむように建ち、国の重要文化財になっています。"],"myth":"後鳥羽上皇が神の火に導かれた話、海から火が上がった話は伝承。","img":["隠岐諸島","後鳥羽天皇","北前船","西ノ島町"],"wp":"焼火神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Precincts_of_Takuhi_jinja.JPG",2352,1568,"焼火神社"],["c:a/ad/%E5%8C%97%E6%96%8E%E6%BC%AB%E7%94%BB_7_-_%E9%9A%A0%E5%B2%90_%E7%84%9A%E7%81%AB%E3%81%AE%E7%A4%BE.jpg",3166,2088],["c:0/00/Hiroshige_Oki_Takuhinoyashiro.jpg",1806,2774],["c:0/0e/Takuhi_jinja_shrine_office.JPG",2352,1568],["c:8/89/Takuhi_jinja_Komainu.JPG",2352,1568],["c:a/ae/Takuhi_jinja_Honden.JPG",2352,1568],["c:8/88/Takuhi_jinja_Haiden.JPG",2352,1568],["c:5/5b/Takuhi_jinja_Gateway.JPG",2352,1568]]},{"id":"32_sunabara","n":"砂原遺跡（最古級の旧石器論争）","yomi":"すなばらいせき","cat":"遺跡","y":-120000,"era":["kyuseki"],"sh":"","rank":"B","ad":"出雲市多伎町砂原","st":"JR小田駅または田儀駅から歩いて約20〜30分。現地は海岸近くの崖で、案内表示は少ない","la":35.294,"lo":132.63,"hook":"日本列島にいつ人が来たのか。その答えを大きく書きかえるかもしれない石が、出雲の海辺の崖から見つかった。","lead":"砂原遺跡は、出雲市多伎町の海岸近くの崖で見つかった旧石器時代の遺跡とされる場所です。2009年、ここで見つかった石が «約12万年前の人がつくった石器ではないか» と発表され、日本で最も古い人の痕跡かもしれないと大きな話題になりました。けれども、本当に人がつくった石器なのかどうかは、研究者のあいだで意見が分かれています。","story":["日本列島に人がやってきたのは、いつなのでしょう? 多くの研究者は、はっきりした証拠があるのは約4万年前ごろから、と考えてきました。ところが2009年、出雲の海辺の崖で見つかった小さな石が、この常識をゆさぶります。","見つけたのは、同志社大学などの研究グループでした。崖の地層を調べていたところ、石の割れ方が人の手で打ち割ったように見えるものが出てきたのです。地層の年代を調べると、約12万年前ごろと考えられました。«もし本当なら、日本の旧石器時代の歴史は大きく変わる!» 発表は新聞やテレビでも取り上げられました。","しかし、ほかの研究者からは疑問の声も上がりました。«自然の力で割れた石ではないか?» 川の流れや崖くずれ、波の力でも、石は人がつくったように割れることがあるからです。また、地層の年代の考え方についても議論がありました。","日本の旧石器研究には、2000年に «旧石器ねつ造事件» が明らかになったという苦い過去があります。だからこそ、とても古い年代の発見には、慎重な確認が求められるのです。砂原遺跡をめぐる議論も、そうした流れの中で続いています。","いま、砂原の崖は静かな海辺の風景の一部です。けれどもこの場所は、«人類はいつ日本列島に来たのか» という大きななぞに、真正面から向き合った場所でもあります。答えはまだ出ていません。だからこそ、わくわくするのです。"],"tl":[["約12万年前（推定）","石器とされる石が含まれる地層ができたと考えられる"],["2009年","研究グループが崖の調査で石器とみられる石を発見・発表"],["2009年以降","人工品か自然石かをめぐる議論が続く"],["2000年","（参考）旧石器ねつ造事件が発覚し、古い石器の検証が厳しくなる"]],"who":[["発掘した研究グループ","同志社大学の研究者らが中心となって調査・発表した"],["批判的な研究者たち","自然に割れた石ではないかと疑問を示した"],["地元の人々","海辺の崖が注目を集めるのを見守った"]],"deep":["«石器かどうか» を見分けるときは、打ち割った面の形、打撃の跡、割れ方の規則性などを調べます。砂原の石はこれらの点について評価が分かれています。","年代の推定には、地層にはさまった火山灰や、光ルミネッセンス法などの方法が使われます。どの層の年代を石にあてはめるかが大切な論点です。","もし12万年前に人がいたとすると、それは私たちと同じホモ・サピエンスなのか、それとも別の人類なのか、という新しいなぞも生まれます。","日本列島で確実な旧石器時代の遺跡は、約3万8000年前ごろ以降に数多く見つかっています。砂原遺跡の年代は、それよりはるかに古いことになります。","遺跡の場所は海岸の崖で、崩れやすい地形です。現地を訪れるときは、崖に近づきすぎないよう注意が必要です。"],"look":["海岸の崖と地層（離れた安全な場所から）","多伎町の海辺の景色","出雲市内の博物館などでの関連展示（あれば）"],"q":["砂原遺跡の石器が注目されたのは、どれくらい昔のものと発表されたから?","約12万年前と発表されたからです。ただし人がつくった石器かどうかは、今も議論が続いています。"],"myth":"約12万年前という年代、人工の石器かどうかはどちらも論争中で定説ではない。","img":["旧石器時代","日本列島の旧石器時代","旧石器捏造事件"],"wp":"砂原遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:f/f5/OdaStationBuilding-2018-1-5.jpg",4608,3456,"近く: 小田駅 (島根県)"],["c:9/97/Kirara_Taki.jpg",1600,1065,"近く: 多伎町"],["c:a/a9/Roadside_Station_Kirara_Taki.jpg",4592,2530,"近く: 道の駅キララ多伎"],["c:8/85/Izumo_Taki_IC.jpg",4154,3111,"近く: 出雲多伎インターチェンジ"]]},{"id":"32_inome","n":"猪目洞窟（黄泉の穴）","yomi":"いのめどうくつ","cat":"遺跡","y":0,"era":["yayoi","kofun","nara"],"sh":"国指定史跡（猪目洞窟遺物包含層）","rank":"B","ad":"出雲市猪目町","st":"JR出雲市駅から車で約40分。一畑電車 出雲大社前駅から車で約20分","la":35.454,"lo":132.74,"hook":"«夢でこの穴に行くと、必ず死ぬ»。1300年前の本に書かれた、あの世の入り口。","lead":"猪目洞窟は、島根半島の北側、日本海に面した猪目の漁港にある洞窟です。奈良時代の «出雲国風土記» に、«夢の中でこの岩屋のあたりに来た人は必ず死ぬ» と書かれた場所だと考えられ、«黄泉の穴» とよばれてきました。実際に洞窟からは、弥生時代から古墳時代の人の骨や、南の海の貝でつくった腕輪などが見つかっています。","story":["出雲国風土記には、ふしぎな場所が書かれています。«脳の磯（なづきのいそ）» の西に岩屋があり、人は入ることができない。夢でこの岩屋のそばに行った者は、必ず死ぬ。だから人々は «黄泉の坂»«黄泉の穴» とよぶ――。黄泉とは、死んだ人がいく世界のことです。","長いあいだ、その場所がどこなのかははっきりしませんでした。ところが1948年、猪目の漁港で船置き場をつくる工事をしていたとき、洞窟の中から人の骨や土器が次々と出てきたのです。«ここが風土記の黄泉の穴なのでは?» と、多くの人が考えるようになりました。","見つかった骨は、弥生時代から古墳時代にかけてのもの。十数体分ともいわれます。その中には、南の島の海でとれる大きな巻貝・ゴホウラでつくった腕輪をはめた人もいました。遠い南の海の品が、どうやってこの日本海の洞窟までやってきたのでしょう? 古代の人々の広いつながりが見えてきます。","この洞窟は、亡くなった人を葬る場所として使われていたと考えられています。暗く、波の音がひびく岩屋。昔の人がここを «あの世への入り口» と感じたのも、わかる気がします。","いまも洞窟は漁港の一部として、漁師さんたちの船置き場に使われています。入り口に立つと、ひんやりした空気と、奥へ続く暗やみ。1300年前の人々のおそれと祈りが、この岩のすきまに今も残っているようです。"],"tl":[["弥生時代〜古墳時代","洞窟が葬送の場として使われる"],["733年","出雲国風土記に «黄泉の穴» の記述"],["1948年","漁港の工事で人骨や土器などが見つかる"],["昭和時代","遺物包含層が国の史跡に指定される"]],"who":[["洞窟に葬られた人々","弥生〜古墳時代の出雲の人々。貝輪などを身につけていた"],["風土記の編者","洞窟にまつわる言い伝えを記録した"],["猪目の漁師たち","洞窟を船置き場として使い、発見のきっかけとなった"]],"deep":["«脳の磯» の «脳» は、今の «のう» ではなく «なづき» と読みます。古いことばで頭や脳を意味します。","ゴホウラは奄美や沖縄など南の海に生きる大きな巻貝です。弥生時代には、九州北部などで身分の高い人が腕輪として身につけました。日本海側の出雲で見つかったのは、遠い交易のあかしです。","出土品には、木の舟や木器、土器、骨角器なども含まれていたといわれ、湿った洞窟ならではの保存の良さが注目されました。","猪目洞窟が風土記の «黄泉の穴» そのものかどうかは、確実とはいえません。風土記の地名と現在の場所をどう重ねるかについては、諸説があります。","洞窟は今も漁港の施設として使われています。見学は入り口付近までにし、漁の作業のじゃまにならないよう気をつけましょう。"],"look":["洞窟の入り口と、奥へ続く暗がり","入口の説明板","猪目の漁港と日本海の景色"],"q":["出雲国風土記で、この洞窟のあたりは何とよばれていた?","«黄泉の坂»«黄泉の穴» です。夢でここに来た人は必ず死ぬ、と書かれていました。"],"myth":"風土記の «黄泉の穴» と猪目洞窟が同じ場所かは諸説。人骨の体数も資料で違う。","img":["出雲国風土記","黄泉","ゴホウラ","島根半島"],"wp":"猪目洞窟","rel":{"ev":[],"grave":[]},"ph":[["c:8/82/Inome-cave.jpg",4608,3456,"猪目洞窟"],["c:4/4f/Inome_cave_artifact_3.jpg",5184,3888],["c:e/e7/Inome_cave_artifact_2.jpg",5184,3888],["c:f/f2/Inome_cave_artifact_1.jpg",5184,3888],["c:4/49/Inome_boat-coffin.jpg",1440,1080],["c:e/e6/Inome_bracelet.jpg",1440,809],["c:d/d8/Sinustrombus_latissimus_01.jpg",5000,3552,"ゴホウラ"]]},{"id":"32_sanbe_maibotsurin","n":"三瓶小豆原埋没林（縄文の森の化石）","yomi":"さんべあずきはらまいぼつりん","cat":"遺跡","y":-2000,"era":["jomon"],"sh":"国指定天然記念物","rank":"B","ad":"大田市三瓶町多根","st":"JR大田市駅から車で約30分。バスの本数は少ないので車が便利","la":35.16,"lo":132.62,"hook":"4000年前、火山の土砂が一瞬で森を飲みこんだ。立ったままの巨木が、いま地下で待っている。","lead":"三瓶小豆原埋没林は、約4000年前の三瓶山の噴火によって、生きたまま土の中にうめられた縄文時代の森です。直径が1mをこえる大きなスギが、立ったままの姿で見つかりました。いまは地下に大きな展示室がつくられ、巨木が根をはったそのままのようすを見ることができます。","story":["縄文時代の後期、今から約4000年前のことです。三瓶山のふもとには、スギやトチノキの大きな森が広がっていました。ある日、三瓶山が噴火します。火山から流れ出た土砂が谷をかけ下り、森を一気にうめてしまいました。","森の木々は、たおれる間もなく、立ったまま土の中に閉じこめられました。空気にふれなかったため、木はくさらずに残ります。そのまま4000年。地上では、人々が田んぼをつくり、村をつくり、長い時代が流れていきました。","1983年、田んぼの工事をしていたところ、地面の下から大きな木が顔を出しました。«こんなところに、なぜ大木が?» 調べてみると、それは縄文時代の森の一部だったのです。その後、本格的な発掘が行われ、たくさんの巨木が立ったままうまっていることがわかりました。","発掘された場所には、深さ10mをこえる地下の展示室がつくられました。展示室の中に入ると、目の前に太いスギの幹がそびえています。見上げると、まるで4000年前の森の中に立っているよう。木の肌の模様まで、はっきりと見えます。","埋没林は、火山のおそろしさを伝えると同時に、縄文時代の森がどんな姿をしていたかを教えてくれる、世界でもめずらしい «タイムカプセル» です。"],"tl":[["約4000年前","三瓶山の噴火で、森が土砂にうもれる"],["1983年","水田工事中に巨大なスギの幹が見つかる"],["1998年ごろ","本格的な発掘調査が行われる"],["2002年","展示施設（三瓶小豆原埋没林公園）が開館"],["2004年","国の天然記念物に指定される"]],"who":[["縄文時代の人々","三瓶山のふもとで、この森の近くに暮らしていたと考えられる"],["発見した地元の人々","工事中に巨木を見つけ、調査のきっかけをつくった"],["研究者たち","発掘し、森がうもれた仕組みを明らかにした"]],"deep":["一番大きなスギは、高さ12m以上、幹の直径が約1.5mもあるといわれます。根元から上まで、立ったままの状態で残っているのが特徴です。","森をうめたのは、火砕流そのものではなく、噴火で山がくずれて流れ下った土石流や、火山灰まじりの土砂と考えられています。","木の年輪を調べることで、森がうもれた時期や、そのころの気候を知る手がかりになります。巨木の年輪は数百年分にもおよびます。","三瓶山は、今は穏やかな山ですが、過去に何度も噴火をくりかえしてきた火山です。約4000年前の噴火は、三瓶山の最も新しい大きな活動の一つとされます。","地下展示室は、発掘した穴をそのまま利用しているため、巨木を «もとあった位置» で見ることができます。"],"look":["地下展示室の立ったままの巨大スギ","木の根がはったままの地面","三瓶山の姿（噴火した火山）"],"q":["三瓶小豆原埋没林の森は、何によってうもれた?","約4000年前の三瓶山の噴火によって流れ下った土砂です。木は立ったまま閉じこめられました。"],"myth":"巨木の寸法や展示室の深さは資料によって少し違う。","img":["三瓶山","埋没林","縄文時代","大田市"],"wp":"三瓶小豆原埋没林","rel":{"ev":[],"grave":[]},"ph":[["c:0/07/Azukihara.jpg",3024,4032,"三瓶小豆原埋没林"],["c:7/7c/Sanbe201402.jpg",1024,768,"三瓶山"],["c:f/f3/Iwami-Ginzan-03578_%2852651572987%29.jpg",3000,1996,"大田市"]]},{"id":"32_tawayama","n":"田和山遺跡（三重の環濠の弥生遺跡）","yomi":"たわやまいせき","cat":"遺跡","y":-200,"era":["yayoi"],"sh":"国指定史跡","rank":"B","ad":"松江市乃白町","st":"JR松江駅からバスで約15分「市立病院」下車、歩いて約5分","la":35.443,"lo":133.043,"hook":"村を守るはずの環濠が、村の外側ではなく、小さな山頂のまわりを三重に取りかこんでいた。何のために?","lead":"田和山遺跡は、松江市にある弥生時代の遺跡です。小高い丘の頂上を、三重の環濠（まわりをかこむ堀）がとりまいています。ふつう環濠は村を守るものですが、ここでは環濠の内側に人の住まいがほとんどなく、何のためにつくられたのか、今もなぞが多い遺跡です。","story":["1990年代、松江市では新しい市立病院をこの丘に建てる計画がありました。事前の発掘調査を始めると、思いがけないものが出てきます。丘の頂上を三重にかこむ、深い堀のあとでした。«これは、ただの村のあとではない。»","弥生時代の人々は、村のまわりに堀をめぐらせて、敵や動物から身を守りました。ところが田和山では、堀の内側、つまり丘の頂上には家のあとがほとんどありません。そのかわり、柱を立てた建物のあとがわずかに見つかりました。人々の住まいは、堀の外側の斜面にあったのです。","では、この堀は何を守っていたのでしょう? 頂上は祭りを行う «神聖な場所» だったのか。それとも、いざというときに逃げこむ «とりで» だったのか。堀の中からは、投げるための石（つぶて）がたくさん見つかっていて、戦いへの備えだったのでは、と考える人もいます。","この発見は大きな話題になり、遺跡を残してほしいという声が高まりました。その結果、病院の建設場所はずらされ、遺跡は国の史跡として守られることになりました。発掘の成果が、町づくりの計画を変えたのです。","いまの田和山は、史跡公園として整備されています。丘を登ると、三重の環濠のようすがわかるように復元されていて、頂上からは松江の町と宍道湖が見渡せます。弥生の人々は、ここから何を見て、何を守ろうとしたのでしょうか。"],"tl":[["弥生時代前期末〜中期","丘の頂上を三重の環濠がかこむ"],["弥生時代中期","環濠が使われなくなる"],["1997年ごろ","市立病院建設のための発掘調査が始まる"],["2001年","国の史跡に指定される"],["その後","史跡公園として整備・公開される"]],"who":[["田和山の弥生人","環濠を掘り、丘のまわりで暮らした人々"],["発掘調査の担当者","三重環濠を明らかにした"],["保存を願った市民","遺跡を残す運動を進めた"]],"deep":["三重の環濠で丘の頂上をかこむ例は全国でもめずらしく、田和山の大きな特徴です。環濠の内側の面積は、とても小さいのがポイントです。","頂上では、柱の穴が並ぶ建物のあとが見つかりました。9本の柱からなる建物だったと考えられ、特別な建物だった可能性があります。","つぶて石は数千個にのぼるともいわれます。ただし、本当に戦いに使われたのかどうかは分かっておらず、見せるための «威嚇» や儀礼だったという見方もあります。","田和山からは、硯（すずり）ではないかといわれる石の板が見つかり、弥生時代に文字が使われていた可能性をめぐって議論になりました。確かなことはまだわかっていません。","遺跡の保存のため病院の建設位置を変えたことは、開発と遺跡保護の関係を考えるうえでよく取り上げられる例です。"],"look":["三重の環濠のようすがわかる丘の斜面","頂上の建物のあと（復元・表示）","頂上から見る宍道湖と松江の町"],"q":["田和山遺跡で、丘の頂上をかこんでいた環濠は何重?","三重です。しかも内側には家がほとんどなく、何のための堀だったのか、今もなぞが残っています。"],"myth":"環濠の目的（祭りか防御か）、つぶて石の用途、硯とされる石の評価は諸説。","img":["環濠集落","弥生時代","松江市"],"wp":"田和山遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:7/76/%E5%90%89%E9%87%8E%E3%83%B6%E9%87%8C%E9%81%BA%E8%B7%A1%E7%92%B0%E6%BF%A0.JPG",3456,2304,"環濠集落"],["c:0/00/Matsue_montage.jpg",1222,1683,"松江市"]]},{"id":"32_meimeian","n":"明々庵（松平不昧の茶室）","yomi":"めいめいあん","cat":"大名屋敷","y":1779,"era":["edo"],"sh":"","rank":"B","ad":"松江市北堀町","st":"JR松江駅からバス（レイクライン）で「塩見縄手」下車、歩いて約3分","la":35.478,"lo":133.048,"hook":"茶の湯を愛しすぎた殿さまがいた。その名は «不昧»。彼の好んだ茶室が、松江城を望む丘に建っている。","lead":"明々庵は、江戸時代の松江藩主・松平治郷（はるさと）が好んで建てさせた茶室です。治郷は «不昧（ふまい）» という号で知られ、茶道の «不昧流» を生んだ大名茶人でした。茅ぶきの屋根をもつ小さな茶室は、何度か場所を移したあと、いまは松江城天守を望む高台に建っています。","story":["江戸時代の中ごろ、松江藩の財政は苦しく、藩は借金にあえいでいました。そこで若くして藩主となった松平治郷は、家老たちとともに藩の立て直しに取り組みます。そのかたわら、治郷が心から打ちこんだのが «茶の湯» でした。","治郷は «不昧» と名のり、茶道具を集め、茶の湯の心について書き残しました。«茶は、ぜいたくのためではなく、心を整えるためのもの。» 不昧はそう考えていたといわれます。けれども、名品の茶道具を集めたことについては、ぜいたくだったという評価もあり、人物像はひとつではありません。","明々庵は1779年、不昧の好みによって、松江の家老・有沢家の屋敷の中に建てられたと伝わります。のちに茶室は東京の松平家の屋敷に移され、さらに松江へもどされました。そして昭和の中ごろ、現在の赤山の高台に移されました。なぜこんなに引っ越しをしたのでしょう? 名茶室として大切にされ、その時々の持ち主が «ぜひ手もとに» と願ったからだと考えられます。","茶室は入母屋造の茅ぶき屋根で、どっしりとした落ち着きがあります。中には «明々庵» と書かれた不昧自筆の額がかかっているといわれます。庭から見上げると、茅ぶきの屋根ごしに、松江城の天守が見えます。","松江の町には、いまも和菓子とお抹茶を楽しむ文化が根づいています。«不昧公好み» とよばれるお菓子もあり、松江は京都・金沢と並ぶ «菓子どころ» ともいわれます。明々庵で一服のお茶をいただくと、不昧公が育てた茶の文化を肌で感じることができます。"],"tl":[["1751年","松平治郷が生まれる"],["1767年","治郷が松江藩主となる"],["1779年","有沢家の屋敷に明々庵が建てられたと伝わる"],["1818年","不昧が亡くなる"],["明治以降","茶室が東京の松平家屋敷に移される"],["1966年","現在の赤山の地に移されたとされる"]],"who":[["松平治郷（不昧）","松江藩7代藩主。大名茶人。明々庵を好んだ"],["有沢家","松江藩の家老。明々庵が最初に建てられた屋敷の持ち主"],["松江の茶人たち","不昧流の茶を受けつぎ、茶室を守った"]],"deep":["不昧は藩主になると、家老の朝日丹波とともに «御立派（おたては）の改革» とよばれる財政改革を行ったとされます。改革の成果と不昧の茶道具収集の関係には、さまざまな評価があります。","不昧が集めた茶道具の目録 «雲州蔵帳» は、茶道具の格付けの目安として後世にも大きな影響をあたえました。","明々庵の茶室は、小さな空間に、にじり口や床の間を整えた草庵風のつくりです。茶室の中には入れないことが多く、外から見学するのが基本です。","松江には、不昧ゆかりの茶室として «菅田庵»（国の重要文化財）もあります。こちらは見学に予約が必要な場合があります。","«不昧» は «昧（くら）からず» という意味の禅のことばからとった号といわれます。«明々庵» の名も、明るさに通じる名前です。"],"look":["茅ぶき屋根の茶室の外観","庭から見える松江城天守","抹茶と和菓子がいただける鑑賞席","近くの塩見縄手の武家屋敷通り"],"q":["松江藩主・松平治郷の茶人としての号は?","«不昧（ふまい）» です。不昧流という茶道の流れを生み、松江の茶と和菓子の文化を育てました。"],"koji":[{"w":"不昧","m":"«くらからず» の意味。心がくもらず、道理に明るいこと。松平治郷の号"}],"myth":"移築の年や経緯は資料で少しずつ違う。","img":["松平治郷","松江城","不昧流","菅田庵"],"wp":"明々庵","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/Meimeian01n4592.jpg",4592,3056,"明々庵"],["c:2/2c/Meimeian03n4592.jpg",4592,3056],["c:3/3f/Meimeian06nt3200.jpg",3200,2130],["c:f/f2/Meimeian3.jpg",2048,1536],["c:c/c6/Meimeian2.jpg",2048,1536],["c:c/cb/Matsudaira_Fumai.JPG",1631,2319,"松平治郷"],["c:8/88/Matsue_Castle_Keep_Tower_20230617.jpg",4988,3741,"松江城"]]},{"id":"32_nishi_amane","n":"西周旧居","yomi":"にしあまねきゅうきょ","cat":"学び","y":1829,"era":["edo","meiji"],"sh":"国指定史跡","rank":"B","ad":"鹿足郡津和野町後田","st":"JR津和野駅から歩いて約25分。レンタサイクルも便利","la":34.462,"lo":131.77,"hook":"«哲学»«科学»«芸術»。私たちが毎日使うことばを、この家で育った人がつくった。","lead":"西周旧居は、明治時代の思想家・西周（にしあまね）が生まれ育った家です。西周は幕末にオランダへ留学し、西洋の学問を日本に紹介しました。そのとき、«哲学»«科学»«芸術» など、たくさんの新しい日本語をつくったことで知られています。旧居は津和野川のほとりにあり、国の史跡になっています。","story":["1829年、西周は津和野藩の医者の家に生まれました。小さなころから本が好きで、家の土蔵にこもって勉強したと伝えられています。そのとき、豆をかじりながら本を読んだ、という話も残っています。","大人になった周は、藩の学問所で学んだのち、江戸へ出ます。そこで出会ったのが、黒船来航にゆれる日本と、西洋の学問でした。«これからの日本には、西洋の考え方を学ぶことが必要だ。» 周は、藩をぬけてまで洋学の道を選びました。","1862年、周は幕府の留学生としてオランダへ渡ります。ライデン大学の教授のもとで、法律や経済、そして «フィロソフィー» を学びました。帰国後、周は西洋の学問を日本語で説明するため、いくつもの新しいことばを考えます。«フィロソフィー» は «哲学»。こうして生まれたことばが、いまも私たちの教科書やニュースで使われています。","明治になると、周は新しい政府で働き、学問の団体 «明六社» にも加わって、日本の近代化に力をつくしました。一方で、軍隊のきまりづくりにも関わるなど、その活動ははば広いものでした。","旧居は、津和野川をはさんで、森鷗外の旧宅の近くにあります。同じ津和野から、明治を代表する二人の知識人が生まれたのです。なぜ小さな城下町から、こんなにすぐれた人が? その答えのひとつは、学問を大切にした津和野藩の藩校 «養老館» にあるのかもしれません。"],"tl":[["1829年","津和野藩医の家に生まれる"],["1850年代","江戸に出て洋学を学ぶ"],["1862年","幕府の留学生としてオランダへ"],["1865年","帰国"],["1873年","明六社の結成に加わる"],["1897年","亡くなる"]],"who":[["西周","津和野出身の思想家。«哲学» などの訳語をつくった"],["森鷗外","津和野出身の文豪。西周とは親戚で、東京で世話になった"],["津田真道","オランダ留学をともにした仲間"],["フィッセリング","ライデン大学で西周らを教えた教授"]],"deep":["西周がつくった、または広めたとされる訳語には、«哲学»«主観»«客観»«理性»«意識» などがあります。ただし、どの語を西周が最初に使ったかについては、研究によって見方が分かれるものもあります。","オランダ留学には、津田真道や榎本武揚らも加わりました。幕府が初めて本格的に送り出したヨーロッパへの留学生でした。","西周は、軍人の心がまえを示した «軍人勅諭» の起草に関わったことでも知られます。学者としての顔と、国家の制度づくりに関わった顔の両方を持っていました。","森鷗外は、西周の親戚にあたり、上京したときに西家に身を寄せたことがあります。のちに鷗外は «西周伝» を書いています。","旧居には、周が勉強部屋にしたと伝わる土蔵が残っています。建物の内部の公開範囲は限られているので、外から見学する形が中心です。"],"look":["津和野川ほとりの旧居と土蔵","近くの森鷗外旧宅と記念館","旧居の説明板"],"q":["西周が «フィロソフィー» を日本語にしたときにつくったことばは?","«哲学» です。西周はほかにも多くの学問のことばを日本語に置きかえました。"],"myth":"土蔵で豆をかじりながら勉強した話は伝承。各訳語の «最初の使用者» については研究上の諸説がある。","img":["森鷗外","明六社","津和野町"],"wp":"西周 (啓蒙家)","rel":{"ev":[],"grave":[]},"ph":[["c:b/bc/Nishi_Amane%2C_supervisor_of_the_Tokyo_Normal_School.jpg",1391,1951,"西周 (啓蒙家)"],["c:f/f4/Sy%C5%ABsuke_Nishi%28Amane_Nishi%29.jpg",2250,3797],["c:4/49/Nishi_Amane_Old_Residence.jpg",2200,1650],["c:2/2e/Nishi_Amane.jpg",523,671],["c:7/71/Mori_Ogai_in_the_atelier_of_Sculptor_Takeishi_Kozaburo_in_1916.jpg",740,1118,"森鷗外"],["c:e/e6/Meiroku_Zasshi_No10_1874_Cover.jpg",2802,4202,"明六社"],["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"]]},{"id":"32_yorokan","n":"藩校養老館（津和野藩）","yomi":"はんこうようろうかん","cat":"学び","y":1786,"era":["edo","meiji"],"sh":"県指定史跡","rank":"B","ad":"鹿足郡津和野町後田（殿町通り）","st":"JR津和野駅から歩いて約10分","la":34.468,"lo":131.773,"hook":"鯉の泳ぐ殿町通りに、武家の子が学んだ学び舎。のちの明治を動かす人材が、ここから巣立った。","lead":"養老館は、津和野藩が1786年に開いた藩校（藩の学校）です。藩士の子どもたちが漢学・国学・医学・兵学などを学び、西周や森鷗外もここで学んだといわれます。いまの建物は幕末に建てられたもので、殿町通りに残り、見学することができます。","story":["江戸時代の中ごろ、津和野藩の藩主・亀井矩賢（のりかた）は «藩を強くするには、人を育てること» と考え、藩校をつくりました。これが養老館です。«養老» という名前には、長く人を養い、学問を大切にするという願いがこめられているといわれます。","養老館では、儒学の本を読むだけでなく、医学や天文・数学、剣術や槍術などの武芸も教えました。幕末には、日本古来の学問 «国学» にも力を入れ、国学者を招いて講義を行いました。","とりわけ注目されるのは、オランダの医学 «蘭医学» も学べたことです。小さな藩でありながら、新しい学問をどんどん取り入れた養老館。そこで学んだ若者の中から、西周のような洋学者が生まれたのは、決して偶然ではありません。","1853年、大火で城下が焼け、養老館も焼けました。その後、殿町に新しく建て直されたのが、いま残る建物です。明治になって藩がなくなると、養老館は学校としての役目を終えますが、建物は残されました。","養老館の前の殿町通りには、堀割に色とりどりの鯉が泳ぎ、白壁の家並みが続きます。«ここで学んだ子どもたちは、どんな未来を思いえがいていたのだろう?» 静かな町並みを歩くと、そんな問いが自然と浮かんできます。"],"tl":[["1786年","津和野藩主・亀井矩賢が藩校養老館を開く"],["幕末","国学・蘭医学などが取り入れられる"],["1853年","大火で焼け、のちに殿町に再建される"],["明治初め","藩がなくなり、藩校としての役目を終える"],["現在","建物が公開され、津和野の歴史を伝える"]],"who":[["亀井矩賢","津和野藩主。養老館を創立した"],["亀井茲監","幕末の津和野藩主。藩校の教育を充実させた"],["大国隆正","国学者。津和野の国学に大きな影響をあたえた"],["西周","養老館で学んだのち、洋学者として活躍"],["森鷗外","幼いころ養老館で学んだといわれる"]],"deep":["幕末の津和野藩主・亀井茲監（これみ）は国学を重んじ、明治の初めには神道の政策づくりに津和野出身の人々が大きな役割を果たしました。福羽美静はその代表です。","養老館で学んだ人物として、西周・森鷗外のほか、福羽美静らの名がよくあげられます。小さな藩から中央で活躍する人材が多く出たことは、津和野の誇りです。","現在残る建物は、剣術教場・槍術教場と書庫などとされ、武芸の稽古場が残っている点が貴重です。","館内は資料館として使われている時期があり、展示内容は変わることがあります。見学の際は開館情報を確かめましょう。","殿町通りの堀割の鯉は、町の人々が大切に育てているものです。昔、火事のときの防火用水だった堀が、いまは町の顔になっています。","藩校の «藩校» とは、江戸時代に各藩が武士の子弟を教育するために建てた学校です。全国に200以上あったといわれ、養老館は小藩の藩校ながら、蘭医学や国学など新しい学問をいち早く取り入れた点で知られています。"],"look":["剣術・槍術の教場の建物","殿町通りの白壁と堀割の鯉","近くの津和野藩家老門などの武家屋敷の門"],"q":["養老館が開かれたのは何年?","1786年（天明6年）です。津和野藩主・亀井矩賢が、藩の人材を育てるために開きました。"],"myth":"残る建物の内訳、森鷗外の在籍の詳細は資料で表現が異なる。","img":["津和野藩","亀井茲監","森鷗外","津和野町"],"wp":"養老館","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/%E6%B4%A5%E5%92%8C%E9%87%8E%E7%94%BA%E9%A4%8A%E8%80%81%E9%A4%A8_01.jpg",1200,800,"養老館"],["c:a/ae/%E6%B4%A5%E5%92%8C%E9%87%8E%E7%94%BA%E9%A4%8A%E8%80%81%E9%A4%A8-02.jpg",1200,900],["c:6/63/Tsuwano_castle_a_site_of_Sanjukkendai.JPG",1367,972,"津和野藩"],["c:9/9b/Kamei_Koremi.jpg",823,1291,"亀井茲監"],["c:7/71/Mori_Ogai_in_the_atelier_of_Sculptor_Takeishi_Kozaburo_in_1916.jpg",740,1118,"森鷗外"],["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"]]},{"id":"32_taikodani","n":"太皷谷稲成神社","yomi":"たいこだにいなりじんじゃ","cat":"寺社","y":1773,"era":["edo"],"sh":"","rank":"B","ad":"鹿足郡津和野町後田","st":"JR津和野駅から歩いて約20分（千本鳥居の参道を登る）。車で上まで行くこともできる","la":34.465,"lo":131.768,"hook":"赤い鳥居が山の斜面をうねりながら、どこまでも続く。そのトンネルの先に、城下町を見おろす社がある。","lead":"太皷谷稲成神社は、1773年に津和野藩主・亀井矩貞（のりさだ）が、京都の伏見稲荷大社から神をむかえて建てた神社です。«日本五大稲荷» のひとつにも数えられるといわれます。ふつう «稲荷» と書くところを «稲成» と書くのが特徴で、«願いが成る» という意味がこめられているといわれます。","story":["江戸時代の中ごろ、津和野藩主の亀井矩貞は、藩の安泰と人々の幸せを願って、京都の伏見稲荷から神さまを分けてもらいました。社は、津和野城の鬼門（北東の方角）の守りとして建てられたともいわれます。","はじめは藩主やその家族のための神社で、町の人が気軽にお参りできる場所ではありませんでした。明治になり藩がなくなると、神社は広く人々に開かれ、たくさんの参拝者が訪れるようになりました。","参道には、朱色の鳥居がすきまなく並びます。その数はおよそ千本ともいわれ、奉納した人々の願いがひとつひとつの鳥居にこめられています。鳥居のトンネルをくぐりながら急な坂を登ると、しだいに津和野の町が眼下に広がっていきます。","なぜ «稲荷» ではなく «稲成» なのでしょう? 神社の説明では、«大願成就»、つまり大きな願いが成るという意味を込めた字だとされています。受験や商売などの願いごとをする人が、全国から訪れます。","本殿にお参りすると、お供えのための油あげやろうそくが売られています。お稲荷さんのお使いはキツネ。キツネの好物とされる油あげを供えて、願いをかけるのです。山の上から見る赤瓦の津和野の町並みは、この神社ならではの景色です。"],"tl":[["1773年","亀井矩貞が伏見稲荷から勧請して創建"],["江戸時代","藩主の祈願所として信仰される"],["明治以降","一般の人々にも参拝が広がる"],["昭和時代","現在の大きな社殿が建てられる"]],"who":[["亀井矩貞","津和野藩主。神社を創建した"],["津和野藩の人々","藩の守り神として信仰した"],["全国の参拝者","鳥居を奉納し、願いをかけてきた"]],"deep":["«日本五大稲荷» の顔ぶれは決まっているわけではなく、神社や地域によって挙げ方が違います。太皷谷稲成神社は、そのひとつに数えられることが多い神社です。","«太皷谷» の名は、このあたりの谷の名前に由来します。城で時を知らせる太鼓の音がひびいた谷、という言い伝えもありますが、確かではありません。","神社には、山の上の本殿のほかに «元宮» があり、古い社のようすを伝えています。","油あげとろうそくをお供えするのが、この神社の参拝のならわしです。ろうそくに火をともして、願いをこめます。","神社は津和野城跡の近くにあり、城跡へのリフト乗り場も近くにあります。あわせて見学すると、城と神社の位置関係がよくわかります。","津和野は «山陰の小京都» とよばれる城下町です。稲成神社の赤い鳥居と、町の赤瓦（石州瓦）の屋根、殿町の白壁が重なる景色は、この町を象徴する風景として写真やポスターにもよく使われます。"],"look":["千本鳥居の参道（トンネルのような朱の列）","山の上の本殿と元宮","境内から見下ろす津和野の赤瓦の町並み"],"q":["太皷谷稲成神社では、なぜ «稲荷» ではなく «稲成» と書く?","«願いが成る»（大願成就）という意味をこめた字だとされています。"],"myth":"«太皷谷» の名の由来、鬼門の守りとして建てたという話は伝承。«五大稲荷» の数え方は一定しない。","img":["稲荷神社","伏見稲荷大社","津和野城","津和野町"],"wp":"太皷谷稲成神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b7/Taikodani_Inarijinjya_haiden.JPG",2048,1536,"太皷谷稲成神社"],["c:0/05/View_from_Taikodani_Inari-jinja_shrine%2C_Tsuwano-cho%2C_Kanoashi-gun%2C_Shimane_001.jpg",10169,3220],["c:5/5d/Toriis_of_Taikodani_Inari_Shrine_4.jpg",4032,3024],["c:5/54/Shimmon_Gate_of_Taikodani_Inari_Shrine.jpg",3973,2980],["c:a/ac/Taikodani_Inari-jinja_Offerings_001.jpg",3264,2448],["c:7/78/Taikodani_Inari-jinja_My%C5%8Dbu_Auxiliary_Shrine_001.jpg",3264,2448],["c:a/a9/Taikodani_Inari-jinja_Former_Shrine_001.jpg",3264,2448],["c:e/ec/Taikodani_Inari-jinja.jpg",3257,2443]]},{"id":"32_hori_teien","n":"堀庭園（笹ヶ谷銅山の堀家）","yomi":"ほりていえん","cat":"産業","y":1900,"era":["edo","meiji"],"sh":"国指定名勝","rank":"B","ad":"鹿足郡津和野町邑輝（旧畑迫）","st":"JR津和野駅から車で約15分","la":34.505,"lo":131.835,"hook":"山あいの村に、銅で財をなした一族の庭がある。紅葉の季節、座敷の外は一面の錦になる。","lead":"堀庭園は、津和野町の畑迫（はたばさこ）地区にある、堀家の屋敷と庭です。堀家は江戸時代から近くの笹ヶ谷銅山などを経営し、«銅山王» ともいえる富を築いた一族でした。明治時代に建てられた «楽山荘» の座敷から見る庭は美しく、国の名勝に指定されています。","story":["津和野の町から山へ入った畑迫の里。ここに、江戸時代から続く堀家の屋敷があります。堀家は、この地の銅山を手に入れ、鉱山の経営で大きな富を築きました。銅は、お金や道具、寺の鐘などに欠かせない金属。山からほり出される銅が、この家を豊かにしたのです。","明治時代、堀家の当主は、客人をもてなすための建物 «楽山荘» を建てました。座敷の窓の外には、池と築山、そして背後の山を借景にした庭が広がります。«山を楽しむ» という名前のとおり、庭と山がひとつの景色になるように工夫されています。","堀家は、ただお金持ちだっただけではありません。村に病院をつくり、医者を招いて人々の健康を守ろうとしました。この «旧畑迫病院» の建物も近くに残っています。なぜ山あいの村に病院を? 鉱山で働く人やその家族、村の人々の暮らしを支えることが、地域の主としての役目だと考えていたのかもしれません。","秋になると、庭のもみじが真っ赤に色づき、座敷の畳にまで紅葉の色がうつりこむように見えます。この景色を見ようと、多くの人が訪れます。","一方で、銅山の開発は、山や川に大きな影響もあたえました。堀庭園を訪れるときは、鉱山がもたらした豊かさと、その陰で生まれた苦しみの両方に思いをはせたいものです。"],"tl":[["江戸時代","堀家が笹ヶ谷銅山などの経営にたずさわる"],["明治時代","堀家が鉱山経営で大きく発展する"],["1890年ごろ","堀家が畑迫に病院を開く"],["1900年","楽山荘が建てられる"],["2006年","堀氏庭園として国の名勝に指定される"]],"who":[["堀家","笹ヶ谷銅山などを経営した一族。庭と屋敷を築いた"],["堀家の当主","楽山荘や病院をつくり、地域を支えた"],["鉱山で働いた人々","銅山を支え、村の暮らしをつくった"]],"deep":["名勝の正式な名前は «堀氏庭園» です。楽山荘の庭と、屋敷まわりの景観があわせて守られています。","楽山荘の庭は、座敷から見ることを前提につくられた «座観式» の庭です。座敷の柱と縁側が額縁のような役目を果たします。","旧畑迫病院は明治時代の洋風の木造建築で、地域の医療のために個人の家がつくった病院として知られます。現在は見学施設として整備されています。","堀家の屋敷の近くには、鉱山の経営に関わる建物や、使用人の住まいなど、鉱山主の暮らしを伝える建物がまとまって残っています。","笹ヶ谷鉱山の歴史には、鉱毒・公害の問題もふくまれます。堀家の華やかさだけでなく、地域がたどった歴史全体を知ることが大切です。","畑迫地区は津和野の町から少しはなれた静かな山里で、鉱山の最盛期には多くの人が行き交いました。堀家の屋敷群・庭園・病院がまとまって残り、ひとつの «鉱山主の里» の姿を伝えている点が、この場所の大きな価値です。"],"look":["楽山荘の座敷から見る庭（紅葉の季節は特に）","旧畑迫病院の洋風建築","堀家の屋敷まわりの石垣や土蔵"],"q":["堀家が富を築いたのは、何の鉱山の経営によってだった?","銅山です。近くの笹ヶ谷銅山などを経営し、大きな財をなしました。"],"myth":"病院の開設年や楽山荘の建築年は資料により多少違う。","img":["笹ヶ谷鉱山","津和野町","名勝"],"wp":"堀庭園","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"],["c:4/4f/Kamikouchi.JPG",640,480,"名勝"],["c:2/2a/Aonoyama20080712.JPG",648,486,"近く: 青野山駅"],["c:9/97/%E6%97%A5%E5%8E%9F%E9%A7%85.jpg",640,480,"近く: 日原駅"],["c:3/3e/Nichihara_Observatory.jpg",1800,2400,"近く: 日原町"],["c:b/b5/Tsuwano_town_Nichihara_elementary_school.jpg",2272,1704,"近く: 津和野町立日原小学校"]]},{"id":"32_sasagatani","n":"笹ヶ谷鉱山跡（石見の銅山）","yomi":"ささがたにこうざんあと","cat":"産業","y":1700,"era":["edo","meiji","showa"],"sh":"","rank":"B","ad":"鹿足郡津和野町笹ヶ谷","st":"JR津和野駅から車で約20分。鉱山跡は山中にあり、見学は外から周辺を見る形が基本","la":34.5,"lo":131.83,"hook":"銅を掘った山は、同時に «石見銀山ねずみ捕り» の毒も生んだ。豊かさと苦しみが同じ山から出てきた場所。","lead":"笹ヶ谷鉱山は、津和野町の山あいにあった銅山です。江戸時代から銅を産出し、鉱山を経営した堀家は大きな富を築きました。一方で、この鉱山からは、ねずみを退治する薬として知られた «石見銀山» の原料になるヒ素もとれたといわれ、のちには鉱山による健康被害が大きな問題となりました。","story":["津和野の町から山へ分け入った笹ヶ谷。ここでは古くから銅の鉱石がとれました。江戸時代、鉱石をほり出し、炉でとかして銅を取り出す仕事がさかんに行われ、山には多くの人が集まって暮らしていました。","江戸時代の人々の家には、ねずみに米を食べられてこまる悩みがありました。そこで売られていたのが、«石見銀山ねずみ捕り» とよばれる毒薬です。名前には «石見銀山» とありますが、じつはその多くが笹ヶ谷の鉱山でとれたヒ素からつくられていた、ともいわれます。なぜ銀山の名前を? 有名な石見銀山の名が、よく効く薬のイメージにぴったりだったからだと考えられています。","明治時代になると、堀家が鉱山の経営に力を入れ、笹ヶ谷は大きく発展しました。けれども、鉱石をとかす煙や、鉱山から出る水には、ヒ素などの毒が含まれていました。それは周りの田畑や川、人々の体にも少しずつ影響をあたえていきました。","鉱山は昭和の時代に閉じられました。その後、近くの人々に慢性ヒ素中毒の健康被害があることが明らかになり、公害として認められました。長いあいだ苦しんだ人たちがいたことを、忘れてはならない歴史です。","いま笹ヶ谷の山は、緑におおわれた静かな場所になっています。けれども鉱山の跡には、鉱害を防ぐための対策が今も続けられています。この地を訪れるときは、鉱山が生んだ富と、それに苦しんだ人々の両方に思いを寄せることが大切です。"],"tl":[["江戸時代","笹ヶ谷で銅の採掘・製錬がさかんに行われる"],["江戸時代","鉱山からとれるヒ素が «石見銀山ねずみ捕り» の原料になったといわれる"],["明治時代","堀家の経営で鉱山が発展する"],["昭和時代","鉱山が閉山する"],["1970年代","周辺住民の慢性ヒ素中毒が公害として認められる"]],"who":[["堀家","笹ヶ谷鉱山を経営し、大きな富を築いた一族"],["鉱山で働いた人々","銅の採掘や製錬にたずさわった"],["周辺の住民","鉱害による健康被害を受け、長く苦しんだ"]],"deep":["«石見銀山ねずみ捕り» は江戸時代に全国で売られた殺鼠剤です。原料の亜ヒ酸は、石見銀山そのものではなく、笹ヶ谷など別の鉱山で産出したものが多かったという説が知られています。","銅鉱石の中には、ヒ素を多く含む «硫砒鉄鉱» などがまじることがあります。製錬の過程で出るヒ素の化合物が、薬の原料にも、また公害の原因にもなりました。","笹ヶ谷の公害は、宮崎県の土呂久（とろく）とともに、鉱山による慢性ヒ素中毒の例として知られています。被害を受けた人々への救済が行われました。","閉山したあとも、鉱山跡からの排水にはヒ素などが含まれるため、水をきれいにする処理が続けられています。鉱山の影響は、閉じたあとも長く残るのです。","堀家の屋敷や庭園（堀庭園）は近くにあり、鉱山がこの地域にもたらした富のすがたを今に伝えています。"],"look":["鉱山跡周辺の山の風景（立ち入りできる範囲で）","近くの堀庭園と旧畑迫病院","鉱害対策の施設（外から）"],"q":["江戸時代に笹ヶ谷のヒ素からつくられたといわれる有名な薬は?","«石見銀山ねずみ捕り» です。名前は石見銀山ですが、原料は笹ヶ谷産が多かったともいわれます。"],"myth":"«石見銀山ねずみ捕り» の原料が主に笹ヶ谷産だったかは通説。閉山年・公害認定の年は要確認。","img":["堀庭園","石見銀山","公害","津和野町"],"wp":"笹ヶ谷鉱山","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:f/ff/Air-pollution-taiwan.JPG",1600,1200,"公害"],["c:2/2f/Hommachi-dori_Street_in_Tsuwano%2C_Kanoashi%2C_Shimane_2.jpg",4032,3024,"津和野町"]]},{"id":"32_ikoji","n":"医光寺（雪舟が住職をした寺）","yomi":"いこうじ","cat":"寺社","y":1479,"era":["muromachi"],"sh":"国指定史跡及び名勝（医光寺庭園）","rank":"B","ad":"益田市染羽町","st":"JR益田駅からバスで約10分「医光寺前」下車すぐ","la":34.67,"lo":131.857,"hook":"水墨画の巨匠・雪舟が、絵筆ではなく石と水と木で描いた «絵»。それがこの寺の庭だといわれる。","lead":"医光寺は、益田市にある臨済宗の寺です。室町時代、水墨画で有名な雪舟が、この寺のもととなった崇観寺の住職をつとめたと伝えられ、雪舟がつくったとされる庭園が残っています。庭は国の史跡と名勝に指定されており、益田を治めた益田氏とのつながりも深い寺です。","story":["室町時代の終わりごろ、石見の益田を治めていたのは、中世から続く武士・益田氏でした。そのころ、中国（明）にわたって絵を学んだ画僧・雪舟が、各地を旅していました。益田氏の招きを受けて、雪舟はこの地をおとずれたと伝えられています。","雪舟は、益田の崇観寺の住職をつとめたといわれます。そして寺の庭をつくりました。心字池（「心」の字の形の池）を中心に、築山や石が組まれ、背後の山の緑と一つになった景色。«これは、雪舟が石で描いた山水画だ。» そう言われるのも、なっとくできます。","なぜ絵かきの雪舟が庭を? 雪舟の水墨画には、切り立った岩や流れる水が力強く描かれています。庭づくりもまた、自然の景色を小さな空間にうつしとる芸術でした。絵と庭は、雪舟にとってつながった表現だったのかもしれません。","寺の入り口に立つ «総門» は、益田氏の本城・七尾城の大手門を移したものと伝えられます。戦国時代が終わり、益田氏が長門（山口県）の須佐へ移ったあと、城の門がこの寺に残されたのです。","庭の季節ごとの表情もみどころで、春のつつじ、秋のもみじが池に映ります。縁側にすわって庭をながめていると、時間の流れがゆっくりになるように感じます。雪舟が見た景色を、500年後の私たちも見ているのです。"],"tl":[["室町時代","益田氏の保護のもと崇観寺が栄える"],["1479年ごろ","雪舟が益田に来て崇観寺の住職をつとめたと伝わる"],["室町時代後期","雪舟が庭をつくったとされる"],["江戸時代","崇観寺の流れを受けついで医光寺となる"],["昭和時代","医光寺庭園が国の史跡・名勝に指定される"]],"who":[["雪舟","室町時代の画僧。崇観寺の住職をつとめ、庭をつくったと伝わる"],["益田兼堯","益田氏の当主。雪舟を招いたとされる"],["益田氏","石見の豪族。寺を保護した"]],"deep":["雪舟が益田に来た年やとどまった期間については諸説あります。益田では、雪舟が晩年をここで過ごし亡くなったという説もあり、市内に «雪舟の郷記念館» や終焉の地とされる場所があります。","益田市内には、同じく雪舟がつくったとされる庭が «萬福寺» にもあり、こちらも国の史跡・名勝です。二つの庭をくらべてみるのもおすすめです。","医光寺の総門は、七尾城の大手門を移したものと伝わる、戦国の城の名残を感じさせる門です。","雪舟作と伝わる庭は全国に何か所もありますが、実際に雪舟がつくったかどうかを確かめる史料が少ないものがほとんどです。医光寺の庭も «伝雪舟» と考えておくのがよいでしょう。","益田氏は平安時代の終わりごろから続く石見の名族で、中世の益田の町づくりにも関わりました。医光寺は、その益田氏の文化の厚みを伝える場所です。"],"look":["心字池を中心にした雪舟庭園","七尾城の大手門を移したと伝わる総門","春のつつじ・秋のもみじ"],"q":["医光寺の総門は、もとはどこの門だったと伝わる?","益田氏の本城・七尾城の大手門です。城がなくなったあと、寺に移されたと伝えられます。"],"myth":"雪舟の在住期間・作庭・終焉の地は伝承と諸説が多い。総門の移築も伝承。","img":["雪舟","益田氏","萬福寺 (益田市)","七尾城 (石見国)"],"wp":"医光寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/75/Portrait_of_Sesshu.jpg",988,1217,"雪舟"],["c:0/05/%E8%90%AC%E7%A6%8F%E5%AF%BA%E5%BA%AD%E5%9C%92%28%E7%9B%8A%E7%94%B0%E5%B8%82%29.jpg",2048,1371,"萬福寺 (益田市)"],["c:a/a3/MasudaNanaojyo.jpg",3504,2336,"七尾城 (石見国)"]]},{"id":"32_nanao_jo","n":"七尾城（益田氏の山城）","yomi":"ななおじょう","cat":"城","y":1193,"era":["kamakura","muromachi"],"sh":"国指定史跡（益田氏城館跡）","rank":"B","ad":"益田市七尾町","st":"JR益田駅から歩いて約25分。登山口の住吉神社から山頂まで歩いて約20〜30分","la":34.672,"lo":131.862,"hook":"尾根が七つに分かれた山。その上で、中世の名族・益田氏は400年近く石見の地を見守った。","lead":"七尾城は、益田市の町の東にある山城で、石見の豪族・益田氏の本拠地でした。鎌倉時代のはじめに築かれたと伝わり、戦国時代まで益田氏の城として使われました。ふもとの館跡 «三宅御土居» とあわせて、国の史跡 «益田氏城館跡» に指定されています。","story":["«七尾» の名は、山の尾根が七つに分かれていることからついたといわれます。鎌倉時代のはじめ、益田氏の先祖・益田兼高がこの山に城を築いたと伝えられます。以来、益田氏は長いあいだこの地を治めました。","山の上には、平らにならした曲輪（くるわ）がいくつも並び、敵の攻撃をふせぐための堀切や土塁のあとが残っています。ふもとには益田氏が暮らした館 «三宅御土居» があり、ふだんは館で暮らし、いざというときは山の城にこもる、というしくみでした。","戦国時代、益田氏は周防の大内氏、のちに毛利氏と結びつきながら家を守りました。特に益田藤兼の時代には、大内氏をたおした陶晴賢と親しかったため、毛利元就と対立する危機もありました。«家を残すには、どうすればよいか?» 益田氏は毛利に従う道を選び、生き残りました。","1600年、関ヶ原の戦いで毛利氏が敗れ、領地を大きく減らされると、益田氏も父祖の地・益田をはなれ、長門の須佐（山口県萩市）へ移ることになりました。こうして七尾城はその役目を終えます。","いま、城の登り口には住吉神社があり、その先の山道を登ると、中世の城のあとを歩くことができます。山頂からは益田の町と日本海が見わたせ、益田氏が守ってきた土地の広がりを感じられます。"],"tl":[["1193年ごろ","益田兼高が七尾城を築いたと伝わる"],["室町時代","益田氏が石見西部の有力者として力をのばす"],["1555年以降","大内氏の滅亡後、益田氏が毛利氏に従う"],["1600年","関ヶ原の戦いののち、益田氏が須佐へ移り、城は役目を終える"],["2004年","三宅御土居跡とともに国の史跡 «益田氏城館跡» に"]],"who":[["益田兼高","益田氏の先祖。七尾城を築いたと伝わる"],["益田藤兼","戦国時代の当主。毛利氏に従う道を選んだ"],["益田元祥","藤兼の子。益田から須佐へ移った"],["毛利元就","益田氏が従った中国地方の大名"]],"deep":["«益田氏城館跡» は、山城の七尾城と、平地の館の三宅御土居をセットで指定した史跡です。山城と居館の関係がよくわかる例として重視されています。","発掘調査では、城内から中国製の陶磁器なども見つかっています。益田氏が日本海を通じた交易にも関わっていたことを示す手がかりです。","益田元祥は、のちに長州藩（毛利家）で家老として藩の財政立て直しに力をつくしたことで知られます。益田家は江戸時代を通じて長州藩の永代家老でした。","城の築城年の «1193年» は伝承にもとづくもので、確かな史料で裏づけられているわけではありません。城が大きく整備されたのは、戦国時代だと考えられています。","医光寺の総門は、七尾城の大手門を移したものと伝わります。城は失われても、その一部は町の中に残っているのです。"],"look":["登り口の住吉神社","山頂部の曲輪群と堀切","ふもとの三宅御土居跡（館跡）","山頂から見る益田の町と日本海"],"q":["関ヶ原の戦いのあと、益田氏はどこへ移った?","長門の須佐（今の山口県萩市）です。以後、益田家は長州藩の家老として続きました。"],"myth":"築城年・築城者は伝承。史跡指定年は要確認。","img":["益田氏","益田元祥","益田市","医光寺"],"wp":"七尾城 (石見国)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/MasudaNanaojyo.jpg",3504,2336,"七尾城 (石見国)"],["c:a/a2/Ikou_temple_soumon.JPG",4000,3000],["c:b/b1/Nanao_Castle_01_Moat.JPG",2400,1800],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:7/7e/Masuda_Motoyoshi.jpg",3093,6504,"益田元祥"],["c:0/05/%E8%90%AC%E7%A6%8F%E5%AF%BA%E5%BA%AD%E5%9C%92%28%E7%9B%8A%E7%94%B0%E5%B8%82%29.jpg",2048,1371,"益田市"]]},{"id":"32_kumagai_ke","n":"熊谷家住宅（銀山町の豪商屋敷）","yomi":"くまがいけじゅうたく","cat":"町","y":1801,"era":["edo"],"sh":"国の重要文化財","rank":"B","ad":"大田市大森町","st":"JR大田市駅からバスで約25分「大森代官所跡」下車、歩いて約10分","la":35.111,"lo":132.446,"hook":"銀の町・大森でいちばん大きな商家。台所には、20人分をこえる食器が今も並ぶ。","lead":"熊谷家住宅は、石見銀山の町・大森にある、江戸時代の大きな商家の建物です。熊谷家は、銀山で集められた年貢の銀を管理する仕事などをまかされた、町いちばんの有力な家でした。1801年ごろに建て直された主屋や土蔵が残り、国の重要文化財に指定されています。","story":["石見銀山のふもとの大森の町には、江戸幕府の代官所が置かれ、銀山とその周りの土地を治めていました。熊谷家は、その大森で代々商いを営み、幕府の役目の一部を手伝う «掛屋（かけや）» などをつとめた家です。","«掛屋» とは、年貢として納められた銀を集めて、しっかり保管したり、決められた場所に送ったりする役目です。お金の管理をまかされるには、信用がなければなりません。熊谷家はそれだけ町の人々や代官所から信頼されていたのです。","1800年、大森の町を大きな火事がおそいました。熊谷家の屋敷も焼けてしまいますが、翌1801年に主屋が建て直されました。それがいま私たちが見ることのできる建物です。«もう火事には負けない。» 分厚い土壁や瓦屋根には、そんな思いがこめられているようです。","屋敷の中には、広い座敷、帳場、台所、そして五つの土蔵があります。台所には大きなかまどがあり、たくさんの食器が並んでいます。どうしてこんなに多くの食器が? 家族だけでなく、使用人やお客さんのための食事をまかなう、大きな家だったからです。","いま熊谷家住宅は、当時の暮らしを再現して公開されています。着物や道具、ひな人形など、季節ごとの展示もあり、銀山の町で暮らした人々の豊かな生活を身近に感じられます。"],"tl":[["江戸時代","熊谷家が大森で商いを営み、有力な町人となる"],["江戸時代","掛屋などとして、年貢銀の管理にかかわる"],["1800年","大森の大火で屋敷が焼ける"],["1801年","主屋が再建される"],["平成","国の重要文化財に指定され、修理のうえ公開される"],["2007年","石見銀山遺跡とその文化的景観が世界遺産になる"]],"who":[["熊谷家の当主","大森の有力商人。掛屋などをつとめた"],["大森代官所の役人","銀山と周辺を治め、熊谷家と関わった"],["熊谷家の使用人","大きな家の家事や商いを支えた"]],"deep":["熊谷家は掛屋のほか、代官所の御用をつとめる «郷宿（ごうやど）»（村の人が役所に来たときに泊まる宿）などもつとめたといわれ、役所と町・村をつなぐ役割を果たしました。","主屋は大森の町並みの中でも特に大きく、間口が広いのが特徴です。町並みの中に建つ «大商家» の姿をよく残しています。","修理にあたっては、残っていた家財道具や古文書が調べられ、江戸時代後期から明治ごろまでの暮らしが、なるべく当時に近い形で再現されました。","大森の町並みは、国の «重要伝統的建造物群保存地区» に選ばれています。熊谷家住宅は、その中でも中心的な建物のひとつです。","近くには、大森代官所跡（石見銀山資料館）や、銀山の坑道 «龍源寺間歩» があり、銀山の «生産» と «町の暮らし» の両方を見学できます。"],"look":["大きな主屋の外観と格子","台所のかまどと並ぶたくさんの食器","座敷と帳場","五つの土蔵"],"q":["熊谷家がつとめた «掛屋» とはどんな仕事?","年貢として納められた銀を集め、保管したり送ったりする仕事です。信用のある家だけがまかされました。"],"myth":"重要文化財の指定年や土蔵の数は資料で確認が必要。","img":["石見銀山","大田市","大森代官所","龍源寺間歩"],"wp":"熊谷家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:f/f3/Iwami-Ginzan-03578_%2852651572987%29.jpg",3000,1996,"大田市"],["c:5/5e/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan05n.jpg",6000,4000,"大森代官所"]]},{"id":"32_tomogaura","n":"鞆ヶ浦（戦国の銀積み出し港）","yomi":"ともがうら","cat":"産業","y":1526,"era":["muromachi"],"sh":"国指定史跡（石見銀山遺跡）・世界遺産構成資産","rank":"B","ad":"大田市仁摩町馬路","st":"JR馬路駅から歩いて約20分。細い道が多いので、車は手前の駐車場を利用","la":35.147,"lo":132.389,"hook":"小さな入り江の岩に、船をつなぐ穴。戦国の銀はここから博多へ、そして世界へ運ばれた。","lead":"鞆ヶ浦は、石見銀山の銀を運び出すために使われた、16世紀前半の港です。岩場に囲まれた小さな入り江で、船をつなぎとめるために岩に穴をあけた «鼻ぐり岩» が今も残っています。石見銀山遺跡の一部として、世界遺産にも登録されています。","story":["1526年、博多の商人・神屋寿禎（かみやじゅてい）が、石見の山で銀の鉱脈を見つけたと伝えられます。これが石見銀山の本格的な開発のはじまりでした。ほり出した銀の鉱石は、山から運び出され、船で博多などへ送られました。その積み出しに使われたのが、鞆ヶ浦です。","鞆ヶ浦は、岩場に守られた、ちいさな入り江です。«こんな小さな港で、本当に大切な銀を運んだの?» と思うかもしれません。けれども、入り江は波が静かで、船をつなぐのに向いていました。銀山からは、山道を通って鉱石や銀が運ばれてきました。","入り江の岩には、ひもを通すための穴がいくつもあけられています。これが «鼻ぐり岩»。船をこの穴にロープでつないで、波に流されないようにしたのです。牛の鼻にとおす輪 «鼻ぐり» に形が似ていることから、この名がついたといわれます。","やがて1533年ごろ、博多から技術者がまねかれ、銀を精錬する «灰吹法» が石見で行われるようになると、銀の生産は大きくのびました。石見の銀は日本各地だけでなく、中国やヨーロッパの商人たちとの交易にも使われ、世界の銀の流れを変えたともいわれます。その後、港の中心は温泉津の沖泊へと移っていきました。","いまの鞆ヶ浦は、漁船がうかぶ静かな漁村です。けれども岩場に残る鼻ぐり岩を見つけると、500年前、銀を積んだ船がここから波の向こうへこぎ出していった光景が浮かんできます。"],"tl":[["1526年","神屋寿禎が石見銀山を見つけたと伝わる"],["16世紀前半","鞆ヶ浦が銀の積み出し港として使われる"],["1533年ごろ","灰吹法が伝わり、銀の生産がのびる"],["16世紀後半","港の中心が温泉津・沖泊へ移っていく"],["2007年","石見銀山遺跡とその文化的景観の一部として世界遺産に"]],"who":[["神屋寿禎","博多の商人。石見銀山の開発を進めたと伝わる"],["大内氏","周防の大名。銀山の初期の経営に関わった"],["港の人々・船乗り","銀の積み出しを支えた"]],"deep":["鞆ヶ浦と銀山の «仙ノ山» のあいだは、山道で結ばれていました。この道は «鞆ヶ浦道» とよばれ、世界遺産の構成資産の一つになっています。","鼻ぐり岩は、鞆ヶ浦のほか、温泉津の沖泊にも残っています。どちらも岩をくりぬいた穴で、港の施設として使われたものです。","«灰吹法» は、鉛を使って鉱石から銀を取り出す方法です。この技術が石見に入ったことで、銀の生産量が大きくふえたとされます。","16〜17世紀、日本は世界有数の銀の産出国だったといわれ、その中心の一つが石見銀山でした。ヨーロッパの地図に «石見» の名が書かれた例もあると紹介されることがあります。","鞆ヶ浦は小さな漁村で、今も人々が暮らしています。見学の際は、生活の場であることを忘れず、静かに歩きましょう。"],"look":["入り江の岩場に残る «鼻ぐり岩»","集落の中の細い道と港の景色","近くの鞆ヶ浦道の入り口（案内板）"],"q":["鞆ヶ浦の岩にあけられた、船をつなぐための穴を何という?","«鼻ぐり岩» です。牛の鼻輪 «鼻ぐり» に形が似ていることから名づけられたといわれます。"],"myth":"神屋寿禎による発見の年は伝承にもとづく。欧州地図の話は紹介例による。","img":["石見銀山","神屋寿禎","温泉津","灰吹法"],"wp":"鞆ヶ浦","rel":{"ev":[],"grave":[]},"ph":[["c:2/2a/Tomogaura_1.JPG",4320,3240,"鞆ヶ浦"],["c:6/6c/Tomogaura_4.JPG",4320,3240],["c:9/9b/Tomogaura_3.JPG",4320,3240],["c:f/f0/Tomogaura_2.JPG",4320,3240],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"]]},{"id":"32_okidomari","n":"沖泊（毛利水軍の港）","yomi":"おきどまり","cat":"産業","y":1562,"era":["muromachi","azuchi"],"sh":"国指定史跡（石見銀山遺跡の一部）","rank":"B","ad":"大田市温泉津町温泉津（沖泊地区）","st":"JR山陰本線・温泉津駅から車で約5分（歩くと約30〜40分）","la":35.101,"lo":132.337,"hook":"岩に100近い «穴» があけられた小さな入り江。ここは戦国の «銀» を積み出し、毛利の水軍が守った秘密の港だった。","lead":"沖泊は、温泉津の町の北にある細長い入り江です。戦国時代、石見銀山でとれた銀はここから船で運び出され、港の入り口には毛利氏の水軍の城が置かれました。いまは静かな漁村ですが、世界遺産 «石見銀山遺跡とその文化的景観» の一部になっています。","story":["海ぞいの細い道をぬけると、とつぜん目の前に、両側を山にはさまれた細長い入り江があらわれます。波はおだやかで、まるで湖のよう。«なぜ、こんなに奥まった場所が大事な港だったの?» その答えは、この入り江の «かたち» にあります。外海の荒波が入りにくく、しかも入り口がせまいので、敵の船が近づけば、すぐに見張りが気づけるのです。","16世紀、石見銀山の銀は日本の外にまで知られるほどの量がとれました。この銀をめぐって、大内氏・尼子氏・毛利氏が何度も争います。最後に銀山を手に入れたのが、安芸の毛利元就でした。元就にとって大切だったのは、銀をほる山だけではありません。«ほった銀を、安全に運び出す港» も必要だったのです。","そこで使われたのが沖泊でした。銀は山から «温泉津沖泊道» と呼ばれる山道を通って運ばれ、この入り江で船に積まれたと考えられています。港の入り口の両側には «鵜丸城» と «櫛島城» という小さな城が置かれ、水軍が海ににらみをきかせました。«銀の港を守れ!» ――そんな声が聞こえてきそうです。","入り江の岩場をよく見ると、ふしぎな穴があちこちにあります。これは «鼻ぐり岩» と呼ばれ、船をつなぐ綱を通すために岩をくりぬいたものです。その数は100近くといわれ、たくさんの船がここに集まっていたことを物語っています。人の手で一つひとつ穴をあけた、その根気を思うと、港のにぎわいが目にうかびます。","江戸時代になると、銀は陸路で尾道方面へ運ばれるようになり、沖泊の役目は小さくなっていきました。そのおかげで、戦国時代の港のすがたが大きく変えられずに残ったともいえます。2007年、沖泊は石見銀山とともに世界遺産になりました。静かな入り江は、いまも «銀の時代» の記憶を守っています。"],"tl":[["1526年","博多の商人・神屋寿禎が石見銀山の開発を始めたと伝わる"],["1533年","«灰吹法» が伝わり、銀の生産が大きくのびる"],["1562年","毛利元就が石見銀山を支配下におさめる"],["16世紀後半","沖泊が銀の積み出し港・水軍の拠点として使われる"],["江戸時代","銀の運び出しが陸路（尾道方面）中心になり、港の役目が小さくなる"],["2007年","«石見銀山遺跡とその文化的景観» として世界遺産に登録"]],"who":[["毛利元就","石見銀山を手に入れ、沖泊を銀の港・水軍の基地として使った"],["神屋寿禎","博多の商人。石見銀山の本格的な開発のきっかけをつくったと伝わる"],["毛利水軍の武士たち","鵜丸城・櫛島城に入り、港の入り口を守った"]],"deep":["鼻ぐり岩: 岩に綱を通す穴をあけたもので、入り江の両岸に数多く残ります。船が岩に直接つながれていた、戦国〜江戸時代の港の «使い方» がわかる貴重な遺構です。","鵜丸城と櫛島城: 入り江の入り口をはさむように置かれた小さな城で、港を守る «海の門番» でした。沖泊と一体で世界遺産の構成資産に含まれています。","世界遺産の考え方: 石見銀山は «銀をほる場所» だけでなく、«運ぶ道» と «積み出す港» までを一つのセットとして評価されました。沖泊はその «出口» にあたります。","鞆ヶ浦との比較: 大内氏の時代には、大田市仁摩町の «鞆ヶ浦» も銀の積み出しに使われました。毛利氏の時代に沖泊が中心になったといわれ、支配者の交代で港も変わったことがわかります。","恵比須神社: 入り江の奥には、海の神をまつる恵比須神社があります。本殿は古い様式を残しており、港の人びとの信仰の中心でした。","入り江の地形: 沖泊は «リアス式» の細長い入り江で、風と波をさけやすい天然の良港です。北前船の時代にも、温泉津とあわせて風待ちの港として使われました。"],"look":["岩場に残る «鼻ぐり岩»（綱を通した穴）","入り江の奥の恵比須神社","入り口をはさむ鵜丸城跡・櫛島城跡の地形","温泉津の町並み（重要伝統的建造物群保存地区）もあわせて歩く"],"q":["沖泊の岩にたくさんあいている穴は何に使われた?","船をつなぐ綱を通すための穴で «鼻ぐり岩» と呼ばれます。100近く残るといわれます。"],"koji":[],"myth":"鼻ぐり岩の数や港の使われ始めの時期には諸説あります。","img":["石見銀山","温泉津","毛利元就"],"wp":"沖泊","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Okidomari_1.JPG",4320,3240,"沖泊"],["c:1/1b/Okidomari_4.JPG",4320,3240],["c:3/3e/Okidomari_3.JPG",4320,3240],["c:f/f7/Okidomari_2.JPG",4320,3240],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"]]},{"id":"32_ginzan_kaido","n":"石見銀山街道（温泉津沖泊道）","yomi":"いわみぎんざんかいどう（ゆのつおきどまりみち）","cat":"街道","y":1562,"era":["muromachi","azuchi","edo"],"sh":"国指定史跡（石見銀山遺跡の一部）","rank":"B","ad":"大田市大森町〜温泉津町（西田など）","st":"JR温泉津駅、または大森バス停（JR大田市駅からバス約25分）が起点。全長約12kmの山道","la":35.087,"lo":132.39,"hook":"銀を背負った人と馬が行き来した山道。石畳を一歩ふむごとに、戦国の «シルバーロード» がよみがえる。","lead":"石見銀山でとれた銀を、港まで運ぶために使われた道です。大森の銀山から温泉津・沖泊の港までは約12km。山をこえる道には石畳や宿場の町並みが残り、世界遺産の一部として歩くことができます。","story":["«銀はとれた。さあ、どうやって運ぶ?» 戦国時代、石見銀山を手に入れた毛利氏が考えたのは、この問題でした。銀はとても重く、しかも宝物ですから、ねらわれやすい荷物です。山の中の銀山から、安全に港まで運ぶ道が必要でした。こうして使われたのが、大森から温泉津・沖泊へぬける «温泉津沖泊道» です。","道は山あいをうねうねと進みます。途中には «降露坂（ごうろざか）» と呼ばれる急な坂があり、いまも石畳が残っています。雨の日には石がすべり、荷物を背負った人や馬はたいへんだったでしょう。«ここを越えれば港はもうすぐだ» ――そう声をかけあいながら歩いたのかもしれません。","道のとちゅうにある «西田» の集落は、宿場として栄えました。旅人や運送にかかわる人びとが休み、荷物を積みかえたといわれます。山の中なのに、ここだけ家が集まっているのは、道があったからこそ。道が人を集め、町を生んだのです。","江戸時代になり、石見銀山が幕府の直轄地になると、銀は主に陸路で瀬戸内海側の尾道方面へ運ばれるようになりました。一方で、温泉津沖泊道は、港から銀山へ食べ物や生活の品を運ぶ道として使われつづけたといわれます。銀山で働く大勢の人びとの暮らしを、この道が支えていたのです。","2007年、石見銀山は «鉱山» だけでなく、«運ぶ道» と «港» まで含めて世界遺産に登録されました。温泉津沖泊道はその一部です。いまはガイドの案内で歩く人もいて、木々の間をぬける道を進むと、かつて銀を運んだ人びとの足音が聞こえてくるようです。"],"tl":[["1526年","神屋寿禎が石見銀山の開発を始めたと伝わる"],["1533年","灰吹法が伝わり、銀の生産が増える"],["1562年","毛利元就が銀山を支配。温泉津・沖泊への道が重要に"],["1600年","関ヶ原の戦いのあと、石見銀山が徳川家の支配に"],["江戸時代","銀は主に尾道方面の陸路で運ばれ、この道は物資の道として使われる"],["2007年","街道が世界遺産 «石見銀山遺跡とその文化的景観» の一部に"]],"who":[["毛利元就","銀山を支配し、温泉津・沖泊を銀の積み出しに使った"],["大久保長安","江戸時代の初め、石見銀山の経営をまかされた徳川家の役人"],["銀を運んだ人びと","馬や人の背で銀や物資を運び、宿場の暮らしを支えた"]],"deep":["道の二つの顔: 戦国時代は «銀を港へ出す道»、江戸時代は «港から生活物資を運び入れる道» の役割が大きかったといわれます。同じ道でも時代で使われ方が変わりました。","もう一つの街道: 石見銀山には、仁摩町の鞆ヶ浦へ向かう «鞆ヶ浦道» もあります。大内氏の時代に使われたとされ、こちらも世界遺産の構成資産です。","尾道への銀山街道: 江戸時代、銀は中国山地をこえて広島県の尾道へ運ばれました。«銀山街道» という名は、このルートをさす場合も多いので注意が必要です。","降露坂: 石畳が残る急な坂道で、道の中でも見どころの一つです。石畳は人や馬が雨でもすべらず歩けるようにするための工夫でした。","西田の宿場: 街道沿いの集落で、宿や荷物の中継ぎの場として栄えました。いまも山あいに古い家並みの雰囲気が残ります。","世界遺産登録の評価: 石見銀山は、環境にやさしい方法で銀をほり、森を大きくこわさなかった点も評価されました。道のまわりの豊かな森もその証拠です。"],"look":["降露坂の石畳","宿場だった西田の集落","道ばたの石仏や道しるべ","ゴールの沖泊・温泉津の港と町並み"],"q":["戦国時代、銀山から運ばれた銀はどこの港で船に積まれた?","温泉津の北にある «沖泊» です。毛利氏の水軍が守っていました。"],"koji":[],"myth":"道の使われ方や宿場の成り立ちの細かい年代には諸説あります。歩くときは足元と天候に注意し、ガイドの利用がおすすめです。","img":["石見銀山","温泉津","大久保長安"],"wp":"石見銀山街道","rel":{"ev":[],"grave":[]},"ph":[["c:1/1b/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E6%B8%A9%E6%B3%89%E6%B4%A5%E6%B2%96%E6%B3%8A%E9%81%9314.JPG",4320,3240,"石見銀山街道"],["c:8/8c/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%939.JPG",4320,3240],["c:f/f8/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%938.JPG",4320,3240],["c:f/f2/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%937.JPG",4320,3240],["c:c/c4/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%935.JPG",4320,3240],["c:0/01/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%934.JPG",4320,3240],["c:9/9c/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%933.JPG",4320,3240],["c:a/a4/%E9%8A%80%E5%B1%B1%E8%A1%97%E9%81%93%E9%9E%86%E3%83%B6%E6%B5%A6%E9%81%932.JPG",4320,3240]]},{"id":"32_ido_jinja","n":"井戸神社（芋代官・井戸平左衛門）","yomi":"いどじんじゃ","cat":"伝承","y":1732,"era":["edo"],"sh":"","rank":"B","ad":"大田市大森町","st":"JR大田市駅からバスで約25分、大森代官所跡のバス停付近から歩いてすぐ","la":35.11,"lo":132.443,"hook":"«おいもで村を救った代官» がまつられた神社。人びとは彼を、神様として感謝しつづけた。","lead":"江戸時代の中ごろ、石見銀山のある大森にやってきた代官・井戸平左衛門（正明）をまつる神社です。ききんで苦しむ人びとのために、サツマイモを広めようとし、年貢を軽くするなどの手を打ったことから «芋代官» と呼ばれ、神としてまつられました。","story":["1731年、60歳近い一人の役人が、石見の大森代官として着任しました。井戸平左衛門です。当時の役人としてはかなりの年配。«そんな年で、遠い石見までご苦労なことだ» と思った人もいたかもしれません。けれど、この人がやがて地域の «恩人» になるとは、まだだれも知りませんでした。","着任してまもなく、西日本を大きなききんがおそいます。1732年の «享保の大飢饉» です。イナゴなどの害虫が大発生して稲がやられ、食べ物が足りなくなりました。村々からは、食べるものがない、年貢がおさめられない、という声がとどきます。«このままでは多くの人が死んでしまう»。井戸はなやみました。","そのころ井戸は、やせた土地でも育つ «サツマイモ» の話を聞いていたといわれます。薩摩（いまの鹿児島県）ではすでに人びとを飢えから救っていた作物です。井戸は種いもを取り寄せ、村々で育てさせようとしました。はじめはうまく育たない所も多かったようですが、やがて石見の地にもサツマイモが根づいていったと伝わります。","さらに井戸は、年貢を軽くしたり、蔵の米を人びとに分けたりする手を打ちました。本来なら幕府の許しが必要なことです。«責めはわたしが負う» ――そんな覚悟だったのでしょうか。井戸は翌1733年、兼ねてまかされていた備中笠岡（いまの岡山県笠岡市）で亡くなりました。責任をとって切腹したという言い伝えもありますが、病死とみる説もあり、はっきりしません。","人びとは井戸の恩を忘れませんでした。石見や備中・備後の各地に、井戸をたたえる石碑が数多く建てられ、明治時代には大森にこの井戸神社がつくられました。«いもの神様» としていまも大切にされ、毎年のお祭りでは、この代官への感謝の気持ちが受けつがれています。"],"tl":[["1672年","井戸平左衛門（正明）が生まれる"],["1731年","石見大森の代官に着任"],["1732年","享保の大飢饉。サツマイモの導入や年貢の軽減などに取り組む"],["1733年","備中笠岡で亡くなる（死因は諸説）"],["1735年","関東で青木昆陽がサツマイモの研究書をまとめる"],["明治時代","大森に井戸神社がつくられる"]],"who":[["井戸平左衛門（正明）","石見大森の代官。サツマイモを広め、ききんから人びとを救おうとした"],["青木昆陽","同じ時代に関東でサツマイモを広めた学者。«甘藷先生»"],["大森や石見の村人たち","井戸の恩を忘れず、各地に石碑を建て神社をつくった"]],"deep":["顕彰碑の多さ: 井戸をたたえる碑は、島根・岡山・広島にわたり数百基あるといわれます。一人の代官がこれほど広くまつられるのは、とてもめずらしいことです。","«芋代官» と «甘藷先生»: 井戸の取り組みは、関東で青木昆陽がサツマイモを広めるより少し前の出来事です。西と東で、ほぼ同じころにサツマイモが «救いの作物» として注目されていました。","死因の謎: 独断で年貢を軽くした責任をとって切腹したという話が広く知られますが、史料からは病死とする見方もあります。人びとの «感謝の物語» がどう育ったかを考える材料になります。","墓所: 井戸の墓は、亡くなった地の岡山県笠岡市にあるとされます。大森の神社とあわせて、二つの土地が井戸を記憶しています。","種いもの入手: 種いもを薩摩から取り寄せたと伝わります。当時、薩摩藩は作物の持ち出しにきびしかったともいわれ、入手の苦労話が語られています。","代官の兼務: 井戸は大森代官と、備中笠岡の代官を兼ねていました。石見銀山を管理する大森代官所は、幕府にとって特に重要な役所でした。"],"look":["井戸神社の社殿と、井戸をたたえる碑","近くの «大森代官所跡»（石見銀山資料館）","大森の町並み（重要伝統的建造物群保存地区）"],"q":["井戸平左衛門が人びとを救うために広めようとした作物は?","サツマイモです。やせた土地でも育つため、ききんに強い作物として期待されました。"],"koji":[],"myth":"切腹説と病死説があり、種いもの入手の経緯なども伝承まじりです。","img":["享保の大飢饉","サツマイモ","石見銀山"],"wp":"井戸正明","rel":{"ev":[],"grave":[]},"ph":[["c:e/ee/Ido_Masaakira02.jpg",464,623,"井戸正明"],["c:9/9a/180505_Iwami_Ginzan_Silver_Mine_Museum_Oda_Shimane_pref_Japan01s3.jpg",6000,4000],["c:d/d8/%E4%BB%8F%E5%BF%83%E5%AF%BA%EF%BC%88%E4%BD%90%E8%B3%80%E5%B8%82%E5%A4%A7%E8%B2%A1%EF%BC%89%E3%81%AE%E4%BA%AB%E4%BF%9D%E3%81%AE%E9%A3%A2%E9%A5%89%E4%BE%9B%E9%A4%8A%E5%A1%94%E3%80%8C%E6%9C%AC%E5%B7%9E%E5%BA%B6%E6%B0%91%E9%A4%93%E6%AD%BB%E7%B4%AF%E8%91%AC%E4%B9%8B%E5%A2%93%E3%80%8D.jpg",3600,4800,"享保の大飢饉"],["c:a/a4/Ipomoea_batatas.jpg",300,239,"サツマイモ"],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"]]},{"id":"32_mitoya_jo","n":"三刀屋城（尼子十旗）","yomi":"みとやじょう","cat":"城","y":1550,"era":["kamakura","muromachi","azuchi"],"sh":"","rank":"B","ad":"雲南市三刀屋町古城","st":"JR木次線・木次駅から車で約10分。三刀屋の町中から登り口まで歩ける","la":35.294,"lo":132.845,"hook":"尼子の «十の旗» の一つとして出雲の南を守った城。城主は最後に、毛利へ寝返る決断をする。","lead":"三刀屋城は、戦国時代に出雲を支配した尼子氏の、大事な守りの城 «尼子十旗» の一つに数えられます。城主の三刀屋氏は鎌倉時代からこの地を治めた一族で、尼子と毛利の間でゆれながら生きのびようとしました。","story":["«三刀屋（みとや）» という名前は、とても古いものです。奈良時代にまとめられた «出雲国風土記» に、大国主命（天の下造らしし大神）が «御門（みと）» を置いた所だから «三刀矢» と呼ぶ、という話が出てきます。神話の時代から名前の由来が語られる土地に、この城はあります。","鎌倉時代、承久の乱のあと、信濃国（長野県）の諏訪部氏がこの地の地頭としてやってきたといわれます。一族はやがて地名をとって «三刀屋氏» と名乗りました。遠い信濃から来た武士が、何百年もかけて出雲の土地になじんでいったのです。","戦国時代、出雲では月山富田城の尼子氏が力をのばします。尼子氏は本城のまわりに «尼子十旗» と呼ばれる10の支城を置き、国を守りました。三刀屋城はその一つで、出雲の南から備後・安芸へぬける道をおさえる大事な場所でした。«南の守りは三刀屋にまかせよ»――そんな信頼があったのかもしれません。","しかし、安芸の毛利元就が攻めこんでくると、出雲の武士たちの心はゆれます。三刀屋氏も、やがて毛利方につきました。«主家を裏切るのか» «いや、一族を守るためだ»。城主の三刀屋久扶は、そんな葛藤の中で道を選んだのでしょう。尼子氏は1566年、月山富田城を明けわたして降伏します。","その後、三刀屋氏も毛利氏のもとで立場を失い、この地を去ったといわれます。江戸時代のはじめには、松江を治めた堀尾氏の支城として使われたとも伝わります。いま城跡には曲輪（平らな段）や空堀が残り、春には桜の名所としても親しまれています。"],"tl":[["733年","«出雲国風土記» に «三刀矢» の地名の由来が記される"],["1221年","承久の乱。その後、諏訪部氏が地頭としてこの地に入ったといわれる"],["戦国時代","三刀屋氏が尼子氏に仕え、三刀屋城が «尼子十旗» の一つに"],["1562年ごろ","毛利元就の出雲侵攻。三刀屋氏は毛利方へ"],["1566年","尼子義久が月山富田城を開城"],["江戸時代初め","堀尾氏の支城として使われたとも伝わる"]],"who":[["三刀屋久扶","戦国時代の城主。尼子から毛利へと立場を変えた"],["尼子晴久","出雲の戦国大名。十旗の城で領国を守った"],["毛利元就","出雲に攻めこみ、尼子氏を降伏させた"],["堀尾吉晴","江戸時代初めに出雲を治めた大名"]],"deep":["尼子十旗とは: 月山富田城を守る10の支城の総称で、白鹿城・三刀屋城・赤穴城・牛尾城などが数えられます。どの城を入れるかは史料によって少しちがいます。","風土記の地名: «出雲国風土記» 飯石郡の «三屋郷» の条に、大神の «御門» があるので «三刀矢» といったと記されています。のちに «三屋» に改められたといわれます。","諏訪部氏から三刀屋氏へ: 東国の武士が承久の乱後に西国の地頭として移ってくる例は多く、三刀屋氏もその一つとされます。","城の構造: 川に面した山に曲輪を段々に並べた山城で、空堀・土塁のあとが残ります。江戸時代初めの改修を示す石垣があるともいわれます。","三刀屋じゃ山城との関係: 近くには三刀屋氏の古い城とされる «三刀屋じゃ山城» もあり、二つの城の使い分けや年代については研究が続いています。","寝返りの背景: 毛利の出雲侵攻の際には、多くの国人が尼子を離れました。国人は «家を残す» ことを何より重んじ、強い側につくのは当時めずらしいことではありませんでした。"],"look":["山頂の本丸跡からの三刀屋の町のながめ","段々に続く曲輪と空堀のあと","春の桜（城跡一帯が公園になっている）"],"q":["«尼子十旗» とはなに?","尼子氏の本城・月山富田城を守った10の支城のこと。三刀屋城もその一つです。"],"koji":[],"myth":"十旗の顔ぶれ、城主の動き、江戸初期の使われ方には諸説あります。","img":["尼子氏","尼子十旗","毛利元就","出雲国風土記"],"wp":"三刀屋城","rel":{"ev":[],"grave":[]},"ph":[["c:f/ff/Mitoya_Castle.jpg",3872,2592,"三刀屋城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"]]},{"id":"32_sentsuzan","n":"船通山（八岐大蛇とスサノオ降臨の山）","yomi":"せんつうざん","cat":"伝承","y":712,"era":["myth","nara"],"sh":"","rank":"B","ad":"仁多郡奥出雲町竹崎（鳥取県日南町との境）","st":"JR木次線・出雲横田駅から車で約30分の登山口から、歩いて1時間半ほど","la":35.208,"lo":133.178,"hook":"スサノオが天から降りてきた «鳥髪の地»。ここからヤマタノオロチ退治の物語が始まる。","lead":"船通山は、島根県と鳥取県の境にある標高1142mの山です。«古事記» に出てくる、高天原を追われたスサノオが降り立った «鳥髪（とりかみ）» の地と伝えられています。山頂には、オロチのしっぽから出てきたという剣の記念碑があります。","story":["高天原で乱暴をはたらき、神々に追放されたスサノオ。«古事記» によると、彼が降り立ったのは «出雲国の肥の河上、名は鳥髪という地» でした。肥の河は、いまの斐伊川と考えられています。その斐伊川のみなもとの一つにある山が、この船通山です。«ここがスサノオの降りた場所だ» と、昔から語りつがれてきました。","川のほとりに降りたスサノオは、上流から箸が流れてくるのを見つけます。«上に人が住んでいるな»。川をさかのぼると、おじいさんとおばあさんが娘をかこんで泣いていました。«八つの頭と八つの尾をもつ大蛇が、毎年娘を食べに来るのです。残ったのはこのクシナダヒメだけ» ――ヤマタノオロチの物語の始まりです。","スサノオは強い酒を用意させ、酔ってねむったオロチを切りきざみます。しっぽを切ったとき、剣の刃がかけました。ふしぎに思って尾を裂くと、中から一本の見事な剣が。これがのちの «天叢雲剣（草薙剣）» で、三種の神器の一つとされます。山頂の «天叢雲剣出顕之地» の碑は、この場面を記念したものです。","なぜこの地にオロチの話が生まれたのでしょうか。一つの説は、たたら製鉄と関係があるというものです。奥出雲は砂鉄と森にめぐまれ、古くから鉄づくりがさかんでした。鉄をとるために山をけずった土砂で川が赤くにごり、あふれる――その暴れ川のすがたがオロチ、鉄の剣は製鉄の象徴だ、と考える人もいます。もちろん確かめられた話ではありません。","いまの船通山は、春のカタクリの花と、山頂近くのイチイの巨木で知られます。毎年夏には山頂で剣にちなむお祭りも行われます。息を切らして頂上に立ち、足元から流れ出す斐伊川の谷を見下ろすと、神話の世界が少し身近に感じられるはずです。"],"tl":[["712年","«古事記» がまとめられ、スサノオの鳥髪降臨とオロチ退治が記される"],["720年","«日本書紀» にもオロチ退治の話（いくつもの異伝）が記される"],["733年","«出雲国風土記» が完成。斐伊川や仁多郡の地名が記される"],["江戸時代","奥出雲でたたら製鉄が最もさかんになる"],["近代以降","山頂に «天叢雲剣出顕之地» の碑が建てられる"]],"who":[["スサノオノミコト","高天原を追われ鳥髪に降り、ヤマタノオロチを退治した神"],["クシナダヒメ","オロチにねらわれた娘。のちにスサノオの妻となる"],["アシナヅチ・テナヅチ","クシナダヒメの父と母"]],"deep":["«鳥髪» の場所: «古事記» の «鳥髪» を船通山とするのが地元の伝承ですが、あくまで比定であり、確かな証拠があるわけではありません。","«日本書紀» の異伝: 書紀には本文のほか «一書に曰く» として別の話がいくつも載り、スサノオが新羅に降りてから出雲に来たという話もあります。","斐伊川と製鉄: 奥出雲では砂鉄をとる «鉄穴流し（かんなながし）» が行われ、大量の土砂が川に流れました。これが斐伊川の天井川化の一因ともいわれます。","イチイの巨木: 山頂近くのイチイは樹齢が非常に長いといわれる巨木で、天然記念物に指定されています。神話の山にふさわしい存在感です。","草薙剣のゆくえ: オロチから出た剣は、のちにヤマトタケルが使い、いまは名古屋の熱田神宮にまつられていると伝わります。","山の名前: «船通山» の名は、山の形が船をひっくり返したように見えるからなど、いくつかの説があります。"],"look":["山頂の «天叢雲剣出顕之地» の碑","山頂近くのイチイの巨木","4〜5月ごろのカタクリの群生","山頂から見る大山や日本海方面のながめ（晴れた日）"],"q":["ヤマタノオロチのしっぽから出てきた剣の名前は?","«天叢雲剣»。のちに «草薙剣» とも呼ばれ、三種の神器の一つとされます。"],"koji":[{"w":"八雲立つ","m":"スサノオがクシナダヒメと結ばれて詠んだとされる歌の出だし。日本最初の和歌ともいわれる"}],"myth":"鳥髪＝船通山は伝承による比定で、オロチ＝製鉄・暴れ川説は解釈の一つです。登山は装備と天候に注意。","img":["ヤマタノオロチ","スサノオ","草薙剣","斐伊川"],"wp":"船通山","rel":{"ev":[],"grave":[]},"ph":[["c:0/0e/Mt.Sentsuzan.jpg",2304,1728,"船通山"],["c:a/a3/Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi.png",2100,1039,"ヤマタノオロチ"],["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"スサノオ"],["c:a/a4/Hiikawa_river.jpg",2304,1728,"斐伊川"]]},{"id":"32_inada_jinja","n":"稲田神社（クシナダヒメの生まれた地）","yomi":"いなたじんじゃ","cat":"伝承","y":712,"era":["myth","nara"],"sh":"","rank":"B","ad":"仁多郡奥出雲町稲原","st":"JR木次線・出雲横田駅から歩いて約20分（車で約5分）","la":35.2,"lo":133.013,"hook":"ヤマタノオロチから救われたお姫様は、ここで生まれた――と伝わる。産湯の池とへその緒の竹が、神話を今に語る。","lead":"稲田神社は、ヤマタノオロチの物語に出てくるクシナダヒメ（稲田姫）が生まれた場所と伝わる神社です。近くには、ヒメが産湯をつかったという池や、へその緒を切った竹が生えたという場所が残っています。","story":["«古事記» では、スサノオが出会った娘は «櫛名田比売（くしなだひめ）»、«日本書紀» では «奇稲田姫（くしいなだひめ）» と書かれます。名前の中の «稲田» は、実りゆたかな田んぼを思わせます。奥出雲の «稲原» という地名と、この «稲田» の名が重なることから、ここがヒメの生まれた地だと語りつがれてきました。","ヒメの父と母は、アシナヅチとテナヅチ。8人の娘がいましたが、毎年ヤマタノオロチがやって来て、1人ずつ食べてしまいました。そして最後に残ったのがクシナダヒメです。«今年はこの子の番…»。泣いている家族のもとへ現れたのが、天から降りてきたスサノオでした。","スサノオはヒメを守るため、ヒメを «くし» に変えて自分の髪にさし、オロチと戦ったといいます。強い酒で酔わせたオロチを退治したあと、二人は結ばれ、スサノオは «八雲立つ 出雲八重垣 妻籠みに 八重垣作る その八重垣を» と歌いました。二人の新居は須賀の地（雲南市）と伝わります。","稲田神社の近くには、ヒメが生まれたときに産湯をつかったという «産湯の池»、そしてへその緒を切った竹を植えたところ、それが根づいたという «笹の宮» があります。«神様にも赤ちゃんのころがあったんだ» と思うと、神話がぐっと身近になります。","ヒメは、のちに稲の実りを守る女神としても信仰されました。オロチを暴れ川とみる説にしたがえば、ヒメは «川の氾濫から守られた田んぼ» そのものなのかもしれません。静かな山里の小さな神社で、はるかな神話の時代に思いをはせてみましょう。"],"tl":[["712年","«古事記» に櫛名田比売の話が記される"],["720年","«日本書紀» に奇稲田姫として記される"],["733年","«出雲国風土記» が完成。仁多郡の地名が記される"],["江戸時代","奥出雲でたたら製鉄がさかんになる"],["現代","産湯の池・笹の宮などが伝承地として整えられ、多くの人がおとずれる"]],"who":[["クシナダヒメ（稲田姫）","オロチから救われた娘。この地で生まれたと伝わる"],["スサノオノミコト","オロチを退治し、ヒメと結ばれた神"],["アシナヅチ・テナヅチ","ヒメの父母。8人の娘をもった"]],"deep":["表記のちがい: «古事記» は «櫛名田比売»、«日本書紀» は «奇稲田姫»。«くし» を «櫛» と見るか «奇（くしび）＝ふしぎな» と見るかで、名前の意味の解釈が変わります。","くしに変身: ヒメを «湯津爪櫛（ゆつつまぐし）» に変えて髪にさしたという場面は «古事記» にあります。櫛には魔よけの力があると考えられていました。","八雲立つの歌: スサノオの «八雲立つ» の歌は、五七五七七の形をもつことから «日本最初の和歌» といわれ、«出雲» という国名の由来と結びつけて語られます。","伝承地の広がり: オロチ神話の伝承地は奥出雲・雲南に多く、船通山（降臨の地）、稲田神社（ヒメ誕生の地）、須我神社（新居の地）などを «たどる旅» が楽しめます。","稲と女神: ヒメは «稲田の女神» とされ、全国の氷川神社や八重垣神社などでもスサノオとともにまつられています。","地名との関係: «稲原» という地名と «稲田» の名が伝承を支えていますが、どちらが先に生まれたかはわかっていません。"],"look":["稲田神社の社殿","ヒメが産湯をつかったと伝わる «産湯の池»","へその緒を切った竹の伝承地 «笹の宮»","近くのそば店など、奥出雲の山里の風景"],"q":["スサノオはオロチと戦うとき、クシナダヒメを何に変えた?","«くし»（櫛）に変えて、自分の髪にさしたと «古事記» に書かれています。"],"koji":[{"w":"八重垣","m":"何重にもめぐらした垣根。スサノオの歌では、妻を大切に守る家の象徴"}],"myth":"ヒメの生誕地という話は地元の伝承で、古事記・日本書紀に場所の記述はありません。","img":["クシナダヒメ","ヤマタノオロチ","スサノオ","須我神社"],"wp":"稲田神社 (奥出雲町)","rel":{"ev":[],"grave":[]},"ph":[["c:b/bc/Inada-jinja_2.jpg",2432,1824,"稲田神社 (奥出雲町)"],["c:2/22/Yaegaki_Jinja_hekiga.jpg",750,1120,"クシナダヒメ"],["c:a/a3/Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi.png",2100,1039,"ヤマタノオロチ"],["c:e/e9/Kuniteru_Gozu_dragon.jpg",882,1303,"スサノオ"],["c:1/13/Suga_jinja.jpg",3872,2592,"須我神社"]]},{"id":"32_sakurai_ke","n":"櫻井家住宅（松江藩の鉄師）","yomi":"さくらいけじゅうたく","cat":"産業","y":1738,"era":["edo"],"sh":"国の重要文化財","rank":"B","ad":"仁多郡奥出雲町上阿井","st":"JR木次線・出雲横田駅から車で約20分（公共交通は少なく、車が便利）","la":35.148,"lo":132.98,"hook":"«鉄» で栄えた山奥の豪邸。殿様をむかえるための門と、滝を取りこんだ庭がのこる。","lead":"櫻井家は、江戸時代に松江藩から «鉄師» とよばれ、たたら製鉄を営んだ家です。奥出雲の山あいに建つ大きな屋敷は国の重要文化財で、藩主をむかえるための門や、滝の見える庭園がのこっています。","story":["奥出雲の谷あいを車で進むと、山すそに大きな屋敷があらわれます。«こんな山の中に、どうしてこれほどの家が?» その答えは «鉄» です。この地方は砂鉄と、燃料にする木炭の森にめぐまれ、昔から日本有数の鉄の産地でした。櫻井家は、その鉄づくりで大きな富をきずいた家なのです。","櫻井家の先祖は、戦国の武将・塙団右衛門直之といわれます。団右衛門は大坂の陣で豊臣方として戦い、討ち死にしました。その子孫がこの地に移り住み、やがて «可部屋（かべや）» の屋号でたたら製鉄を始めたと伝わります。«武士から鉄の商人へ»――大きな生き方の転換でした。","江戸時代、松江藩は鉄づくりを藩の大事な産業とし、限られた家にだけ許しをあたえました。その家々を «鉄師» と呼びます。とくに田部家・絲原家・櫻井家は «鉄師御三家» と呼ばれ、たくさんの職人をかかえ、山や田畑も持つ、地域の大黒柱でした。","いまの屋敷の中心となる主屋は、江戸時代の中ごろに建てられたと考えられています。屋敷には、藩主が立ち寄るときだけ使う «御成門» や、殿様をむかえる座敷がありました。«殿様がおいでになるぞ»――そのたびに家じゅうが緊張したことでしょう。庭園には «岩浪» と呼ばれる滝があり、座敷から水の流れを楽しめるようになっています。","明治時代になると、西洋式の製鉄が広まり、たたら製鉄はしだいにおとろえていきました。けれど櫻井家の屋敷と道具類は大切に守られ、いまは «可部屋集成館» として公開されています。山奥の豪邸は、日本の近代化を支えた «鉄の道» の出発点を教えてくれます。"],"tl":[["1615年","大坂夏の陣で塙団右衛門直之が戦死"],["江戸時代初め","子孫が奥出雲に移り住んだと伝わる"],["江戸時代","«可部屋» としてたたら製鉄を営み、松江藩の鉄師となる"],["1738年ごろ","いまの主屋が建てられたとされる"],["明治時代","洋式製鉄の広まりで、たたら製鉄がおとろえる"],["昭和時代","住宅が国の重要文化財に指定される"],["現代","«可部屋集成館» として公開"]],"who":[["塙団右衛門直之","櫻井家の先祖とされる戦国武将。大坂の陣で戦死"],["櫻井家の代々の当主","鉄師としてたたら製鉄を営み、地域を支えた"],["松江藩主","鉄師を保護し、櫻井家に立ち寄ったと伝わる"]],"deep":["鉄師御三家: 田部家・絲原家・櫻井家は松江藩の鉄師の中でも特に大きく、«御三家» と呼ばれました。三家とも屋敷や資料館があり、見くらべるとおもしろいです。","たたら製鉄のしくみ: 粘土の炉に砂鉄と木炭を入れ、三日三晩ほど燃やしつづけて鉄の塊をつくりました。できた «玉鋼» は日本刀の材料にもなります。","屋号 «可部屋»: 先祖が広島の可部（いまの広島市安佐北区）とかかわりがあったためといわれますが、由来には諸説あります。","御成門: 藩主のためだけに使われる門で、ふだんは閉じられていました。鉄師が藩からどれほど重く見られていたかを示します。","庭園と滝: 屋敷の庭には山の水を引いた滝 «岩浪» があり、座敷からながめられるよう工夫されています。紅葉のころは特に見事です。","森と鉄: たたら製鉄には大量の木炭が必要で、鉄師は広い山林を持ち、木を切っては植える «循環» で山を管理しました。"],"look":["主屋と «御成門»","庭園の滝 «岩浪»","可部屋集成館の鉄づくりの道具や古文書","周辺の山あいの景色（棚田や、鉄穴流しでできた地形）"],"q":["松江藩で、たたら製鉄を許された家を何と呼んだ?","«鉄師»。櫻井家は田部家・絲原家とならぶ «鉄師御三家» の一つです。"],"koji":[],"myth":"先祖を塙団右衛門とする話や、屋号の由来、主屋の建築年・建築年には諸説があります。","img":["たたら製鉄","塙直之","奥出雲町","玉鋼"],"wp":"櫻井家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Kabeya_Shuseikan_Sakurai.jpg",4128,3096,"櫻井家住宅"],["c:f/f1/Kabeya_Shuseikan_Sakurai_garden.jpg",4128,3096],["c:8/82/Kabeya_Shuseikan.jpg",4128,3096],["c:1/10/Japanischer_Tatara-Ofen_mit_Fl%C3%BCgelgebl%C3%A4se_%2818_Jahrhundert%29.jpg",2000,1660,"たたら製鉄"],["c:f/f3/Ban_Naoyuki.jpg",1350,1870,"塙直之"],["c:9/9f/Oninoshitaburui.jpg",2304,1728,"奥出雲町"],["c:8/8d/Tamahagane_yao.jpg",2064,1528,"玉鋼"]]},{"id":"32_kiyomizudera_yasugi","n":"清水寺（安来の古刹・三重塔）","yomi":"きよみずでら","cat":"寺社","y":1393,"era":["asuka","muromachi","edo"],"sh":"国の重要文化財（根本堂）","rank":"B","ad":"安来市清水町","st":"JR安来駅からバスで約20分、«清水» 下車すぐ","la":35.405,"lo":133.235,"hook":"山陰で数少ない «のぼれる三重塔»。室町時代のお堂とともに、1400年の祈りを伝える山寺。","lead":"安来の清水寺は、飛鳥時代の始まりと伝わる古いお寺です。室町時代に建てられた根本堂は国の重要文化財。江戸時代の終わりにできた三重塔は、中にのぼれるめずらしい塔として知られます。","story":["京都の清水寺は有名ですが、島根県安来市にも «清水寺（きよみずでら）» があります。寺の言い伝えでは、飛鳥時代、尊隆という僧が、きれいな水のわく場所に十一面観音をまつったのが始まりとされます。«清らかな水の寺»――名前の由来もそこにあるといわれます。","山の中の参道を登っていくと、杉木立の奥にどっしりしたお堂があらわれます。これが根本堂です。室町時代、1393年に建てられたことがわかっている建物で、国の重要文化財に指定されています。600年以上も、雨や雪にたえてきたお堂です。«よくここまで残ったものだ» と、見上げずにはいられません。","さらに登ると、朱色の三重塔が見えてきます。江戸時代の終わりごろ、長い年月をかけて完成した塔です。この塔のすごいところは、中の階段で上の層までのぼれること。«塔にのぼる» 体験ができるのは、全国的にもめずらしいのです。窓からは安来の平野や中海の方までが見わたせます。","清水寺は «厄よけの観音さま» としても知られ、昔から多くの参拝者を集めてきました。戦国時代には、近くに尼子氏の月山富田城があり、このあたりは戦の舞台にもなりました。寺もまた、きびしい時代をくぐりぬけてきたことでしょう。","いまの清水寺は、紅葉の名所としても人気です。また宿坊では、肉や魚を使わない «精進料理» を味わえます。古いお堂、のぼれる塔、そして山の静けさ――ゆっくり時間をかけて歩きたいお寺です。"],"tl":[["587年","尊隆上人が開いたと寺では伝える"],["1393年","根本堂が建てられる"],["戦国時代","近くの月山富田城をめぐって尼子・毛利が争う"],["江戸時代末","三重塔が完成（のぼれる塔として知られる）"],["現代","根本堂が国の重要文化財、紅葉と精進料理の寺として親しまれる"]],"who":[["尊隆上人","寺を開いたと伝わる僧"],["寺を守った僧たち","戦乱や災害の中で堂塔を守り、再建した"],["安来の人びと","厄よけ観音として信仰し、寺を支えてきた"]],"deep":["根本堂の年代: 根本堂は建築年代が明徳4年（1393年）とわかる建物で、山陰地方の中世の仏堂として貴重です。","のぼれる三重塔: 多くの塔は内部に入れないつくりですが、ここでは階段で上の層まであがれます。塔の内部構造（心柱など）を間近に見られる点でも貴重です。","寺の宗派: 天台宗の寺で、瑞光山という山号をもちます。山全体を境内とする山岳寺院のつくりです。","京都の清水寺との関係: 同じ «清水寺» の名ですが、直接の本寺・末寺の関係はありません。«清水» の名は全国各地にあり、水の信仰と結びついています。","精進料理: 宿坊で出される精進料理は、ごま豆腐や山菜など山寺らしい品が中心で、予約制で味わえます。","月山富田城とのつながり: 清水寺は月山富田城から近く、戦国時代の尼子氏や毛利氏とのかかわりを伝える話もありますが、確かな史料は多くありません。"],"look":["室町時代の根本堂（国重要文化財）","中にのぼれる三重塔と、上からのながめ","杉木立の参道","秋の紅葉"],"q":["清水寺の三重塔がめずらしいのはなぜ?","中の階段で上の層までのぼれるからです。"],"koji":[],"myth":"587年の創建や尊隆上人の開山は寺伝です。三重塔の完成年や戦国武将とのかかわりには諸説あります。","img":["月山富田城","三重塔","安来市"],"wp":"清水寺 (安来市)","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Yasugi_Kiyomizu-dera_konpondo.jpg",3872,2592,"清水寺 (安来市)"],["c:8/86/Yasugi_Kiyomizu-dera_sanjuto.jpg",2592,3872],["c:b/b9/Yasugi_Kiyomizu-dera_konpondo.2.jpg",3872,2592],["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"],["c:c/c5/Hokiji03ds1536.jpg",2900,4350,"三重塔"],["c:2/2f/Adachi_Museum_of_Art01st3200.jpg",3200,2130,"安来市"]]},{"id":"32_ichibata","n":"一畑寺（一畑薬師）","yomi":"いちばたじ（いちばたやくし）","cat":"寺社","y":894,"era":["heian","taisho"],"sh":"","rank":"B","ad":"出雲市小境町","st":"一畑電車・一畑口駅から車で約10分（バスあり）。旧参道の長い石段で登ることもできる","la":35.457,"lo":132.868,"hook":"海から引き上げた仏さまが、母の目を治した――«目のお薬師さま» のために、鉄道まで敷かれた。","lead":"一畑寺は、«目のお薬師さま» として全国から信仰を集めてきたお寺です。平安時代、漁師が海から引き上げた薬師如来をまつったのが始まりと伝わります。参拝客を運ぶために «一畑電車» がつくられたほどの人気でした。","story":["寺の言い伝えによると、平安時代の894年、日本海の赤浦の海で、与市という漁師が網を入れると、一体の仏像がかかりました。薬師如来です。与市はこの仏さまを大切にまつりました。与市には、目の見えない年老いた母がいました。«どうか母の目を…»。毎日祈りつづけると、母の目が見えるようになった――と伝わります。","このふしぎな話が広まり、仏さまは宍道湖の北の一畑山にまつられるようになりました。«目の病気を治してくださるお薬師さま» として、出雲だけでなく全国から人びとが祈りに来るようになります。«一畑薬師» の名は、やがて全国に知られるようになりました。","参拝の人びとが登ったのが、ふもとから続く長い石段です。1000段をこえる石段を一段一段のぼることも、祈りの一つでした。«目が見えるようになりますように»――自分のため、家族のため、多くの人がこの石段を歩いたのです。","大正時代、お参りの人を運ぶための鉄道がつくられました。いまの «一畑電車» です。名前に «一畑» とあるのはそのため。かつては寺のふもとの «一畑駅» まで線路がのびていましたが、戦争中に休止し、のちに廃止されました。いまは «一畑口駅» の名前だけが、その歴史を伝えています。","境内からは、晴れた日には宍道湖や出雲の平野、遠くの山々まで見わたせます。目を大切にするお寺にふさわしい、すばらしいながめです。«目を休めて、遠くを見よう»――そんな教えをもらった気持ちになります。"],"tl":[["894年","漁師・与市が海から薬師如来を引き上げたと伝わる"],["中世〜江戸時代","«目のお薬師さま» として信仰が広がる"],["1914年","一畑軽便鉄道が開業（のちの一畑電車）"],["大正時代","一畑駅まで線路がのび、参拝客を運ぶ"],["1944年","戦争のため一畑口〜一畑間が休止（のち廃止）"],["現代","一畑薬師教団の総本山として信仰を集める"]],"who":[["与市","海から薬師如来を引き上げたと伝わる漁師"],["与市の母","目が見えるようになったと伝わる"],["全国の参拝者","目の病の回復を願って石段を登った"]],"deep":["宗派: 一畑寺は臨済宗妙心寺派に属し、«一畑薬師教団» の総本山です。禅宗の寺でありながら、薬師信仰の中心になっているのが特徴です。","一畑電車の由来: 鉄道会社の名前に寺の名がつくのは、参拝客輸送が目的だったから。«一畑口駅» で線路がスイッチバックする形になっているのは、かつて一畑駅へのびていた名残です。","石段: ふもとからの参道の石段は «1000段以上» といわれ、今も歩いて登る人がいます。","目の祈願: «め» の字を書いた絵馬や、目にまつわるお守りなどが知られ、子どもの目の健康を願う人も多く訪れます。","海から来た仏: 海中から仏像を引き上げるという話は全国に見られ、«海のかなたから福が来る» という信仰とつながっていると考えられます。","境内の広がり: 本堂のほかにも多くのお堂があり、眺望のよい山上の寺として、宍道湖の景色を楽しむ人も多い寺です。"],"look":["本堂（薬師本堂）","ふもとからの長い石段の参道","境内から見る宍道湖と出雲平野","一畑口駅のスイッチバック（寺の歴史の名残）"],"q":["一畑電車の «一畑» は何に由来する?","一畑寺（一畑薬師）です。参拝客を運ぶために鉄道がつくられました。"],"koji":[],"myth":"与市の話と894年の年代は寺の縁起によるものです。石段の段数も数え方で異なります。","img":["一畑電車","一畑口駅","薬師如来","宍道湖"],"wp":"一畑寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0a/Ichibataji.JPG",2400,1800,"一畑寺"],["c:3/34/Unshu-Hirata_stn.jpg",992,727,"一畑電車"],["c:2/2b/Ichibataguchi-Station.JPG",3072,2304,"一畑口駅"],["c:b/bc/%E6%85%A7%E6%97%A5%E5%AF%BA_%E8%96%AC%E5%B8%AB%E5%A6%82%E6%9D%A5%E5%9D%90%E5%83%8F.jpg",2448,3264,"薬師如来"],["c:1/13/Lake_shinji_landsat.jpg",1024,791,"宍道湖"]]},{"id":"32_hinomisaki_todai","n":"出雲日御碕灯台（明治の石造灯台）","yomi":"いずもひのみさきとうだい","cat":"近代","y":1903,"era":["meiji"],"sh":"国の重要文化財","rank":"B","ad":"出雲市大社町日御碕","st":"JR出雲市駅または一畑電車・出雲大社前駅からバス「日御碕」行きで終点下車、歩いて約5分","la":35.433,"lo":132.63,"hook":"石でつくられた灯台として日本一の高さ。明治の職人が積み上げた白い塔が、今も日本海を照らす。","lead":"出雲日御碕灯台は、1903年（明治36年）に明かりをともした石造りの灯台です。塔の高さは約44mで、石造の灯台としては日本一。中の階段で展望台までのぼることができ、日本海の大パノラマが広がります。","story":["出雲大社から西へ、海ぞいの道を進んだ岬の先に、まっ白な塔が空に向かってのびています。«なんて高いんだろう!» 近づくと、見上げる首が痛くなるほど。これが出雲日御碕灯台です。明治時代、日本は西洋の技術をとり入れて、日本じゅうの岬に灯台を建てていきました。","日本海は、冬になると荒れる海です。島根半島の西のはしのこのあたりは、船にとって目印が必要な場所でした。夜の海で、岩にぶつかれば大事故になります。«船を安全に導く光を»――そんな願いで建てられたのがこの灯台で、1903年4月に初めて光をともしました。","灯台は、外側を石、内側をレンガでつくった二重の壁になっています。重い石を一つずつ積み上げ、高さ約44mの塔を完成させたのは、明治の技術者と職人たちでした。石造の灯台としては日本一の高さで、100年以上たった今も現役で海を照らしています。","らせん階段をぐるぐると160段あまりのぼると、展望台に出ます。目の前には青い日本海、足元にはごつごつした岩の海岸。近くの «経島» はウミネコの繁殖地として知られ、季節によってはたくさんの鳥が見られます。«灯台守は毎日この景色を見ていたのか»と、うらやましくなるかもしれません。","灯台のすぐ近くには、«日が沈む宮» と呼ばれる日御碕神社があります。出雲大社が «日が昇る方» なら、こちらは «日が沈む方» を守るとされます。夕日の時間に灯台と海をながめると、神話と近代が同じ景色の中にとけあっているのを感じられます。"],"tl":[["1868年","明治時代が始まり、西洋式灯台の建設が進む"],["1903年","出雲日御碕灯台が初点灯"],["昭和時代","無人化され、自動で光る灯台になる"],["1998年","«世界の歴史的灯台100選» に選ばれる"],["2022年","国の重要文化財に指定される"]],"who":[["明治の灯台技術者・職人たち","石とレンガを積み上げて塔を完成させた"],["灯台守","無人化まで灯台に住みこみ、光を守りつづけた"],["日本海を行く船乗りたち","この光を目印に安全に航海した"]],"deep":["石造で日本一: 塔の高さ約44mは石造灯台として国内最高で、海面から灯火までの高さは約63mあります。","二重構造: 外壁は石、内壁はレンガでできていて、あいだにすき間を設けた構造です。湿気や地震の揺れへの工夫とも考えられています。","一等灯台: 最大級のレンズを使う «第1等» の灯台の一つで、光は遠くの沖合までとどきます。","世界の灯台100選: 1998年、国際的な灯台の団体によって «世界の歴史的灯台100選» に選ばれました。日本からは数か所しか選ばれていません。","参観灯台: 内部を一般公開している数少ない灯台の一つで、らせん階段で展望台までのぼれます（悪天候時などは閉鎖）。","経島と日御碕神社: 灯台近くの経島はウミネコの繁殖地として天然記念物に指定され、日御碕神社の神域でもあります。"],"look":["白い石造の塔と、らせん階段","展望台からの日本海のながめ","近くの経島（ウミネコ）と日御碕神社","夕日の時間の灯台"],"q":["出雲日御碕灯台は何でつくられた灯台として日本一の高さ?","石造りの灯台として日本一です（塔の高さ約44m）。"],"koji":[],"myth":"","img":["日御碕神社","経島","出雲大社"],"wp":"出雲日御碕灯台","rel":{"ev":[],"grave":[]},"ph":[["c:d/d0/Hinomisaki_lighthouse_Izumo01bs3200.jpg",2130,3200,"出雲日御碕灯台"],["c:3/30/Cape_Hinomisaki_Izumo06bs4592.jpg",4592,3056],["c:b/b6/Hinomisaki-stairway2015.jpg",2448,3264],["c:f/f8/Hinomisaki_lighthouse_Izumo02bs3200.jpg",3200,2130],["c:9/93/Izumo_Hinomisaki_Sakaguri_irradiation_light.jpg",2400,1600],["c:7/7d/Hinomisaki-todai81.JPG",1200,1600],["c:9/94/Hinomisaki-todai46.JPG",1200,1600],["c:4/4b/Hinomisaki-todai44.JPG",1200,1600]]},{"id":"32_momen_kaido","n":"木綿街道（平田の商人町）","yomi":"もめんかいどう","cat":"街道","y":1750,"era":["edo","meiji"],"sh":"","rank":"B","ad":"出雲市平田町（新町・宮の町・片原町など）","st":"一畑電車・雲州平田駅から歩いて約10分","la":35.434,"lo":132.816,"hook":"«雲州木綿» の積み出しでにぎわった川ぞいの町。しょうゆ・酒・生姜糖――老舗の香りが路地にただよう。","lead":"木綿街道は、出雲市平田にある古い商人の町並みです。江戸時代から明治時代にかけて、このあたりでつくられた木綿 «雲州平田木綿» が集まり、船で運び出されました。いまもしょうゆ蔵や酒蔵、生姜糖の老舗が軒をならべています。","story":["一畑電車の雲州平田駅でおりて、川の方へ歩いていくと、白壁と焼き杉の板壁の家が続く通りに出ます。ここが «木綿街道»。«街道» と名がついていますが、実は町の中の通りです。この名前は、近年になって、町の歴史をわかりやすく伝えるためにつけられました。","江戸時代、出雲の平野では綿がたくさん栽培され、農家の女性たちが糸をつむぎ、布を織りました。できた木綿は «雲州平田木綿» と呼ばれ、丈夫でよい品として大坂など遠くの市場でも評判になったといわれます。«平田の木綿なら安心だ»――そんな信用が町を豊かにしました。","木綿を集め、船で運び出す商人たちが、この通りに店をかまえました。町のそばを流れる川は宍道湖につながり、そこから先の海へと荷物が運ばれていきました。川ぞいに蔵が並んでいるのは、船の積みおろしに便利だったからです。","通りを歩くと、何百年も続く老舗が目に入ります。しょうゆの醸造元、酒蔵、そして江戸時代の中ごろ創業と伝わる生姜糖の店。生姜糖は出雲のショウガを使った砂糖菓子で、お土産として人気です。«この店、いつからあるの?» と聞くと、びっくりするような年数が返ってくるかもしれません。","明治時代以降、機械でつくる安い布が広まると、手織りの木綿はしだいにすがたを消していきました。けれど商人の町並みは残り、地元の人たちが大切に守っています。古い家の中を見学できる場所もあり、商人たちの暮らしぶりを身近に感じることができます。"],"tl":[["江戸時代前期","出雲の平野で綿づくりが広がる"],["江戸時代中期","平田が木綿の集散地として栄える。老舗の生姜糖屋が創業したと伝わる"],["江戸時代後期","«雲州平田木綿» が各地で評判になる"],["明治時代","機械織りの布が広まり、手織り木綿がおとろえる"],["平成時代","町並みが «木綿街道» の名で紹介されるようになる"]],"who":[["平田の木綿商人","木綿を買い集め、船で各地に送り出した"],["綿を織った農家の女性たち","糸をつむぎ、布を織って木綿の生産を支えた"],["老舗の職人たち","しょうゆ・酒・生姜糖づくりの技を今に伝える"]],"deep":["名前の新しさ: «木綿街道» は歴史的な呼び名ではなく、町おこしの中で名付けられたものです。ただし木綿でにぎわった歴史そのものは確かです。","川と湖の水運: 平田は宍道湖の西北にあり、川を通じて湖と結ばれていました。陸の道よりも船の方が、重い荷物を多く運べました。","町家のつくり: 通りには «切妻» の屋根や «妻入り» と «平入り» の家がまじり、焼き杉板の外壁が落ち着いた色合いをつくっています。","生姜糖: 出雲のショウガと砂糖を煮つめて固めた菓子で、江戸時代から続く店があるといわれます。松江藩の時代から献上品にもなったと伝わります。","斐伊川との関係: 江戸時代のはじめ、斐伊川の流れが東の宍道湖の方へ変わったことが、平田の水運や土地の開発にも影響したといわれます。","見学できる町家: 大きな商家の屋敷などが公開されることがあり、商人の暮らしや帳場のようすを見ることができます（公開日は要確認）。"],"look":["川ぞいに並ぶ蔵と白壁の町並み","しょうゆ蔵・酒蔵などの老舗","生姜糖の老舗","公開されている商家の屋敷"],"q":["平田で作られ、遠くまで評判になった布の名前は?","«雲州平田木綿»。この木綿の積み出しで町が栄えました。"],"koji":[],"myth":"老舗の創業年は各店の伝えによるもので、町の成り立ちの年代には諸説あります。","img":["平田市","一畑電車","生姜糖","斐伊川"],"wp":"木綿街道","rel":{"ev":[],"grave":[]},"ph":[["c:0/0a/Ichibataji.JPG",2400,1800,"平田市"],["c:3/34/Unshu-Hirata_stn.jpg",992,727,"一畑電車"],["c:1/19/Modern_Shogat%C5%8D_made_by_Iwatoya.jpg",4608,3456,"生姜糖"],["c:a/a4/Hiikawa_river.jpg",2304,1728,"斐伊川"]]},{"id":"32_okuni_haka","n":"出雲阿国の墓（歌舞伎の祖）","yomi":"いずものおくにのはか","cat":"墓所","y":1603,"era":["azuchi","edo"],"sh":"","rank":"B","ad":"出雲市大社町杵築北","st":"一畑電車・出雲大社前駅から歩いて約15分（稲佐の浜へ向かう途中）","la":35.397,"lo":132.682,"hook":"京の都で «かぶき踊り» を始め、天下を熱狂させた女性。ふるさと出雲に帰り、静かにねむると伝わる。","lead":"出雲阿国は、およそ400年前、京都で «かぶき踊り» を始めた女性で、歌舞伎のもとをつくった人とされます。出雲大社の近くには、阿国が晩年を過ごし、ここにねむると伝わる墓があります。","story":["時は1603年、江戸幕府が開かれた年。京都の北野天満宮や鴨川の河原に、見たこともない踊りがあらわれました。男のような派手な服を着て、刀をさし、町の若者 «かぶき者» をまねた女性が、ユーモアたっぷりに踊るのです。«なんだあれは!» と人びとは集まり、大評判になりました。その中心にいたのが阿国です。","当時の記録 «当代記» には、出雲の巫女と名乗る «国» という女性が、かぶき踊りを見せて人気を集めたことが書かれています。阿国は «出雲大社の修理のためのお金を集めている» と名乗っていたともいわれます。«出雲から来た踊り手»――それが彼女の看板でした。","阿国の踊りはたちまちまねされ、女性たちの一座による «女歌舞伎» が各地で大流行します。しかし風紀が乱れるとして、幕府は1629年に女性が舞台に立つことを禁じました。その後、若い男性の «若衆歌舞伎»、大人の男性による «野郎歌舞伎» へと形を変え、今の歌舞伎へとつながっていきます。","では阿国自身は、その後どうなったのでしょうか。出雲に伝わる話では、阿国は出雲大社に仕える鍛冶の家の娘で、年をとってからふるさとに帰り、尼になって静かに暮らしたといいます。出雲大社の近く、稲佐の浜へ向かう道の途中にある墓は、その阿国のものと伝えられています。","実は、阿国の生まれや亡くなった年・場所は、はっきりわかっていません。京都などにも阿国の墓とされる場所があります。それでも、出雲の人びとは «歌舞伎のふるさとはここだ» と阿国をたたえてきました。墓の前に立ち、ふるさとの海をながめた阿国の晩年を想像してみるのもよいでしょう。"],"tl":[["16世紀後半","阿国が出雲で生まれたといわれる（年は不明）"],["1603年","京都でかぶき踊りを演じ、大評判になる（«当代記»）"],["1629年","幕府が女性の歌舞伎を禁止"],["1652年","若衆歌舞伎も禁止され、野郎歌舞伎へ"],["江戸時代","阿国が出雲に帰り、晩年を過ごしたと伝わる（伝承）"]],"who":[["出雲阿国","かぶき踊りを始め、歌舞伎の祖とされる女性"],["名古屋山三郎","阿国とともに踊った恋人ともいわれる人物（伝承・創作の要素が大きい）"],["出雲大社","阿国は大社の勧進（寄付集め）を名乗ったといわれる"]],"deep":["史料の少なさ: 阿国について同時代の確かな記録は «当代記» などわずかで、生まれ・亡くなった時期・場所はほとんどわかっていません。","«かぶく» の意味: «かぶく» は «かたむく» から来たことばで、常識外れの派手な身なりやふるまいをすることをいいました。«歌舞伎» の字はあとから当てられたものです。","名古屋山三郎との話: 阿国の恋人で、ともに舞台に立ったという話は有名ですが、後世の物語や芝居で大きくふくらんだ部分が多いと考えられています。","墓は複数: 出雲大社近くの墓のほか、京都にも阿国の墓と伝わる場所があり、どれが本当かはわかっていません。","出雲大社の勧進: 阿国一座が «出雲大社の巫女» を名乗ったのは、当時の人びとにとって «出雲» が神聖で魅力的な名前だったからとも考えられます。","京都の阿国像: 京都の南座近く、鴨川のほとりには阿国の像があり、歌舞伎発祥の地として紹介されています。"],"look":["阿国の墓と伝わる石塔","近くの稲佐の浜（国ゆずり神話の舞台）","出雲大社とその門前町"],"q":["阿国が京都で始めた、派手なかっこうで踊る芸能は?","«かぶき踊り»。のちの歌舞伎のもとになりました。"],"koji":[{"w":"かぶく","m":"常識外れの派手な身なりやふるまいをすること。歌舞伎の語源"}],"myth":"出自・晩年の帰郷・墓の場所はいずれも伝承で、史料で確かめられていません。","img":["歌舞伎","出雲大社","稲佐の浜"],"wp":"出雲阿国","rel":{"ev":[],"grave":[]},"ph":[["c:7/75/Okuni_kabuki_byobu-zu_cropped_and_enhanced.jpg",624,934,"出雲阿国"],["c:1/18/Okuni_kabuki_byobu-zu.jpg",12030,3886],["c:7/7b/%E6%AD%8C%E8%88%9E%E4%BC%8E4033.JPG",2304,3072],["c:1/12/Odori_Keiy%C5%8D_Edo-e_no_sakae_by_Toyokuni_III.jpg",2570,1167,"歌舞伎"],["c:1/1c/Haiden_of_Izumo-taisha-1.JPG",5077,3377,"出雲大社"],["c:2/2e/Bentenjima_on_Inasa_Beach.jpg",3056,2294,"稲佐の浜"]]},{"id":"32_yaguchi_yashiro","n":"揖夜神社（黄泉比良坂の近くの古社）","yomi":"いやじんじゃ","cat":"寺社","y":659,"era":["myth","asuka","nara"],"sh":"","rank":"B","ad":"松江市東出雲町揖屋","st":"JR山陰本線・揖屋駅から歩いて約10分","la":35.439,"lo":133.139,"hook":"あの世とこの世の境 «黄泉比良坂» のすぐそば。イザナミをまつる古社には、日本書紀に残る «ふしぎな前ぶれ» の記録もある。","lead":"揖夜神社は、国を生んだ女神イザナミノミコトなどをまつる古い神社です。近くには、神話で黄泉の国（死者の国）への入り口とされる «黄泉比良坂» の伝承地があります。«日本書紀» や «出雲国風土記» にも名前が出てくる、由緒ある社です。","story":["イザナギとイザナミは、日本の島々や神々を生んだ夫婦の神です。ところがイザナミは火の神を生んだときの大やけどがもとで亡くなり、黄泉の国へ行ってしまいました。«もう一度会いたい»。イザナギは妻を追って黄泉の国へ向かいます。その入り口が «黄泉比良坂» でした。","«古事記» には、この坂について «今、出雲国の伊賦夜坂（いふやざか）という» と書かれています。«伊賦夜» は、この神社のある «揖屋（いや）» の古い書き方と考えられています。神社から少し離れた山の中には、黄泉比良坂の伝承地があり、道をふさいだという大きな岩 «千引の岩» を思わせる石が置かれています。","イザナギは «決してわたしの姿を見ないで» という約束を破り、変わりはてた妻の姿を見てしまいます。怒ったイザナミに追われ、イザナギは坂まで逃げると、大岩で道をふさぎました。岩をはさんで、二人は別れのことばを交わします。«あなたの国の人を1日に千人殺しましょう» «ならばわたしは1日に千五百の産屋を建てよう»。生と死の始まりを語る、有名な場面です。","揖夜神社は、そのイザナミを主な神としてまつっています。«日本書紀» の斉明天皇5年（659年）の記事には、犬が死人の腕を «言屋社（いうやのやしろ）» にくわえて置いた、という気味の悪い出来事が記され、天皇が亡くなる前ぶれだとされました。この «言屋社» が揖夜神社のことだと考えられています。«なぜ、わざわざこの社の名が記録に?» 都の人にとっても、ここは «あの世» に近い特別な場所だったのかもしれません。","いまの境内は、地元の人に親しまれる落ち着いた神社です。大社造の本殿や、古くから続くお祭りが大切に守られています。神話の坂と歴史書の記録――二つの時代を重ねて歩くと、出雲が «神々の国» と呼ばれる理由が見えてきます。"],"tl":[["659年","«日本書紀» に «言屋社» の怪異が記される"],["712年","«古事記» に黄泉比良坂が «伊賦夜坂» と記される"],["733年","«出雲国風土記» に «伊布夜社» として記される"],["927年","«延喜式» 神名帳に名前が載る（式内社）"],["現代","地域の神社として祭礼が受けつがれる"]],"who":[["イザナミノミコト","国を生んだ女神。揖夜神社の主な祭神で、黄泉の国の神となった"],["イザナギノミコト","イザナミの夫。黄泉比良坂で妻と別れた"],["斉明天皇","659年の «言屋社» の記事にかかわる天皇"]],"deep":["三つの書き方: «言屋社»（日本書紀）、«伊布夜社»（出雲国風土記）、«伊賦夜坂»（古事記）と、同じ地名がいろいろな字で書かれています。漢字は音を表すために当てられたものです。","659年の記事: 同じ記事には、出雲国造に神の宮を修理させたことや、狐が役夫の持つ葛を食いちぎったことも記されています。当時、出雲で大きな神社の工事が行われていたことがわかります。","黄泉比良坂の伝承地: 神社から南東の山あいにあり、石柱や大岩が置かれています。昭和以降に整えられたもので、«ここが本当の坂» と確かめられたわけではありません。","祭神: イザナミのほか、大己貴命（大国主命）、少彦名命、事代主命などもまつられています。","延喜式の式内社: 平安時代の «延喜式» に載る古い神社（式内社）で、古代から国に認められた社でした。","«揖屋» の地名: 中海に面した港町で、古くから東出雲の中心の一つでした。«いや» という音が «黄泉（よみ）» と結びつけて語られることもありますが、語源はわかっていません。"],"look":["大社造の本殿","境内の古い木々と静かな雰囲気","南東の山あいの «黄泉比良坂» 伝承地（大岩）","中海に近い揖屋の町"],"q":["«古事記» で黄泉比良坂は今のどこだと書かれている?","«出雲国の伊賦夜坂»。揖夜神社のある揖屋のあたりと考えられています。"],"koji":[{"w":"千引の岩","m":"千人で引くほどの大岩。イザナギが黄泉の国との境をふさいだ岩"}],"myth":"黄泉比良坂の場所は神話上のもので、伝承地は後世の比定です。«言屋社»＝揖夜神社も通説です。","img":["黄泉比良坂","イザナミ","イザナギ","斉明天皇"],"wp":"揖夜神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Izumo-iya-jinja-1.jpg",1280,960,"揖夜神社"],["c:0/04/Yomotsu_Hirasaka.JPG",2352,1568,"黄泉比良坂"],["c:8/84/Kobayashi_Izanami_and_Izanagi.jpg",592,1307,"イザナミ"],["c:e/e3/Empress_Kogyoku-Saimei.jpg",610,775,"斉明天皇"]]},{"id":"32_kaka_kukedo","n":"加賀の潜戸（佐太大神誕生の洞窟）","yomi":"かかのくけど","cat":"伝承","y":733,"era":["myth","nara"],"sh":"","rank":"B","ad":"松江市島根町加賀","st":"JR松江駅からバスで約50分、加賀港（マリンプラザしまね）から遊覧船で約50分（冬期や荒天時は運休）","la":35.561,"lo":133.046,"hook":"金の矢が岩を射ぬき、洞窟が光りかがやいた――«出雲国風土記» に語られる、神の誕生の海の洞窟。","lead":"加賀の潜戸は、島根半島の北の海にある海食洞（波がけずった洞窟）です。«出雲国風土記» には、佐太大神がここで生まれたという話が記されています。船で洞窟の中をくぐりぬけることができ、子どもの霊をまつる «旧潜戸» もあります。","story":["加賀港から小さな船に乗り、切り立った崖の海岸を進むと、岩に大きな穴があいた洞窟が見えてきます。船はそのままトンネルのような洞窟の中へ。波の音が岩にひびき、向こう側の出口から光がさしこみます。«ここで神様が生まれたんだって»――そんな話を聞くと、ぞくっとするかもしれません。","奈良時代の «出雲国風土記» には、こんな話があります。キサカヒメという女神が、この洞窟で子を生もうとしたとき、弓矢がなくなってしまいました。ヒメが «わたしの子が神の子なら、なくした弓矢よ出てこい» と祈ると、まず角の弓矢が流れてきました。«これではない» と投げすてると、次に金の弓矢が流れてきたのです。","ヒメは «なんと暗い岩屋だこと» と言って、その金の矢で洞窟の岩を射ぬきました。すると暗かった洞窟に光がさしこみ、ぱっと «かがやいた» といいます。そうしてここで生まれたのが、佐太神社にまつられる佐太大神だとされます。«加賀（かか）» という地名も、このかがやきから来たと風土記は説明しています。","風土記には、ちょっとこわい注意書きもあります。«この洞窟のそばを通るときは、必ず大声を出して通れ。こっそり通ると神が現れて突風が起こり、船がひっくり返る» というのです。海の難所だったこの場所への、昔の人のおそれと敬いが伝わってきます。","近くにはもう一つ、«旧潜戸» と呼ばれる洞窟があります。こちらは幼くして亡くなった子どもたちの霊が集まる所と伝えられ、小さな石積みやお地蔵さまが並んでいます。明治時代にここをおとずれた小泉八雲も、その光景を文章に残しました。にぎやかな «新潜戸» と、静かな祈りの «旧潜戸»。一つの海岸に、生と死の物語が並んでいるのです。"],"tl":[["733年","«出雲国風土記» に佐太大神の誕生の話が記される"],["平安時代以降","佐太神社が出雲の有力な神社として信仰される"],["江戸時代","旧潜戸が子どもの霊をとむらう場所として信仰される"],["明治時代中ごろ","松江に住んだ小泉八雲が加賀の潜戸をおとずれる"],["現代","遊覧船で新潜戸・旧潜戸をめぐることができる"]],"who":[["キサカヒメ（枳佐加比売命）","金の矢で洞窟を射ぬき、佐太大神を生んだ女神"],["佐太大神","この洞窟で生まれたとされる神。佐太神社の主祭神"],["小泉八雲","明治時代にこの地をたずね、旧潜戸のことを書いた作家"]],"deep":["新潜戸と旧潜戸: 船でくぐりぬけられる大きな洞窟が «新潜戸»（佐太大神誕生の地）、子どもの霊をまつるのが «旧潜戸» です。旧潜戸は船をおりて見学する形です。","«かか» の由来: 風土記は、洞窟が «かがやいた» ことから «加賀» の名がついたと説明しています。古代の地名説話の典型的な例です。","大声を出して通れ: 風土記の «ひそかに行けば神が現れ突風が起こる» という記述は、海の難所への注意を神話の形で伝えたものとも考えられます。","佐太神社: 佐太大神をまつる松江市鹿島町の佐太神社は出雲国二宮ともいわれ、ユネスコ無形文化遺産の «佐陀神能» で知られます。","小泉八雲の記録: 八雲は «知られぬ日本の面影» の中で、旧潜戸の子どもの霊の話を紹介しています。","海食洞: 日本海の荒波が、長い年月をかけて岩をけずってできた洞窟です。島根半島の北岸にはこうした地形が多く見られ、国引きジオパークの見どころにもなっています。"],"look":["船でくぐる新潜戸の洞窟の内部","旧潜戸の石積みと地蔵","切り立った海岸の岩と青い海","加賀港の町並み"],"q":["佐太大神が生まれたとき、洞窟が «かがやいた» のは何で岩を射ぬいたから?","金の弓矢です。この «かがやき» が «加賀» の地名の由来とされます。"],"koji":[],"myth":"神話は風土記の記述、旧潜戸の子どもの霊の話は民間の伝承です。遊覧船は季節・天候で運休があります。","img":["佐太神社","出雲国風土記","小泉八雲","島根半島"],"wp":"加賀の潜戸","rel":{"ev":[],"grave":[]},"ph":[["c:c/c8/Sada_jinja.jpg",3872,2592,"佐太神社"],["c:0/07/Lafcadio_Hearn_portrait.jpg",712,1024,"小泉八雲"],["c:d/d7/Shimane_NPP_Unit_1-2.jpg",4286,3194,"近く: 島根原子力発電所"],["c:4/4d/%E5%8A%A0%E8%B3%80%E7%A5%9E%E7%A4%BE.JPG",3264,2448,"近く: 島根町"]]},{"id":"32_enjoji_matsue","n":"堀尾吉晴の墓（圓成寺）","yomi":"ほりおよしはるのはか（えんじょうじ）","cat":"墓所","y":1611,"era":["azuchi","edo"],"sh":"","rank":"B","ad":"松江市栄町","st":"JR松江駅からバスで約15分、松江城の北側。城の北堀あたりから歩いて約10分","la":35.481,"lo":133.048,"hook":"松江の町と城をゼロからつくった男は、完成を見届けるように世を去った。その «生みの親» がねむる寺。","lead":"圓成寺は、松江城と城下町をつくった大名・堀尾吉晴のお墓がある寺です。吉晴は戦国の世を生きぬいた武将で、晩年に出雲へ移り、湖のほとりの丘に新しい城と町をきずきました。","story":["堀尾吉晴は1543年、尾張（いまの愛知県）に生まれました。若いころから織田信長、そして豊臣秀吉に仕え、多くの戦で手柄を立てます。性格はおだやかで、«仏の茂助» と呼ばれたと伝わります。しかし戦場ではたいへん勇敢でした。やさしさと強さをあわせもつ武将だったのです。","1600年の関ヶ原の戦いのころ、吉晴はすでに50代後半。この戦いでは息子の忠氏が徳川方として活躍し、その功で出雲・隠岐24万石の大名になりました。ところが忠氏は1604年、20代の若さで急死してしまいます。残されたのは幼い孫の忠晴。«この子が大きくなるまで、わしが支えねば»――吉晴はふたたび表に出て、孫の後見となりました。","吉晴が取り組んだのが、新しい城づくりです。それまでの本拠は、山の上にある月山富田城。守りは固くても、町を広げたり、船で物を運んだりするには不便でした。吉晴は宍道湖のほとりの亀田山を選び、1607年ごろから城と城下町の建設を始めます。湿地をうめたて、堀をほり、道をひく大工事でした。","城が完成したのは1611年ごろ。そしてその年、吉晴は70歳近くで亡くなりました。まるで最後の大仕事を見届けるかのような最期です。吉晴はこの圓成寺にほうむられました。しかし堀尾家は、孫の忠晴に跡継ぎがいなかったため、1633年に家がとだえてしまいます。","その後、松江は京極氏、そして松平氏が治め、城下町は大きく栄えていきました。今、国宝となった松江城の天守をながめるとき、その土台をきずいた吉晴のことを思い出してみてください。お墓の前に立つと、«町の生みの親» への感謝の気持ちがわいてきます。"],"tl":[["1543年","堀尾吉晴が尾張で生まれる"],["1600年","関ヶ原の戦い。子の忠氏が出雲・隠岐24万石を得る"],["1604年","忠氏が急死。吉晴が孫・忠晴の後見となる"],["1607年ごろ","亀田山で松江城と城下町の建設を始める"],["1611年","松江城がほぼ完成。同じ年に吉晴が亡くなる"],["1633年","堀尾忠晴が亡くなり、堀尾家が断絶"],["2015年","松江城天守が国宝に指定される"]],"who":[["堀尾吉晴","松江城と城下町をつくった大名。圓成寺にねむる"],["堀尾忠氏","吉晴の子。関ヶ原の功で出雲の大名となるが早世"],["堀尾忠晴","吉晴の孫。跡継ぎがなく、堀尾家は断絶"],["松平直政","堀尾・京極のあと松江藩主となった松平家の初代"]],"deep":["仏の茂助: 吉晴の通称は «茂助»。温和な人柄から «仏の茂助» と呼ばれたと伝わりますが、後世の書物による評判も含まれます。","関ヶ原直前の負傷: 関ヶ原の戦いの直前、吉晴は三河の池鯉鮒で起きた殺傷事件に巻きこまれて負傷したといわれ、本戦には子の忠氏が出陣しました。","城地の選定: 城を置く場所をめぐって、吉晴と忠氏の意見が分かれたという話も伝わります。最終的に亀田山が選ばれました（伝承を含む）。","国宝の決め手: 松江城天守は、2012年に «慶長16年（1611年）» と書かれた祈祷札が再発見され、完成時期がはっきりしたことが国宝指定の決め手の一つになりました。","圓成寺の庭園: 寺は庭園でも知られ、心字池を中心とした落ち着いた庭をながめることができます。","堀尾家の終わり: 忠晴に男子がいなかったため、1633年に堀尾家は断絶。その後、1634年に京極忠高、1638年に松平直政が入り、松平家が明治まで治めました。"],"look":["堀尾吉晴の墓（大きな石塔）","寺の庭園","近くの松江城天守（国宝）と北堀の町並み"],"q":["松江城と城下町の建設を始めた大名はだれ?","堀尾吉晴です。1607年ごろから工事を始め、城がほぼできあがった1611年に亡くなりました。"],"koji":[],"myth":"«仏の茂助» の呼び名や、城地選びの親子の対立、松江城の人柱伝説などは伝承です。","img":["松江城","堀尾忠氏","堀尾忠晴"],"wp":"堀尾吉晴","rel":{"ev":[],"grave":[]},"ph":[["c:0/0a/Horio_Yoshiharu.jpg",1115,2450,"堀尾吉晴"],["c:5/52/Hakkensha.jpg",6016,4016],["c:f/ff/Horio_Yoshiharu_tomb.JPG",2000,3008],["c:3/31/Hideyoshi_and_Horio_Yoshiharu.jpg",1536,1151],["c:8/88/Matsue_Castle_Keep_Tower_20230617.jpg",4988,3741,"松江城"],["c:8/89/Horio_Tadauji.jpg",1166,1410,"堀尾忠氏"],["c:f/fd/Horio_Tadaharu.jpg",1159,1403,"堀尾忠晴"]]},{"id":"32_togamiyama_jo","n":"十神山城（安来の海城）","yomi":"とがみやまじょう","cat":"城","y":1560,"era":["nara","muromachi","azuchi"],"sh":"","rank":"B","ad":"安来市安来町（十神山）","st":"JR安来駅から歩いて約20分で登山口、山頂まで歩いて約30分","la":35.44,"lo":133.262,"hook":"中海にぽっかり浮かぶような円い山。風土記では «島»、戦国時代には海を見張る城だった。","lead":"十神山は、安来の港の目の前、中海に突き出した標高約90mの小さな山です。奈良時代の «出雲国風土記» に出てくる «砥神島» と考えられ、戦国時代には、尼子氏が中海の水運を守るための城を置いたといわれます。","story":["安来駅を出て港の方をながめると、海の中にこんもりとした円い山が見えます。まるで海に浮かぶお椀のよう。これが十神山です。今は陸とつながっていますが、昔は島のように海に囲まれていたと考えられています。«なぜこんな所に城が?» 答えは、その «海の上» という場所にあります。","奈良時代の «出雲国風土記» には、意宇郡の島として «砥神島（とかみしま）» の名が出てきます。これが今の十神山のことだと考えられています。1300年近く前から、人びとはこの山を特別な目印として見ていたのです。","戦国時代、安来は尼子氏の本拠・月山富田城の «海の玄関» でした。富田城から流れる飯梨川の河口近くにある安来の港は、船で物や兵を運ぶ大切な場所です。尼子氏はこの港を守るため、中海をひと目で見わたせる十神山に城を置いたといわれます。«敵の船が来たら、すぐに知らせよ!» 見張りの兵が、山の上から海をにらんでいたことでしょう。","やがて毛利元就が出雲に攻めこみ、1566年に月山富田城は開城します。その後も、尼子家を再びおこそうとする山中鹿介らの戦いの中で、中海のまわりの城はくりかえし争いの舞台となりました。十神山城も、そうした戦いの中で使われたと伝わりますが、くわしいことはよくわかっていません。","今の十神山は、ふもとに «十神山なぎさ公園» がある、市民の散歩道です。山頂近くには城の曲輪（平らな所）の跡が残り、木々の間から中海や大山をながめることができます。小さな山ですが、神話の時代から戦国まで、ずっと安来の海を見守ってきた山なのです。"],"tl":[["733年","«出雲国風土記» に «砥神島» が記される（十神山とされる）"],["戦国時代","尼子氏が中海の水運を守るため城を置いたといわれる"],["1566年","月山富田城が開城し、尼子氏が降伏"],["1569〜1570年ごろ","尼子再興軍と毛利軍の戦いが出雲各地で起こる"],["現代","ふもとが公園となり、散策路が整備される"]],"who":[["尼子氏","月山富田城を本拠とした出雲の戦国大名。十神山城を海の守りとしたといわれる"],["毛利元就","出雲に攻めこみ、尼子氏を降伏させた"],["山中鹿介","尼子家の再興をめざして毛利と戦った武将"]],"deep":["砥神島: 風土記の意宇郡の条には、中海に浮かぶいくつかの島が記されていて、その一つが «砥神島» です。十神山は、その後の土砂の堆積などで陸とつながったと考えられています。","海城の役割: 海に面した山城は «海城» とも呼ばれ、港の見張りや船の出入りの管理を担いました。十神山城は安来の港を守る役目をもっていたと考えられます。","富田城とのつながり: 月山富田城のふもとを流れる飯梨川は中海に注ぎ、安来の港から富田城へは川と陸の道で結ばれていました。","城主について: 十神山城の城主については、尼子氏の家臣の名があげられることがありますが、史料が少なく、はっきりしません。","山の形: 円錐形の美しい山で、安来の港のシンボルです。古くから船の目印としても大事にされてきたといわれます。","遺構: 山頂付近に曲輪の跡とされる平らな場所が残りますが、大規模な石垣などはありません。"],"look":["山頂付近の曲輪の跡","山から見る中海と大山","ふもとの十神山なぎさ公園","安来港から見る十神山の円い姿"],"q":["十神山は «出雲国風土記» で何と呼ばれている?","«砥神島（とかみしま）»。昔は島だったと考えられています。"],"koji":[],"myth":"城主や使われた時期には諸説があり、確かな史料は多くありません。","img":["月山富田城","尼子氏","中海","山中幸盛"],"wp":"十神山城","rel":{"ev":[],"grave":[]},"ph":[["c:4/4e/Tokamiyama_Castle.jpg",3872,2592,"十神山城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"],["c:a/a1/Lake_nakaumi_landsat.jpg",1024,802,"中海"],["c:d/dc/Taiheikieiyuden_36_YamanakaYukimori.jpg",2162,2870,"山中幸盛"]]},{"id":"32_suku_mozuka","n":"スクモ塚古墳（石見最大の古墳）","yomi":"すくもづかこふん","cat":"遺跡","y":480,"era":["kofun"],"sh":"国指定史跡","rank":"B","ad":"益田市久城町","st":"JR益田駅から車で約10分（萩・石見空港方面）","la":34.687,"lo":131.823,"hook":"全長およそ100m――石見の国でいちばん大きな古墳。ここにねむる «王» はだれだったのか。","lead":"スクモ塚古墳は、益田市にある古墳時代の大きなお墓です。長さは約100mあり、石見地方でいちばん大きな古墳とされます。国の史跡に指定され、周りは公園として整えられています。","story":["益田の町から北へ、海に近い平野の中に、こんもりとした丘が二つ並んで見えます。«ただの丘かな?» と思うかもしれませんが、これは人の手でつくられたお墓、古墳です。長さはおよそ100m。学校のグラウンドの直線コースよりずっと長い大きさです。","古墳が盛んにつくられたのは、3世紀から7世紀ごろ。大きな古墳は、その地域を治めた有力な人物、いわば «王» のお墓と考えられています。スクモ塚古墳は、5世紀ごろにつくられたと考えられ、そのころ益田のあたりに、大きな力をもつ人がいたことを教えてくれます。","この古墳のふしぎなところは、その «かたち» です。円い丘と四角い丘がつながった形をしているのですが、これを一つの前方後円墳とみる考えと、円墳と方墳が並んでいるとみる考えがあります。«一人の王のお墓なのか、二人のお墓なのか?» 研究者の間でも意見が分かれてきました。","«スクモ» ということばは、この地方でもみがら（稲のから）を指すといわれます。昔、この丘にもみがらが積まれていたから、などの話も伝わりますが、名前の由来ははっきりしません。何百年ものあいだ、地元の人は大きな丘を身近な風景として見てきたのでしょう。","益田は、中世には益田氏が治めた町として知られますが、そのずっと前から人びとの暮らしの中心だったことが、この古墳からわかります。古墳のまわりを一周しながら、1500年以上前、ここで行われた盛大な葬儀を想像してみましょう。"],"tl":[["3世紀後半","日本各地で大きな古墳がつくられ始める"],["5世紀ごろ","スクモ塚古墳がつくられたと考えられる"],["中世","益田氏がこの地域を治める"],["昭和時代","国の史跡に指定される"],["現代","周辺が整備され、見学できるようになる"]],"who":[["ねむる «王»","5世紀ごろ、益田地方を治めた有力な人物と考えられる（名前は不明）"],["古墳をつくった人びと","土を運び、何年もかけて大きな丘をきずいた"],["益田氏","中世にこの地を治めた一族（古墳とは時代がちがう）"]],"deep":["形の論争: 前方後円墳とする見方と、円墳と方墳が接した «二つの古墳» とみる見方があります。どちらと見るかで、全長のとらえ方も変わります。","石見最大: 全長約100mは石見地方で最大級です。出雲の大きな古墳とくらべても見劣りしない規模で、石見にも有力な勢力がいたことがわかります。","年代: 5世紀ごろとされますが、発掘調査は限られていて、細かい年代はまだ確定していません。","名前の由来: «スクモ» は、もみがらや、泥炭（すくも）を指す方言ともいわれ、由来には諸説あります。","益田平野の古墳: 益田には他にも古墳が点在し、古代から高津川・益田川の平野が豊かな土地だったことを示しています。","見学: 墳丘のまわりは公園として整備され、形を外から観察できます。墳丘の上に登るときは、史跡を傷つけないよう注意しましょう。"],"look":["二つの丘が並ぶ墳丘の形","墳丘の大きさ（まわりを一周してみる）","周辺の平野と日本海方面の景色"],"q":["スクモ塚古墳の形をめぐって、分かれている二つの考えとは?","一つの前方後円墳とみる考えと、円墳と方墳が並んだ二つの古墳とみる考えです。"],"koji":[],"myth":"形・年代・名前の由来にはいずれも諸説あります。","img":["古墳","前方後円墳","益田市","益田氏"],"wp":"スクモ塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:d/d3/Sukumoduka%28Masuda-city%29.jpg",3072,2304,"スクモ塚古墳"],["c:9/92/Sukumoduka%28Masuda-city%292.jpg",3072,2304],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"古墳"],["c:0/05/%E8%90%AC%E7%A6%8F%E5%AF%BA%E5%BA%AD%E5%9C%92%28%E7%9B%8A%E7%94%B0%E5%B8%82%29.jpg",2048,1371,"益田市"]]},{"id":"32_futatsuyama_jo","n":"二ツ山城（出羽氏の城）","yomi":"ふたつやまじょう","cat":"城","y":1550,"era":["kamakura","muromachi","azuchi"],"sh":"","rank":"B","ad":"邑智郡邑南町鱒渕","st":"JR三次駅または浜田・広島方面から車で（公共交通では行きにくい）。登山道あり","la":34.85,"lo":132.54,"hook":"二つの峰にまたがる山城。石見の山あいの小さな一族は、毛利家から «殿様の息子» をむかえて生きのびた。","lead":"二ツ山城は、石見の山あい（いまの邑南町）を治めた国人・出羽氏の城です。名前のとおり二つの峰を使った山城で、戦国時代、出羽氏は毛利元就と結びつき、元就の子を養子にむかえたといわれます。","story":["広島県との県境に近い、中国山地の中の盆地。ここが «出羽（いずは）» の里です。この地の武士・出羽氏は、鎌倉時代から戦国時代まで、この山あいの土地を治めてきたといわれます。その本拠が、二つの峰がならぶ山にきずかれた二ツ山城でした。","山城は、ふだんは見張りと守りのための場所です。二つの峰のそれぞれに曲輪（平らにならした場所）を設け、そのあいだを尾根でつなぎます。«片方がやられても、もう片方で守れる»。二つの峰をいかした城のつくりは、山国の武士たちの知恵でした。","戦国時代、石見の山あいの国人たちは、東の尼子氏、西の大内氏、そして南の安芸から力をのばした毛利氏のあいだで、どこにつくかを常に考えなければなりませんでした。出羽氏は、早くから毛利元就と手を結んだといわれます。«強い味方がいなければ、小さな家は生き残れない»。国人たちの切実な選択でした。","やがて元就の息子の一人・元倶（もととも）が、出羽氏の養子になったと伝わります。毛利家と出羽家は、血のつながりで固く結ばれることになりました。しかし元倶は若くして亡くなったといわれ、出羽氏のその後の道は平らなものではありませんでした。","関ヶ原の戦いのあと、毛利氏が防長二国に減らされると、出羽氏も石見を離れたとされます。山の上の城は役目を終え、今は森の中に曲輪や堀切のあとが静かに残ります。山道を登って二つの峰を歩けば、戦国の山国で生きた一族の知恵と苦労が感じられるでしょう。"],"tl":[["鎌倉時代","出羽氏がこの地を治めるようになったといわれる"],["南北朝〜室町時代","二ツ山城がきずかれたとされる（年代は諸説）"],["戦国時代","出羽氏が毛利元就と結ぶ"],["16世紀中ごろ","元就の子・元倶が出羽氏の養子になったと伝わる"],["1600年","関ヶ原の戦い。のち毛利氏は防長二国へ。出羽氏も石見を離れたとされる"]],"who":[["出羽氏","石見の山あい・出羽郷を本拠とした国人"],["毛利元就","出羽氏と結び、子を養子に出したといわれる"],["出羽元倶","元就の子で、出羽氏の養子となったと伝わる"]],"deep":["城の名前: 二つの峰を一つの城として使ったことから «二ツ山城» と呼ばれます。峰ごとに役割を分けた «一城別郭» のようなつくりともいわれます。","養子政策: 元就は、吉川氏・小早川氏をはじめ、周辺の国人の家に子を養子に入れて勢力を広げました。出羽氏への養子もその一つと考えられます。","遺構: 曲輪・堀切・土塁などの跡が山中に残っています。石垣が少なく、土を削って造成した戦国時代の山城らしい姿です。","築城年: 南北朝時代の築城とする説がありますが、史料ではっきりとは確かめられていません。","地域の位置: 出羽の地は石見と安芸（広島県）を結ぶ道の途中にあり、毛利氏にとって石見へ進むための大事な足場でした。","見学の注意: 山城は整備が十分でない所もあります。登山道の状況を事前に確認し、歩きやすい靴で行きましょう。"],"look":["二つの峰に残る曲輪の跡","尾根を断ち切った堀切","山頂から見る出羽の盆地"],"q":["二ツ山城を本拠とした一族は?","出羽氏（いずはし）です。毛利元就と結びつきを強めました。"],"koji":[],"myth":"築城年、城主の系譜、元倶の養子入りの時期などには諸説があります。","img":["毛利元就","出羽元倶","邑南町"],"wp":"二ツ山城","rel":{"ev":[],"grave":[]},"ph":[["c:1/1c/Hutatsuyama_castle.jpg",1984,1185,"二ツ山城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"],["c:c/c1/Dangyokei.jpg",5472,3648,"邑南町"]]},{"id":"32_nuyu_jo","n":"温湯城（石見小笠原氏の城）","yomi":"ぬくゆじょう","cat":"城","y":1559,"era":["muromachi","azuchi"],"sh":"","rank":"B","ad":"邑智郡川本町川本","st":"JR大田市駅や江津駅から車で約40〜50分（旧JR三江線は2018年に廃止）。登山道あり","la":35.015,"lo":132.49,"hook":"江の川を見下ろす山の城で、石見小笠原氏は毛利の大軍に1年以上もちこたえた。","lead":"温湯城は、江の川の流れにそった川本町にある山城で、石見小笠原氏の本拠でした。戦国時代、小笠原長雄は尼子氏と結んで毛利元就と戦い、この城で長い籠城を続けたあと、1559年に毛利に降伏しました。","story":["石見小笠原氏のふるさとは、遠い信濃・甲斐のあたりといわれます。鎌倉時代、承久の乱のあとに石見の地頭として移ってきたと伝わる一族です。以来、江の川ぞいの山あいを治め、やがてこの温湯城を本拠としました。«小笠原» と聞くと礼法の家を思いうかべる人もいるでしょう。同じ一族の流れをくむ家です。","戦国時代の石見では、石見銀山をめぐって大内・尼子・毛利が争いました。小笠原長雄は、尼子氏と手を結び、毛利元就に対抗します。1556年の «忍原崩れ»、1558年の «降露坂の戦い» では、尼子方が毛利軍を破ったといわれ、小笠原氏もその一翼をになっていました。","元就はついに温湯城を攻めます。江の川をはさんで毛利の大軍が陣をしき、城を囲みました。しかし山の上の城はなかなか落ちません。«城の者たちは、まだ耐えているのか…»。籠城は1年以上におよんだといわれます。援軍を期待した尼子氏の助けも十分には届きませんでした。","1559年、長雄はついに降伏します。元就は小笠原氏をほろぼさず、領地の一部をとりあげたうえで、家の存続を認めました。«敵であっても、使える力は生かす»――それが元就のやり方でした。こうして小笠原氏は毛利氏の家臣となり、やがて近くの丸山城へ本拠を移していきます。","今の温湯城跡には、山の上に曲輪の段や堀切が残っています。城跡からは、ゆったりと流れる江の川と川本の町が見わたせます。長い籠城のあいだ、城兵たちも毎日この川をながめていたのでしょうか。"],"tl":[["1221年","承久の乱。のち小笠原氏が石見に入ったといわれる"],["室町時代","温湯城がきずかれ、小笠原氏の本拠となる"],["1556年","忍原崩れ。尼子方が毛利軍を破る"],["1558年","降露坂の戦い。毛利軍が敗れる"],["1558〜1559年","毛利元就が温湯城を包囲"],["1559年","小笠原長雄が降伏。毛利氏の家臣に"]],"who":[["小笠原長雄","石見小笠原氏の当主。温湯城で毛利軍に抵抗した"],["毛利元就","温湯城を攻め、小笠原氏を降伏させた"],["尼子晴久","小笠原氏と結び、毛利と石見銀山を争った"]],"deep":["承久の乱と東国武士: 小笠原氏は、承久の乱のあとに地頭として石見の邑智郡に入ったと伝わります。三刀屋氏など、同じように東国から来た一族は山陰に多くいます。","江の川の要地: 温湯城は中国地方最大級の川・江の川の中流をおさえ、川を使った物の行き来や、石見銀山への道にも目を光らせる位置にありました。","長い包囲戦: 包囲は1年以上におよんだといわれ、山城の守りのかたさと、元就が力攻めより包囲を選んだことがうかがえます。","降伏の条件: 小笠原氏は所領の多くを失ったといわれます。家は残りましたが、勢力は大きく小さくなりました。","石見銀山との関係: 温湯城の戦いは、元就が石見銀山を完全に手に入れる前の段階の戦いで、1562年ごろの銀山支配につながる一歩でした。","遺構: 山頂の主郭から段状に曲輪が連なり、堀切の跡も見られます。"],"look":["山頂の主郭跡","段状に続く曲輪と堀切","城跡から見る江の川と川本の町"],"q":["温湯城で毛利元就に降伏した石見小笠原氏の当主は?","小笠原長雄です。1559年に降伏し、毛利氏の家臣になりました。"],"koji":[],"myth":"小笠原氏の入部の時期、籠城の長さ、戦いの細部には諸説があります。","img":["石見小笠原氏","小笠原長雄","毛利元就","江の川"],"wp":"温湯城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"],["c:e/e5/Hamaharadam01.JPG",5184,3456,"江の川"]]},{"id":"32_maruyama_jo","n":"丸山城（小笠原氏最後の城）","yomi":"まるやまじょう","cat":"城","y":1565,"era":["azuchi"],"sh":"","rank":"B","ad":"邑智郡川本町三原","st":"JR大田市駅や江津駅から車で約50分。城跡の登り口まで車が便利","la":34.97,"lo":132.52,"hook":"毛利に降った小笠原氏が、新しく築いた «最後の本拠»。山の上には、戦国の石垣と井戸がのこる。","lead":"丸山城は、温湯城で毛利元就に降伏した石見小笠原氏が、そのあと本拠とした山城です。毛利氏の家臣として過ごした一族の «最後の城» で、16世紀の終わりに小笠原氏が出雲へ移ると、その役目を終えました。","story":["1559年、温湯城での長い籠城のすえに毛利元就に降伏した小笠原長雄。家は残されましたが、領地は大きく減りました。«これからは毛利家の一員として生きていく»。そう決めた小笠原氏が、新しい本拠としてきずいたのが、この丸山城です。","丸山城は、名前のとおり丸みをおびた山の上にある城です。山頂の本丸を中心に、曲輪が取り囲むように配置されています。戦国時代の後半につくられた城らしく、石を積んだ跡や、城の暮らしに欠かせない井戸のあとも残っているといわれます。«水がなければ籠城はできない» ――温湯城で長い包囲を経験した小笠原氏には、身にしみた教訓だったかもしれません。","毛利氏の家臣となった小笠原氏は、尼子氏との戦いや、そのあとの各地の戦に加わったといわれます。かつては毛利と戦った一族が、今度は毛利のために戦う。戦国時代の国人たちは、そうしてたくましく生きのびていったのです。","16世紀の終わりごろ、小笠原氏は毛利氏の命令で、石見を離れて出雲へ移ったといわれます。鎌倉時代から300年以上も治めてきた土地を離れるのは、どんな気持ちだったでしょう。«ふるさとの山よ、さらば»。持ち主を失った丸山城は、しだいに森にかえっていきました。","今、城跡をおとずれると、木々の中に曲輪の平らな地面や、石垣の跡が見られます。山の上に立つと、石見の山々が重なるように続いているのが見えます。この山並みの中で、小笠原氏は何百年も生きてきたのです。"],"tl":[["1559年","小笠原長雄が温湯城で毛利元就に降伏"],["1560年代","丸山城をきずき、本拠を移したといわれる"],["1566年","月山富田城が開城し、尼子氏が降伏"],["16世紀末","小笠原氏が出雲へ移ったといわれ、丸山城は役目を終える"],["1600年","関ヶ原の戦い。毛利氏は防長二国に減らされる"]],"who":[["小笠原長雄","毛利氏に降伏したあと、丸山城を本拠とした当主"],["小笠原長旌","長雄の子。毛利氏の家臣として活動した"],["毛利元就","小笠原氏を家臣として取りこんだ戦国大名"]],"deep":["温湯城から丸山城へ: 降伏後、小笠原氏は多くの領地を失いました。本拠を移したのは、残された領地の中心に城を置くためだったと考えられます。","城のつくり: 山頂の本丸を中心に曲輪が同心円状に配置される形とされ、戦国時代後半の山城の特徴をよく示しています。","井戸: 山城の中に井戸が残るのは貴重です。長い籠城に備えて、水の確保がどれほど大事だったかがわかります。","出雲への移動: 小笠原氏は16世紀末、毛利氏の領国の配置がえにより出雲へ移されたといわれますが、時期や移った先については諸説があります。","関ヶ原のあと: 毛利氏が防長二国に減らされると、小笠原氏の多くも長門・周防へ移ったとされ、石見との縁は薄くなりました。","見学: 山城のため、道がわかりにくい所があります。地元の案内や地図を確認してから登りましょう。"],"look":["山頂の本丸跡","残る石垣の跡と井戸の跡","曲輪から見る石見の山並み"],"q":["丸山城の前に小笠原氏が本拠としていた城は?","温湯城です。1559年に毛利元就に降伏したあと、丸山城へ移りました。"],"koji":[],"myth":"築城年、城の遺構の細部、出雲へ移った時期には諸説があります。","img":["石見小笠原氏","温湯城","毛利元就","小笠原長雄"],"wp":"丸山城 (石見国)","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Maruyamacastle03.JPG",5184,3456,"丸山城 (石見国)"],["c:3/38/Maruyamacastle02.JPG",5184,3456],["c:a/a7/Maruyamacastle01.JPG",5184,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"]]},{"id":"32_arawai_jo","n":"荒隈城（毛利元就の本陣跡）","yomi":"あらわいじょう","cat":"古戦場","y":1563,"era":["muromachi","azuchi"],"sh":"","rank":"B","ad":"松江市国屋町","st":"一畑電車・松江しんじ湖温泉駅から車で約10分。宍道湖の北岸","la":35.47,"lo":133.015,"hook":"宍道湖を見下ろす丘に、60代の元就は «4年がかり» の陣をしいた。尼子をたおすための、長い長い本陣。","lead":"荒隈城は、戦国時代、毛利元就が出雲の尼子氏を攻めるときに本陣とした城です。宍道湖の北岸の丘にきずかれ、ここから白鹿城や月山富田城への攻撃が指揮されました。尼子氏が降伏するまで、元就は長くこの地にとどまったといわれます。","story":["1562年、安芸の毛利元就は、ついに出雲への本格的な攻撃を始めました。相手は、長く中国地方で力をふるってきた尼子氏です。元就はこのとき60代半ば。«これが人生最後の大仕事になるかもしれぬ»――そんな思いがあったかもしれません。元就が陣をかまえたのが、宍道湖の北岸にある荒隈の丘でした。","なぜここだったのでしょう。荒隈は、宍道湖と中海を結ぶ水の道に近く、尼子方の城々を見わたせる場所でした。北には尼子十旗の一つ «白鹿城»、東には本城の月山富田城。元就はこの丘に大きな陣城をきずき、兵や物資を集め、じわじわと尼子を追いつめていく作戦をとりました。","1563年、元就の長男・隆元が、出雲へ向かう途中で急死するという悲しい出来事が起こります。«なぜ、わしより先に…»。元就の悲しみは深かったといわれます。それでも元就は攻撃をやめませんでした。同じ年、激しい戦いのすえ白鹿城を落とし、月山富田城への補給路を断っていきます。","月山富田城は山の上のかたい城で、力ずくでは落ちません。元就は城を囲んで食料が入らないようにし、城の中から投降する者が出るのを待ちました。こうして1566年、尼子義久はついに城を明けわたし、降伏します。荒隈の丘での長い陣は、ここでようやく終わりを迎えました。","今の荒隈城跡は、住宅地や畑にかこまれた丘になっていて、城の面影は多くありません。それでも丘の上から宍道湖をながめると、元就がこの景色を見ながら何年も作戦を練っていた姿が思いうかびます。戦国の大逆転劇の «司令塔» があった場所なのです。"],"tl":[["1562年","毛利元就が出雲へ本格的に攻めこむ。荒隈に陣をかまえる"],["1563年","元就の長男・毛利隆元が急死"],["1563年","白鹿城が落城"],["1566年","尼子義久が月山富田城を開城し、尼子氏が降伏"],["1569〜1571年ごろ","尼子再興軍との戦い。出雲各地で戦いが続く"]],"who":[["毛利元就","荒隈城を本陣とし、尼子氏をたおした戦国大名"],["毛利隆元","元就の長男。出雲攻めのさなかに急死"],["尼子義久","月山富田城で降伏した尼子氏の当主"],["吉川元春・小早川隆景","元就の子で、出雲攻めの中心となった武将"]],"deep":["城の名前: «荒隈» は «洗合（あらわい）» とも書かれます。長く使われた本陣で、臨時の陣というより本格的な城だったと考えられています。","長期戦の理由: 月山富田城は難攻不落の山城でした。元就は正面からの攻撃ではなく、支城を一つずつ落とし、補給を断つ «兵糧攻め» を選びました。","隆元の死: 隆元は1563年、出雲へ向かう途中の安芸で急死しました。毒殺をうたがう話もありますが、はっきりしません。","元就の病: 出雲の陣中で元就が重い病にかかり、名医・曲直瀬道三が治療にあたったという話が伝わります。","水運の拠点: 荒隈は宍道湖に面し、船で兵や物資を運ぶのに便利でした。陸と水の両方の道をおさえる場所だったのです。","遺構の現状: 開発で失われた部分が多いものの、丘の地形に曲輪の名残を見ることができます。"],"look":["丘の地形（曲輪の名残）","丘から見る宍道湖","白鹿城跡や月山富田城跡とあわせてめぐると、戦いの流れがよくわかる"],"q":["毛利元就が荒隈城を本陣として攻め、1566年に降伏させた大名は?","尼子氏（当主は尼子義久）です。月山富田城を明けわたしました。"],"koji":[{"w":"三本の矢","m":"元就が息子たちに、一本では折れる矢も三本束ねれば折れないと説いたという話。後世の創作とされる"}],"myth":"隆元の死因、元就の病の話、陣の期間の細部には諸説があります。«三本の矢» は後世の創作です。","img":["毛利元就","尼子氏","月山富田城","白鹿城"],"wp":"荒隈城","rel":{"ev":[],"grave":[]},"ph":[["c:4/40/Mori_Motonari.jpg",1935,4000,"毛利元就"],["c:a/ab/%E6%9C%88%E5%B1%B1.jpg",6000,4000,"月山富田城"],["c:1/16/Shiraga_castle.jpg",3872,2592,"白鹿城"]]},{"id":"32_mihonoseki_jiken","n":"美保関事件（昭和の海軍演習事故の慰霊碑）","yomi":"みほのせきじけん","cat":"昭和","y":1927,"era":["showa"],"sh":"","rank":"B","ad":"松江市美保関町美保関","st":"JR境港駅から美保関行きのバスで約25分、終点付近。JR松江駅からもバスあり（乗りかえ）","la":35.566,"lo":133.306,"hook":"1927年の夏の夜、灯りを消した軍艦どうしが衝突した。沈んだ駆逐艦の乗組員をしのぶ碑が、美保関に立つ。","lead":"1927年（昭和2年）8月、島根半島の東のはし・美保関の沖で行われた海軍の夜間演習で、軍艦どうしが次々に衝突する大事故が起こりました。駆逐艦が沈み、百人をこえる乗組員が亡くなりました。«美保関事件» と呼ばれ、美保関には犠牲者をしのぶ慰霊碑があります。","story":["1927年8月24日の夜。美保関の沖では、日本海軍の艦隊が大がかりな夜間演習を行っていました。灯りを消した船が、暗やみの中で敵に見つからないように動き回り、攻撃の練習をするのです。本番さながらの、とても危険な訓練でした。","そのとき、悲劇が起こります。軽巡洋艦 «神通» が駆逐艦 «蕨（わらび）» に衝突し、蕨は船体が二つにさけて、あっというまに沈んでしまいました。さらに、軽巡洋艦 «那珂» と駆逐艦 «葦（あし）» も衝突し、葦も大きな被害を受けました。暗い海に、叫び声が響いたことでしょう。","この事故で、蕨の艦長をふくむ百人をこえる乗組員が命を落としました。多くは若い水兵たちでした。«なぜ、演習でこんなことに…»。家族や仲間の悲しみはどれほどだったでしょう。事故は大きく報道され、国じゅうに衝撃をあたえました。","事故のあと、責任を問う軍法会議が開かれました。神通の艦長・水城圭次大佐は、判決を待たずに自ら命を絶ちました。事故の重さを一人で背負おうとしたのかもしれません。この出来事は、訓練の安全と «責任» のあり方について、多くの問いを残しました。","美保関には、亡くなった人びとをしのぶ慰霊碑が建てられ、地元の人たちによって大切に守られてきました。美しい港町の穏やかな海を前に、ここで失われた命のことを、静かに思い出したいものです。"],"tl":[["1927年8月24日","美保関沖の夜間演習中に «神通» と «蕨»、«那珂» と «葦» が衝突。蕨が沈没"],["1927年","事故の責任をめぐり軍法会議が開かれる"],["1927年（判決前）","神通の艦長・水城圭次大佐が自決"],["事故後","美保関に殉難者の慰霊碑が建てられる"],["現代","地元で慰霊の行事が続けられている"]],"who":[["駆逐艦 «蕨» の乗組員","衝突で船が沈み、艦長をふくむ多くの人が殉職した"],["水城圭次","軽巡洋艦 «神通» の艦長。軍法会議の判決前に自決"],["美保関の人びと","慰霊碑を守り、犠牲者をしのんできた"]],"deep":["演習の背景: 当時の日本海軍は、少ない戦力で強い相手に勝つために夜戦を重視し、灯りを消した危険な演習をくり返していました。","二組の衝突: 事故は «神通と蕨»、«那珂と葦» の二か所で起こりました。蕨は沈み、葦は大きく損傷しました。","犠牲者の数: 亡くなった人はおよそ120人とされ、その多くが蕨の乗組員でした（資料によって数字に少しちがいがあります）。","軍法会議と自決: 艦長の自決は、当時大きく報じられました。個人に責任を負わせるあり方に疑問を持つ声もありました。","その後の海軍: 事故後も夜戦の訓練は続けられ、日本海軍の «夜戦重視» は太平洋戦争まで受けつがれました。","慰霊碑: 美保関の地に碑があり、今も手を合わせる人がいます。見学の際は、慰霊の場所であることを心にとめて静かにおとずれましょう。"],"look":["美保関の殉難者慰霊碑","事故が起きた美保関沖の海（地蔵崎方面）","美保関灯台と美保神社"],"q":["美保関事件で沈没した駆逐艦の名前は?","«蕨（わらび）»。軽巡洋艦 «神通» と衝突して沈みました。"],"koji":[],"myth":"犠牲者数は資料によって少しちがいがあります。慰霊碑の正確な場所は現地で確認してください。","img":["神通 (軽巡洋艦)","美保関町"],"wp":"美保関事件","rel":{"ev":[],"grave":[]},"ph":[["c:c/cd/%E7%BE%8E%E4%BF%9D%E9%96%A2%E7%81%AF%E5%8F%B0%E3%81%8B%E3%82%89%E3%81%AE%E6%97%A5%E6%9C%AC%E6%B5%B7%E9%81%A0%E6%99%AF.jpg",5184,3888],["c:e/e1/%E5%B9%B3%E5%92%8C%E7%A5%88%E5%BF%B5%E5%A1%94%E3%81%AE%E7%94%B1%E6%9D%A5%EF%BC%88%E7%BE%8E%E4%BF%9D%E9%96%A2%EF%BC%89.jpg",5184,3888],["c:2/21/%E9%A7%86%E9%80%90%E8%89%A6%E8%95%A8%E5%8F%8A%E8%91%A6%E6%AE%89%E8%81%B7%E8%80%85%E5%BF%A0%E9%AD%82%E7%A2%91.jpg",4000,1800],["c:7/71/%E6%85%B0%E9%9C%8A%E5%A1%94%EF%BC%88%E5%A2%83%E6%B8%AF%EF%BC%89%E6%B5%B7%E8%BB%8D%E7%9C%81%E4%B8%8B%E4%BB%98%E4%BF%82%E7%95%99%E6%A9%9F%E9%9B%B7%E3%83%BB%E4%BA%8C%E7%AD%89%E9%A7%86%E9%80%90%E8%89%A612%E3%8E%9D%E7%A0%B2%E8%BA%AB.jpg",1800,4000],["c:f/f2/%E6%85%B0%E9%9C%8A%E5%A1%94%EF%BC%88%E5%A2%83%E6%B8%AF%EF%BC%89.jpg",4000,1800],["c:0/02/%E6%85%B0%E9%9C%8A%E5%A1%94%E7%94%B1%E6%9D%A5%E8%AA%AC%E6%98%8E%E3%83%BB%E4%BA%8B%E6%95%85%E6%99%82%E8%89%A6%E9%9A%8A%E5%9B%B3%EF%BC%88%E5%A2%83%E6%B8%AF%EF%BC%89.jpg",4000,1800],["c:2/26/%E5%B9%B3%E5%92%8C%E7%A5%88%E5%BF%B5%E5%A1%94%EF%BC%88%E7%BE%8E%E4%BF%9D%E9%96%A2%EF%BC%89.jpg",1800,4000],["c:1/16/%E7%BE%8E%E4%BF%9D%E9%96%A2%E7%81%AF%E5%8F%B0%EF%BC%8B%E3%83%93%E3%83%A5%E3%83%83%E3%83%95%E3%82%A7.jpg",1600,720]]},{"id":"32_mihonoseki_machi","n":"美保関の青石畳通り（北前船の港町）","yomi":"みほのせきのあおいしだたみどおり","cat":"町","y":1800,"era":["myth","edo","meiji"],"sh":"","rank":"B","ad":"松江市美保関町美保関","st":"JR境港駅から美保関行きのバスで約25分。JR松江駅からもバスあり（乗りかえ）","la":35.567,"lo":133.305,"hook":"雨にぬれると石畳が青く光る。えびす様の総本宮の門前に、北前船の時代の港町がそのまま残る。","lead":"美保関は、島根半島の東のはしにある港町です。«えびす様» をまつる美保神社の門前には、雨の日に青く光る石畳の «青石畳通り» が続きます。江戸時代には北前船が風待ちに立ち寄り、たいへんにぎわいました。","story":["美保関の港に着くと、目の前に大きな美保神社の鳥居。その横から細い路地に入ると、足元に青みがかった石が敷きつめられた通りが続いています。これが «青石畳通り»。雨の日には石がしっとりぬれて、名前のとおり青く光ります。«昔の人も、この石の上を歩いたんだな» と思うと、足の運びも自然とゆっくりになります。","美保神社にまつられている神の一人は、事代主神（ことしろぬしのかみ）。えびす様としても知られ、全国のえびす社の総本宮とされます。神話では、大国主命が国をゆずるかどうかを決めるとき、美保の岬で釣りをしていた事代主神に意見を聞いたといいます。事代主神は «この国をお譲りしましょう» と答えました。","江戸時代、美保関は日本海を行き来する北前船の «風待ちの港» として栄えました。天気や風が悪いとき、船はここで何日も待ちます。そのあいだ、船乗りたちは町で買い物をし、宿に泊まり、神社にお参りしました。青石畳の通りには旅館や商家がならび、夜まで人の声がとぎれなかったといわれます。","石畳の石は、近くでとれた凝灰岩と考えられています。荷物を運ぶ人や船乗りたちがたくさん行き来したので、ぬかるまないように敷かれたのでしょう。長い年月のあいだに人びとの足でみがかれ、なめらかな表面になりました。","美保神社では、今も «諸手船神事» や «青柴垣神事» など、国ゆずり神話にちなむ古いお祭りが行われています。岬の先には明治時代の美保関灯台も立っています。神話、港町、そして近代の灯台――小さな町に、日本の歴史の層がぎゅっとつまっています。"],"tl":[["712年","«古事記» に国ゆずり神話が記され、事代主神が «御大の御前» で釣りをしていたとされる"],["733年","«出雲国風土記» に美保郷の名が記される"],["江戸時代","北前船の風待ち港として栄え、青石畳の通りがにぎわう"],["1898年","美保関灯台が初点灯"],["2017年","美保神社本殿が国宝に指定される"]],"who":[["事代主神","美保神社にまつられる神。えびす様として信仰される"],["北前船の船乗りたち","風待ちで美保関に滞在し、町をにぎわせた"],["美保関の人びと","港町の暮らしと神事を今に受けついでいる"]],"deep":["美保造: 美保神社の本殿は、大社造の社殿を二つ横にならべた独特の形で «美保造» とも呼ばれ、国宝に指定されています。","諸手船神事: 毎年12月3日、国ゆずりの神話で使者が事代主神のもとへ船で向かった故事にちなみ、二そうの船が港で競い合う神事です。","青柴垣神事: 毎年4月7日に行われ、国ゆずりのあと事代主神が青柴垣にこもったという神話をもとにしています。","鳴り物の奉納: 美保神社には、楽器が多く奉納されていて、«音曲の神» としての信仰もあります。","北前船の寄港地: 美保関は、下関から日本海を北上する北前船の航路にあり、風待ち港として重要でした。","美保関灯台: 明治時代に建てられた山陰でも古い石造の灯台で、岬の地蔵崎に立っています。灯台の前には、隠岐まで見わたせる展望地があります。"],"look":["雨の日の青石畳通り","美保神社の本殿（国宝）と拝殿","港の風景と古い旅館","地蔵崎の美保関灯台"],"q":["美保神社にまつられ、えびす様としても知られる神は?","事代主神（ことしろぬしのかみ）です。美保神社は全国のえびす社の総本宮とされます。"],"koji":[],"myth":"石畳が敷かれた時期や石の産地には諸説があります。","img":["美保神社","美保関灯台","北前船","事代主神"],"wp":"美保関町","rel":{"ev":[],"grave":[]},"ph":[["c:2/2a/Mihonoseki_Lighthouse_2015.jpg",2560,1920,"美保関町"],["c:a/a6/Meoto_Iwa_%28Mihonoseki%29.jpg",4120,2552],["c:9/99/Miho-jinja_haiden.jpg",3872,2592,"美保神社"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:3/31/Nagatajinjya0906.JPG",4288,2848,"事代主神"]]},{"id":"32_matsue_soujo","n":"松江騒擾事件（終戦直後の県庁焼き討ち）","yomi":"まつえそうじょうじけん","cat":"昭和","y":1945,"era":["showa"],"sh":"","rank":"B","ad":"松江市殿町（島根県庁の一帯）","st":"JR松江駅からバスで約10分、«県庁前» 下車すぐ","la":35.472,"lo":133.05,"hook":"戦争が終わってわずか9日後、«降伏を認めない» 若者たちが県庁に火を放った。","lead":"1945年（昭和20年）8月24日、終戦に反対する若者たちのグループが、松江市の島根県庁などを襲い、県庁の庁舎に火をつけて焼いてしまいました。«松江騒擾事件» と呼ばれ、終戦直後の混乱を伝える出来事です。今は新しい県庁が建っています。","story":["1945年8月15日、天皇のラジオ放送で、日本が戦争に負けたことが国民に伝えられました。«これで戦争が終わる» とほっとした人も、«負けを認めるものか» と怒った人もいました。国じゅうが大きくゆれていたのです。","松江でも、終戦を受け入れない若者たちがいました。中心になったのは岡崎功という青年で、仲間と «皇国義勇軍» と名乗り、戦争を続けるよう人びとに呼びかけようとしました。«今、立ち上がらなければ国はほろびる»。彼らはそう思いこんでいたといわれます。","8月24日の未明、グループは手分けして、島根県庁や発電所・変電所、新聞社、放送局などを襲いました。県庁には火がつけられ、庁舎は燃え落ちてしまいます。暗い夜空に炎があがるのを、町の人びとは不安な気持ちで見つめたことでしょう。","しかし、国全体の流れを変えることはできませんでした。グループのメンバーは次々とつかまり、裁判で重い刑を受けました。戦争が終わったあとも、人びとの心の中の戦争はすぐには終わらなかった――この事件は、そのことを示しています。","焼けた県庁は戦後に建て直され、いまの県庁の建物からは、当時のようすを想像するのはむずかしいでしょう。松江城のすぐそばのこの場所で、終戦の混乱の中、こうした事件があったことを覚えておきたいものです。"],"tl":[["1945年8月15日","終戦の詔書がラジオで放送される"],["1945年8月24日","若者のグループが島根県庁などを襲撃し、県庁舎が焼ける"],["1945年","メンバーが逮捕される"],["戦後","裁判でメンバーに刑が言いわたされる"],["戦後","新しい県庁舎が建てられる"]],"who":[["岡崎功","事件を起こしたグループの中心人物"],["グループの若者たち","終戦に反対し、県庁などを襲った"],["松江の人びと","終戦直後の混乱の中で事件に直面した"]],"deep":["終戦直後の抗戦事件: 1945年8月には、東京の «宮城事件» など、終戦に反対する動きがいくつか起こりました。松江の事件は、地方で起きた代表的な例の一つです。","襲撃の範囲: 県庁だけでなく、発電所・変電所・新聞社・放送局などもねらわれました。情報と電気をおさえ、人びとに決起を呼びかける計画だったと考えられています。","女性の参加: グループには女性のメンバーもいたといわれます。","県庁の焼失: 当時の県庁舎は木造だったため、火は大きく広がりました。多くの行政の書類も失われたといわれます。","呼び名: 当時の法律上の «騒擾罪» に問われたことから «騒擾事件» と呼ばれます。","現在の県庁: 今の島根県庁は戦後に建てられた建物で、松江城の堀のすぐそばにあります。事件を記す碑などは目立ちませんが、場所を知って歩くと戦後史の見え方が変わります。"],"look":["島根県庁の一帯（事件の舞台）","すぐそばの松江城と堀","県立図書館など、戦後に整えられた殿町の官庁街"],"q":["松江騒擾事件が起きたのは、終戦の放送から何日後?","9日後の1945年8月24日です。"],"koji":[],"myth":"グループの人数、襲撃した施設の範囲、被害の細部は資料によって異なります。","img":["宮城事件","島根県庁"],"wp":"松江騒擾事件","rel":{"ev":[],"grave":[]},"ph":[["c:a/a7/Matsue_riot_incident.jpg",799,583,"松江騒擾事件"],["c:2/21/Miho_airport.JPG",4000,3000],["c:1/17/Matsue_gokoku_jinja.jpg",4000,3000],["c:4/42/Ishin_kouron.JPG",4000,3000],["c:a/ad/Asahi19450926.jpg",2361,2731],["c:d/d1/Shimane-Prefectural-Government-Office-Circa-1920.png",1192,773],["c:f/fb/NHKmatsue1940.jpg",702,483],["c:a/af/Shimane_Prefectural_Government_Office_Main_Building.jpg",5010,3757,"島根県庁"]]},{"id":"32_hibayama","n":"比婆山久米神社（イザナミの陵の伝承）","yomi":"ひばやまくめじんじゃ","cat":"伝承","y":712,"era":["myth","nara"],"sh":"","rank":"B","ad":"安来市伯太町横屋","st":"JR安来駅から車で約30分。山頂の奥宮までは登山道を歩いて約40分","la":35.36,"lo":133.21,"hook":"国を生んだ母神イザナミは «出雲と伯耆の境の比婆山» にほうむられた――その山がここだと伝わる。","lead":"比婆山久米神社は、安来市伯太町の比婆山にある神社です。«古事記» に、イザナミノミコトが «出雲国と伯伎国との境の比婆之山» にほうむられたと書かれていて、この山がその陵（お墓）だと伝えられています。山頂には奥宮があります。","story":["日本の島々と多くの神々を生んだイザナミノミコト。しかし火の神カグツチを生んだときの大やけどで、ついに亡くなってしまいます。夫のイザナギは深く悲しみ、涙を流しました。«古事記» には、イザナミは «出雲国と伯伎（ほうき）国との境の比婆之山» にほうむられた、と記されています。","«比婆之山とはどこなのか?»――この問いには、昔からいくつもの答えがあります。広島県庄原市の比婆山、鳥取県の山々など、候補地は各地にあります。その一つが、この安来市伯太町の比婆山です。ここは実際に、かつての出雲国と伯耆国の境に近い場所にあります。","山のふもとには神社があり、山頂には奥宮と、イザナミの御陵と伝わる場所があります。静かな山道を登っていくと、木々に囲まれた山頂にたどり着きます。«母なる神の眠る山»。地元の人びとは、この山を大切に守ってきました。","このあたりは、神話と結びつく地名が多い土地です。出雲の東の端、伯耆との境には、黄泉比良坂の伝承地（東出雲町）もあります。イザナミをめぐる話が、出雲の東側に集まっているのはなぜでしょう。«あの世» と «この世» の境、国と国の境――境目の土地に、死と生の神話が語られたのかもしれません。","本当の比婆山がどこか、決めることはできません。けれど、この山を «イザナミのお墓» と信じ、祈りをささげてきた人びとの思いは本物です。登山道を歩き、山頂で手を合わせるとき、神話は昔話ではなく、この土地の人びとの信仰として生きていることに気づくでしょう。"],"tl":[["712年","«古事記» にイザナミが比婆之山にほうむられたと記される"],["720年","«日本書紀» の一書では、イザナミは紀伊国の熊野の有馬村にほうむられたとされる"],["733年","«出雲国風土記» が完成"],["江戸時代以降","比婆山の御陵伝承が各地で語られる"],["現代","ふもとの神社と山頂の奥宮に参拝者がおとずれる"]],"who":[["イザナミノミコト","国生みの女神。比婆山にほうむられたと «古事記» にある"],["イザナギノミコト","イザナミの夫。妻の死を深く悲しんだ"],["カグツチ","火の神。その誕生がイザナミの死の原因となった"]],"deep":["候補地の多さ: «比婆之山» の候補は、広島県庄原市の比婆山（御陵とされる場所がある）、この安来市の比婆山、鳥取県内の山などがあり、どれかに決まってはいません。","日本書紀の異伝: «日本書紀» の一書では、イザナミは紀伊国熊野の有馬村にほうむられたとされ、三重県熊野市の花の窟神社がその地と伝えられています。","«久米» の名: 神社名の «久米» は、古代の氏族や地名とかかわるとの説がありますが、はっきりしません。","境の山: 比婆山は、古代の出雲国と伯耆国の境に近く、«古事記» の記述と地理的に合うことが、この地を候補とする理由の一つになっています。","黄泉比良坂との位置関係: 東出雲町の黄泉比良坂の伝承地とも比較的近く、イザナミ神話ゆかりの場所をめぐる旅ができます。","山頂の奥宮: 山頂付近には奥宮と御陵とされる場所があり、神聖な場所として大切にされています。"],"look":["ふもとの比婆山久米神社","山頂の奥宮と御陵と伝わる場所","山道の静かな森"],"q":["«古事記» でイザナミがほうむられたとされる山は、どの国とどの国の境にある?","出雲国と伯伎（伯耆）国の境の «比婆之山» です。"],"koji":[],"myth":"比婆之山の場所は候補が複数あり、この山を御陵とするのは地元の伝承です。","img":["イザナミ","比婆山","黄泉比良坂","花の窟神社"],"wp":"比婆山久米神社","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/%E6%AF%94%E5%A9%86%E5%B1%B1%E3%81%AE%E5%B1%B1%E9%A0%82%E4%BB%98%E8%BF%91%E3%81%AB%E3%81%82%E3%82%8B%E4%BC%8A%E9%82%AA%E9%82%A3%E7%BE%8E%E5%91%BD%E5%BE%A1%E9%99%B5%E3%81%A8%E4%BC%9D%E3%82%8F%E3%82%8B%E5%8F%A4%E5%A2%B3.JPG",3264,1836,"比婆山久米神社"],["c:c/cd/%E9%99%B0%E9%99%BD%E7%AB%B9.JPG",1836,3264],["c:1/1b/%E7%8E%89%E6%8A%B1%E7%9F%B3.JPG",1836,3264],["c:6/69/%E6%AF%94%E5%A9%86%E5%B1%B1.JPG",3264,1836],["c:8/84/Kobayashi_Izanami_and_Izanagi.jpg",592,1307,"イザナミ"],["c:0/04/Yomotsu_Hirasaka.JPG",2352,1568,"黄泉比良坂"],["c:0/0b/Hananoiwaya_Shrine03.jpg",1000,750,"花の窟神社"]]}];
